function filterStatutoryRecordsForFormDRJAutofill(records, headers) {
  if (!Array.isArray(records) || records.length === 0) return records;
  if (!Array.isArray(headers) || headers.length === 0) return records;
  const isDayHeader = (hdr) => /^\d{1,2}$/.test(String(hdr || '').trim());
  return records.filter((rec) => {
    const columnName = String(rec?.ColumnName ?? rec?.columnName ?? '').trim();
    if (!columnName) return true;
    const headerKey = findBaseHeaderForStatutoryColumnName(columnName, headers);
    const hdr = headerKey || columnName;
    const val = String(rec?.Value ?? rec?.value ?? '').trim();
    if (isFormDRJPeopleFieldHeader(hdr) || isDayHeader(hdr)) {
      if (!val) return false;
      if (/^enter\b/i.test(val)) return false;
      if (/^enter\s+/i.test(val)) return false;
    }
    return true;
  });
}

function applyStatutoryDataOverlayToRows(
  baseRows,
  baseHeaders,
  statutoryRecords,
  employeeOrder = null,
  rowIndexOffset = 0
) {
  if (
    !Array.isArray(baseRows) ||
    !Array.isArray(baseHeaders) ||
    !Array.isArray(statutoryRecords) ||
    statutoryRecords.length === 0
  ) {
    return baseRows;
  }
  const formUsesRowIndexKeys = !headersHaveStatutoryEmployeeIdentityColumn(baseHeaders);
  const useRowOrder =
    formUsesRowIndexKeys && Array.isArray(employeeOrder) && employeeOrder.length > 0;

  return baseRows.map((row, localIdx) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) return row;
    const out = { ...row };
    const globalRowIdx = rowIndexOffset + localIdx;
    const rowEmployeeKeys = resolveStatutoryOverlayRowMatchKeys(row, baseHeaders);
    if (useRowOrder && employeeOrder[globalRowIdx]) {
      rowEmployeeKeys.push(String(employeeOrder[globalRowIdx]).trim());
    }
    statutoryRecords.forEach((rec) => {
      const employeeKey = String(rec?.ChangeDataHeader ?? rec?.changeDataHeader ?? '').trim();
      const columnName = String(rec?.ColumnName ?? rec?.columnName ?? '').trim();
      const value = rec?.Value ?? rec?.value;
      if (!employeeKey || !columnName || value == null || String(value).trim() === '') return;
      let matched = false;
      if (formUsesRowIndexKeys) {
        const rowKeyIdx = parseStatutoryRowIndexKey(employeeKey);
        if (rowKeyIdx != null && rowKeyIdx === globalRowIdx) {
          matched = true;
        } else if (useRowOrder) {
          const expectedKey = String(employeeOrder[globalRowIdx] ?? '').trim();
          matched = expectedKey
            ? statutoryOverlayEmployeeKeysMatch([expectedKey], employeeKey)
            : false;
          if (!matched && !/^VE\d/i.test(employeeKey) && rowKeyIdx == null) {
            matched = statutoryOverlayEmployeeKeysMatch(rowEmployeeKeys, employeeKey);
          }
        } else if (rowKeyIdx == null) {
          matched = statutoryOverlayEmployeeKeysMatch(rowEmployeeKeys, employeeKey);
        }
      } else {
        matched = statutoryOverlayEmployeeKeysMatch(rowEmployeeKeys, employeeKey);
      }
      if (!matched) return;
      const headerKey = findBaseHeaderForStatutoryColumnName(columnName, baseHeaders);
      if (headerKey && isForm12AdvancesManualRepaymentColumnHeader(headerKey)) return;
      if (headerKey && isFormMGJContactHeader(headerKey)) {
        out[headerKey] = sanitizeFormMGJGujaratMobileValue(value);
      } else if (headerKey) {
        out[headerKey] = String(value);
      }
    });
    return out;
  });
}

async function overlayStatutoryDataOntoGridRows(rows, headers, context = {}) {
  if (!Array.isArray(rows) || rows.length === 0) return rows;
  const records = await fetchStatutoryDataSnapshot(context);
  if (!records.length) return rows;
  const employeeOrder =
    Array.isArray(context.statutoryDataEmployeeOrder) && context.statutoryDataEmployeeOrder.length > 0
      ? context.statutoryDataEmployeeOrder
      : buildStatutoryDataEmployeeOrder(
          resolveStatutoryEmployeesForSaveOrder(context.employees),
          rows.length
        );
  return applyStatutoryDataOverlayToRows(
    rows,
    headers,
    records,
    employeeOrder,
    Number(context.rowIndexOffset) || 0
  );
}

/** Fetch latest SampleData grid snapshot for a statutory ROWID (import/autofill/save). */
async function fetchStatutorySampleDataSnapshot(statutoryId, context = {}) {
  const idStr = String(statutoryId || '').trim();
  const formNameCtx = String(context?.formName || '').trim();
  const monthCtx = String(
    context?.monthFilter || context?.MonthFilter || context?.monthfilter || ''
  ).trim();
  const formMonthOnlyLookup = formNameCtx && (idStr === '0' || !/^\d+$/.test(idStr));
  if (!formMonthOnlyLookup && !/^\d+$/.test(idStr)) return null;
  try {
    const params = new URLSearchParams({ _ts: String(Date.now()) });
    if (formNameCtx) params.set('formName', formNameCtx);
    if (monthCtx) params.set('monthFilter', monthCtx);
    if (formMonthOnlyLookup) params.set('matchByFormMonth', '1');
    const lookupId = /^\d+$/.test(idStr) ? idStr : '0';
    const resp = await fetch(
      `/server/statutoryreg_function/statutory/${lookupId}/sampledata?${params.toString()}`
    );
    if (!resp.ok) return null;
    const json = await resp.json().catch(() => null);
    const block = json?.data?.sampleData;
    if (!block || !Array.isArray(block.rows) || block.rows.length === 0) return null;
    return normalizeSampleDataSnapshotBlock(block);
  } catch {
    return null;
  }
}

/** Try several statutory ids (bulk row vs linked ROWID) until ImportData or SampleData is found. */
async function fetchFirstAvailableStatutorySampleDataSnapshot(...args) {
  const seen = new Set();
  let context = null;
  const statutoryIds = [];
  for (const raw of args) {
    if (raw && typeof raw === 'object' && !Array.isArray(raw) && raw.formName != null) {
      context = raw;
      continue;
    }
    statutoryIds.push(raw);
  }
  const uniqueIds = [];
  for (const raw of statutoryIds) {
    const idStr = String(raw || '').trim();
    if (!/^\d+$/.test(idStr) || seen.has(idStr)) continue;
    seen.add(idStr);
    uniqueIds.push(idStr);
  }

  const fetchTasks = [];
  if (context?.formName) {
    fetchTasks.push(
      fetchStatutoryImportDataSnapshot('0', context),
      fetchStatutorySampleDataSnapshot('0', context)
    );
  }
  uniqueIds.forEach((idStr) => {
    fetchTasks.push(
      fetchStatutoryImportDataSnapshot(idStr, context || {}),
      fetchStatutorySampleDataSnapshot(idStr, context || {})
    );
  });
  if (fetchTasks.length === 0) return null;

  const results = await Promise.all(fetchTasks.map((task) => task.catch(() => null)));
  return results.find((block) => block && Array.isArray(block.rows) && block.rows.length > 0) || null;
}

function uniqueNumericStatutoryIds(...candidates) {
  const seen = new Set();
  const out = [];
  for (const raw of candidates) {
    const idStr = String(raw ?? '').trim();
    if (!/^\d+$/.test(idStr) || seen.has(idStr)) continue;
    seen.add(idStr);
    out.push(idStr);
  }
  return out;
}

/** Normalize header/row keys saved from Excel (may contain \\r\\n in column names). */
function normalizeSampleDataSnapshotBlock(block) {
  if (!block || typeof block !== 'object') return null;
  const rawHeaders = Array.isArray(block.headers) ? block.headers : [];
  const headers = rawHeaders.map((h) => normalizeSampleDataGridKey(h));
  const rows = Array.isArray(block.rows)
    ? block.rows.map((row) => {
        if (!row || typeof row !== 'object' || Array.isArray(row)) return row;
        const out = {};
        for (const [key, val] of Object.entries(row)) {
          if (String(key).startsWith('__')) continue;
          const normKey = normalizeSampleDataGridKey(key);
          const headerMatchIdx = rawHeaders.findIndex(
            (h, idx) => normalizeSampleDataGridKey(h) === normKey || headers[idx] === normKey
          );
          const targetKey =
            headerMatchIdx >= 0 ? headers[headerMatchIdx] || normKey : normKey;
          out[targetKey] = val;
        }
        return out;
      })
    : [];
  return {
    ...block,
    headers,
    rows,
    monthfilter: block.monthfilter || block.MonthFilter || null,
    MonthFilter: block.MonthFilter || block.monthfilter || null
  };
}

/** Day-of-month columns (Form 25 / Form XXII `Dates_1` … `Dates_31`). */
function countStatutoryDayColumnHeaders(headers) {
  if (!Array.isArray(headers)) return 0;
  return headers.filter((h) => {
    const t = String(h || '').trim();
    if (/^\d{1,2}$/.test(t)) {
      const n = Number(t);
      return n >= 1 && n <= 31;
    }
    const suff = t.match(/_(\d{1,2})$/);
    if (suff) {
      const n = Number(suff[1]);
      return n >= 1 && n <= 31;
    }
    return false;
  }).length;
}

/** Keep modal / template headers when SampleData snapshot has fewer day columns. */
function pickRicherStatutoryTableHeaders(baseHdrs, sampleHdrs) {
  const base = Array.isArray(baseHdrs) ? baseHdrs : [];
  const sample = Array.isArray(sampleHdrs) ? sampleHdrs : [];
  if (sample.length === 0) return [...base];
  if (base.length === 0) return [...sample];
  const baseDays = countStatutoryDayColumnHeaders(base);
  const sampleDays = countStatutoryDayColumnHeaders(sample);
  if (baseDays > sampleDays) return [...base];
  if (sampleDays > baseDays) return [...sample];
  if (base.length >= sample.length) return [...base];
  return [...sample];
}

function isStatutoryDayColumnHeaderKey(header) {
  const t = String(header || '').trim();
  if (/^\d{1,2}$/.test(t)) {
    const n = Number(t);
    return n >= 1 && n <= 31;
  }
  const suff = t.match(/_(\d{1,2})$/);
  if (suff) {
    const n = Number(suff[1]);
    return n >= 1 && n <= 31;
  }
  return false;
}

function listStatutoryDayColumnHeaders(headers) {
  const out = [];
  (Array.isArray(headers) ? headers : []).forEach((h) => {
    if (isStatutoryDayColumnHeaderKey(h)) out.push(h);
  });
  return out;
}

/** Form XXII draft download: SampleData may have names but no P/A/WO in day columns. */
function formXXIIDownloadRowsNeedAttendanceEnrich(rows, headers) {
  if (!Array.isArray(rows) || rows.length === 0) return true;
  return !rows.some((row) => rowHasAnyFormXXIIAPAttendance(row));
}

function formXXIIAttendanceCodeFromValue(v) {
  return /^(P|A|WO|H|L|WOP|OD|SL|CL|EL)$/i.test(String(v ?? '').trim())
    ? String(v).trim()
    : '';
}

function formXXIIEmployeeNameFromRow(row, hdrs) {
  if (!row || typeof row !== 'object') return '';
  const list = Array.isArray(hdrs) ? hdrs : [];
  const nameHdr =
    list.find((h) => /name\s+of\s+the\s+(employee|workman|workmen)/i.test(String(h || ''))) ||
    list.find((h) => /\bname\b/i.test(String(h || '')) && !/establishment/i.test(String(h || '')));
  if (nameHdr && row[nameHdr] != null) return String(row[nameHdr]).trim().toLowerCase();
  for (const [key, val] of Object.entries(row)) {
    if (String(key).startsWith('__')) continue;
    if (/name\s+of\s+the\s+(employee|workman|workmen)/i.test(String(key || ''))) {
      return String(val ?? '').trim().toLowerCase();
    }
  }
  return '';
}

function pickFormXXIIAttendanceFromRow(row, header) {
  if (!row || typeof row !== 'object') return '';
  const direct = formXXIIAttendanceCodeFromValue(row[header]);
  if (direct) return direct;
  const day = resolveFormXXIIAPDayNumberFromHeader(header);
  if (day >= 1 && day <= 31) {
    const viaReader = formXXIIAttendanceCodeFromValue(readFormXXIIAPCellValue(row, String(day)));
    if (viaReader) return viaReader;
  }
  return '';
}

/** Copy P/A/WO day-grid values from enriched rows onto live/export rows without wiping employee fields. */
function overlayFormXXIIAttendanceFromEnriched(baseRows, enrichedRows, headers) {
  const base = Array.isArray(baseRows) ? baseRows.map((r) => ({ ...r })) : [];
  const enriched = Array.isArray(enrichedRows) ? enrichedRows : [];
  if (!enriched.length) return base;
  if (!base.length) return enriched.map((r) => ({ ...r }));

  const resolvedHdrs = ensureFormXXIIAPDayColumnHeaders(
    resolveFormXXIIExportHeaders(headers, enriched)
  );
  const dayHdrs = listFormXXIIAPDayHeaders(resolvedHdrs);

  const findEnrichedRow = (baseRow, idx) => {
    if (enriched[idx] && typeof enriched[idx] === 'object') return enriched[idx];
    const baseName = formXXIIEmployeeNameFromRow(baseRow, resolvedHdrs);
    if (!baseName) return null;
    return (
      enriched.find((r) => r && formXXIIEmployeeNameFromRow(r, resolvedHdrs) === baseName) || null
    );
  };

  for (let i = 0; i < base.length; i += 1) {
    const er = findEnrichedRow(base[i], i);
    if (!er) continue;
    dayHdrs.forEach(({ header, day }) => {
      const existing =
        readFormXXIIAPCellValue(base[i], header) || readFormXXIIAPCellValue(base[i], String(day));
      if (isFormXXIIAPAttendanceCode(existing)) return;
      const val =
        readFormXXIIAPCellValue(er, header) || readFormXXIIAPCellValue(er, String(day));
      if (!isFormXXIIAPAttendanceCode(val)) return;
      base[i][header] = val;
      base[i][String(day)] = val;
    });
  }
  return base;
}

/** Form XVI Muster Roll — prefer saved SampleData / live grid rows that contain P/A/WO. */
function resolveFormXVIAPMusterExportPayload(mappedData, headersToUse, options = {}) {
  const {
    cachedSampleBlock = null,
    usedLiveModalGrid = false,
    liveRows = [],
    liveHeaders = []
  } = options;
  let rows = Array.isArray(mappedData) ? mappedData.map((row) => ({ ...row })) : [];
  let hdrs = Array.isArray(headersToUse) ? [...headersToUse] : [];

  if (usedLiveModalGrid && Array.isArray(liveRows) && liveRows.length > 0) {
    rows = liveRows.map((row) => ({ ...row }));
    if (Array.isArray(liveHeaders) && liveHeaders.length > 0) {
      hdrs = pickRicherStatutoryTableHeaders(liveHeaders, hdrs);
    }
    return { mappedData: rows, headersToUse: hdrs };
  }

  const sampleRows = Array.isArray(cachedSampleBlock?.rows) ? cachedSampleBlock.rows : [];
  const sampleHdrs = Array.isArray(cachedSampleBlock?.headers) ? cachedSampleBlock.headers : [];
  if (sampleRows.length > 0) {
    const mergedHdrs = pickRicherStatutoryTableHeaders(hdrs, sampleHdrs);
    const sampleHasAttendance = !formXXIIDownloadRowsNeedAttendanceEnrich(sampleRows, mergedHdrs);
    if (sampleHasAttendance) {
      if (rows.length === 0 || formXXIIDownloadRowsNeedAttendanceEnrich(rows, mergedHdrs)) {
        rows = sampleRows.map((row) => ({ ...row }));
      } else {
        rows = overlayLiveModalRowsOntoDownload(rows, sampleRows, mergedHdrs, mergedHdrs);
      }
      hdrs = mergedHdrs;
    } else if (rows.length > 0) {
      rows = overlaySampleDataRowsOntoBase(rows, sampleRows, sampleHdrs, hdrs, {
        fillOnlyEmpty: true,
        allowIndexFallback: true
      });
      hdrs = pickRicherStatutoryTableHeaders(hdrs, sampleHdrs);
    } else {
      rows = sampleRows.map((row) => ({ ...row }));
      hdrs = pickRicherStatutoryTableHeaders(hdrs, sampleHdrs);
    }
  }

  return { mappedData: rows, headersToUse: hdrs };
}

/** Overlay SampleData / imported manual columns onto autofill rows (all forms). */
function overlaySampleDataRowsOntoBase(baseRows, sampleRows, sampleHeaders, baseHeaders, options = {}) {
  return overlayImportRowsOntoBase(baseRows, sampleRows, sampleHeaders, baseHeaders, {
    fillOnlyEmpty: options.fillOnlyEmpty !== false,
    allowIndexFallback: options.allowIndexFallback === true
  });
}

/** Overlay live modal / imported rows; when fillOnlyEmpty=false, non-empty import values always win. */
function overlayImportRowsOntoBase(baseRows, importRows, importHeaders, baseHeaders, options = {}) {
  const fillOnlyEmpty = options.fillOnlyEmpty !== false;
  const allowIndexFallback = options.allowIndexFallback === true;
  const base = Array.isArray(baseRows) ? baseRows : [];
  const imports = Array.isArray(importRows) ? importRows : [];
  if (imports.length === 0) return base;
  if (base.length === 0) return imports.map((r) => ({ ...r }));
  const importHdrs = Array.isArray(importHeaders) ? importHeaders : [];
  const baseHdrs = Array.isArray(baseHeaders) ? baseHeaders : [];
  const norm = (v) =>
    String(v || '')
      .replace(/[\r\n]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  const rowSerial = (row, hdrs) => {
    if (!row || typeof row !== 'object') return '';
    const serialHdr =
      hdrs.find((h) =>
        /s\.?\s*no|serial\s*number|sl\.?\s*no|number\s+in\s+register|register\s+number/i.test(String(h || ''))
      ) || hdrs[0];
    if (serialHdr && row[serialHdr] != null) return String(row[serialHdr]).trim();
    const vals = Object.values(row);
    return vals.length ? String(vals[0] ?? '').trim() : '';
  };
  const findMatchingImportRow = (baseRow, idx) => {
    const baseSerial = normRegisterSerial(rowSerial(baseRow, baseHdrs));
    if (baseSerial) {
      for (const ir of imports) {
        if (!ir || typeof ir !== 'object') continue;
        if (normRegisterSerial(rowSerial(ir, importHdrs)) === baseSerial) return ir;
        for (const val of Object.values(ir)) {
          if (normRegisterSerial(val) === baseSerial) return ir;
        }
      }
    }
    if (allowIndexFallback && imports[idx] && typeof imports[idx] === 'object') {
      return imports[idx];
    }
    return null;
  };
  const findBaseHeaderForImportHeader = (importHeader, outRow) => {
    const target = norm(importHeader);
    if (!target) return importHeader;
    const exact = baseHdrs.find((h) => norm(h) === target);
    if (exact) return exact;
    const outKey = Object.keys(outRow || {}).find((k) => norm(k) === target);
    if (outKey) return outKey;
    const fuzzy = baseHdrs.find((h) => {
      const nh = norm(h);
      return nh && (nh.includes(target) || target.includes(nh));
    });
    return fuzzy || importHeader;
  };
  const applyImportValue = (out, importHeader, val) => {
    if (val == null || String(val).trim() === '') return;
    const baseKey = findBaseHeaderForImportHeader(importHeader, out);
    const existing = String(out[baseKey] ?? '').trim();
    if (!fillOnlyEmpty || existing === '') {
      out[baseKey] = val;
    }
  };
  return base.map((baseRow, idx) => {
    const importRow = findMatchingImportRow(baseRow, idx);
    if (!importRow) return { ...baseRow };
    const out = { ...baseRow };
    importHdrs.forEach((ih) => applyImportValue(out, ih, importRow[ih]));
    Object.entries(importRow).forEach(([k, v]) => {
      if (v == null || String(v).trim() === '') return;
      const nk = norm(k);
      const existingKey = Object.keys(out).find((bk) => norm(bk) === nk);
      if (existingKey) {
        const existing = String(out[existingKey] ?? '').trim();
        if (!fillOnlyEmpty || existing === '') out[existingKey] = v;
      } else {
        out[k] = v;
      }
    });
    return out;
  });
}

/** Live Autofill modal edits always win over SampleData/Zoho on download. */
function overlayLiveModalRowsOntoDownload(baseRows, liveRows, liveHeaders, baseHeaders) {
  const base = Array.isArray(baseRows) ? baseRows : [];
  const imports = Array.isArray(liveRows) ? liveRows : [];
  if (imports.length === 0) return base;
  if (base.length === 0) return imports.map((r) => ({ ...r }));
  const baseHdrs = Array.isArray(baseHeaders) && baseHeaders.length > 0 ? baseHeaders : liveHeaders;
  const liveHdrs = Array.isArray(liveHeaders) && liveHeaders.length > 0 ? liveHeaders : baseHdrs;
  // Modal grid is authoritative when it has more employee rows than stale snapshot/base data.
  if (imports.length > base.length) {
    return remapFormARowsByColumnIndex(imports, liveHdrs, baseHdrs);
  }
  return overlayImportRowsOntoBase(base, imports, liveHdrs, baseHdrs, {
    fillOnlyEmpty: false,
    allowIndexFallback: false
  });
}

/** Normalize employee register / serial for row matching (VE1044 === VE 1044). */
function normRegisterSerial(value) {
  const s = String(value ?? '')
    .trim()
    .toUpperCase()
    .replace(/\s+/g, '');
  if (!s) return '';
  return s.replace(/[^A-Z0-9]/g, '');
}

/** Apply SampleData snapshot rows/headers to download payload (imported/saved grid). */
function applyStatutorySampleDataBlockToDownload(mappedData, headersToUse, sampleBlock, options = {}) {
  if (!sampleBlock || !Array.isArray(sampleBlock.rows) || sampleBlock.rows.length === 0) {
    return { mappedData, headersToUse, usedSnapshot: false, headerFormData: null };
  }
  const sampleRows = sampleBlock.rows;
  const sampleHeaders = Array.isArray(sampleBlock.headers) ? sampleBlock.headers : [];
  const headerFormData =
    sampleBlock.headerFormData &&
    typeof sampleBlock.headerFormData === 'object' &&
    !Array.isArray(sampleBlock.headerFormData)
      ? sampleBlock.headerFormData
      : null;
  const preferSampleOnly = options.preferSampleOnly === true;
  const forceOverlay = options.forceOverlay === true;
  const rejectNonSubstantiveSample = options.rejectNonSubstantiveSample === true;
  const hasBaseRows = Array.isArray(mappedData) && mappedData.length > 0;
  const sampleHasSubstantiveRows = wageRegisterDownloadHasSubstantiveRows(
    sampleRows,
    sampleHeaders.length > 0 ? sampleHeaders : headersToUse
  );
  if (rejectNonSubstantiveSample && !sampleHasSubstantiveRows) {
    if (hasBaseRows) {
      return {
        mappedData,
        headersToUse,
        usedSnapshot: false,
        headerFormData: null
      };
    }
    return {
      mappedData: Array.isArray(mappedData) ? mappedData : [],
      headersToUse,
      usedSnapshot: false,
      headerFormData: null
    };
  }
  if ((preferSampleOnly && !forceOverlay) || !hasBaseRows) {
    if (!sampleHasSubstantiveRows && hasBaseRows) {
      return {
        mappedData,
        headersToUse,
        usedSnapshot: false,
        headerFormData: null
      };
    }
    return {
      mappedData: sampleRows,
      headersToUse: sampleHeaders.length > 0 ? [...sampleHeaders] : headersToUse,
      usedSnapshot: true,
      headerFormData
    };
  }
  return {
    mappedData: overlaySampleDataRowsOntoBase(mappedData, sampleRows, sampleHeaders, headersToUse),
    headersToUse: pickRicherStatutoryTableHeaders(headersToUse, sampleHeaders),
    usedSnapshot: true,
    headerFormData
  };
}

function buildSampleDataDownloadApplyOptions(options = {}) {
  const {
    isForm10Download = false,
    isForm12Download = false,
    isFormTSEDownload = false,
    isFormXXIIIDownload = false,
    isFormXVIIDownload = false,
    isFormXVIIIMPDownload = false,
    isFormXXIIDownload = false,
    isFormXVIDownload = false,
    isFormXDownload = false,
    usedLiveModalGrid = false
  } = options;
  const forceOverlay =
    isForm10Download ||
    isForm12Download ||
    isFormTSEDownload ||
    isFormXXIIIDownload ||
    isFormXVIIDownload ||
    isFormXVIIIMPDownload ||
    isFormXXIIDownload ||
    isFormXVIDownload ||
    usedLiveModalGrid;
  return {
    // Form X: never prefer SampleData alone — May/empty months often store template "1 2 3 4" model rows.
    preferSampleOnly: !forceOverlay && !isFormXDownload,
    forceOverlay,
    rejectNonSubstantiveSample:
      isFormXXIIIDownload ||
      isFormXVIIDownload ||
      isFormXVIIIMPDownload ||
      isFormXXIIDownload ||
      isFormXDownload
  };
}

async function resolveStatutorySampleDataBlockForDownload(fetchIds, context = {}) {
  const ids = Array.isArray(fetchIds) ? fetchIds : [...fetchIds];
  return fetchFirstAvailableStatutorySampleDataSnapshot(...ids, context);
}

/** Overlay SampleData / imported manual columns onto Zoho autofill rows (Form 12). */
function overlayForm12SampleRowsOntoBase(baseRows, sampleRows, sampleHeaders, baseHeaders) {
  return overlaySampleDataRowsOntoBase(baseRows, sampleRows, sampleHeaders, baseHeaders, {
    fillOnlyEmpty: true,
    allowIndexFallback: false
  });
}

function isStatutoryPayloadTooLargeResponse(response, rawText) {
  const status = Number(response?.status);
  if (status === 413) return true;
  const text = String(rawText || '');
  if (/PayloadTooLargeError/i.test(text)) return true;
  if (/request entity too large/i.test(text)) return true;
  return false;
}

let statutoryBroadcastChannel = null;
try {
  if (typeof BroadcastChannel !== 'undefined') {
    statutoryBroadcastChannel = new BroadcastChannel(STATUTORY_BROADCAST_CHANNEL_NAME);
  }
} catch (_) {
  statutoryBroadcastChannel = null;
}

function broadcastStatutoryDataChange(detail = {}) {
  const payload = { ts: Date.now(), ...detail };
  try {
    localStorage.setItem(STATUTORY_DATA_REVISION_KEY, JSON.stringify(payload));
  } catch (_) {}
  try {
    statutoryBroadcastChannel?.postMessage(payload);
  } catch (_) {}
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('statutoryDataUpdated', { detail: payload }));
  }
}

/** Align Statutory rows with ChecklistBulk master (Sector, State, Act, Form Name, Description). */
function checklistBulkRowIdentityKey(row) {
  const norm = (v) =>
    String(v ?? '')
      .trim()
      .toLowerCase()
      .replace(/\s+/g, ' ');
  return [
    norm(row?.formName ?? row?.FormName),
    norm(row?.sector ?? row?.Sector),
    norm(row?.state ?? row?.State),
    norm(row?.act ?? row?.Act),
    norm(row?.description ?? row?.Description)
  ].join('\x1f');
}

/** Split comma-joined Statutory Site column values for comparisons (multi-site per state). */
function parseResolvedSiteTokens(resolved) {
  return String(resolved || '')
    .trim()
    .toLowerCase()
    .split(/\s*,\s*/)
    .map((p) => p.trim())
    .filter(Boolean);
}

function resolvedSitesOverlap(resolvedA, resolvedB) {
  const a = parseResolvedSiteTokens(resolvedA);
  const b = parseResolvedSiteTokens(resolvedB);
  if (a.length === 0 || b.length === 0) return false;
  const setA = new Set(a);
  return b.some((x) => setA.has(x));
}

function resolvedSiteMatchesSingleTarget(resolved, targetSiteSingle) {
  const t = String(targetSiteSingle || '').trim().toLowerCase();
  if (!t) return false;
  return parseResolvedSiteTokens(resolved).includes(t);
}

function resolvedSiteAnyAllowed(resolved, allowedSitesLowerSet) {
  return parseResolvedSiteTokens(resolved).some((x) => allowedSitesLowerSet.has(x));
}

/** Prefer statutory donors that belong to the active ?site= context (avoids admin/other-site bleed in site view). */
function statutoryDonorSitePreferenceScore(row, targetSiteSingle) {
  const t = String(targetSiteSingle || '').trim().toLowerCase();
  if (!t) return 0;
  const explicit = String(row?.site ?? row?.Site ?? row?.siteName ?? row?.SiteName ?? '').trim();
  if (!explicit) return 0;
  if (resolvedSiteMatchesSingleTarget(explicit, t)) return 3000;
  return -4000;
}

/**
 * Single site name only — never comma-joined multi-site labels.
 * Statutory must store Site + State + Sector so one state's sites stay separate.
 */
function pickSingleSiteNameToken(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (!raw.includes(',')) return raw;
  const tokens = raw
    .split(/\s*,\s*/)
    .map((p) => p.trim())
    .filter(Boolean);
  return tokens.length === 1 ? tokens[0] : '';
}

/** Resolve one concrete site for Catalyst Site column (URL site wins). */
function resolveSingleSiteNameForStatutorySave(item, siteFromUrl, resolvedDisplayName = '') {
  const fromUrl = pickSingleSiteNameToken(siteFromUrl);
  if (fromUrl) return fromUrl;
  const explicit = pickSingleSiteNameToken(
    item?.site ?? item?.Site ?? item?.siteName ?? item?.SiteName ?? ''
  );
  if (explicit) return explicit;
  return pickSingleSiteNameToken(resolvedDisplayName);
}

/**
 * When ?site= is active, only overlay workflow metadata from rows that belong to that site.
 * Rows with a different explicit Site must never bleed across sites in the same state.
 */
function statutoryDonorBelongsToTargetSite(row, targetSiteSingle, { allowEmptySite = false } = {}) {
  const t = String(targetSiteSingle || '').trim().toLowerCase();
  if (!t) return true;
  const explicit = String(row?.site ?? row?.Site ?? row?.siteName ?? row?.SiteName ?? '').trim();
  if (!explicit) return !!allowEmptySite;
  return resolvedSiteMatchesSingleTarget(explicit, t);
}

/**
 * Keep ChecklistBulk form lines visible for every site in the same state.
 * If this row belongs to another site, clear draft/sent/proof so Site B still shows all forms empty.
 */
function clearStatutoryWorkflowForOtherSite(item, targetSiteName) {
  const site = String(targetSiteName || '').trim();
  const keepSyntheticId =
    item?.isBulkImported ||
    isSyntheticStatutoryRowId(item?.id) ||
    String(item?.id ?? '').startsWith('bulk_');
  const nextId = keepSyntheticId
    ? item.id
    : `bulk_resite_${squashStatutoryKeyPart(site) || 'site'}_${checklistBulkRowIdentityKey(item) || String(item?.id ?? '')}`;
  return {
    ...item,
    id: nextId,
    site: site || null,
    Site: site || null,
    isBulkImported: true,
    draftFile: null,
    DraftFile: null,
    draftFileName: null,
    DraftFileName: null,
    draft: '',
    Draft: '',
    proofSubmissionFile: null,
    ProofSubmissionFile: null,
    proofSubmissionFileName: null,
    ProofSubmissionFileName: null,
    sendForApproval: '',
    SendForApproval: '',
    approval: '',
    Approval: '',
    status: '',
    Status: '',
    remarks: '',
    Remarks: '',
    submittedDate: '',
    SubmittedDate: '',
    approvedDate: '',
    ApprovedDate: '',
    draftStatutoryRowIdForFile: null
  };
}

/** True when row Site is missing or matches the active single-site context. */
function statutoryRowMatchesActiveSite(item, targetSiteSingle) {
  const t = String(targetSiteSingle || '').trim().toLowerCase();
  if (!t) return true;
  const explicit = pickSingleSiteNameToken(item?.site ?? item?.Site ?? '');
  if (!explicit) {
    // Empty Site with draft/sent is legacy/other-site data — keep the form, but not as this site's save.
    const hasWorkflow =
      hasStatutoryDraftFileRef(item) ||
      statutorySendForApprovalIsSent(item) ||
      !!(item?.proofSubmissionFile ?? item?.ProofSubmissionFile);
    return !hasWorkflow;
  }
  return explicit.toLowerCase() === t;
}

function hasStatutoryDraftFileRef(row) {
  const d = row?.draftFile ?? row?.DraftFile;
  return d != null && String(d).trim() !== '' && String(d).trim() !== 'null';
}

function isNumericStatutoryBackendId(id) {
  return /^\d+$/.test(String(id ?? '').trim());
}

function isSyntheticStatutoryRowId(id) {
  const idStr = String(id ?? '').trim();
  return (
    idStr.startsWith('formmaster_') ||
    idStr.startsWith('bulk_') ||
    idStr.startsWith('checklist_') ||
    idStr.startsWith('placeholder_')
  );
}

/** When this user is logged in, Statutory is filtered by ?site= (Delphi site → sector); separate from Site Management industry scope */
const SITE_WISE_STATUTORY_EMAIL = 'afrindinu14@gmail.com';
/** localStorage key for persisting the statutory month filter (based on saved due date) */
const STATUTORY_MONTH_FILTER_KEY = 'statutory_month_filter';
/** sessionStorage: last scoped merge for Site Incharge / ?site= — instant paint on refresh without org-wide flash */
const STATUTORY_SCOPED_SNAPSHOT_PREFIX = 'statutory_scoped_snapshot_v1:';

function buildStatutoryScopedSnapshotKey(userEmail, siteFromUrl, actCategories) {
  const email = normalizeEmail(userEmail) || 'unknown';
  const site = String(siteFromUrl || '').trim().toLowerCase();
  const cats = (Array.isArray(actCategories) ? actCategories : []).slice().sort().join(',');
  return `${STATUTORY_SCOPED_SNAPSHOT_PREFIX}${email}|${site}|${cats}`;
}

function readStatutoryScopedSnapshot(userEmail, siteFromUrl, actCategories) {
  try {
    const raw = sessionStorage.getItem(buildStatutoryScopedSnapshotKey(userEmail, siteFromUrl, actCategories));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) return null;
    return parsed;
  } catch (_) {
    return null;
  }
}

function writeStatutoryScopedSnapshot(userEmail, siteFromUrl, actCategories, snapshot) {
  try {
    if (!snapshot || !Array.isArray(snapshot.data) || snapshot.data.length === 0) return;
    sessionStorage.setItem(
      buildStatutoryScopedSnapshotKey(userEmail, siteFromUrl, actCategories),
      JSON.stringify(snapshot)
    );
  } catch (_) {}
}

/** First paint: restore last scoped snapshot without waiting for Site Management API (smooth refresh / re-open). */
function readStatutoryScopedSnapshotBestEffort(userEmail, siteFromUrl) {
  if (typeof window === 'undefined' || typeof sessionStorage === 'undefined') return null;
  const email = normalizeEmail(userEmail) || 'unknown';
  const site = String(siteFromUrl || '').trim().toLowerCase();
  const keyPrefix = `${STATUTORY_SCOPED_SNAPSHOT_PREFIX}${email}|${site}|`;
  const anySitePrefix = `${STATUTORY_SCOPED_SNAPSHOT_PREFIX}${email}|`;
  let best = null;
  let bestTs = 0;
  try {
    for (let i = 0; i < sessionStorage.length; i += 1) {
      const key = sessionStorage.key(i);
      if (!key || !key.startsWith(anySitePrefix)) continue;
      if (site && !key.startsWith(keyPrefix)) continue;
      const parsed = JSON.parse(sessionStorage.getItem(key));
      if (!parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) continue;
      const ts = Number(parsed.savedAt) || 0;
      if (!best || ts >= bestTs) {
        best = parsed;
        bestTs = ts;
      }
    }
  } catch (_) {}
  return best;
}

/** Org-wide / last-visit cache — paint Act/Description as soon as Statutory opens. */
function readStatutoryLocalCacheBestEffort() {
  try {
    if (typeof localStorage === 'undefined') return null;
    const cached = localStorage.getItem('statutoryData');
    if (!cached) return null;
    const parsed = JSON.parse(cached);
    if (!Array.isArray(parsed) || parsed.length === 0) return null;
    return parsed;
  } catch (_) {
    return null;
  }
}

function deriveActCategoriesFromInchargeSites(inchargeSites) {
  if (!Array.isArray(inchargeSites) || inchargeSites.length === 0) return null;
  const cats = [...new Set(inchargeSites.map((s) => s.actCategory).filter(Boolean))];
  return cats.length > 0 ? cats : null;
}

/** Filter cached/API rows for first paint (site incharge) without waiting for checklist merge. */
function filterStatutoryRowsForImmediatePaint(rows, { actCategories, allowedSiteNames, allowedStates } = {}) {
  if (!Array.isArray(rows) || rows.length === 0) return [];
  let data = rows;
  if (Array.isArray(actCategories) && actCategories.length > 0) {
    const allow = new Set(actCategories);
    data = data.filter((item) => {
      const cat = getActCategoryFromActSector(item.act || item.Act, item.sector || item.Sector);
      return allow.has(cat) || cat === 'other';
    });
  }
  if (Array.isArray(allowedSiteNames) && allowedSiteNames.length > 0) {
    const allowedSites = new Set(
      allowedSiteNames.map((s) => String(s || '').trim().toLowerCase()).filter(Boolean)
    );
    data = data.filter((item) => {
      const explicit = String(item?.site ?? item?.Site ?? '')
        .trim()
        .toLowerCase();
      if (!explicit) return true;
      return [...allowedSites].some((a) => explicit === a || explicit.includes(a) || a.includes(explicit));
    });
  }
  if (Array.isArray(allowedStates) && allowedStates.length > 0) {
    data = data.filter((item) =>
      statesFieldMatchesInchargeSiteStates(item.state || item.State || '', allowedStates)
    );
  }
  return data;
}

/** Build Site column lookup maps from Site Management rows (sync cache paint + API refresh). */
function buildStatutorySiteMetaFromDetails(details, loginEmail = '', options = {}) {
  const { allSitesInCategoryBuckets = false } = options;
  if (!Array.isArray(details) || details.length === 0) {
    return {
      byCategory: {},
      allowedNames: null,
      inchargeStates: null,
      inchargeSites: [],
      organizationSites: [],
      siteDetails: []
    };
  }
  const loginResolved = normalizeEmail(loginEmail || '');
  const buckets = {
    factories: new Set(),
    shops_and_establishment: new Set(),
    clra: new Set()
  };
  const allowedNames = new Set();
  const inchargeStates = new Set();
  const inchargeSites = [];
  const organizationSites = [];
  details.forEach((s) => {
    const industry = String(s?.industry ?? s?.Industry ?? '').trim();
    const siteName = String(s?.siteName ?? s?.SiteName ?? '').trim();
    const st = String(s?.siteState ?? s?.SiteState ?? s?.state ?? s?.State ?? '').trim();
    if (siteName && st) {
      organizationSites.push({
        siteName,
        siteState: st,
        industry,
        actCategory: industryLabelToActCategory(industry)
      });
    }
    if (allSitesInCategoryBuckets && industry && siteName) {
      const orgCat = industryLabelToActCategory(industry);
      if (orgCat && buckets[orgCat]) buckets[orgCat].add(siteName);
    }
    const inchargeEmail = normalizeEmail(
      String(s?.inchargeEmail ?? s?.InchargeEmail ?? s?.incharge_email ?? '')
    );
    if (!inchargeEmail || (loginResolved && inchargeEmail !== loginResolved)) return;
    if (siteName) allowedNames.add(siteName);
    if (st) inchargeStates.add(st);
    if (siteName) {
      inchargeSites.push({
        siteName,
        siteState: st,
        industry,
        actCategory: industryLabelToActCategory(industry)
      });
    }
    if (!industry || !siteName) return;
    const cat = industryLabelToActCategory(industry);
    if (!cat || !buckets[cat]) return;
    buckets[cat].add(siteName);
  });
  return {
    byCategory: {
      factories: Array.from(buckets.factories),
      shops_and_establishment: Array.from(buckets.shops_and_establishment),
      clra: Array.from(buckets.clra)
    },
    allowedNames: allowedNames.size > 0 ? Array.from(allowedNames) : null,
    inchargeStates: inchargeStates.size > 0 ? Array.from(inchargeStates) : null,
    inchargeSites,
    organizationSites,
    siteDetails: details
  };
}

function statutoryRowMatchesStateFilter(item, selectedState) {
  if (!selectedState || selectedState === 'all') return true;
  const rowState = String(item?.state ?? item?.State ?? '').trim();
  if (!rowState) return false;
  return (
    checklistStateMatchesSiteState(rowState, selectedState) ||
    rowState.toLowerCase() === String(selectedState).trim().toLowerCase()
  );
}

function statutoryRowMatchesIndustryFilter(item, selectedIndustry, getActCategoryFn, allRows = []) {
  if (!selectedIndustry || selectedIndustry === 'all') return true;
  const selected = String(selectedIndustry).trim();
  const selectedLower = selected.toLowerCase();
  const sector = String(item?.sector ?? item?.Sector ?? '').trim();
  const act = String(item?.act ?? item?.Act ?? '').trim();
  if (sector) {
    const sectorLower = sector.toLowerCase();
    if (
      sectorLower === selectedLower ||
      sectorLower.includes(selectedLower) ||
      selectedLower.includes(sectorLower)
    ) {
      return true;
    }
  }
  const selectedCat = industryLabelToActCategory(selected);
  if (selectedCat) {
    const rowCat = typeof getActCategoryFn === 'function' ? getActCategoryFn(item, allRows) : null;
    if (rowCat === selectedCat) return true;
    if (getActCategoryFromActSector(act, sector) === selectedCat) return true;
  }
  if (act && act.toLowerCase().includes(selectedLower)) return true;
  return false;
}

/** After Autofill → Save, patch grid row locally so background table does not jump on full refresh. */
function patchStatutoryRowsAfterDraftSave(rows, patch) {
  if (!Array.isArray(rows) || rows.length === 0) return rows;
  const keeperId = String(patch?.keeperId ?? '').trim();
  const currentItem = patch?.currentItem;
  const saved = patch?.savedStatutory || {};
  const draftFile = saved.draftFile ?? saved.DraftFile ?? patch?.draftFile ?? null;
  const draftFileName =
    saved.draftFileName ?? saved.DraftFileName ?? patch?.draftFileName ?? null;
  const monthFilter = patch?.monthFilter ?? null;
  if (!keeperId && !draftFile && !currentItem) return rows;

  return rows.map((row) => {
    const rowId = String(row?.id ?? '').trim();
    const matchesKeeper = keeperId && rowId === keeperId;
    const matchesLine = currentItem && statutoryLineMetadataMatches(currentItem, row);
    if (!matchesKeeper && !matchesLine) return row;
    const nextId = /^\d+$/.test(keeperId) ? keeperId : row.id;
    return {
      ...row,
      id: nextId,
      draftFile: draftFile ?? row.draftFile ?? row.DraftFile,
      DraftFile: draftFile ?? row.draftFile ?? row.DraftFile,
      draftFileName: draftFileName ?? row.draftFileName ?? row.DraftFileName,
      DraftFileName: draftFileName ?? row.draftFileName ?? row.DraftFileName,
      draftStatutoryRowIdForFile: /^\d+$/.test(keeperId) ? keeperId : row.draftStatutoryRowIdForFile,
      monthFilter: monthFilter ?? row.monthFilter ?? row.MonthFilter,
      MonthFilter: monthFilter ?? row.monthFilter ?? row.MonthFilter,
      monthfilter: monthFilter ?? row.monthfilter ?? row.monthFilter
    };
  });
}
/** Formmaster templates API – form names in Statutory come from here (not ChecklistBulk/SEMaster) */
const FORMMASTER_TEMPLATES_API = '/server/formmaster_function/templates';

/** Form file modal: Zoho autofill + Excel table header row (single accent). */
const STAT_FORM_FILE_ACCENT_BG = '#3b82f6';
const STAT_FORM_FILE_ACCENT_BORDER = '#2563eb';
const STAT_FORM_FILE_ACCENT_BG_HOVER = '#2563eb';

/** Form U "format 2" – full column headers (Name of the employee, Employee Identification No., etc.) so downloaded draft shows full labels and template alignment is preserved */
const FORM_U_FORMAT2_HEADERS = [
  'S.No',
  'Name of the employee',
  'Employee Identification No.',
  'Gender',
  'Father / Spouse Name',
  'Date of Birth',
  'Date of Joining',
  'Designation',
  'Present Address',
  'Permanent Address',
  'Worker Identity No.',
  'Aadhaar',
  'Date on which joined',
  'Date on which left',
  'Period of service',
  'Bank A/c',
  'Photo'
];

/** Form U Rule 34 – confidential character (Sr. No. + Name of the person). */
const FORM_U_CONFIDENTIAL_HEADERS = ['Sr. No.', 'Name of the person'];

/** Tamil Nadu Form I (listed as "Form 1") — Register of Workmen under Conferment of Permanent Status Act. */
const FORM_I_TABLE_HEADERS = [
  'S No',
  'Emp ID',
  'Name and Address of the workman',
  'Designation of the workmen',
  'Whether Temporary, casual, Badli, or Apprentice (other than those covered under the Apprentices Act, 1961)',
  'Date of first entry into service',
  'Date on which he completed 480 days of service',
  'Date on which made permanent',
  'Remarks',
  'Signature of the workman with date (to attest the entries)'
];

/** Ensure Form I workmen register shows all statutory columns (older saves/templates may omit trailing fields). */
const normalizeFormIWorkmenTableHeaders = (headers) => {
  const canonical = [...FORM_I_TABLE_HEADERS];
  const trimmed = (headers || []).map((h) => String(h || '').trim()).filter(Boolean);
  if (trimmed.length === 0) return canonical;
  if (trimmed.length >= canonical.length) return trimmed;
  return [...trimmed, ...canonical.slice(trimmed.length)];
};

const padFormIWorkmenRowsForHeaders = (rows, headers) => {
  if (!Array.isArray(rows) || !Array.isArray(headers) || headers.length === 0) return rows;
  return rows.map((row) => {
    const next = row && typeof row === 'object' && !Array.isArray(row) ? { ...row } : {};
    headers.forEach((h) => {
      if (next[h] == null) next[h] = '';
    });
    return next;
  });
};

const rowHasTableSerialHeader = (rowTextLower) =>
  /\bs\.?\s*no\.?\b/.test(rowTextLower) ||
  /\bsr\.?\s*no\.?\b/.test(rowTextLower) ||
  /\bsl\.?\s*no\.?\b/.test(rowTextLower) ||
  rowTextLower.includes('serial number') ||
  rowTextLower.includes('serial no');

const normalizeExcelHeaderCell = (txt) =>
  String(txt || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

const excelCellLooksLikeSerialHeader = (rawText) => {
  const t = normalizeExcelHeaderCell(rawText);
  return !!(t && (rowHasTableSerialHeader(t) || t.includes('serial')));
};

/** CLRA forms (e.g. AP Form XXIII) split one column title across 2–4 stacked Excel rows. */
function combineStackedStatutoryTableHeaders({
  headerRowIndex,
  headers,
  jsonData,
  getMergedAwareCellText,
  effectiveSheetCols
}) {
  if (headerRowIndex < 0 || !Array.isArray(headers) || headers.length < 2) {
    return { headers, headerRowIndex, stackedHeaderBandEnd: headerRowIndex };
  }

  const normalizeHeaderFragment = (txt) =>
    String(txt || '')
      .replace(/\.{2,}/g, ' ')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

  // TN LWF Form C: single header row; body starts with "1. Total Realisations…" — do not fold into thead.
  {
    const list = headers.map((h) => String(h || '').toLowerCase());
    const hasQuarterCols = list.some((h) => /quarter\s+ending/.test(h));
    const hasFinesDetailsCol = list.some((h) =>
      /details\s+of\s+fines|unpaid\s+accumulations/.test(h)
    );
    const looksLikeEmployeeRegister =
      list.some((h) => /\bs\.?\s*no\b|serial\s+number/.test(h)) &&
      list.some((h) => /name\s+of\s+(the\s+)?employee/.test(h));
    if (hasQuarterCols && hasFinesDetailsCol && !looksLikeEmployeeRegister) {
      const cleaned = headers.map((h) => normalizeHeaderFragment(h));
      while (cleaned.length > 0 && !cleaned[cleaned.length - 1]) cleaned.pop();
      return {
        headers: cleaned.some((h) => h) ? cleaned : headers,
        headerRowIndex,
        stackedHeaderBandEnd: headerRowIndex
      };
    }
  }

  const rowIsColumnNumberIndexRow = (rowCells) => {
    let nums = 0;
    let total = 0;
    for (let c = 0; c < rowCells.length; c += 1) {
      const t = normalizeHeaderFragment(rowCells[c]);
      if (!t) continue;
      total += 1;
      if (/^\d+$/.test(t)) nums += 1;
    }
    return total >= 3 && nums / total >= 0.75;
  };

  const rowLooksLikeFixedAggregateBody = (rowCells) => {
    const nonEmpty = (rowCells || []).map((t) => normalizeHeaderFragment(t)).filter(Boolean);
    if (nonEmpty.length === 0) return false;
    return nonEmpty.some(
      (t) =>
        /^\d+\.\s*/.test(t) ||
        /^\([ivx]+\)/i.test(t) ||
        /total\s+realisations/i.test(t) ||
        /basic\s+wages/i.test(t) ||
        /see\s+definition\s+of/i.test(t) ||
        /_{2,}nil_{2,}/i.test(t) ||
        /^_{0,}nil_{0,}$/i.test(t)
    );
  };

  const readRowCells = (r) => {
    const maxCols = Math.max(headers.length, effectiveSheetCols, 12);
    const cells = [];
    for (let c = 0; c < maxCols; c += 1) {
      cells.push(normalizeHeaderFragment(getMergedAwareCellText(r, c)));
    }
    return cells;
  };

  const mainNonEmpty = headers.map((h) => normalizeHeaderFragment(h)).filter(Boolean).length;
  if (mainNonEmpty < 3) {
    return { headers, headerRowIndex, stackedHeaderBandEnd: headerRowIndex };
  }

  const hasSerialOnMain = excelCellLooksLikeSerialHeader(headers[0]);

  let bandEnd = headerRowIndex;
  for (let lookFwd = 1; lookFwd <= 4; lookFwd += 1) {
    const r = headerRowIndex + lookFwd;
    if (r >= jsonData.length) break;
    const rowCells = readRowCells(r);
    const nonEmpty = rowCells.filter(Boolean);
    if (nonEmpty.length === 0) break;
    if (rowIsColumnNumberIndexRow(rowCells.slice(0, headers.length))) break;
    if (rowLooksLikeFixedAggregateBody(rowCells)) break;

    const serialContinuation =
      hasSerialOnMain && /^(no\.?|number)$/i.test(nonEmpty[0] || '');
    const shortFragments =
      nonEmpty.length >= 2 &&
      nonEmpty.every((t) => t.length <= 48 && !/^[a-z]+\s+[a-z]+\s+[a-z]+\s+[a-z]+/i.test(t));
    const fillsGaps = rowCells.some((t, idx) => {
      if (!t || idx >= headers.length) return false;
      return !normalizeHeaderFragment(headers[idx]);
    });
    const extendsPartial = rowCells.some((t, idx) => {
      if (!t || idx >= headers.length) return false;
      const main = normalizeHeaderFragment(headers[idx]);
      if (!main || main.toLowerCase() === t.toLowerCase()) return false;
      if (/^\d+$/.test(t)) return false;
      return t.length <= 28;
    });

    if (serialContinuation || shortFragments || fillsGaps || extendsPartial) {
      bandEnd = r;
      continue;
    }
    break;
  }

  if (bandEnd === headerRowIndex) {
    return { headers, headerRowIndex, stackedHeaderBandEnd: headerRowIndex };
  }

  const combined = [];
  const maxCols = Math.max(headers.length, effectiveSheetCols);
  for (let c = 0; c < maxCols; c += 1) {
    const parts = [];
    for (let r = headerRowIndex; r <= bandEnd; r += 1) {
      const t = normalizeHeaderFragment(getMergedAwareCellText(r, c));
      if (!t || /^\d+$/.test(t)) continue;
      const lower = t.toLowerCase();
      if (parts.some((p) => p.toLowerCase() === lower)) continue;
      parts.push(t);
    }
    let joined = parts.join(' ').replace(/\s+/g, ' ').trim();
    if (/^sl\.?\s+no\.?$/i.test(joined)) joined = 'Sl. No.';
    combined.push(joined);
  }

  while (combined.length > 0 && !combined[combined.length - 1]) combined.pop();

  return {
    headers: combined.some((h) => h && !/^column\s+[a-z0-9]+$/i.test(h)) ? combined : headers,
    headerRowIndex,
    stackedHeaderBandEnd: bandEnd
  };
}

function isFormUAutofillContext(hints = {}) {
  const blob = [
    hints.fileName,
    hints.formFileName,
    hints.formName,
    hints.itemFormName,
    hints.formHeaderTitle,
    hints.sheetText
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return /\bform\s*u\b/i.test(blob) || /\bform[\s_-]*u\b/i.test(blob);
}

/** Form U – employee particulars register (many columns) vs Rule 34 confidential character (2 columns). */
function detectFormUSheetVariant(hints = {}) {
  if (
    isFormMGJGujaratContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    )
  ) {
    return 'unknown';
  }
  const blob = [
    hints.sheetText,
    hints.formHeaderTitle,
    hints.fileName,
    hints.formFileName
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  const hasEmployee =
    /name\s+of\s+the\s+employee/.test(blob) ||
    /employee\s+identification/.test(blob) ||
    /father\s*\/\s*spouse/.test(blob) ||
    /date\s+of\s+birth/.test(blob);
  const hasConfidential =
    /confidential\s+character/.test(blob) ||
    /occupying\s+position\s+of\s+confidential/.test(blob) ||
    (/see\s+rule\s*34/.test(blob) && /name\s+of\s+the\s+person/.test(blob));
  if (hasConfidential && !hasEmployee) return 'confidential_character';
  if (hasEmployee) return 'employee_register';
  if (/name\s+of\s+the\s+person/.test(blob) && !hasEmployee) return 'confidential_character';
  return 'unknown';
}

function inferFormUVariantFromRow(item) {
  if (
    isFormMGJGujaratContext(
      null,
      item,
      item?.formFileName || item?.FormFileName || '',
      '',
      null
    )
  ) {
    return null;
  }
  if (
    isFormIRegisterOfWorkmenContext(
      item,
      item?.formFileName || item?.FormFileName,
      null,
      null
    )
  ) {
    return null;
  }
  const blob = [
    item?.description,
    item?.Description,
    item?.act,
    item?.Act,
    item?.formName,
    item?.FormName,
    item?.formFileName,
    item?.FormFileName
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  if (/confidential|rule\s*34|confidential\s+character/.test(blob)) {
    return 'confidential_character';
  }
  if (/\bform\s*xxiii\b|\bform_xxiii\b|\bform-xxiii\b/i.test(blob)) {
    return null;
  }
  if (/appointment(?:\s*(?:ltr|letter|order))?|letter\s+of\s+appointment/i.test(blob)) {
    return null;
  }
  if (matchesFormXXVIHint(blob) && /andhra|appointment|letter\s+of\s+appointment/i.test(blob)) {
    return null;
  }
  if (matchesFormVIIHint(blob) && /notice\s+of\s+change|andhra/i.test(blob)) {
    return null;
  }
  if (matchesFormXHint(blob) && /register\s+of\s+fines|andhra/i.test(blob)) {
    return null;
  }
  if (
    /employee|particulars|register\s+of\s+employees|shops\s+and\s+establishment|wage\s+register/.test(
      blob
    )
  ) {
    return 'employee_register';
  }
  return null;
}

function isFormUEmployeeRegisterContext(hints = {}) {
  if (
    isFormMGJGujaratContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item || hints,
      hints.fileName || hints.formFileName || '',
      hints.sheetText || '',
      hints.tableHeaders
    )
  ) {
    return false;
  }
  if (
    isFormXXVIAPAppointmentLetterContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    )
  ) {
    return false;
  }
  if (
    isFormVIIAPNoticeOfChangeContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    ) &&
    !isFormXAPRegisterOfFinesContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    )
  ) {
    return false;
  }
  if (
    isFormXXIIIContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName
    ) ||
    isRegisterOfWagesFormContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.tableHeaders
    )
  ) {
    return false;
  }
  if (
    isFormIRegisterOfWorkmenContext(
      hints.item || hints,
      hints.fileName || hints.formFileName,
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.tableHeaders
    )
  ) {
    return false;
  }
  const variant = detectFormUSheetVariant(hints);
  if (variant === 'employee_register') return true;
  if (variant === 'confidential_character') return false;
  const rowVariant = inferFormUVariantFromRow(hints.item || hints);
  if (rowVariant === 'employee_register') return true;
  if (rowVariant === 'confidential_character') return false;
  const blob = [
    hints.sheetText,
    hints.formHeaderTitle,
    hints.fileName,
    hints.formFileName
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return (
    isFormUAutofillContext(hints) &&
    (/employee\s+identification/.test(blob) || /name\s+of\s+the\s+employee/.test(blob))
  );
}

function isFormUConfidentialCharacterContext(hints = {}) {
  const variant = detectFormUSheetVariant(hints);
  if (variant === 'confidential_character') return true;
  if (variant === 'employee_register') return false;
  const rowVariant = inferFormUVariantFromRow(hints.item || hints);
  if (rowVariant === 'confidential_character') return true;
  if (rowVariant === 'employee_register') return false;
  const blob = [
    hints.sheetText,
    hints.formHeaderTitle,
    hints.fileName,
    hints.formFileName
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return (
    isFormUAutofillContext(hints) &&
    (/name\s+of\s+the\s+person/.test(blob) ||
      /confidential\s+character/.test(blob) ||
      /occupying\s+position\s+of\s+confidential/.test(blob))
  );
}

function validateFormUTemplateForRow(item, sheetHints = {}) {
  const expected = inferFormUVariantFromRow(item);
  const actual = detectFormUSheetVariant(sheetHints);
  if (actual !== 'unknown' && isFormUAutofillContext(sheetHints)) return null;
  if (!expected || actual === 'unknown' || expected === actual) return null;
  const label = (v) =>
    v === 'employee_register'
      ? 'Employee particulars register (Name of the employee, Gender, etc.)'
      : 'Confidential character – Rule 34 (Name of the person)';
  return (
    `Wrong Excel template for this row. Expected Form U: ${label(expected)}. ` +
    `The linked file is Form U: ${label(actual)}. ` +
    `In Form Master, upload the correct template for this row's Act, Description, Sector, and State, ` +
    `then run Link Form Files on Checklist Bulk.`
  );
}

/** When parseExcelForm returns no headers, use canonical Form U columns for the detected variant. */
const mapFormXVRowsToCanonicalHeaders = (rows, priorHeaders, canonicalHeaders) => {
  const list = Array.isArray(rows) ? rows : [];
  const canon = Array.isArray(canonicalHeaders) && canonicalHeaders.length > 0
    ? canonicalHeaders
    : [...FORM_XV_TABLE_HEADERS];
  const prior = Array.isArray(priorHeaders) ? priorHeaders : [];
  const pickValue = (row, targetHeader, colIndex) => {
    if (!row || typeof row !== 'object') return '';
    if (Object.prototype.hasOwnProperty.call(row, targetHeader)) return row[targetHeader];
    const targetNorm = normalizeFormXVTableHeader(targetHeader);
    const key = Object.keys(row).find((k) => {
      const n = normalizeFormXVTableHeader(k);
      return n === targetNorm || n.includes(targetNorm) || targetNorm.includes(n);
    });
    if (key) return row[key];
    const priorKey = prior[colIndex];
    if (priorKey && Object.prototype.hasOwnProperty.call(row, priorKey)) return row[priorKey];
    return '';
  };
  return list.map((row, rowIndex) => {
    const out = {};
    canon.forEach((header, colIndex) => {
      let value = pickValue(row, header, colIndex);
      if ((value == null || String(value).trim() === '') && colIndex === 0) {
        value = rowIndex + 1;
      }
      out[header] = value != null ? value : '';
    });
    return out;
  });
};

/** Prefer modal/export headers; never pass a non-array into autofill (avoids `.map is not a function`). */
function resolveStatutoryAutofillHeadersFromModal(headersToUse, modalData, tableHeaders) {
  const pick = () => {
    if (Array.isArray(headersToUse) && headersToUse.length > 0) return headersToUse;
    if (Array.isArray(modalData?.parsedTableHeaders) && modalData.parsedTableHeaders.length > 0) {
      return modalData.parsedTableHeaders;
    }
    return Array.isArray(tableHeaders) ? tableHeaders : [];
  };
  const hdrs = pick();
  const fnBlob = [
    modalData?.fileName,
    modalData?.formFileName,
    modalData?.item?.formName,
    modalData?.item?.FormName,
    modalData?.parsedFormHeader?.title,
  ]
    .filter(Boolean)
    .join(' ');
  if (
    /form[\s._-]*xv[\s._-]*rj|\bxv[\s._-]*rj\b/i.test(fnBlob) ||
    isFormXVRJWageSlipContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || ''
    )
  ) {
    return resolveFormXVRJTableHeaders(hdrs);
  }
  if (
    /form[\s._-]*a[\s._-]*rj|\bform_a_rj\b/i.test(fnBlob) ||
    isFormARajasthanContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || '',
      hdrs
    )
  ) {
    return resolveFormARajasthanTableHeaders(hdrs);
  }
  if (
    /form[\s._-]*15[\s._-]*rj|\bform_15_rj\b|\b15_rj\b/i.test(fnBlob) ||
    isForm15RajasthanContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || '',
      hdrs
    )
  ) {
    return resolveForm15RajasthanTableHeaders(hdrs);
  }
  if (
    looksLikeForm14RajasthanFileName(fnBlob) ||
    isForm14RajasthanContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || '',
      hdrs
    )
  ) {
    // Keep template headers — do not force Form 11 leaf layout onto Form 14 RJ.
    return Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [];
  }
  if (
    looksLikeForm12RajasthanFileName(fnBlob) ||
    isForm12RajasthanContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || '',
      hdrs
    )
  ) {
    return resolveForm12RajasthanTableHeaders(hdrs);
  }
  if (
    /form[\s._-]*11[\s._-]*rj|\bform_11_rj\b|\b11_rj\b/i.test(fnBlob) ||
    isForm11RajasthanContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || '',
      hdrs
    )
  ) {
    return resolveForm11RajasthanTableHeaders(hdrs);
  }
  if (
    /form[\s._-]*xix[\s._-]*rj|\bxix_rj\b/i.test(fnBlob) ||
    isFormXIXRajasthanOvertimeRegisterContext(
      modalData?.parsedFormHeader,
      modalData?.item,
      fnBlob,
      modalData?.sheetText || ''
    )
  ) {
    return resolveFormXIXRJTableHeaders(hdrs);
  }
  const formUHints = {
    item: modalData?.item,
    fileName: modalData?.fileName || modalData?.formFileName || '',
    formFileName: modalData?.formFileName || modalData?.fileName || '',
    formHeaderTitle: modalData?.parsedFormHeader?.title,
    formHeaderSubtitle: modalData?.parsedFormHeader?.subtitle,
    sheetText: modalData?.sheetText || '',
    tableHeaders: hdrs
  };
  if (
    isFormUEmployeeRegisterContext(formUHints) ||
    (/form[_\s-]*u/i.test(fnBlob) && !/form[_\s-]*u[_\s-]*(rajasthan|gujarat|gj)/i.test(fnBlob))
  ) {
    return normalizeFormUEmployeeRegisterHeaders(hdrs, formUHints);
  }
  return hdrs;
}

function resolveAutofillTableHeaders(currentHeaders, hints = {}) {
  const raw = Array.isArray(currentHeaders) ? currentHeaders : [];
  if (
    isFormXXVIAPAppointmentLetterContext(
      hints.formHeader || { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    ) ||
    isFormXXVIAPTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormXXVIAPTableHeaders(raw);
  }
  if (
    isFormVIIAPNoticeOfChangeContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    ) &&
    !isFormXAPRegisterOfFinesContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    )
  ) {
    return [];
  }
  if (
    isFormXIXAPTableWageSlipContext(
      hints.formHeader || { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    ) ||
    isFormXIXAPTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormXIXAPWageTableHeaders(raw);
  }
  if (
    isFormXIXAPHeaderFieldLayoutFormHeader(hints.formHeader) &&
    !isFormXIXMPTableLayoutFormHeader(hints.formHeader) &&
    !isFormXIXKarnatakaTableLayoutFormHeader(hints.formHeader) &&
    !isFormXIXAPTableLayoutFormHeader(hints.formHeader)
  ) {
    return [];
  }
  if (
    isFormXVContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName
    )
  ) {
    return [...FORM_XV_TABLE_HEADERS];
  }
  if (
    isFormXIXKarnatakaWageSlipContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    ) ||
    isFormXIXKarnatakaTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormXIXKarnatakaWageTableHeaders(raw);
  }
  if (
    isFormXIXTamilNaduWageSlipContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    ) ||
    isFormXIXTamilNaduTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormXIXTamilNaduTableHeaders(raw);
  }
  if (
    isFormXIXMPWageSlipContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    )
  ) {
    return [...FORM_XIX_MP_WAGE_TABLE_HEADERS];
  }
  if (
    isFormXIVMPEmploymentCardContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    )
  ) {
    return resolveFormXIVMPTableHeaders([], {
      formHeader: { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      item: hints.item,
      fileName: hints.fileName || hints.formFileName,
      sheetText: hints.sheetText || '',
    });
  }
  if (
    isFormQKarnatakaContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    ) ||
    isFormQKarnatakaTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormQKarnatakaTableHeaders(raw);
  }
  if (
    isFormPGJGujaratTableLayoutFormHeader(hints.formHeader) ||
    isFormPGJGujaratContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || '',
      raw
    )
  ) {
    return resolveFormPGJGujaratTableHeaders(raw);
  }
  if (
    isFormFLeaveWithWagesContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || ''
    ) ||
    isFormFKarnatakaTableLayoutFormHeader(hints.formHeader)
  ) {
    return resolveFormFKarnatakaTableHeaders(raw);
  }
  if (isFormIIMaharashtraContext(
    { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
    hints.item,
    hints.fileName || hints.formFileName,
    raw
  )) {
    return normalizeFormIIMaharashtraTableHeaders(raw);
  }
  const wageRegisterCtx =
    isRegisterOfWagesFormContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      raw
    ) ||
    isFormXXVIIContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName
    );
  if (wageRegisterCtx && raw.length > 0) {
    return raw.map((h, i) => {
      const t = String(h || '').trim();
      return t || `Column ${i + 1}`;
    });
  }
  const trimmed = raw
    .map((h) => String(h || '').trim())
    .filter(Boolean);
  if (isFormUConfidentialCharacterContext(hints)) {
    return normalizeFormUConfidentialHeaders(trimmed, hints);
  }
  const formIWorkmenCtx = isFormIRegisterOfWorkmenContext(
    hints.item,
    hints.fileName || hints.formFileName,
    { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
    trimmed.length > 0 ? trimmed : raw,
    hints.sheetText
  );
  if (formIWorkmenCtx) {
    if (trimmed.length > 0 && !headersIndicateFormUEmployeeRegister(trimmed)) {
      return normalizeFormIWorkmenTableHeaders(trimmed);
    }
    return [...FORM_I_TABLE_HEADERS];
  }
  const formAMusterCtx = isFormAMusterRollRowContext(
    { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle, reference: hints.formHeaderReference },
    hints.item,
    hints.fileName || hints.formFileName,
    hints.sheetText
  );
  if (formAMusterCtx) {
    if (trimmed.length > 0 && headersIndicateFormAMusterRoll(trimmed) && !headersLookLikePivotOrWrongFormATable(trimmed)) {
      return trimmed;
    }
    if (headersLookLikePivotOrWrongFormATable(trimmed)) {
      const workbookHeaders = hints?.formAWorkbookHeaders;
      if (Array.isArray(workbookHeaders) && workbookHeaders.length >= 3 && !headersLookLikePivotOrWrongFormATable(workbookHeaders)) {
        return workbookHeaders;
      }
      return [];
    }
    return trimmed.filter((h) => String(h || '').trim());
  }
  if (trimmed.length > 0) return trimmed;
  if (
    isFormXXIIIContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName
    ) ||
    isRegisterOfWagesFormContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      raw
    )
  ) {
    return raw;
  }
  if (
    isFormMGJGujaratContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || '',
      raw
    )
  ) {
    return [];
  }
  if (
    (isFormUTamilNaduEmployeeRegisterContext(hints) ||
      headersIndicateFormUTamilNaduRegister(trimmed)) &&
    FORM_U_TAMILNADU_HEADERS.length > 0
  ) {
    return normalizeFormUTamilNaduEmployeeRegisterHeaders(trimmed, hints);
  }
  if (isFormUEmployeeRegisterContext(hints) && FORM_U_FORMAT2_HEADERS.length > 0) {
    return [...FORM_U_FORMAT2_HEADERS];
  }
  if (
    isForm27CStatutoryContext(
      hints.item,
      hints.fileName || hints.formFileName,
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      raw,
      hints.sheetText
    )
  ) {
    if (trimmed.length > 0 && headersIndicateForm27CTable(trimmed)) {
      return normalizeForm27CTableHeaders(trimmed);
    }
    return [...FORM_27C_CANONICAL_HEADERS];
  }
  if (
    isForm17BStatutoryContext(
      hints.item,
      hints.fileName || hints.formFileName,
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      raw,
      hints.sheetText
    )
  ) {
    if (trimmed.length > 0 && headersIndicateForm17BTable(trimmed)) {
      return normalizeForm17BTableHeaders(trimmed);
    }
    return [...FORM_17B_CANONICAL_HEADERS];
  }
  if (
    isForm14ChildWorkersContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle, reference: hints.formHeaderReference },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText
    ) ||
    headersIndicateForm14Table(trimmed.length > 0 ? trimmed : raw)
  ) {
    if (trimmed.length > 0 && headersIndicateForm14Table(trimmed)) {
      return normalizeForm14APTableHeaders(trimmed);
    }
    return [...FORM_14_AP_CANONICAL_HEADERS];
  }
  if (
    isForm11PeriodOfWorkContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle, reference: hints.formHeaderReference },
      hints.item,
      hints.fileName || hints.formFileName,
      trimmed.length > 0 ? trimmed : raw,
      hints.sheetText
    )
  ) {
    if (trimmed.length > 0 && headersIndicateForm11PeriodOfWork(trimmed)) {
      return normalizeForm11PeriodOfWorkTableHeaders(trimmed);
    }
    return buildForm11APCanonicalHeaders();
  }
  if (
    isFormARajasthanContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || '',
      trimmed.length > 0 ? trimmed : raw
    )
  ) {
    return resolveFormARajasthanTableHeaders(trimmed.length > 0 ? trimmed : raw);
  }
  if (
    isForm15RajasthanContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || '',
      trimmed.length > 0 ? trimmed : raw
    ) ||
    /form[\s._-]*15[\s._-]*rj|\bform_15_rj\b|\b15_rj\b/i.test(
      `${hints.fileName || ''} ${hints.formFileName || ''}`
    )
  ) {
    return resolveForm15RajasthanTableHeaders(trimmed.length > 0 ? trimmed : raw);
  }
  if (
    isForm12RajasthanContext(
      { title: hints.formHeaderTitle, subtitle: hints.formHeaderSubtitle },
      hints.item,
      hints.fileName || hints.formFileName,
      hints.sheetText || '',
      trimmed.length > 0 ? trimmed : raw
    ) ||
    looksLikeForm12RajasthanFileName(`${hints.fileName || ''} ${hints.formFileName || ''}`)
  ) {
    return resolveForm12RajasthanTableHeaders(trimmed.length > 0 ? trimmed : raw);
  }
  return trimmed;
}

/** Form Q (Excel model): worker columns + Working hours / Interval for Rest / Date of the Month (1–31) + wage summary. */
const FORM_Q_WAGE_TAIL_HEADERS = [
  'Total Days worked',
  'Minimum rate of wages payable Rs.',
  'Total production in case of piece rate Rs.',
  'Actual Wages Paid Rs',
  'House Rent Allowance Paid Rs.',
  'Dearness Allowance Paid Rs.',
  'Gross Amount Payable Rs.',
  'Total hours of overtime worked during the month',
  'Overtime earnings Rs.',
  'Provident Fund Rs.',
  'Family Pension Rs.',
  'ESI Contribution Rs.',
  'Professional Tax Rs.',
  'Income Tax Rs.',
  'Loan & Interest Rs.',
  'Advances Rs.',
  'Other Deductions Rs.',
  'Total Deduction Rs.',
  'Net Payable Rs.',
  'Date of Payment',
  'Signature/Thumb Impression',
];

const formQWageHeaderNorm = (h) =>
  String(h || '')
    .replace(/^\(?\d+\)?\s*[\.\)]?\s*/i, '')
    .replace(/\r?\n/g, ' ')
    .replace(/[^a-z0-9 ]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

const isFormQWageTailHeader = (header) => {
  const n = formQWageHeaderNorm(header);
  if (!n) return false;
  if (FORM_Q_WAGE_TAIL_HEADERS.some((h) => formQWageHeaderNorm(h) === n)) return true;
  return (
    /total\s+days?\s+worked/.test(n) ||
    /minimum\s+rate\s+of\s+wages/.test(n) ||
    /total\s+production/.test(n) ||
    /actual\s+wages\s+paid/.test(n) ||
    /house\s+rent\s+allowance/.test(n) ||
    /dearness\s+allowance/.test(n) ||
    /gross\s+amount\s+payable/.test(n) ||
    (/overtime/.test(n) && (/hour|earning/.test(n))) ||
    /provident\s+fund/.test(n) ||
    /family\s+pension/.test(n) ||
    /esi\s+contribution/.test(n) ||
    /professional\s+tax/.test(n) ||
    /income\s+tax/.test(n) ||
    /loan.*interest/.test(n) ||
    /^advances$/.test(n) ||
    /other\s+deductions?/.test(n) ||
    /total\s+deductions?/.test(n) ||
    /net\s+payable/.test(n) ||
    /date\s+of\s+payment/.test(n) ||
    /signature|thumb\s+impression/.test(n)
  );
};

const buildFormQCanonicalHeaders = (daysInMonth = 31) => {
  const headers = [
    'Sr. No.',
    'Full Name of the worker',
    'Designation of the worker and nature of work',
    'Age',
    'Sex',
    'Date of entry into service',
    'Working hours_From',
    'Working hours_To',
    'Interval for Rest_From',
    'Interval for Rest_To'
  ];
  const days = Math.min(Math.max(Number(daysInMonth) || 31, 28), 31);
  for (let d = 1; d <= days; d += 1) {
    headers.push(`Date of the Month_${d}`);
  }
  FORM_Q_WAGE_TAIL_HEADERS.forEach((h) => headers.push(h));
  return headers;
};

const buildFormQSubColumnsFromHeaders = (headers) => {
  const subs = {};
  (headers || []).forEach((h) => {
    const m = String(h || '').match(/^(.+)_([\s\S]+)$/);
    if (!m) return;
    const parent = m[1].trim();
    const sub = m[2].trim();
    if (!subs[parent]) subs[parent] = [];
    if (!subs[parent].includes(sub)) subs[parent].push(sub);
  });
  return subs;
};

/** Ensure wage-summary columns after day 1–31 are always present in the modal grid. */
const resolveFormQDisplayHeaders = (headers, daysInMonth = 31) => {
  const canonical = stripAndNormalizeFormQTableHeaders(buildFormQCanonicalHeaders(daysInMonth));
  const current = stripAndNormalizeFormQTableHeaders(headers || []);
  if (current.length >= canonical.length) return current;
  const seen = new Set(current.map((h) => String(h || '').toLowerCase()));
  const out = [...current];
  canonical.forEach((h) => {
    const key = String(h || '').toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      out.push(h);
    }
  });
  return out;
};

