function isForm12StatutoryContext(item, fileName, formHeader) {
  const blob = [
    item?.formName,
    item?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle
  ]
    .map((s) => String(s || ''))
    .join(' ');
  return (
    /register\s+of\s+advances\s+of\s+wages/i.test(blob) ||
    /\bform\s*[-"']?\s*(12|xii)\b/i.test(blob)
  );
}

/** Form No. 17-B — exact template column titles (sheet "17-B"). */
const FORM_17B_CANONICAL_HEADERS = [
  'Sr. No.',
  'Department',
  'Name of the worker',
  'Age at last birthday',
  'Date of employment in present work',
  'Date of leaving or transfer with reasons for discharge or transfer',
  'Nature of Job or Occupation',
  'Raw Material or by products handled',
  'Date of weekly examination with results',
  'Nature of symptoms',
  'Signature of Medical Practioner'
];

function form17BHeaderNorm(txt) {
  return String(txt || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function form17BHeaderAliasBucket(norm) {
  if (!norm) return '';
  if (/^s\.?\s*no|serial|sl\.?\s*no|^no\.?$/.test(norm)) return 'sno';
  if (/department/.test(norm)) return 'department';
  if (/name/.test(norm) && (/worker/.test(norm) || /^name\s+of/.test(norm))) return 'name';
  if (/age/.test(norm) && !/wage/.test(norm)) return 'age';
  if (
    /date/.test(norm) &&
    (/employment/.test(norm) || /present\s*work/.test(norm) || /entry/.test(norm) || /\ben\b/.test(norm))
  ) {
    return 'employment';
  }
  if (/date/.test(norm) && (/leav/.test(norm) || /transfer/.test(norm) || /discharge/.test(norm))) {
    return 'leaving';
  }
  if (/nature/.test(norm) && (/job/.test(norm) || /occupation/.test(norm))) return 'job';
  if (/raw\s*mat/.test(norm) || /by\s*product/.test(norm)) return 'raw';
  if (/date/.test(norm) && (/examin/.test(norm) || /weekly/.test(norm))) return 'examination';
  if (/nature/.test(norm) && /symptom/.test(norm)) return 'symptoms';
  if (/signature/.test(norm) && /medical/.test(norm)) return 'signature';
  return norm;
}

function normalizeForm17BTableHeaders(parsedHeaders) {
  const src = Array.isArray(parsedHeaders) ? parsedHeaders : [];
  const out = [...FORM_17B_CANONICAL_HEADERS];
  src.forEach((h, i) => {
    if (i < out.length && String(h || '').trim()) out[i] = String(h).trim();
  });
  return out;
}

function remapForm17BRowsToHeaders(rows, sourceHeaders, targetHeaders) {
  const src = Array.isArray(sourceHeaders) ? sourceHeaders : [];
  const tgt = normalizeForm17BTableHeaders(targetHeaders);
  if (!Array.isArray(rows)) return [];
  return rows.map((row, rowIndex) => {
    if (!row || typeof row !== 'object') return {};
    const out = {};
    tgt.forEach((targetHeader, colIdx) => {
      let val = '';
      if (Object.prototype.hasOwnProperty.call(row, targetHeader)) {
        val = row[targetHeader];
      } else if (src[colIdx] && Object.prototype.hasOwnProperty.call(row, src[colIdx])) {
        val = row[src[colIdx]];
      } else {
        const bucket = form17BHeaderAliasBucket(form17BHeaderNorm(targetHeader));
        for (const [k, v] of Object.entries(row)) {
          if (form17BHeaderAliasBucket(form17BHeaderNorm(k)) === bucket) {
            val = v;
            break;
          }
        }
      }
      if (
        (val == null || val === '') &&
        form17BHeaderAliasBucket(form17BHeaderNorm(targetHeader)) === 'sno'
      ) {
        val = rowIndex + 1;
      }
      out[targetHeader] = val == null ? '' : val;
    });
    return out;
  });
}

function headersIndicateForm17BTable(tableHeaders) {
  if (!Array.isArray(tableHeaders) || tableHeaders.length < 4) return false;
  const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join(' ');
  return (
    /department/.test(joined) &&
    /name/.test(joined) &&
    (/worker/.test(joined) || /name\s+of/.test(joined)) &&
    /age/.test(joined) &&
    (/raw\s*mat/.test(joined) ||
      /medical\s*prac/.test(joined) ||
      /weekly\s*examin/.test(joined) ||
      /symptom/.test(joined))
  );
}

function isForm17BStatutoryContext(item, fileName, formHeader, tableHeaders, sheetText = '') {
  if (isForm27CStatutoryContext(item, fileName, formHeader, tableHeaders, sheetText)) return false;
  const blob = [
    item?.formName,
    item?.FormName,
    item?.description,
    item?.Description,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    sheetText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  if (/\bform[\s._-]*no\.?\s*17[\s._-]*b\b/.test(blob)) return true;
  if (/\bform[\s._-]*17[\s._-]*b\b/.test(blob)) return true;
  if (/\b17[\s._-]*b\b/.test(blob) && /\bform\b/.test(blob)) return true;
  return headersIndicateForm17BTable(tableHeaders);
}

const FORM_17B_DISPLAY_TITLE = 'Form 17 B';
const FORM_27C_DISPLAY_TITLE = 'Form 27-C – Health Register';
const FORM_11_POW_DISPLAY_TITLE = 'FORM NO. 11';
const FORM_11_POW_DISPLAY_SUBTITLE =
  '(Prescribed under Rule 79) Notice of period of work for adult and children';

const STATUTORY_ESTABLISHMENT_HIDDEN_HEADER_KEYS = new Set([
  'statutory_establishment_name',
  'statutory_establishment_name_shop',
  'statutory_establishment_address',
  'statutory_principal_employer'
]);

function isStatutoryEstablishmentHiddenHeaderField(field) {
  const key = String(field?.key || '').trim();
  if (STATUTORY_ESTABLISHMENT_HIDDEN_HEADER_KEYS.has(key)) return true;
  const label = String(field?.label || '');
  return (
    isEstablishmentNameHeaderLabel(label) ||
    isEstablishmentAddressHeaderLabel(label) ||
    isPrincipalEmployerHeaderLabel(label)
  );
}

function filterStatutoryEstablishmentHeaderFields(fields) {
  return (Array.isArray(fields) ? fields : []).filter((field) => !isStatutoryEstablishmentHiddenHeaderField(field));
}

function stripStatutoryEstablishmentHeaderFormDataKeys(headerData) {
  if (!headerData || typeof headerData !== 'object') return headerData;
  const out = { ...headerData };
  let changed = false;
  STATUTORY_ESTABLISHMENT_HIDDEN_HEADER_KEYS.forEach((key) => {
    if (Object.prototype.hasOwnProperty.call(out, key)) {
      delete out[key];
      changed = true;
    }
  });
  return changed ? out : headerData;
}

function shouldHideStatutoryEstablishmentHeaderInAutofill(
  formHeader,
  field,
  fileName = '',
  tableHeaders = [],
  sheetText = ''
) {
  const form27 =
    isForm27CStatutoryContext(null, fileName, formHeader, tableHeaders, sheetText) ||
    matchesForm27CHint(`${fileName} ${formHeader?.title || ''}`);
  const form11 = isForm11PeriodOfWorkContext(formHeader, null, fileName, tableHeaders, sheetText);
  const form6 =
    isForm6APHumidityRegisterContext(formHeader, null, fileName, sheetText) ||
    headersIndicateForm6APHumidityTable(tableHeaders);
  const form25APMuster = isForm25APMusterRollContext(
    formHeader,
    null,
    fileName,
    tableHeaders,
    sheetText
  );
  if (!form27 && !form11 && !form6 && !form25APMuster) return false;
  return isStatutoryEstablishmentHiddenHeaderField(field);
}

function enrichForm25APMusterDisplayHeader(formHeader, fileName = '', item = null, tableHeaders = [], sheetText = '') {
  if (!isForm25APMusterRollContext(formHeader, item, fileName, tableHeaders, sheetText)) {
    return formHeader;
  }
  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  let fields = filterStatutoryEstablishmentHeaderFields(base.fields || []);
  const hasKey = (k) => fields.some((f) => f.key === k);
  FORM_25_AP_FACTORY_HEADER_SPECS.forEach((spec) => {
    if (!hasKey(spec.key)) {
      fields.push({ label: spec.label, value: '', key: spec.key });
    }
  });
  const ordered = [];
  FORM_25_AP_FACTORY_HEADER_SPECS.forEach((spec) => {
    const match = fields.find((f) => f.key === spec.key);
    if (match) ordered.push(match);
  });
  fields.forEach((f) => {
    if (!ordered.some((o) => o.key === f.key)) ordered.push(f);
  });
  base.fields = ordered;
  base.form25APMusterLayout = true;
  return base;
}

function enrichForm6APDisplayHeader(formHeader, fileName = '', item = null, tableHeaders = [], sheetText = '') {
  if (
    !isForm6APHumidityRegisterContext(formHeader, item, fileName, sheetText) &&
    !headersIndicateForm6APHumidityTable(tableHeaders)
  ) {
    return formHeader;
  }
  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  base.title = 'FORM NO. 6';
  base.subtitle = '[Prescribed under Rule 22]';
  if (!/humidity/i.test(String(base.reference || ''))) {
    base.reference = 'Humidity register';
  }
  base.form6APHumidityLayout = true;
  base.fields = ensureForm6APHeaderFields(
    filterStatutoryEstablishmentHeaderFields(base.fields || [])
  );
  return base;
}

function enrichForm11POWDisplayHeader(formHeader, fileName = '', item = null, tableHeaders = [], sheetText = '') {
  if (!isForm11PeriodOfWorkContext(formHeader, item, fileName, tableHeaders, sheetText)) {
    return formHeader;
  }
  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  if (!/^form\s*no\.?\s*11\b/i.test(String(base.title || '').trim())) {
    base.title = FORM_11_POW_DISPLAY_TITLE;
  }
  if (!/notice\s+of\s+period\s+of\s+work|rule\s*79/i.test(String(base.subtitle || ''))) {
    base.subtitle = FORM_11_POW_DISPLAY_SUBTITLE;
  }
  if (Array.isArray(base.fields)) {
    base.fields = filterStatutoryEstablishmentHeaderFields(base.fields);
  }
  return base;
}

function enrichForm27CDisplayHeader(formHeader, fileName = '', item = null, tableHeaders = [], sheetText = '') {
  if (
    !isForm27CStatutoryContext(item, fileName, formHeader, tableHeaders, sheetText) &&
    !matchesForm27CHint(`${fileName} ${formHeader?.title || ''}`)
  ) {
    return formHeader;
  }
  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  base.title = FORM_27C_DISPLAY_TITLE;
  if (!/health\s+register/i.test(String(base.subtitle || ''))) {
    base.subtitle = 'Health Register';
  }
  if (Array.isArray(base.fields)) {
    base.fields = filterStatutoryEstablishmentHeaderFields(base.fields);
  }
  return base;
}

function enrichForm17BDisplayHeader(formHeader, fileName = '', item = null, tableHeaders = [], sheetText = '') {
  if (
    !isForm17BStatutoryContext(item, fileName, formHeader, tableHeaders, sheetText) &&
    !/\bform[\s._-]*17[\s._-]*b\b/i.test(`${fileName} ${formHeader?.title || ''}`)
  ) {
    return formHeader;
  }
  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  base.title = FORM_17B_DISPLAY_TITLE;
  return base;
}

function isForm17BSkipAutofillHeader(h) {
  const s = normalizeLooseHeaderText(h);
  if (!s) return false;
  if (/raw\s*mat/.test(s) || /by\s*product/.test(s)) return true;
  if (/weekly\s*examin/.test(s)) return true;
  if (/nature/.test(s) && /symptom/.test(s)) return true;
  if (/medical\s*prac/.test(s) || (/signature/.test(s) && /medical/.test(s))) return true;
  return false;
}

/** Form No. 27-C (AP) — Health Register; must not collide with Form XXVII (27) quarterly returns. */
function matchesForm27CHint(blob) {
  const parts = String(blob || '').toLowerCase();
  return (
    /\bform[\s._-]*no\.?\s*27[\s._-]*c\b/.test(parts) ||
    /\bform[\s._-]*27[\s._-]*c\b/.test(parts) ||
    (/\b27[\s._-]*c\b/.test(parts) && (/health\s+register/.test(parts) || /\bform\b/.test(parts)))
  );
}

/** Form No. 27-C (AP) — Health Register (Schedule XXI / Rule 95). */
const FORM_27C_CANONICAL_HEADERS = [
  'Serial Number',
  'Department / Works',
  'Name of Worker',
  'Sex',
  'Age (last birthday)',
  'Date of employment on present work',
  'Date of leaving or transfer to other work with reasons for discharge or transfer',
  'Nature of Job / Occupation',
  'Raw materials, products or by products likely to be exposed to',
  'Date',
  'Result Fit / Unfit',
  'Signs and symptoms observed during examination',
  'Nature of tests and results thereof',
  'If declared unfit for work, state period of suspension with reasons in detail',
  'Whether certificate of unfitness issued to the worker',
  'Date on which certified fit to resume duty',
  'Signature of the Certifying surgeon with date'
];

function form27CHeaderNorm(txt) {
  return form17BHeaderNorm(txt);
}

function form27CHeaderAliasBucket(norm) {
  if (!norm) return '';
  if (/^sex$|\bgender\b/.test(norm)) return 'sex';
  const b17 = form17BHeaderAliasBucket(norm);
  if (b17 !== norm) return b17;
  if (/department/.test(norm) && /works?/.test(norm)) return 'department';
  if (/medical\s+examin/.test(norm)) return 'manual';
  if (/fit\s*\/\s*unfit|result\s+fit/.test(norm)) return 'manual';
  if (/certifying\s+surgeon/.test(norm)) return 'manual';
  if (/nature/.test(norm) && /test/.test(norm)) return 'manual';
  if (/unfit/.test(norm) && (/certificate|suspension/.test(norm))) return 'manual';
  if (/certified\s+fit/.test(norm) && /resume/.test(norm)) return 'manual';
  return norm;
}

function normalizeForm27CTableHeaders(parsedHeaders) {
  const src = Array.isArray(parsedHeaders) ? parsedHeaders.filter((h) => String(h || '').trim()) : [];
  if (src.length >= 8 && headersIndicateForm27CTable(src)) {
    return src.map((h) => String(h || '').trim());
  }
  const out = [...FORM_27C_CANONICAL_HEADERS];
  src.forEach((h, i) => {
    if (i < out.length && String(h || '').trim()) out[i] = String(h).trim();
  });
  return out;
}

function remapForm27CRowsToHeaders(rows, sourceHeaders, targetHeaders) {
  const src = Array.isArray(sourceHeaders) ? sourceHeaders : [];
  const tgt = normalizeForm27CTableHeaders(targetHeaders);
  if (!Array.isArray(rows)) return [];
  return rows.map((row, rowIndex) => {
    if (!row || typeof row !== 'object') return {};
    const out = {};
    tgt.forEach((targetHeader, colIdx) => {
      let val = '';
      if (Object.prototype.hasOwnProperty.call(row, targetHeader)) {
        val = row[targetHeader];
      } else if (src[colIdx] && Object.prototype.hasOwnProperty.call(row, src[colIdx])) {
        val = row[src[colIdx]];
      } else {
        const bucket = form27CHeaderAliasBucket(form27CHeaderNorm(targetHeader));
        for (const [k, v] of Object.entries(row)) {
          if (form27CHeaderAliasBucket(form27CHeaderNorm(k)) === bucket) {
            val = v;
            break;
          }
        }
      }
      if (
        (val == null || val === '') &&
        form27CHeaderAliasBucket(form27CHeaderNorm(targetHeader)) === 'sno'
      ) {
        val = rowIndex + 1;
      }
      out[targetHeader] = val == null ? '' : val;
    });
    return out;
  });
}

function headersIndicateForm27CTable(tableHeaders) {
  if (!Array.isArray(tableHeaders) || tableHeaders.length < 6) return false;
  const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join(' ');
  return (
    /department/.test(joined) &&
    /name/.test(joined) &&
    /worker/.test(joined) &&
    /\bsex\b/.test(joined) &&
    /age/.test(joined) &&
    (/health\s+register/.test(joined) ||
      /medical\s+examin/.test(joined) ||
      /certifying\s+surgeon/.test(joined) ||
      /fit\s*\/\s*unfit/.test(joined) ||
      (/raw\s*mat|by\s*product/.test(joined) && /symptom/.test(joined)))
  );
}

function isForm27CStatutoryContext(item, fileName, formHeader, tableHeaders, sheetText = '') {
  const blob = [
    item?.formName,
    item?.FormName,
    item?.description,
    item?.Description,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    sheetText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  if (matchesForm27CHint(blob)) return true;
  return headersIndicateForm27CTable(tableHeaders);
}

function isForm27CWorkerNameHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return /name/.test(s) && /worker/.test(s);
}

function isForm27CSkipAutofillHeader(h) {
  const s = normalizeLooseHeaderText(h);
  if (!s) return false;
  if (isForm17BSkipAutofillHeader(h)) return true;
  if (/raw\s*mat|by\s*product/.test(s) && (/exposed|likely/.test(s) || /product/.test(s))) return true;
  if (/medical\s+examin/.test(s)) return true;
  if (/fit\s*\/\s*unfit|result\s+fit/.test(s)) return true;
  if (/certifying\s+surgeon/.test(s)) return true;
  if (/unfit/.test(s) && (/certificate|suspension|period/.test(s))) return true;
  if (/certified\s+fit/.test(s) && /resume/.test(s)) return true;
  if (/nature/.test(s) && /test/.test(s)) return true;
  if (/sign/.test(s) && /symptom/.test(s)) return true;
  return false;
}

function getForm27CEmployeeFullName(emp) {
  const fn = String(emp?.FirstName || emp?.['FirstName'] || emp?.firstName || emp?.['First Name'] || '').trim();
  const ln = String(emp?.LastName || emp?.['LastName'] || emp?.lastName || emp?.['Last Name'] || '').trim();
  if (fn && ln) return `${fn} ${ln}`;
  return fn || ln || '';
}

function statutoryDetectionBlob(...parts) {
  return parts
    .filter((x) => x != null && String(x).trim() !== '')
    .join(' ')
    .toLowerCase();
}

/** True when filename / row metadata explicitly targets a numbered form (e.g. Form_14). */
function statutoryFilenameRequestsFormNumber(...args) {
  const nums = args.filter((x) => typeof x === 'number');
  const text = statutoryDetectionBlob(...args.filter((x) => typeof x !== 'number'));
  if (!text || nums.length === 0) return false;
  return nums.some((n) => {
    const num = String(n);
    if (num === '14' && /form[\s._-]*14(?:[\s._\W-]|$)/.test(text)) return true;
    if (num === '11' && /form[\s._-]*11(?:[\s._\W-]|$)/.test(text)) return true;
    return (
      new RegExp(`\\bform\\s*no\\.?\\s*${num}\\b`).test(text) ||
      new RegExp(`form[\\s._-]*${num}(?:[\\s._\\W-]|$)`).test(text)
    );
  });
}

function statutorySheetContentIndicatesFormNumber(formHeader, sheetText, formNumber) {
  const blob = statutoryDetectionBlob(
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText
  );
  const num = String(formNumber);
  if (new RegExp(`\\bform\\s*no\\.?\\s*${num}\\b`).test(blob)) return true;
  return new RegExp(`form[\\s._-]*${num}(?:[\\s._\\W-]|$)`).test(blob);
}

function scoreStatutoryWorkbookSheetForFormNumber(workbook, sheetName, formNumber) {
  const num = String(formNumber);
  const sheetLower = String(sheetName || '').toLowerCase();
  const sheetText = buildStatutorySheetTextBlob(workbook, sheetName).toLowerCase();
  let score = 0;
  const sheetToken = extractStatutoryFormNumberToken(sheetLower);
  if (sheetToken === num) score += 220;
  if (statutorySheetContentIndicatesFormNumber(null, sheetText, num)) score += 200;
  if (/^\d+$/.test(num) && sheetToken && sheetToken !== num) score -= 320;
  if (num === '14' && /period\s+of\s+work|rule\s*79/.test(sheetText) && !/child\s+worker|rule\s*86/.test(sheetText)) {
    score -= 280;
  }
  if (num === '11' && /child\s+worker|register\s+of\s+child|rule\s*86/.test(sheetText)) score -= 280;
  return score;
}

/** Multi-tab AP workbooks: pick Form 11 vs Form 14 sheet from filename hints. */
function repickForm14Or11APWorkbookSheetIfNeeded(workbook, hints = {}, currentSheetName = '') {
  const names = Array.isArray(workbook?.SheetNames) ? workbook.SheetNames : [];
  if (names.length <= 1) return currentSheetName || names[0] || null;
  const blob = statutoryDetectionBlob(
    hints.fileName,
    hints.formFileName,
    hints.formName,
    hints.item?.formName,
    hints.item?.FormName,
    hints.item?.formFileName,
    hints.item?.FormFileName
  );
  let targetNum = '';
  if (statutoryFilenameRequestsFormNumber(blob, 14)) targetNum = '14';
  else if (statutoryFilenameRequestsFormNumber(blob, 11)) targetNum = '11';
  if (!targetNum) return currentSheetName || names[0];
  let best = currentSheetName && names.includes(currentSheetName) ? currentSheetName : names[0];
  let bestScore = scoreStatutoryWorkbookSheetForFormNumber(workbook, best, targetNum);
  for (const name of names) {
    const score = scoreStatutoryWorkbookSheetForFormNumber(workbook, name, targetNum);
    if (score > bestScore) {
      bestScore = score;
      best = name;
    }
  }
  return bestScore > 0 ? best : currentSheetName || names[0];
}

function statutoryOpenedSheetMismatchesRequestedForm(workbook, sheetName, requestedFormNumber) {
  const requested = Number(requestedFormNumber);
  if (!workbook || !sheetName || !requested) return false;
  const sheetText = buildStatutorySheetTextBlob(workbook, sheetName);
  if (statutorySheetContentIndicatesFormNumber(null, sheetText, requested)) return false;
  const wrongNumber = requested === 14 ? 11 : requested === 11 ? 14 : 0;
  if (!wrongNumber) return false;
  return statutorySheetContentIndicatesFormNumber(null, sheetText, wrongNumber);
}

function findFormMasterTemplateRecordByFileNamePattern(templates, pattern) {
  const list = Array.isArray(templates) ? templates : [];
  let best = null;
  let bestScore = -1;
  for (const t of list) {
    const name = String(t.templateFileName || t.name || t.fileName || '').trim();
    if (!name || !pattern.test(name)) continue;
    const id = t.id != null ? String(t.id) : t.fileId != null ? String(t.fileId) : '';
    if (!id) continue;
    let score = 10;
    if (/andhra/i.test(name)) score += 6;
    if (score > bestScore) {
      bestScore = score;
      best = { formFile: id, formFileName: name };
    }
  }
  return best;
}

/** Form No. 14 (AP) — Register of Child Workers (Rule 86). */
const FORM_14_AP_CANONICAL_HEADERS = [
  'Serial No.',
  'Name and residential address of the worker',
  "Father's name",
  'Date of first employment',
  'Number of certificate and its date',
  'Token number giving reference to the certificate',
  'Letter of Groups as in Form 11',
  'Number of relay if working shifts',
  'Remarks'
];

function headersIndicateForm14Table(tableHeaders) {
  const joined = (Array.isArray(tableHeaders) ? tableHeaders : [])
    .map((h) => normalizeLooseHeaderText(h))
    .join('\n');
  if (!joined) return false;
  if (/child\s+worker|register\s+of\s+child/.test(joined)) return true;
  if (/date\s+of\s+first\s+employment/.test(joined) && /father/.test(joined)) return true;
  if (/letter\s+of\s+group/.test(joined) && /token\s+number/.test(joined)) return true;
  return false;
}

function normalizeForm14APTableHeaders(parsedHeaders) {
  const src = Array.isArray(parsedHeaders) ? parsedHeaders : [];
  const out = [...FORM_14_AP_CANONICAL_HEADERS];
  src.forEach((h, i) => {
    if (i < out.length && String(h || '').trim()) out[i] = String(h).trim();
  });
  return out;
}

function form14APHeaderNorm(txt) {
  return String(txt || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function form14APHeaderAliasBucket(h) {
  const s = form14APHeaderNorm(h);
  if (/^s\.?\s*no|serial|sl\.?\s*no/.test(s)) return 'sno';
  if (/name/.test(s) && /address/.test(s) && /worker/.test(s)) return 'nameAddress';
  if (/father/.test(s)) return 'father';
  if (/date/.test(s) && /first/.test(s) && /employ/.test(s)) return 'firstEmployment';
  if (/certificate/.test(s)) return 'certificate';
  if (/token/.test(s)) return 'token';
  if (/letter/.test(s) && /group/.test(s)) return 'groupLetter';
  if (/relay/.test(s)) return 'relay';
  if (/remark/.test(s)) return 'remarks';
  return s;
}

function remapForm14APRowsToHeaders(rows, sourceHeaders, targetHeaders) {
  const src = Array.isArray(sourceHeaders) ? sourceHeaders : [];
  const tgt = normalizeForm14APTableHeaders(targetHeaders);
  if (!Array.isArray(rows)) return [];
  const srcBuckets = src.map(form14APHeaderAliasBucket);
  const tgtBuckets = tgt.map(form14APHeaderAliasBucket);
  return rows.map((row) => {
    if (!row || typeof row !== 'object') return tgt.reduce((o, h) => ({ ...o, [h]: '' }), {});
    const out = {};
    tgt.forEach((th, ti) => {
      const tb = tgtBuckets[ti];
      let val = '';
      if (Object.prototype.hasOwnProperty.call(row, th)) {
        val = row[th];
      } else {
        const si = srcBuckets.indexOf(tb);
        if (si >= 0 && src[si]) {
          const sk = src[si];
          if (Object.prototype.hasOwnProperty.call(row, sk)) val = row[sk];
        }
      }
      out[th] = val == null ? '' : val;
    });
    return out;
  });
}

function isForm14SkipAutofillHeader(h) {
  const s = normalizeLooseHeaderText(h);
  if (!s) return false;
  if (/letter/.test(s) && /group/.test(s)) return true;
  if (/certificate/.test(s)) return true;
  if (/token/.test(s) && /reference/.test(s)) return true;
  if (/relay/.test(s) && /shift/.test(s)) return true;
  if (/^remarks?$/.test(s.replace(/\s+/g, ' ').trim())) return true;
  return false;
}

function isForm14ResidentialAddressHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return s.includes('name') && s.includes('address') && (s.includes('worker') || s.includes('residential'));
}

/** Rows that contain CLRA/site header text exported into the child-worker table by mistake. */
function isForm14HeaderSpillRow(row) {
  if (!row || typeof row !== 'object') return false;
  const blob = Object.values(row)
    .map((v) => String(v ?? '').trim())
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  if (!blob) return false;
  if (/nature\s+and\s+location\s+of\s+work/.test(blob)) return true;
  if (/establishment[\s\S]{0,160}contract\s+is\s+carried\s+on/.test(blob)) return true;
  if (/name\s+and\s+address\s+of\s+principal\s+employer/.test(blob)) return true;
  if (/name\s+and\s+address\s+of\s+contractor/.test(blob)) return true;
  if (/registration\s+no\.?\s*:/.test(blob)) return true;
  if (/name\s+of\s+the\s+establishment\s*:/.test(blob)) return true;
  if (/address\s+of\s+the\s+establishment\s*:/.test(blob)) return true;
  return false;
}

function filterForm14APExportRows(rows) {
  if (!Array.isArray(rows)) return [];
  return rows.filter((row) => !isForm14HeaderSpillRow(row));
}

function buildForm14WorkerNameAndAddress(emp) {
  const name =
    emp.FirstName ||
    emp['FirstName'] ||
    emp.Name ||
    emp['Name'] ||
    emp.Name1 ||
    emp['Name1'] ||
    emp.EmployeeName ||
    emp['Employee Name'] ||
    `${emp.FirstName || emp['FirstName'] || ''} ${emp.LastName || emp['LastName'] || ''}`.trim() ||
    '';
  const parts = [
    emp.Address_Line_1 || emp['Address_Line_1'] || emp.AddressLine1 || '',
    emp.Address_Line_2 || emp['Address_Line_2'] || emp.AddressLine2 || '',
    emp.City || emp['City'] || emp.City1 || emp['City1'] || '',
    emp.Country || emp['Country'] || emp.Country1 || emp['Country1'] || ''
  ]
    .map((v) => String(v || '').trim())
    .filter(Boolean);
  const address = parts.join(', ');
  return [name, address].filter(Boolean).join(', ').trim();
}

/** Form No. 11 (AP) — Notice of period of work for adult and children (Rule 79). */
const FORM_11_AP_PERIOD_COL = 'Periods of work';
const FORM_11_AP_TAIL_HEADERS = ['Group letter', 'Nature of work', 'Remarks'];

/** Fixed side labels in column A (rows 9–20 on AP Form 11 template). */
const FORM_11_AP_TEMPLATE_ROWS = [
  { label: 'On working days', groupLetter: 'A' },
  { label: 'From', groupLetter: 'B' },
  { label: 'To', groupLetter: 'C' },
  { label: 'From', groupLetter: 'D' },
  { label: 'To', groupLetter: 'E' },
  { label: 'From', groupLetter: 'F' },
  { label: 'To', groupLetter: 'G' },
  { label: 'On partial working days', groupLetter: 'H' },
  { label: 'From', groupLetter: 'I' },
  { label: 'To', groupLetter: 'J' },
  { label: 'From', groupLetter: '' },
  { label: 'To', groupLetter: '' }
];

function buildForm11APCanonicalHeaders() {
  const headers = [FORM_11_AP_PERIOD_COL];
  const relays = ['1', '2', '3'];
  ['A', 'B', 'C'].forEach((g) => relays.forEach((r) => headers.push(`Men_${g}_${r}`)));
  ['D', 'E', 'F', 'G', 'H', 'I'].forEach((g) => relays.forEach((r) => headers.push(`Women_${g}_${r}`)));
  headers.push(...FORM_11_AP_TAIL_HEADERS);
  return headers;
}

function form11APHeaderNorm(txt) {
  return String(txt || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function headersLookLikeBrokenForm11PeriodOfWork(tableHeaders) {
  if (!Array.isArray(tableHeaders) || tableHeaders.length < 8) return false;
  const joined = tableHeaders.map((h) => form11APHeaderNorm(h)).join(' ');
  if (!/period/.test(joined) || !/work/.test(joined)) return false;
  const menTotalHits = tableHeaders.filter((h) => /men[_\s].*total\s+number\s+of\s+men/i.test(String(h || ''))).length;
  return menTotalHits >= 3;
}

function headersIndicateForm11PeriodOfWork(tableHeaders) {
  if (!Array.isArray(tableHeaders) || tableHeaders.length < 10) return false;
  const joined = tableHeaders.map((h) => form11APHeaderNorm(h)).join(' ');
  if (/accident\s+book|insurance\s+no|cause\s+of\s+injury|injured/.test(joined)) return false;
  if (/men_[a-i]_\d|women_[a-i]_\d/.test(joined.replace(/\s+/g, ''))) return true;
  if (/periods?\s+of\s+work/.test(joined) && /group\s+letter/.test(joined) && /nature\s+of\s+work/.test(joined)) {
    return true;
  }
  return headersLookLikeBrokenForm11PeriodOfWork(tableHeaders);
}

function isForm11PeriodOfWorkContext(formHeader, rowItem, fileName, tableHeaders, sheetText = '') {
  // Form 2-A (AP Notice of Change) must never be treated as Form 11 period-of-work.
  if (
    isForm2APHeaderFieldLayoutFormHeader(formHeader) ||
    isForm2APChangeNoticeContext(formHeader, rowItem, fileName, sheetText)
  ) {
    return false;
  }
  // Rajasthan Form 11 / Form 12 employment registers are not AP period-of-work.
  if (isForm12RajasthanContext(formHeader, rowItem, fileName, sheetText, tableHeaders)) {
    return false;
  }
  if (isForm11RajasthanContext(formHeader, rowItem, fileName, sheetText, tableHeaders)) {
    return false;
  }
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    rowItem?.formFileName,
    rowItem?.FormFileName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  if (
    statutoryFilenameRequestsFormNumber(
      rowItem?.formFileName,
      rowItem?.FormFileName,
      fileName,
      rowItem?.formName,
      rowItem?.FormName,
      14
    ) &&
    !statutoryFilenameRequestsFormNumber(
      rowItem?.formFileName,
      rowItem?.FormFileName,
      fileName,
      rowItem?.formName,
      rowItem?.FormName,
      11
    )
  ) {
    return false;
  }
  if (/accident\s+book|employees.? state insurance|regulation\s*66/.test(parts)) return false;
  if (/notice\s+of\s+period\s+of\s+work|period\s+of\s+work\s+for\s+adult/.test(parts)) return true;
  if (/\bform[\s._-]*11\b/.test(parts) && /period\s+of\s+work|periods?\s+of\s+work/.test(parts)) return true;
  if (/\bform[\s._-]*11\b/.test(parts) && /rule\s*79/.test(parts)) return true;
  if (/\bform[\s._-]*11\b/.test(parts) && /andhra/.test(parts) && !/accident\s+book|esic|employees.? state insurance/.test(parts)) {
    return true;
  }
  return headersIndicateForm11PeriodOfWork(tableHeaders);
}

function normalizeForm11PeriodOfWorkTableHeaders(parsedHeaders) {
  const canonical = buildForm11APCanonicalHeaders();
  const src = Array.isArray(parsedHeaders) ? parsedHeaders : [];
  if (src.length === canonical.length && headersIndicateForm11PeriodOfWork(src)) {
    return src.map((h, i) => String(h || '').trim() || canonical[i]);
  }
  return canonical;
}

function remapForm11PeriodOfWorkRowsToHeaders(rows, sourceHeaders, targetHeaders) {
  const src = Array.isArray(sourceHeaders) ? sourceHeaders : [];
  const tgt = normalizeForm11PeriodOfWorkTableHeaders(targetHeaders);
  if (!Array.isArray(rows)) return [];
  const norm = form11APHeaderNorm;
  const relayKeyFromHeader = (h) => {
    const t = String(h || '').trim();
    const m = t.match(/^(Men|Women)_([A-I])_([123])$/i);
    if (m) return `${m[1]}_${m[2].toUpperCase()}_${m[3]}`;
    if (/^periods?\s+of\s+work$/i.test(t) || /periods?\s+of\s+work[_\s]+groups?/i.test(t)) {
      return FORM_11_AP_PERIOD_COL;
    }
    if (/group\s+letter/i.test(t)) return 'Group letter';
    if (/nature\s+of\s+work/i.test(t)) return 'Nature of work';
    if (/^remarks$/i.test(t)) return 'Remarks';
    return t;
  };
  return rows.map((row) => {
    if (!row || typeof row !== 'object') return {};
    const out = {};
    tgt.forEach((targetHeader, colIdx) => {
      let val = '';
      if (Object.prototype.hasOwnProperty.call(row, targetHeader)) {
        val = row[targetHeader];
      } else if (src[colIdx] && Object.prototype.hasOwnProperty.call(row, src[colIdx])) {
        val = row[src[colIdx]];
      } else {
        const targetKey = relayKeyFromHeader(targetHeader);
        for (const [k, v] of Object.entries(row)) {
          const srcKey = relayKeyFromHeader(k);
          if (srcKey === targetKey || norm(k) === norm(targetHeader)) {
            val = v;
            break;
          }
          const brokenMen = k.match(/^Men[_\s].*Total\s+Number\s+of\s+men\s+employed$/i);
          if (brokenMen && /^Men_[ABC]_/i.test(targetHeader)) {
            const idx = src.indexOf(k);
            if (idx >= 0 && colIdx === idx) {
              val = v;
              break;
            }
          }
        }
      }
      out[targetHeader] = val == null ? '' : val;
    });
    return out;
  });
}

function buildForm11APDefaultRows(headers) {
  const hdrs = normalizeForm11PeriodOfWorkTableHeaders(headers);
  return FORM_11_AP_TEMPLATE_ROWS.map(({ label, groupLetter }) => {
    const row = {};
    hdrs.forEach((h) => {
      row[h] = '';
    });
    row[FORM_11_AP_PERIOD_COL] = label;
    if (groupLetter) row['Group letter'] = groupLetter;
    return row;
  });
}

function isForm11APFooterSideLabel(val) {
  const norm = form11APHeaderNorm(val);
  return /date on which this notice|first exhibited|authorised signatory|authorized signatory/.test(norm);
}

function isForm11APSideLabelValue(val) {
  const norm = form11APHeaderNorm(val);
  if (!norm || isForm11APFooterSideLabel(norm)) return false;
  if (/^on working days$|^on partial working days$/.test(norm)) return true;
  if (/^from$|^to$|^relay$|^groups$/.test(norm)) return true;
  return false;
}

function isForm11APPrimarySideLabel(val) {
  const norm = form11APHeaderNorm(val);
  return /^on working days$|^on partial working days$/.test(norm);
}

function ensureForm11APTemplateRows(rows, headers) {
  const hdrs = normalizeForm11PeriodOfWorkTableHeaders(headers);
  const defaults = buildForm11APDefaultRows(hdrs);
  const src = (Array.isArray(rows) ? rows : []).filter((row) => {
    const label = String(row?.[FORM_11_AP_PERIOD_COL] ?? '').trim();
    if (isForm11APFooterSideLabel(label)) return false;
    if (/^relay$/i.test(label)) return false;
    return true;
  });
  if (src.length === 0) return defaults;
  return defaults.map((defRow, idx) => {
    const srcRow = src[idx] || src.find((r) => {
      const lbl = form11APHeaderNorm(r?.[FORM_11_AP_PERIOD_COL]);
      return lbl && lbl === form11APHeaderNorm(defRow[FORM_11_AP_PERIOD_COL]);
    }) || {};
    const merged = { ...defRow };
    hdrs.forEach((h) => {
      const v = srcRow[h];
      if (v != null && String(v).trim() !== '') merged[h] = v;
    });
    const srcLabel = String(srcRow[FORM_11_AP_PERIOD_COL] ?? '').trim();
    merged[FORM_11_AP_PERIOD_COL] =
      srcLabel && !isForm11APFooterSideLabel(srcLabel) && !/^relay$/i.test(srcLabel)
        ? srcLabel
        : defRow[FORM_11_AP_PERIOD_COL];
    if (!String(merged['Group letter'] ?? '').trim() && defRow['Group letter']) {
      merged['Group letter'] = defRow['Group letter'];
    }
    return merged;
  });
}

const decodeExcelColumnLetters = (letters) => {
  let n = 0;
  const s = String(letters || '').toUpperCase();
  for (let i = 0; i < s.length; i += 1) {
    n = n * 26 + (s.charCodeAt(i) - 64);
  }
  return n - 1;
};

const parseExcelMergeRangeSpec = (spec) => {
  if (!spec) return null;
  if (typeof spec === 'object') {
    if (spec.s && spec.e) {
      return { sr: spec.s.r, sc: spec.s.c, er: spec.e.r, ec: spec.e.c };
    }
    if (spec.top != null) {
      return { sr: spec.top, sc: spec.left, er: spec.bottom, ec: spec.right };
    }
  }
  if (typeof spec === 'string') {
    const parts = spec.split(':');
    if (parts.length !== 2) return null;
    const decodeAddr = (addr) => {
      const m = String(addr || '')
        .trim()
        .match(/^(\$?)([A-Z]+)(\$?)(\d+)$/i);
      if (!m) return null;
      return { row: parseInt(m[4], 10) - 1, col: decodeExcelColumnLetters(m[2]) };
    };
    const s = decodeAddr(parts[0]);
    const e = decodeAddr(parts[1]);
    if (!s || !e) return null;
    return { sr: s.row, sc: s.col, er: e.row, ec: e.col };
  }
  return null;
};

const createExcelJsMergedAwareGetter = (worksheet, cellStrFn) => {
  const mergeSpecs = [];
  const modelMerges = worksheet?.model?.merges;
  if (Array.isArray(modelMerges)) {
    modelMerges.forEach((m) => {
      const parsed = parseExcelMergeRangeSpec(m);
      if (parsed) mergeSpecs.push(parsed);
    });
  }
  return (r, c) => {
    const direct = cellStrFn(worksheet.getCell(r + 1, c + 1)?.value).trim();
    if (direct) return direct;
    for (let i = 0; i < mergeSpecs.length; i += 1) {
      const m = mergeSpecs[i];
      if (r >= m.sr && r <= m.er && c >= m.sc && c <= m.ec) {
        return cellStrFn(worksheet.getCell(m.sr + 1, m.sc + 1)?.value).trim();
      }
    }
    return '';
  };
};

function resolveForm11APWorksheetColumnMap(getCellText, effectiveSheetCols = 40) {
  const norm = form11APHeaderNorm;
  let bandStartRow = -1;
  for (let r = 0; r < 25; r += 1) {
    for (let c = 0; c < 6; c += 1) {
      const t = norm(getCellText(r, c));
      if (t.includes('period') && t.includes('work') && !t.includes('nature')) {
        bandStartRow = r;
        break;
      }
    }
    if (bandStartRow >= 0) break;
  }

  let lettersRow = -1;
  let letterEntries = [];
  for (let r = 0; r < 25; r += 1) {
    const entries = [];
    for (let c = 1; c < Math.max(effectiveSheetCols, 45); c += 1) {
      const t = String(getCellText(r, c) || '').trim();
      if (/^[A-I]$/.test(t)) entries.push({ col: c, letter: t.toUpperCase() });
    }
    if (entries.length > letterEntries.length) {
      lettersRow = r;
      letterEntries = entries;
    }
  }
  if (lettersRow < 0 || letterEntries.length < 6) return null;
  if (bandStartRow < 0) bandStartRow = Math.max(0, lettersRow - 2);

  const relayRow = lettersRow + 1;
  const sectionForLetter = (letter) => (['A', 'B', 'C'].includes(letter) ? 'Men' : 'Women');
  const colMap = [{ header: FORM_11_AP_PERIOD_COL, col: 0 }];
  const canonical = buildForm11APCanonicalHeaders();

  letterEntries.forEach(({ col, letter }) => {
    const section = sectionForLetter(letter);
    const relayCols = [];
    for (let dc = 0; dc < 6 && relayCols.length < 3; dc += 1) {
      const c = col + dc;
      const relayVal = String(getCellText(relayRow, c) || '').trim();
      if (/^[123]$/.test(relayVal)) relayCols.push(c);
    }
    if (relayCols.length < 3) {
      relayCols.length = 0;
      for (let i = 0; i < 3; i += 1) relayCols.push(col + i);
    }
    ['1', '2', '3'].forEach((relay, idx) => {
      colMap.push({
        header: `${section}_${letter}_${relay}`,
        col: relayCols[idx] ?? col + idx
      });
    });
  });

  const lastDataCol = colMap[colMap.length - 1]?.col ?? 0;
  FORM_11_AP_TAIL_HEADERS.forEach((tailHdr) => {
    let foundCol = -1;
    for (let r = bandStartRow; r <= relayRow + 1; r += 1) {
      for (let c = lastDataCol + 1; c < Math.max(effectiveSheetCols, 50); c += 1) {
        const t = norm(getCellText(r, c));
        if (tailHdr === 'Group letter' && t.includes('group') && t.includes('letter')) {
          foundCol = c;
          break;
        }
        if (tailHdr === 'Nature of work' && t.includes('nature') && t.includes('work')) {
          foundCol = c;
          break;
        }
        if (tailHdr === 'Remarks' && t === 'remarks') {
          foundCol = c;
          break;
        }
      }
      if (foundCol >= 0) break;
    }
    if (foundCol < 0) {
      foundCol = lastDataCol + FORM_11_AP_TAIL_HEADERS.indexOf(tailHdr) + 1;
    }
    colMap.push({ header: tailHdr, col: foundCol });
  });

  if (colMap.length !== canonical.length) return null;
  return { bandStartRow, relayRow, dataStartRow: relayRow + 1, colMap };
}

function resolveForm11APLayoutFromXlsxWorkbook(workbook, sheetNameHint = '') {
  if (!workbook || !Array.isArray(workbook.SheetNames) || workbook.SheetNames.length === 0) return null;
  const sheetName =
    workbook.SheetNames.find((n) => /^11$/i.test(String(n || '').trim())) ||
    (sheetNameHint && workbook.SheetNames.includes(sheetNameHint) ? sheetNameHint : null) ||
    workbook.SheetNames.find((n) => /\b11\b/.test(String(n || ''))) ||
    workbook.SheetNames[0];
  const ws = workbook.Sheets[sheetName];
  if (!ws) return null;
  const merges = ws['!merges'] || [];
  const rawCell = (r, c) => {
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = ws[ref];
    return cell && cell.v != null ? String(cell.v).trim() : '';
  };
  const getCellText = (r, c) => {
    const direct = rawCell(r, c);
    if (direct) return direct;
    for (let i = 0; i < merges.length; i += 1) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        return rawCell(m.s.r, m.s.c);
      }
    }
    return '';
  };
  return resolveForm11APWorksheetColumnMap(getCellText, 45);
}

/** AP Form 11 typical column bands (includes spacer cols K, U after C and F). */
function buildForm11APFallbackColumnMap(parsedDataStartIndex) {
  const letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'];
  const letterStartCols = [1, 4, 7, 11, 14, 17, 21, 24, 27];
  const colMap = [{ header: FORM_11_AP_PERIOD_COL, col: 0 }];
  letters.forEach((letter, li) => {
    const section = ['A', 'B', 'C'].includes(letter) ? 'Men' : 'Women';
    const start = letterStartCols[li] ?? 1 + li * 3;
    ['1', '2', '3'].forEach((relay, ri) => {
      colMap.push({ header: `${section}_${letter}_${relay}`, col: start + ri });
    });
  });
  let tailStart = (colMap[colMap.length - 1]?.col ?? 27) + 1;
  FORM_11_AP_TAIL_HEADERS.forEach((tailHdr) => {
    colMap.push({ header: tailHdr, col: tailStart });
    tailStart += 1;
  });
  const dataStartRow =
    parsedDataStartIndex != null && parsedDataStartIndex >= 0 ? parsedDataStartIndex : 8;
  const relayRow = Math.max(0, dataStartRow - 1);
  const bandStartRow = Math.max(0, relayRow - 2);
  return { bandStartRow, relayRow, dataStartRow, colMap };
}

function resolveForm11APWorksheetLayout({
  templateWb,
  worksheet,
  cellStrFn,
  parsedDataStartIndex,
  sheetNameHint = ''
}) {
  const fromXlsx = templateWb ? resolveForm11APLayoutFromXlsxWorkbook(templateWb, sheetNameHint) : null;
  if (fromXlsx) return fromXlsx;
  if (worksheet && typeof cellStrFn === 'function') {
    const getCellText = createExcelJsMergedAwareGetter(worksheet, cellStrFn);
    const fromExcelJs = resolveForm11APWorksheetColumnMap(getCellText, 45);
    if (fromExcelJs) return fromExcelJs;
  }
  return buildForm11APFallbackColumnMap(parsedDataStartIndex);
}

const rebuildForm11PeriodOfWorkHeaders = ({
  jsonData,
  effectiveSheetCols,
  getMergedAwareCellText,
  headers,
  expandedHeaders,
  headerRowIndex,
  startIndex,
  tableData,
  firstSheetName,
  formHeaderInfo,
  parseHints = {}
}) => {
  const probeHeaders = expandedHeaders?.length ? expandedHeaders : headers || [];
  const sheetTextBlob = (jsonData || [])
    .slice(0, Math.min(20, jsonData.length))
    .map((row) => (Array.isArray(row) ? row : []).map((c) => String(c || '')).join(' '))
    .join(' ');
  if (
    statutoryFilenameRequestsFormNumber(
      parseHints.fileName,
      parseHints.formFileName,
      parseHints.formName,
      parseHints.item?.formFileName,
      parseHints.item?.FormFileName,
      parseHints.item?.formName,
      parseHints.item?.FormName,
      14
    ) &&
    !statutoryFilenameRequestsFormNumber(
      parseHints.fileName,
      parseHints.formFileName,
      parseHints.formName,
      parseHints.item?.formFileName,
      parseHints.item?.FormFileName,
      parseHints.item?.formName,
      parseHints.item?.FormName,
      11
    )
  ) {
    return null;
  }
  const shouldRebuild =
    isForm11PeriodOfWorkContext(
      formHeaderInfo,
      parseHints.item || null,
      parseHints.fileName || parseHints.formFileName || firstSheetName,
      probeHeaders,
      sheetTextBlob
    ) ||
    headersLookLikeBrokenForm11PeriodOfWork(probeHeaders);
  if (!shouldRebuild) return null;

  const layout =
    resolveForm11APWorksheetColumnMap(
      (r, c) => getMergedAwareCellText(r, c),
      effectiveSheetCols
    ) || buildForm11APFallbackColumnMap(startIndex);
  if (!layout?.colMap?.length) return null;

  const { bandStartRow, relayRow, dataStartRow, colMap } = layout;
  const newExpanded = colMap.map((x) => x.header);
  const priorHeaders = probeHeaders;
  const priorRows = Array.isArray(tableData) ? tableData.map((row) => ({ ...row })) : [];
  let newTableData = [];

  for (let i = dataStartRow; i < jsonData.length; i += 1) {
    const periodLabel = String(getMergedAwareCellText(i, 0) || '').trim();
    if (isForm11APFooterSideLabel(periodLabel)) break;
    if (/^relay$/i.test(periodLabel)) continue;
    const rowData = {};
    colMap.forEach(({ header, col }) => {
      rowData[header] = String(getMergedAwareCellText(i, col) || '').trim();
    });
    if (periodLabel && !String(rowData[FORM_11_AP_PERIOD_COL] || '').trim()) {
      rowData[FORM_11_AP_PERIOD_COL] = periodLabel;
    }
    const hasData = Object.values(rowData).some((val) => String(val ?? '').trim() !== '');
    if (hasData || periodLabel) {
      newTableData.push(rowData);
    }
  }

  if (
    priorRows.length > 0 &&
    (!newTableData.length ||
      newTableData.every((row) => !Object.values(row).some((val) => String(val ?? '').trim() !== '')))
  ) {
    newTableData = remapForm11PeriodOfWorkRowsToHeaders(priorRows, priorHeaders, newExpanded);
  }
  newTableData = ensureForm11APTemplateRows(newTableData, newExpanded);

  return {
    headers: newExpanded,
    expandedHeaders: newExpanded,
    subColumnsData: {},
    headerRowIndex: bandStartRow,
    startIndex: dataStartRow,
    tableData: newTableData.length ? newTableData : priorRows,
    columnGroupLabels: null,
    originalHeaderRowIndex: bandStartRow,
    tableStartCol: 0
  };
};

/** Register of Wages / Form XXIII / Form W — must not use Form U Excel save path. */
function isStatutoryWageRegisterSaveContext(formHeader, rowItem, fileName, tableHeaders) {
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.wagePeriodText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .filter((x) => x != null && String(x).trim() !== '')
    .join(' ')
    .toLowerCase();
  if (
    isFormQKarnatakaContext(
      formHeader,
      rowItem,
      fileName,
      Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
    )
  ) {
    return false;
  }
  if (/\bform\s*xxiii\b|\bform_xxiii\b|\bform-xxiii\b/i.test(parts)) return true;
  if (/register\s+of\s+advances?\s+of\s+wages/i.test(parts)) return false;
  if (matchesFormXXVIIHint(parts) && !isFormXXVIIQuarterlyReturnsContext(null, null, parts, null, parts)) {
    return true;
  }
  if (parts.includes('form w') || parts.includes('form-w') || parts.includes('form_w')) return true;
  if (parts.includes('register') && /\bwages?\b/.test(parts)) return true;
  if (/wage\s*period/.test(parts) && /\bwages?\b/.test(parts)) return true;
  return false;
}

/** Minimum Wages Act Form I — Register of Fines (PW Form I), not Tamil Nadu workmen register. */
function isFormIRegisterOfFinesContext(item, fileName, formHeader, tableHeaders, sheetText) {
  if (
    isFormXAPRegisterOfFinesContext(formHeader, item, fileName, sheetText, tableHeaders)
  ) {
    return false;
  }
  if (isFormXXIAPRegisterOfFinesContext(formHeader, item, fileName, sheetText, tableHeaders)) {
    return false;
  }
  // Form_I_-_TamilNadu.xlsx SA suspension / subsistence register is not Register of Fines
  // (both cite Payment/Minimum Wages Act and share the same filename).
  if (
    isFormITamilNaduSuspensionWorkbookContext({
      fileName,
      formFileName: fileName,
      formHeader,
      headers: tableHeaders,
      sheetText
    })
  ) {
    return false;
  }
  // Conferment Register of Workmen sheet must not be labeled Register of Fines just because
  // the statutory catalog description says "Register of Fines".
  if (sheetIndicatesFormIRegisterOfWorkmen(formHeader, tableHeaders, sheetText)) {
    return false;
  }
  const formTBlob = [
    item?.formName,
    item?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  // Karnataka Form T — Combined Muster Roll cum Register of Wages (citations mention PW Form I / Register of Fines).
  if (
    /\bform[\s._-]*t\b/i.test(formTBlob) &&
    (/form[_\s-]*t/i.test(String(fileName || '').toLowerCase()) ||
      /combined\s+muster\s+roll|muster\s+roll\s+cum\s+register/i.test(formTBlob) ||
      (/karnataka/.test(formTBlob) && /rule\s+24\s*\(\s*9[\s-]*b/i.test(formTBlob)))
  ) {
    return false;
  }
  const blob = [
    item?.formName,
    item?.FormName,
    item?.act,
    item?.Act,
    item?.description,
    item?.Description,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();

  // TN LWF Form C — "Register of Fines and Unpaid Accumulations" is not PW / Minimum Wages Form I.
  if (/register\s+of\s+fines\s+and\s+unpaid\s+accumulations/i.test(blob)) return false;
  if (/\bform\s*[-–]?\s*c\b/i.test(blob) && /labou?r\s*welfare|unpaid\s+accumulations/i.test(blob)) {
    return false;
  }
  if (/form[\s._-]*c[\s._-]*tamil/i.test(String(fileName || '').toLowerCase())) return false;
  if (Array.isArray(tableHeaders) && tableHeaders.length > 0) {
    const joinedHdr = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
    if (/quarter\s+ending/.test(joinedHdr) && /details\s+of\s+fines|unpaid\s+accumulations/.test(joinedHdr)) {
      return false;
    }
  }

  if (/register\s+of\s+fines/.test(blob) || /register\s+of\s+fine\b/.test(blob)) return true;
  if (
    (/\bform\s*[-–]?\s*i\b/.test(blob) ||
      (/\bform[\s._-]*1(?:[\s._-]|$)/i.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob))) &&
    (/minimum\s+wages?/.test(blob) || /payment\s+of\s+wages/.test(blob))
  ) {
    return true;
  }
  if (/pw\s+form\s*i\b/.test(blob)) return true;

  if (Array.isArray(tableHeaders) && tableHeaders.length > 0) {
    const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
    if (/act\s+or\s+omission.*fine\s+imposed|fine\s+imposed/.test(joined)) return true;
    if (/fine\s+realised|fine\s+realized/.test(joined)) return true;
    if (/date\s+on\s+which\s+fine/.test(joined)) return true;
  }
  return false;
}

/** Tamil Nadu Form I (statutory name "Form 1") — Register of Workmen, not Form U Employee Register. */
function isFormIRegisterOfWorkmenContext(item, fileName, formHeader, tableHeaders, sheetText) {
  // Sheet content wins — catalog may wrongly say Register of Fines for a workmen template.
  if (sheetIndicatesFormIRegisterOfWorkmen(formHeader, tableHeaders, sheetText)) return true;
  if (sheetIndicatesFormIRegisterOfFines(formHeader, tableHeaders, sheetText)) return false;
  if (isFormIRegisterOfFinesContext(item, fileName, formHeader, tableHeaders, sheetText)) return false;
  // Form_I_-_TamilNadu.xlsx is the suspension / subsistence register — not Register of Workmen.
  if (
    isFormITamilNaduSuspensionWorkbookContext({
      fileName,
      formFileName: fileName,
      formHeader,
      headers: tableHeaders,
      sheetText
    })
  ) {
    return false;
  }
  const blob = [
    item?.formName,
    item?.FormName,
    item?.act,
    item?.Act,
    item?.description,
    item?.Description,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();

  // Filename Form_I_-_TamilNadu alone is suspension; do not treat "tamil" as workmen signal.
  if (
    /date\s+of\s+suspension|subsistence\s+allowance|kept\s+under\s+suspension|employees\s+placed\s+under\s+suspension|nature\s+of\s+offence/.test(
      blob
    )
  ) {
    return false;
  }

  // Form_XV_-_TamilNadu.xlsx is CLRA Service Certificate — never Form I Register of Workmen,
  // even when the catalog row title says "Form 1 Register of Workmen".
  if (/form[\s._-]*xv(?![a-z])/i.test(blob)) return false;
  if (/service\s+certificate/i.test(blob) && /\b(?:rule\s*77|see\s+rule\s*77)\b/i.test(blob)) {
    return false;
  }

  // AP / Central CLRA Form XIII Register of Workmen — never Tamil Nadu Form I/1.
  if (matchesFormXIIIHint(blob)) return false;
  if (
    /register\s+of\s+workmen\s+employed\s+by\s+contractor/i.test(blob) ||
    (/vide\s+rule\s*75/i.test(blob) && /contract\s+labou?r/i.test(blob))
  ) {
    return false;
  }

  if (/register\s+of\s+workmen/.test(blob)) {
    if (matchesFormXIVHint(blob)) return false;
    if (/employment\s+card/i.test(blob)) return false;
    if (/see\s+rule\s+76/i.test(blob)) return false;
    if (/see\s+rule\s+77/i.test(blob)) return false;
    if (/service\s+certificate/i.test(blob)) return false;
    return true;
  }
  if (/conferment\s+of\s+permanent\s+status|register\s+of\s+conferment/.test(blob)) {
    return true;
  }
  if (matchesFormXIVHint(blob) || /employment\s+card/i.test(blob)) return false;
  // Form I / Form-1 (letter I or digit 1) + workmen/conferment signals (NOT bare "tamil").
  const looksFormIFile =
    /form[_\s-]*i(?:[_\s-]|$)/i.test(blob) ||
    (/\bform[\s._-]*1(?:[\s._-]|$)/i.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob));
  if (looksFormIFile && /workmen|workman|conferment|permanent\s+status/.test(blob)) {
    return true;
  }
  if (/\bform\s*[-–]?\s*i\b/.test(blob) && /workmen|workman|conferment|permanent\s+status/.test(blob)) {
    return true;
  }
  if (/\bform[\s._-]*1(?:[\s._-]|$)/i.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob)) {
    if (/workmen|workman|conferment|permanent\s+status|register\s+of\s+workmen/.test(blob)) return true;
  }

  if (Array.isArray(tableHeaders) && tableHeaders.length > 0) {
    const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
    if (/date\s+of\s+suspension|subsistence\s+allowance|nature\s+of\s+offence/.test(joined)) {
      return false;
    }
    if (/name\s+and\s+address\s+of\s+the\s+workman/.test(joined)) {
      if (/form[\s._-]*xv(?![a-z])/i.test(blob) || /service\s+certificate/i.test(blob)) return false;
      return true;
    }
    if (/emp\s*id/.test(joined) && /480\s+days/.test(joined)) return true;
  }
  return false;
}

/** Shops & Establishments employee register (Form U style) — not Tamil Nadu Form I workmen register. */
function isForm1EmployeeRegisterContext(item, fileName, formHeader, tableHeaders) {
  if (isFormIRegisterOfWorkmenContext(item, fileName, formHeader, tableHeaders)) return false;

  const blob = [
    item?.formName,
    item?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();

  if (/\bform[\s._-]*1(?:[\s._-]|$)/i.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob)) return false;
  if (/employee\s+register/.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob)) return true;

  if (Array.isArray(tableHeaders) && tableHeaders.length > 0) {
    const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
    if (
      /present\s+address/.test(joined) &&
      /permanent\s+address/.test(joined) &&
      /name\s+of\s+the\s+employee/.test(joined) &&
      !/worker\s+identity/.test(joined)
    ) {
      return true;
    }
  }
  return false;
}

/** Conferment / Register of Workmen signals from parsed sheet only (ignore catalog row). */
function sheetIndicatesFormIRegisterOfWorkmen(formHeader, tableHeaders, sheetText) {
  const blob = [formHeader?.title, formHeader?.subtitle, formHeader?.reference, sheetText]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  const hdr = Array.isArray(tableHeaders)
    ? tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n')
    : '';
  const combined = `${blob}\n${hdr}`;
  if (/register\s+of\s+fines/.test(combined) && /fine\s+imposed|act\s+or\s+omission/.test(combined)) {
    return false;
  }
  if (/date\s+of\s+suspension|subsistence\s+allowance|kept\s+under\s+suspension/.test(combined)) {
    return false;
  }
  if (/conferment\s+of\s+permanent\s+status|register\s+of\s+conferment/.test(combined)) return true;
  if (/register\s+of\s+workmen/.test(combined) && !/employed\s+by\s+contractor/.test(combined)) {
    return true;
  }
  if (/name\s+and\s+address\s+of\s+the\s+workman/.test(hdr) && /480\s+days/.test(hdr)) return true;
  if (/emp\s*id/.test(hdr) && /480\s+days/.test(hdr) && /designation\s+of\s+the\s+workmen/.test(hdr)) {
    return true;
  }
  return false;
}

/** PW Register of Fines signals from parsed sheet only (ignore catalog row). */
function sheetIndicatesFormIRegisterOfFines(formHeader, tableHeaders, sheetText) {
  if (sheetIndicatesFormIRegisterOfWorkmen(formHeader, tableHeaders, sheetText)) return false;
  const blob = [formHeader?.title, formHeader?.subtitle, formHeader?.reference, sheetText]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  const hdr = Array.isArray(tableHeaders)
    ? tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n')
    : '';
  const combined = `${blob}\n${hdr}`;
  if (/register\s+of\s+fines\s+and\s+unpaid\s+accumulations/.test(combined)) return false;
  if (/register\s+of\s+fines/.test(combined) || /register\s+of\s+fine\b/.test(combined)) return true;
  if (/act\s+or\s+omission/.test(hdr) && /fine\s+imposed/.test(hdr)) return true;
  if (/fine\s+realised|fine\s+realized|date\s+on\s+which\s+fine/.test(hdr)) return true;
  return false;
}

/** What the statutory/catalog row asks for — do not use linked template sheet text. */
function inferFormIVariantFromCatalogRow(item) {
  if (!item) return null;
  const blob = [
    item.formName,
    item.FormName,
    item.act,
    item.Act,
    item.description,
    item.Description
  ]
    .map((s) => String(s || ''))
    .join(' ')
    .toLowerCase();
  if (!blob.trim()) return null;
  if (/register\s+of\s+fines\s+and\s+unpaid\s+accumulations/.test(blob)) return null;
  if (/register\s+of\s+fines/.test(blob) || /register\s+of\s+fine\b/.test(blob)) {
    return 'register_of_fines';
  }
  if (/pw\s+form\s*i\b/.test(blob)) return 'register_of_fines';
  if (
    (/\bform\s*[-–]?\s*i\b/.test(blob) ||
      (/\bform[\s._-]*1(?:[\s._-]|$)/i.test(blob) && !/\bform[\s._-]*1[0-9]/i.test(blob))) &&
    (/minimum\s+wages?/.test(blob) || /payment\s+of\s+wages/.test(blob)) &&
    !/conferment|register\s+of\s+workmen|permanent\s+status/.test(blob)
  ) {
    return 'register_of_fines';
  }
  if (/register\s+of\s+workmen|conferment\s+of\s+permanent|permanent\s+status\s+to\s+workmen/.test(blob)) {
    return 'register_of_workmen';
  }
  return null;
}

/** What the opened Excel sheet actually is — ignore catalog description. */
function inferFormIVariantFromSheetContent(formHeader, tableHeaders, sheetText) {
  if (sheetIndicatesFormIRegisterOfFines(formHeader, tableHeaders, sheetText)) {
    return 'register_of_fines';
  }
  if (sheetIndicatesFormIRegisterOfWorkmen(formHeader, tableHeaders, sheetText)) {
    return 'register_of_workmen';
  }
  return null;
}

function inferFormIVariantFromRow(item, extra = {}) {
  const formHeader = {
    title: extra.formHeaderTitle,
    subtitle: extra.formHeaderSubtitle,
    reference: extra.formHeaderReference
  };
  const fileName =
    extra.fileName ||
    extra.formFileName ||
    item?.formFileName ||
    item?.FormFileName ||
    '';
  const headers = extra.sampleHeaders || extra.tableHeaders || null;
  const sheetText = extra.sheetText || '';
  // Sheet content always wins over a mismatched catalog label (e.g. row says Fines,
  // linked Form_I_-_TamilNadu.xlsx is Conferment Register of Workmen).
  const sheetVariant = inferFormIVariantFromSheetContent(formHeader, headers, sheetText);
  if (sheetVariant) return sheetVariant;
  if (isFormIRegisterOfFinesContext(item, fileName, formHeader, headers, sheetText)) {
    return 'register_of_fines';
  }
  if (isFormIRegisterOfWorkmenContext(item, fileName, formHeader, headers, sheetText)) {
    return 'register_of_workmen';
  }
  return inferFormIVariantFromCatalogRow(item);
}

function inferFormIVariantFromSavedHeaders(headers) {
  if (!Array.isArray(headers) || headers.length === 0) return null;
  if (isFormIRegisterOfFinesContext(null, null, '', headers, '')) return 'register_of_fines';
  if (isFormIRegisterOfWorkmenContext(null, null, '', headers, '')) return 'register_of_workmen';
  return null;
}

function inferFormIVariantFromSheetHints(hints = {}) {
  // Prefer pure sheet classification so catalog "Register of Fines" cannot mask a workmen template.
  const sheetOnly = inferFormIVariantFromSheetContent(
    {
      title: hints.formHeaderTitle,
      subtitle: hints.formHeaderSubtitle,
      reference: hints.formHeaderReference
    },
    hints.tableHeaders || hints.sampleHeaders || null,
    hints.sheetText || ''
  );
  if (sheetOnly) return sheetOnly;
  return inferFormIVariantFromRow(hints.item || null, {
    fileName: hints.fileName,
    formFileName: hints.formFileName,
    formHeaderTitle: hints.formHeaderTitle,
    formHeaderSubtitle: hints.formHeaderSubtitle,
    formHeaderReference: hints.formHeaderReference,
    tableHeaders: hints.tableHeaders,
    sheetText: hints.sheetText
  });
}

const getForm12PresentAddress = (emp) =>
  pickFirstNonEmptyString(
    emp.Present_Address,
    emp['Present_Address'],
    emp['Present Address'],
    emp.PresentAddress,
    emp['PresentAddress'],
    emp.presentAddress,
    findNestedValueByNormalizedKey(emp, 'presentaddress')
  );

const getForm12PermanentAddress = (emp) =>
  pickFirstNonEmptyString(
    emp.Permanent_Address,
    emp['Permanent_Address'],
    emp['Permanent address'],
    emp.Permanentaddress,
    emp['Permanentaddress'],
    emp.PermanentAddress,
    emp['PermanentAddress'],
    emp.permanentAddress,
    findNestedValueByNormalizedKey(emp, 'permanentaddress')
  );

const isForm12PresentAddressHeader = (h) => {
  const s = normalizeLooseHeaderText(h);
  return s.includes('present') && s.includes('address');
};

const isForm12PermanentAddressHeader = (h) => {
  const s = normalizeLooseHeaderText(h);
  return s.includes('permanent') && s.includes('address');
};

/** AP Form XXII — Register of Employment (Shops & Establishment; daily attendance P/A/L/H columns). */
function isFormXXIIRegisterOfEmploymentContext(formHeader, rowItem, fileName, tableHeaders, sheetText = '') {
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  if (isFormKRegisterOfEmploymentContext(formHeader, rowItem, fileName, tableHeaders)) return false;
  if (/register\s+of\s+advances/i.test(parts)) return false;
  const isXXIIHint =
    /form[\s._-]*xxii(?![a-z])/i.test(parts) ||
    /form[\s._-]*22(?!\d)/i.test(parts) ||
    /(?:^|[\s._-])xxii(?=[\s._\W-]|$)/i.test(parts);
  if (isXXIIHint) return true;
  if (
    /register\s+of\s+employment/i.test(parts) &&
    (/andhra\s+pradesh|a\.?\s*p\.?\s*shops/i.test(parts) || /rule\s+29\s*\(1\)/i.test(parts))
  ) {
    return true;
  }
  return false;
}

function isFormJStatutoryContext(item, fileName, formHeader) {
  if (isFormKRegisterOfEmploymentContext(formHeader, item, fileName, null)) return false;
  if (isFormXXIIRegisterOfEmploymentContext(formHeader, item, fileName, null, '')) return false;
  const blob = [
    item?.formName,
    item?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference
  ]
    .map((s) => String(s || ''))
    .join(' ');
  // Require explicit Form J — never treat Tamil Nadu Form V / generic
  // "Register of Employment" as Form J (that produced blank Form V downloads).
  if (/\bform\s*[-"']?\s*v\b/i.test(blob) || /form[_\s-]*v(?:[_\s-]|$)/i.test(blob)) {
    return false;
  }
  return /\bform\s*[-"']?\s*j\b/i.test(blob);
}

/** Form K — Register of Employment (hotel / restaurant / theatre; numbered "Hours worked on" columns). */
function isFormKRegisterOfEmploymentContext(formHeader, rowItem, fileName, tableHeaders) {
  if (isFormKGJGujaratContext(formHeader, rowItem, fileName, '', tableHeaders)) return false;
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  if (/\bform\s*k\b|\bform_k\b|\bform-k\b/i.test(parts)) return true;
  return (
    /register\s+of\s+employment/i.test(parts) &&
    /residential\s+hotel|restaurant|eating\s+house|theatre|public\s+amusement|entertainment/i.test(parts)
  );
}

/** Legacy spacer keys from earlier Form II builds — stripped on normalize/remap. */
const FORM_II_MH_LEGACY_SPACER_HEADERS = ['__formII_col_margin_1__', '__formII_col_margin_2__'];

const isFormIILegacySpacerHeader = (h) =>
  FORM_II_MH_LEGACY_SPACER_HEADERS.includes(String(h || ''));

const isBlankOrGeneratedTableHeader = (h) => {
  const t = String(h || '').trim();
  if (!t) return true;
  return /^column\s+([a-z]+|\d+)$/i.test(t);
};

const countLeadingBlankTableHeaders = (headers) => {
  if (!Array.isArray(headers)) return 0;
  let n = 0;
  for (let i = 0; i < headers.length; i += 1) {
    if (isBlankOrGeneratedTableHeader(headers[i]) || isFormIILegacySpacerHeader(headers[i])) n += 1;
    else break;
  }
  return n;
};

const normalizeFormIIHeaderKey = (h) =>
  String(h || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, '');

const isFormIISerialHeader = (h) => {
  const s = String(h || '').trim().toLowerCase().replace(/\s+/g, ' ');
  return (
    /^sl\.?\s*no\.?$/.test(s) ||
    /^s\.?\s*no\.?$/.test(s) ||
    s === 'sl no' ||
    s === 's no' ||
    s === 'sr no' ||
    /^sr\.?\s*no\.?$/.test(s)
  );
};

const isFormIIDeputyHeader = (h) => /deputy\s*id/i.test(String(h || ''));

const isFormIIEmployeeCodeHeader = (h) => {
  const s = String(h || '').toLowerCase();
  return s.includes('employee') && s.includes('code');
};

const isFormIIWorkmenNameHeader = (h) => /name\s+of\s+the\s+workmen/i.test(String(h || ''));

const isFormIIMinimumRateBasicHeader = (h) => {
  const s = normalizeFormIIHeaderKey(h);
  return s.includes('minimum') && s.includes('rate') && s.includes('wage') && s.includes('basic');
};

const isFormIIActualRateHraHeader = (h) => {
  const s = normalizeFormIIHeaderKey(h);
  return s.includes('actual') && s.includes('rate') && (s.includes('hra') || (s.includes('wage') && s.includes('payable')));
};

const isFormIIConveyanceHeader = (h) => {
  const s = normalizeFormIIHeaderKey(h);
  return s.includes('conveyance') || /\bconv\b/.test(s);
};

const isFormIIBonusHeader = (h) => /\bbonus\b/i.test(String(h || ''));

const isFormIIRecognizedDataHeader = (h) => {
  const text = String(h || '').trim();
  if (!text || isFormIILegacySpacerHeader(text)) return false;
  return (
    isFormIISerialHeader(text) ||
    isFormIIDeputyHeader(text) ||
    isFormIIEmployeeCodeHeader(text) ||
    isFormIIWorkmenNameHeader(text) ||
    isFormIIMinimumRateBasicHeader(text) ||
    isFormIIActualRateHraHeader(text) ||
    isFormIIConveyanceHeader(text) ||
    isFormIIBonusHeader(text) ||
    /total|product|case|piece|allow|wage|rate|payable|deduct|remark|signature/i.test(text)
  );
};

/** How many leading Excel/UI columns to drop before Sl.No. for Form II. */
const countLeadingFormIIColumnsToStrip = (headers) => {
  if (!Array.isArray(headers)) return 0;
  const withoutLegacy = headers.filter((h) => !isFormIILegacySpacerHeader(h));
  const trimmed = withoutLegacy.map((h) => String(h || '').trim());
  const slIdx = trimmed.findIndex((h) => h && isFormIISerialHeader(h));
  if (slIdx > 0) return slIdx;
  return countLeadingBlankTableHeaders(withoutLegacy);
};

/** Form II Maharashtra UI grid: Sl.No. is column A (leading blank Excel margin columns are not shown). */
const normalizeFormIIMaharashtraTableHeaders = (headers) => {
  if (!Array.isArray(headers) || headers.length === 0) return [];
  let list = headers
    .filter((h) => !isFormIILegacySpacerHeader(h))
    .map((h) => String(h || '').trim())
    .filter(Boolean);

  const slIdx = list.findIndex((h) => isFormIISerialHeader(h));
  if (slIdx > 0) {
    list = list.slice(slIdx);
  } else {
    let drop = 0;
    while (drop < list.length && !isFormIIRecognizedDataHeader(list[drop])) drop += 1;
    if (drop > 0 && drop < list.length) list = list.slice(drop);
  }

  while (list.length > 1 && isFormIISerialHeader(list[0]) && isFormIISerialHeader(list[1])) {
    list = list.slice(1);
  }

  return list;
};

const alignFormIIColumnGroupLabels = (labels, leadingColsToStrip) => {
  if (!Array.isArray(labels) || leadingColsToStrip <= 0) return labels;
  return labels.slice(leadingColsToStrip);
};

const extractLeadingFormIIJunkValue = (row, oldList, newH) => {
  if (!row || typeof row !== 'object' || !isFormIISerialHeader(newH)) return '';
  for (let si = 0; si < FORM_II_MH_LEGACY_SPACER_HEADERS.length; si += 1) {
    const key = FORM_II_MH_LEGACY_SPACER_HEADERS[si];
    const v = row[key];
    if (v != null && String(v).trim() !== '') return v;
  }
  const rawOld = Array.isArray(oldList) ? oldList : [];
  const strip = countLeadingFormIIColumnsToStrip(rawOld);
  for (let i = 0; i < strip; i += 1) {
    const key = rawOld[i];
    if (key == null || isFormIILegacySpacerHeader(key)) continue;
    const v = row[key];
    if (v != null && String(v).trim() !== '') return v;
  }
  return '';
};

const remapFormIIRowsToHeaders = (rows, oldHeaders, newHeaders) => {
  if (!Array.isArray(rows) || !Array.isArray(newHeaders) || newHeaders.length === 0) return rows || [];
  const oldList = Array.isArray(oldHeaders) ? oldHeaders : [];
  const oldDataHeaders = normalizeFormIIMaharashtraTableHeaders(oldList);

  return rows.map((row) => {
    if (!row || typeof row !== 'object') return row;
    const next = {};
    newHeaders.forEach((newH, i) => {
      if (row[newH] != null && String(row[newH]).trim() !== '') {
        next[newH] = row[newH];
        return;
      }
      const nk = normalizeFormIIHeaderKey(newH);
      for (const key of Object.keys(row)) {
        if (isFormIILegacySpacerHeader(key) || key.startsWith('__')) continue;
        if (normalizeFormIIHeaderKey(key) === nk) {
          next[newH] = row[key];
          return;
        }
      }
      const oldH = oldDataHeaders[i];
      if (oldH && row[oldH] != null && String(row[oldH]).trim() !== '') {
        next[newH] = row[oldH];
        return;
      }
      const strip = countLeadingFormIIColumnsToStrip(oldList);
      const offsetKey = oldList[strip + i];
      if (offsetKey && row[offsetKey] != null && String(row[offsetKey]).trim() !== '') {
        next[newH] = row[offsetKey];
        return;
      }
      const leadingVal = extractLeadingFormIIJunkValue(row, oldList, newH);
      if (leadingVal !== '') {
        next[newH] = leadingVal;
        return;
      }
      next[newH] = '';
    });
    return next;
  });
};

function isFormIIMaharashtraContext(formHeader, rowItem, fileName, tableHeaders) {
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  // Form_II / Form-II filenames — JS \b does not treat "_" as a word boundary.
  if (/form[\s._-]*ii(?:[\s._-]|$)/i.test(parts) && !/form[\s._-]*iii/i.test(parts)) return true;
  const hdrBlob = Array.isArray(tableHeaders) ? tableHeaders.join(' ').toLowerCase() : '';
  return (
    /deputy\s*id/.test(hdrBlob) &&
    /name\s+of\s+(the\s+)?workmen?/.test(hdrBlob) &&
    (/minimum\s+rate\s+of\s+wages/.test(hdrBlob) || /actual\s+rate\s+of\s+wages/.test(hdrBlob))
  );
}

const FORM_K_HEADER_TO_SPEC_KEY = (rawHeader) => {
  const raw = String(rawHeader || '').trim();
  const directDay = raw.match(/^(\d{1,2})$/);
  if (directDay) {
    const dayNum = parseInt(directDay[1], 10);
    if (dayNum >= 1 && dayNum <= 31) return `hours_${dayNum}`;
  }
  const dateDayMatch =
    raw.match(/(?:dates?|attendance)[^0-9]*(\d{1,2})$/i) ||
    raw.match(/_(\d{1,2})$/);
  if (dateDayMatch) {
    const dayNum = parseInt(dateDayMatch[1], 10);
    if (dayNum >= 1 && dayNum <= 31) return `hours_${dayNum}`;
  }
  if (/^dates_\d{1,2}$/i.test(raw.replace(/\s+/g, ''))) {
    const dayNum = parseInt(raw.match(/(\d{1,2})$/)?.[1] || '', 10);
    if (dayNum >= 1 && dayNum <= 31) return `hours_${dayNum}`;
  }
  const n = raw
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, '');
  const hoursMatch = raw.match(/hours?\s+worked\s+on[_\s-]+(\d{1,2})/i);
  if (hoursMatch) return `hours_${parseInt(hoursMatch[1], 10)}`;
  if (/name\s+of\s+the\s+employee/.test(n) || /employee.*establishment/.test(n)) return 'name';
  if (/^name$/.test(n) || /employee\s+name/.test(n) || /name\s+of\s+employee/.test(n)) return 'name';
  if (n === 'sex' || n === 'gender') return 'sex';
  if (n === 'age') return 'age';
  if (/employment\s+commence/.test(n) || /time\s+at\s+which\s+employment\s+commence/.test(n)) return 'commence';
  if (/employment\s+cease/.test(n) || /time\s+at\s+which\s+employment\s+cease/.test(n)) return 'cease';
  if (/rest\s+interval/.test(n)) return 'rest';
  if (/total\s+hours/.test(n)) return 'total_hours';
  if (/overtime/.test(n)) return 'overtime';
  if (/days\s+on\s+which/.test(n)) return 'overtime_days';
  return null;
};

/** Form J Register of Employment: title + (See Rule…) + multi-line register text (no S.No column). */
const buildFormJRegisterHeaderFromSheet = ({
  headerRowIndex,
  getMergedAwareCellText,
  jsonData,
  effectiveSheetCols,
  formTitle,
  formSubtitle,
  formReference
}) => {
  if (headerRowIndex <= 0) return null;

  const jLines = [];
  for (let r = 0; r < headerRowIndex; r++) {
    let line = '';
    const maxCols = Math.min(Math.max(effectiveSheetCols || 0, 20), 40);
    for (let c = 0; c < maxCols; c++) {
      const t = String(getMergedAwareCellText(r, c) || '')
        .trim()
        .replace(/\s+/g, ' ');
      if (t.length > line.length) line = t;
    }
    if (!line) {
      line = (jsonData[r] || [])
        .map((cell) => String(cell || '').trim())
        .filter(Boolean)
        .join(' ')
        .replace(/\s+/g, ' ')
        .trim();
    }
    if (line) jLines.push(line);
  }

  const blob = jLines.join(' ').toLowerCase();
  const isFormJ =
    /\bform\s+j\b/i.test(blob) ||
    (/register\s+of\s+employment/i.test(blob) &&
      (/shop\s+or\s+commercial|establishment\s+where\s+opening|week\s+ending/i.test(blob)));

  if (!isFormJ) return null;

  const titleLine =
    jLines.find((l) => /\bform\s+j\b/i.test(l)) || formTitle || 'FORM J';
  const refLine =
    jLines.find((l) => /\[.*see.*rule/i.test(l) || /^\(\s*see\s+rule/i.test(l)) ||
    formReference ||
    '';
  const subtitleLines = jLines.filter((l) => {
    if (l === refLine) return false;
    if (/^\s*form\s+j\s*$/i.test(l)) return false;
    if (/register\s+of\s+employment/i.test(l)) return true;
    if (/establishment\s+where\s+opening|ordinarily\s+uniform/i.test(l)) return true;
    if (/week\s+ending/i.test(l)) return true;
    return false;
  });

  let subtitle = subtitleLines.join('\n');
  if (!subtitle) {
    const parts = [formSubtitle, formReference]
      .map((s) => String(s || '').trim())
      .filter(Boolean);
    subtitle = parts.join('\n');
  }

  return {
    title: titleLine.replace(/\s+/g, ' ').trim(),
    subtitle,
    reference: refLine ? refLine.replace(/\s+/g, ' ').trim() : formReference
  };
};

const shouldPlaceFormJReferenceBeforeSubtitle = (formHeader) => {
  const title = String(formHeader?.title || '').trim();
  const ref = String(formHeader?.reference || '').trim();
  if (!ref || !/\bsee\s+rule/i.test(ref)) return false;
  return (
    /\bform\s+j\b/i.test(title) ||
    /register\s+of\s+employment/i.test(String(formHeader?.subtitle || ''))
  );
};

const normalizeFormJHeaderForDisplay = (formHeader, item, fileName) => {
  if (!formHeader || !isFormJStatutoryContext(item, fileName, formHeader)) return formHeader;

  let subtitle = String(formHeader.subtitle || '').trim();
  const textRows = Array.isArray(formHeader.textRows) ? formHeader.textRows : [];
  const needsMoreLines =
    /register\s+of\s+employment/i.test(subtitle) &&
    !/establishment\s+where\s+opening/i.test(subtitle) &&
    !/week\s+ending/i.test(subtitle);
  if (needsMoreLines) {
    const extra = textRows.filter((line) => {
      const l = String(line || '').toLowerCase();
      return (
        /establishment\s+where\s+opening|ordinarily\s+uniform/i.test(l) ||
        /week\s+ending/i.test(l)
      );
    });
    if (extra.length > 0) subtitle = [subtitle, ...extra].filter(Boolean).join('\n');
  }

  const subtitleNorm = subtitle.replace(/\s+/g, ' ').toLowerCase();
  let wagePeriodText = formHeader.wagePeriodText;
  const wageNorm = String(wagePeriodText || '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (wageNorm && subtitleNorm && (subtitleNorm.includes(wageNorm) || /week\s+ending/i.test(wageNorm))) {
    wagePeriodText = '';
  }

  return {
    ...formHeader,
    subtitle,
    textRows: [],
    wagePeriodText: wagePeriodText || ''
  };
};

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
/** Keep page small so wide day-grid forms (Form Q / muster) stay scrollable after Autofill. */
const FORM_TABLE_PAGE_SIZE = 20;

/**
 * Editable autofill cell — always shows an <input> so values look and feel editable.
 * Paginated modal rows keep DOM size manageable; commits on blur / Enter.
 */
function StatutoryModalEditableCell({
  value,
  readOnly = false,
  onCommit,
  placeholder = '',
  inputStyle = null,
  textAlign = 'left',
}) {
  const [draft, setDraft] = useState(value == null ? '' : String(value));
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    if (!focused) setDraft(value == null ? '' : String(value));
  }, [value, focused]);

  const sharedBox = {
    width: '100%',
    boxSizing: 'border-box',
    ...(inputStyle || {}),
  };

  if (readOnly) {
    const display = value === '' || value == null ? '\u00a0' : String(value);
    return (
      <div
        title={value == null ? '' : String(value)}
        style={{
          ...sharedBox,
          border: '1px solid transparent',
          color: '#374151',
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          cursor: 'default',
          backgroundColor: '#f9fafb',
          textAlign,
        }}
      >
        {display}
      </div>
    );
  }

  return (
    <input
      type="text"
      value={draft}
      placeholder={placeholder}
      title={value == null ? '' : String(value)}
      onChange={(e) => setDraft(e.target.value)}
      onFocus={() => {
        setFocused(true);
        setDraft(value == null ? '' : String(value));
      }}
      onBlur={() => {
        setFocused(false);
        const next = draft;
        if (String(next) !== String(value ?? '') && typeof onCommit === 'function') {
          onCommit(next);
        }
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          e.currentTarget.blur();
        } else if (e.key === 'Escape') {
          e.preventDefault();
          setDraft(value == null ? '' : String(value));
          e.currentTarget.blur();
        }
      }}
      style={{
        ...sharedBox,
        border: '1px solid #d1d5db',
        borderRadius: sharedBox.borderRadius || '4px',
        backgroundColor: 'white',
        color: '#374151',
        textAlign,
      }}
    />
  );
}

const MONTH_ABBR = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const formTableRowHasMeaningfulData = (row) => {
  if (!row || typeof row !== 'object') return false;
  if (Array.isArray(row)) {
    return row.some((v) => v != null && String(v).trim() !== '');
  }
  return Object.values(row).some((v) => v != null && String(v).trim() !== '');
};

/** Ignore template sample rows that only contain serial numbers (1, 2, 3…) without employee data. */
const isStatutoryTemplateColumnIndexRow = (row, headers = []) => {
  if (!row || typeof row !== 'object') return false;
  const hdrList =
    Array.isArray(headers) && headers.length > 0 ? headers.filter(Boolean) : Object.keys(row);
  if (hdrList.length < 4) return false;
  let sequentialHits = 0;
  let filled = 0;
  let allFilledAreNumeric = true;
  for (let i = 0; i < hdrList.length; i += 1) {
    const val = String(row[hdrList[i]] ?? '').trim();
    if (!val) continue;
    filled += 1;
    if (!/^\d{1,2}$/.test(val)) allFilledAreNumeric = false;
    if (/^\d{1,2}$/.test(val) && Number(val) === i + 1) sequentialHits += 1;
  }
  if (filled < 4 || !allFilledAreNumeric) return false;
  return sequentialHits >= Math.min(4, filled);
};

const filterStatutoryTemplateColumnIndexRows = (rows, headers = []) => {
  if (!Array.isArray(rows)) return [];
  return rows.filter((row) => !isStatutoryTemplateColumnIndexRow(row, headers));
};

/** Excel row under Form U headers: 1,2,3… column index strip (not employee sample data). */
const excelFormURowLooksLikeColumnIndexRow = (worksheet, rowNum, startCol, cellToString) => {
  if (!worksheet || rowNum < 1 || startCol < 1) return false;
  const toStr =
    typeof cellToString === 'function'
      ? cellToString
      : (val) => (val == null ? '' : String(val));
  let sequentialHits = 0;
  let filled = 0;
  let allFilledAreSmallIntegers = true;
  for (let c = startCol; c <= startCol + 17; c += 1) {
    const raw = String(toStr(worksheet.getCell(rowNum, c)?.value) || '').trim();
    if (!raw) continue;
    filled += 1;
    if (!/^\d{1,2}$/.test(raw)) {
      allFilledAreSmallIntegers = false;
      break;
    }
    if (Number(raw) === c - startCol + 1) sequentialHits += 1;
  }
  return filled >= 4 && allFilledAreSmallIntegers && sequentialHits >= Math.min(4, filled);
};

/** Template sample employee row under Form U headers (e.g. Sangamesh / VE1131). */
const excelFormURowLooksLikeEmployeeSampleRow = (
  worksheet,
  rowNum,
  headerColMap,
  startCol,
  cellToString
) => {
  if (!worksheet || rowNum < 1) return false;
  const toStr =
    typeof cellToString === 'function'
      ? cellToString
      : (val) => (val == null ? '' : String(val));
  for (const [col, headerText] of headerColMap.entries()) {
    if (!/name\s+of\s+the\s+employee|name\s+of\s+employee/.test(headerText)) continue;
    const v = String(toStr(worksheet.getCell(rowNum, col)?.value) || '').trim();
    if (/[a-z]{3,}/i.test(v)) return true;
  }
  for (let c = startCol; c <= startCol + 7; c += 1) {
    const v = String(toStr(worksheet.getCell(rowNum, c)?.value) || '').trim();
    if (!v || /^\d+$/.test(v)) continue;
    if (/\bVE\d{3,}\b/i.test(v)) return true;
    if (/^(male|female)$/i.test(v)) return true;
    if (/[a-z]{4,}/i.test(v)) return true;
  }
  return false;
};

const draftTableRowHasSubstantiveData = (row, headers = []) => {
  if (!formTableRowHasMeaningfulData(row)) return false;
  if (isStatutoryTemplateColumnIndexRow(row, headers)) return false;
  if (isStatutoryTableFooterOrSignatoryRow(row, headers)) return false;
  if (formTablePageHasEmployeeAutofillData(row, headers)) return true;
  let substantiveCells = 0;
  Object.entries(row || {}).forEach(([key, v]) => {
    const val = String(v ?? '').trim();
    if (!val) return;
    const k = String(key || '').toLowerCase().replace(/\s+/g, ' ').trim();
    if (/^(s\.?\s*no\.?|serial(\s+number)?|sr\.?\s*no\.?)$/.test(k)) return;
    if (/^\d{1,3}$/.test(val) && /^(s\.?\s*no\.?|serial|sr\.?\s*no\.?)/.test(k)) return;
    substantiveCells += 1;
    if (/[a-z]{2,}/i.test(val)) substantiveCells += 1;
  });
  return substantiveCells >= 1;
};

/** Excel footer / signatory block must not appear as editable table rows when opening saved drafts. */
const isStatutoryTableFooterOrSignatoryRow = (row, headers = []) => {
  const vals = collectFixedAggregateRowValues(row, headers);
  if (vals.length === 0) return false;
  if (vals.some((v) => cellValueIsSignatureFooterText(v))) return true;
  const joined = vals.join(' ').toLowerCase();
  if (/for\s*\(\s*company/.test(joined)) return true;
  if (/signature\s+of\s+(the\s+)?(employee|workman|worker|employer|manager)/.test(joined)) return true;
  if (/authorised\s+signatory|authorized\s+signatory/.test(joined)) return true;
  return false;
};

const filterStatutoryDraftTableRows = (rows, headers = [], { trustSavedSnapshot = false } = {}) => {
  if (!Array.isArray(rows)) return [];
  return rows.filter((row) => {
    if (isStatutoryTableFooterOrSignatoryRow(row, headers)) return false;
    if (trustSavedSnapshot) return formTableRowHasMeaningfulData(row);
    return draftTableRowHasSubstantiveData(row, headers);
  });
};

/** Paginated autofill: S.No-only template rows must not skip fetching employee + attendance data. */
/** Fast paginated autofill: show employee names in the grid before payroll/attendance enrichment finishes. */
const buildFastPaginatedStatutoryGridRows = (
  employees,
  headers,
  employeePageOffset,
  helpers = {}
) => {
  const list = Array.isArray(employees) ? employees : [];
  const hdrs = Array.isArray(headers) ? headers : [];
  const {
    sanitizeValue = (v) => String(v ?? '').trim(),
    getEmployeeLookupName = () => '',
    getFallbackName = () => '',
    getFallbackEmployeeId = () => '',
    getFallbackWorkerId = () => '',
    getFallbackFatherOrSpouse = () => '',
    getPayrollEmployeeId = () => '',
    firstPresent = (...vals) => vals.find((v) => v != null && String(v).trim() !== '') ?? '',
    formatStatutoryDateDisplay = (v) => String(v ?? '').trim(),
    getEmployeeDateofjoiningRaw = () => '',
  } = helpers;
  return list.map((empItem, index) => {
    const globalRowIndex = employeePageOffset + index;
    const emp = empItem?.Employee || empItem?.employee || empItem || {};
    const row = {};
    hdrs.forEach((header) => {
      row[header] = '';
    });
    const lookupName = getEmployeeLookupName(emp) || getFallbackName(emp);
    row.__employeeLookupName = lookupName;
    row.__employeeLookupId = firstPresent(
      getPayrollEmployeeId(emp),
      getFallbackEmployeeId(emp),
      getFallbackWorkerId(emp)
    );
    hdrs.forEach((header) => {
      const hl = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
      if (!hl) return;
      if (
        isWageRegisterSerialHeaderCell(header) ||
        /^(s\.?\s*no\.?|serial(\s+number)?|sr\.?\s*no\.?)$/.test(hl)
      ) {
        row[header] = String(globalRowIndex + 1);
        return;
      }
      if (
        hl.includes('name') &&
        (hl.includes('employee') ||
          hl.includes('worker') ||
          hl.includes('workman') ||
          /name of th/.test(hl) ||
          hl === 'name')
      ) {
        row[header] = sanitizeValue(lookupName);
        return;
      }
      if (hl.includes('father') || hl.includes('husband')) {
        row[header] = sanitizeValue(getFallbackFatherOrSpouse(emp));
        return;
      }
      if (hl.includes('gender') || hl === 'sex' || hl.includes('male/female')) {
        row[header] = sanitizeValue(emp.Sex || emp.Gender || emp['Gender'] || '');
        return;
      }
      if (hl.includes('designation') || hl.includes('department')) {
        row[header] = sanitizeValue(emp.Designation || emp['Designation'] || emp.Department || '');
        return;
      }
      if (
        hl.includes('join') ||
        hl.includes('entry into employment') ||
        (hl.includes('period') && hl.includes('employ') && hl.includes('from'))
      ) {
        row[header] = sanitizeValue(
          formatStatutoryDateDisplay(getEmployeeDateofjoiningRaw(emp) || emp.Dateofjoining || '')
        );
        return;
      }
      if (hl.includes('period') && hl.includes('employ') && hl.includes('to') && !hl.includes('from')) {
        row[header] = sanitizeValue(formatStatutoryDateDisplay(getEmployeeDateofexitRaw(emp)));
        return;
      }
      if (isPeopleEsicRegistrationHeader(header)) {
        row[header] = sanitizeValue(resolvePeopleEsicRegistrationNumber(emp));
        return;
      }
      if (isPeopleEpfUanRegistrationHeader(header)) {
        row[header] = sanitizeValue(emp.UAN_Number || emp['UAN Number'] || emp.UAN || emp['UAN No.'] || '');
      }
    });
    return row;
  });
};

const formTablePageHasEmployeeAutofillData = (row, headers = []) => {
  if (!row || typeof row !== 'object') return false;
  if (isStatutoryTemplateColumnIndexRow(row, headers)) return false;
  for (let i = 0; i < headers.length; i += 1) {
    const header = headers[i];
    const k = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
    if (!k) continue;
    const isWorkerName =
      (k.includes('worker') || k.includes('workman') || k.includes('workmen')) && k.includes('name');
    const isWorkerId =
      (k.includes('worker') || k.includes('workman')) &&
      (k.includes('identity') || k.includes('identify') || k.includes('id'));
    const isEmpId = /^emp\s*id$/.test(k) || (k.includes('emp') && k.includes('id'));
    const isEmployeeName = k.includes('employee') && k.includes('name');
    const cellVal = String(row[header] || '').trim();
    if ((isWorkerName || isWorkerId || isEmpId || isEmployeeName) && cellVal && /[a-zA-Z]{2,}/.test(cellVal)) {
      return true;
    }
  }
  return Object.entries(row).some(([key, v]) => {
    if (v == null || String(v).trim() === '') return false;
    const k = String(key || '').toLowerCase().replace(/\s+/g, ' ').trim();
    if (/^(s\.?\s*no\.?|serial(\s+number)?|sr\.?\s*no\.?)$/.test(k)) return false;
    if (/^\d{1,2}$/.test(String(key || '').trim())) return false;
    if (/^(10|dates)[_-]\d{1,2}$/i.test(String(key || '').trim())) return false;
    if (/^column\s+\d+$/i.test(k)) return false;
    return /[a-zA-Z]{2,}/.test(String(v));
  });
};

const countMeaningfulFormTableRows = (rows) => {
  if (!Array.isArray(rows)) return 0;
  return rows.filter((row) => formTableRowHasMeaningfulData(row)).length;
};

/** Zoho People `bookedAndBalance` expects `from` / `to` as DD-Mon-YYYY (aligned with Statutory month picker). */
function zohoBookedBalanceRangeForUiMonth(selectedMonthStr) {
  const now = new Date();
  let monthIdx = now.getMonth();
  const idx = MONTH_NAMES.findIndex((m) =>
    m.toLowerCase().startsWith(String(selectedMonthStr || '').toLowerCase().trim())
  );
  if (idx >= 0) monthIdx = idx;
  const year = now.getFullYear();
  const first = new Date(year, monthIdx, 1);
  const last = new Date(year, monthIdx + 1, 0);
  const dd = (n) => String(n).padStart(2, '0');
  const fromDate = `${dd(first.getDate())}-${MONTH_ABBR[first.getMonth()]}-${first.getFullYear()}`;
  const toDate = `${dd(last.getDate())}-${MONTH_ABBR[last.getMonth()]}-${last.getFullYear()}`;
  return { fromDate, toDate };
}

function resolveFormQMonthEndDateForAutofill(selectedMonthStr, formatDate = null) {
  const now = new Date();
  let monthIdx = now.getMonth();
  const idx = MONTH_NAMES.findIndex((m) =>
    m.toLowerCase().startsWith(String(selectedMonthStr || '').toLowerCase().trim())
  );
  if (idx >= 0) monthIdx = idx;
  const year = now.getFullYear();
  const last = new Date(year, monthIdx + 1, 0);
  const iso = `${year}-${String(monthIdx + 1).padStart(2, '0')}-${String(last.getDate()).padStart(2, '0')}`;
  if (typeof formatDate === 'function') {
    return formatDate(iso) || iso;
  }
  return iso;
}

function normalizeLooseHeaderText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** EPF/UAN registration column — not MP Form XVIII PF deduction amount column. */
function isPeopleEpfUanRegistrationHeader(header) {
  if (isFormXVIIIMPPayrollDeductionHeader(header)) return false;
  const s = normalizeLooseHeaderText(header);
  if (/\bepf\b/.test(s) && (s.includes('no') || s.includes('uan') || s.includes('number') || s.includes('account'))) {
    return true;
  }
  if (s.includes('provident') && (s.includes('no') || s.includes('fund') || s.includes('uan'))) return true;
  if (/\buan\b/.test(s) && (s.includes('no') || s.includes('number'))) return true;
  if (/\bpf\b/.test(s) && (s.includes('no') || s.includes('uan') || s.includes('account') || s.includes('number'))) {
    return true;
  }
  return false;
}

/** ESIC registration number column — not MP Form XVIII ESIC deduction amount column. */
function isPeopleEsicRegistrationHeader(header) {
  if (isFormXVIIIMPPayrollDeductionHeader(header)) return false;
  const s = normalizeLooseHeaderText(header);
  // "designation" contains the letters "esi" — never treat job title columns as ESIC.
  if (/designation|nature\s+of\s+work/.test(s)) return false;
  if (s.includes('esic') && (s.includes('no') || s.includes('number') || s.includes('corporation'))) return true;
  if (/\besi\b/.test(s) && (s.includes('no') || s.includes('number') || s.includes('corporation'))) return true;
  if (s.includes('insurance') && (s.includes('corporation') || s.includes('no'))) return true;
  return false;
}

/** Resolve People ESIC / ESI registration number for Form 12 / Form U style columns. */
function resolvePeopleEsicRegistrationNumber(emp) {
  if (!emp || typeof emp !== 'object') return '';
  return pickFirstNonEmptyString(
    emp["Employee's State Insurance Corporation No."],
    emp["Employee's State Insurance Corporation No"],
    emp.ESI_Number,
    emp['ESI Number'],
    emp.ESINumber,
    emp.ESIC_Number,
    emp['ESIC Number'],
    emp['ESIC No.'],
    emp['ESIC No'],
    emp.ESICNo,
    emp.esicNo,
    emp.ESI_No,
    emp['ESI No'],
    emp.Insurance_Number,
    emp['Insurance Number'],
    emp.InsuranceNo,
    findNestedValueByNormalizedKey(emp, 'esinumber'),
    findNestedValueByNormalizedKey(emp, 'esicnumber'),
    findNestedValueByKeyPattern(emp, /esi.*no|esic.*no|insurance.*no/i)
  );
}

function isFormDRemunerationHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return (
    s.includes('components of remuneration') ||
    s.includes('rate of remuneration') ||
    s.includes('basic wages') ||
    s.includes('basic wage') ||
    s.includes('wages or salary') ||
    (s.includes('basic') && s.includes('salary')) ||
    s.includes('dearness') ||
    /\bda\b/.test(s) ||
    s.includes('house rent allowance') ||
    s.includes('hra') ||
    (s.includes('house') && s.includes('rent')) ||
    s.includes('other allowance') ||
    (s.includes('other') && s.includes('allowance'))
  );
}

function isLikelyFormDCategoryHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return s.includes('category of workers') || s.includes('category of worker');
}

function isLikelyFormDRowCountHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return (
    s.includes('noofmenemployed') ||
    s.includes('numberofmenemployed') ||
    s.includes('men employed') ||
    s.includes('male employed') ||
    s.includes('noofwomenemployed') ||
    s.includes('numberofwomenemployed') ||
    s.includes('women employed') ||
    s.includes('female employed')
  );
}

function isFormDAutofillHeaders(tableHeaders) {
  if (!Array.isArray(tableHeaders) || tableHeaders.length === 0) return false;
  const hasFormDCounts =
    tableHeaders.some((h) => isLikelyFormDCategoryHeader(h)) ||
    tableHeaders.some((h) => isLikelyFormDRowCountHeader(h));
  const hasRateOfRemuneration = tableHeaders.some((h) =>
    normalizeLooseHeaderText(h).includes('rate of remuneration')
  );
  const hasComponentsOfRemuneration = tableHeaders.some((h) =>
    normalizeLooseHeaderText(h).includes('components of remuneration')
  );
  const hasBriefDescription = tableHeaders.some((h) => {
    const s = normalizeLooseHeaderText(h);
    return (
      (s.includes('brief') && s.includes('description') && s.includes('work')) ||
      s.includes('brief description of work')
    );
  });
  // Require Form D structural markers. Basic/DA/HRA/Other alone appear on many wage forms
  // (e.g. AP Form XXVI Letter of Appointment) and must not route those through Form D export.
  return (
    tableHeaders.some((h) => isFormDRemunerationHeader(h)) &&
    (hasFormDCounts || hasRateOfRemuneration || hasComponentsOfRemuneration || hasBriefDescription)
  );
}

function resolveFormDEmployeeGender(emp) {
  const raw = String(
    emp?.Sex ||
      emp?.Gender ||
      emp?.gender ||
      emp?.['Sex'] ||
      emp?.['Gender.displayValue'] ||
      emp?.['Gender'] ||
      ''
  )
    .trim()
    .toLowerCase();
  if (!raw) return '';
  if (raw === 'm' || raw === 'male' || raw.startsWith('male')) return 'male';
  if (raw === 'f' || raw === 'female' || raw.startsWith('female')) return 'female';
  return raw;
}

function isFormDBriefDescriptionOfWorkHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return (
    (s.includes('brief') && s.includes('description') && s.includes('work')) ||
    s.includes('brief description of work')
  );
}

function isFormDNoMenEmployedHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return (
    s.includes('men employed') ||
    s.includes('male employed') ||
    (s.includes('no') && s.includes('men') && s.includes('employed')) ||
    (s.includes('number') && s.includes('men') && s.includes('employed'))
  );
}

function isFormDNoWomenEmployedHeader(h) {
  const s = normalizeLooseHeaderText(h);
  return (
    s.includes('women employed') ||
    s.includes('female employed') ||
    s.includes('noofwomen') ||
    s.includes('no.of women') ||
    (s.includes('no') && s.includes('women') && s.includes('employed')) ||
    (s.includes('number') && s.includes('women') && s.includes('employed'))
  );
}

function formDHeaderSubLabel(h) {
  const raw = String(h || '');
  const m = raw.match(/^(.+)_([\s\S]+)$/);
  if (!m) return normalizeLooseHeaderText(raw);
  const parentNorm = normalizeLooseHeaderText(m[1]);
  if (parentNorm.includes('components') && parentNorm.includes('remuneration')) {
    return normalizeLooseHeaderText(m[2]);
  }
  return normalizeLooseHeaderText(raw);
}

function isFormDBasicSalaryHeader(h) {
  const s = formDHeaderSubLabel(h);
  return (
    s.includes('basic wages') ||
    s.includes('basic wage') ||
    s.includes('wages or salary') ||
    (s.includes('basic') && s.includes('salary'))
  );
}

function isFormDHouseRentAllowanceHeader(h) {
  const s = formDHeaderSubLabel(h);
  return (
    s.includes('house rent allowance') ||
    /\bhra\b/.test(s) ||
    s.includes('hra fbp') ||
    (s.includes('house') && s.includes('rent'))
  );
}

function isFormDOtherAllowanceHeader(h) {
  const s = formDHeaderSubLabel(h);
  if (s.includes('cash') && (s.includes('concessional') || s.includes('commodities'))) {
    return false;
  }
  return s.includes('other allowance') || (s.includes('other') && s.includes('allowance'));
}

function formDRowHasPayrollWageValues(row, headers) {
  if (!row || typeof row !== 'object' || !Array.isArray(headers)) return false;
  return headers.some((h) => {
    if (
      !isFormDBasicSalaryHeader(h) &&
      !isFormDHouseRentAllowanceHeader(h) &&
      !isFormDOtherAllowanceHeader(h)
    ) {
      return false;
    }
    const v = String(row[h] ?? '').trim();
    return v && v !== '0' && !/^enter\b/i.test(v);
  });
}

/** Form D download: gender counts alone are not enough — refresh when wage columns are still blank. */
function formDDownloadNeedsPayrollRefresh(rows, headers) {
  if (!isFormDAutofillHeaders(headers) || !Array.isArray(rows) || rows.length === 0) return false;
  return rows.some((row) => {
    if (!row || typeof row !== 'object') return false;
    const hasRowStructure =
      headers.some((h) => isFormDBriefDescriptionOfWorkHeader(h) && String(row[h] ?? '').trim()) ||
      headers.some((h) => isFormDNoMenEmployedHeader(h) && String(row[h] ?? '').trim()) ||
      headers.some((h) => isFormDNoWomenEmployedHeader(h) && String(row[h] ?? '').trim());
    return hasRowStructure && !formDRowHasPayrollWageValues(row, headers);
  });
}

function formDHeaderMatchesExcelCellLabel(headerKey, excelLabel) {
  const excel = normalizeLooseHeaderText(String(excelLabel || '').replace(/\r?\n/g, ' '));
  if (!excel) return false;
  const hdr = String(headerKey || '');
  const split = hdr.match(/^(.+)_([\s\S]+)$/);
  if (split) {
    const parentNorm = normalizeLooseHeaderText(split[1]);
    const subNorm = normalizeLooseHeaderText(split[2]);
    if (parentNorm.includes('components') && parentNorm.includes('remuneration')) {
      return excel === subNorm || excel.includes(subNorm) || subNorm.includes(excel);
    }
  }
  const bare = formDHeaderSubLabel(hdr);
  return excel === bare || excel.includes(bare) || bare.includes(excel);
}

function applyFormDGenderEmployedCounts(row, emp, headers) {
  if (!row || !emp || !Array.isArray(headers)) return;
  const gender = resolveFormDEmployeeGender(emp);
  const menHeader = headers.find(isFormDNoMenEmployedHeader);
  const womenHeader = headers.find(isFormDNoWomenEmployedHeader);
  if (gender === 'male') {
    if (menHeader) row[menHeader] = '1';
    if (womenHeader) row[womenHeader] = '';
  } else if (gender === 'female') {
    if (womenHeader) row[womenHeader] = '1';
    if (menHeader) row[menHeader] = '';
  } else {
    if (menHeader) row[menHeader] = '';
    if (womenHeader) row[womenHeader] = '';
  }
}

const FORM_A_AUTOFILL_TABLE_HEADERS = [
  'S.No.',
  'Name of the woman and age',
  'Age',
  'Name of husband or father',
  'Nature of Work',
  'Date on which employed',
  'Dates with month and year in which employed',
  'Date of giving notice of Pregnancy',
  'Date of giving notice of Delivery',
  'Date of Production of Proof of Birth',
  'Date of production of proof of death if any',
  'Date on which payment was made',
  'Details of Payment',
  'a) Maternity Benefit',
  'b) Subsequent Payment',
  'c) Bonus'
];

function resolveFormATableHeaders(tableHeaders) {
  const list = Array.isArray(tableHeaders)
    ? tableHeaders.map((h) => String(h || '').trim()).filter(Boolean)
    : [];
  const joined = list.map((h) => String(h || '').toLowerCase()).join('\n');
  if (/row\s+labels|count\s+of\s+(male|female)/.test(joined)) {
    return [...FORM_A_AUTOFILL_TABLE_HEADERS];
  }
  if (
    list.length >= 6 &&
    (/name\s+of\s+the\s+woman/.test(joined) ||
      (/woman/.test(joined) && /\bage\b/.test(joined)) ||
      (/husband\s+or\s+father/.test(joined) && /nature\s+of\s+work/.test(joined)))
  ) {
    return list;
  }
  return [...FORM_A_AUTOFILL_TABLE_HEADERS];
}

function isFormATableLayoutFormHeader(formHeader) {
  return !!formHeader?.formATableLayout;
}

const FORM_A_ESTABLISHMENT_HEADER_KEYS = new Set([
  'form_a_establishment_name',
  'form_a_establishment_address'
]);

function classifyFormATableColumn(header) {
  const raw = String(header || '').replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim();
  const s = normalizeLooseHeaderText(header)
    .replace(/^\(?\d+\)?[.\s:-]*/, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (/^s\.?\s*no/.test(s) || s === 'serial no' || s === 'sl no') return 'sno';
  if (s.includes('woman') && (s.includes('age') || s.includes('name'))) return 'womanAge';
  if (/^age\s*:?$/.test(s) || s === 'age') return 'age';
  if ((s.includes('husband') || s.includes('father')) && !s.includes('proof')) return 'husbandFather';
  if (s.includes('nature') && s.includes('work')) return 'natureOfWork';
  if (s.includes('proof') && s.includes('birth')) return 'proofBirth';
  if (s.includes('proof') && s.includes('death')) return 'proofDeath';
  if (s.includes('pregnancy') && (s.includes('notice') || s.includes('giving'))) return 'noticePregnancy';
  if (s.includes('delivery') && (s.includes('notice') || s.includes('giving'))) return 'noticeDelivery';
  if (
    (s.includes('days') && s.includes('employed') && !s.includes('laid') && !s.includes('not')) ||
    (s.includes('month') && (s.includes('employed') || s.includes('laid') || s.includes('not employed'))) ||
    (s.includes('dates') && s.includes('month') && s.includes('employed'))
  ) {
    return 'datesEmployed';
  }
  if (s.includes('laid') && s.includes('off')) return 'datesEmployed';
  if (s.includes('not') && s.includes('employed') && s.includes('days')) return 'datesEmployed';
  if (s.includes('date') && s.includes('employed') && !s.includes('month') && !s.includes('laid')) {
    return 'dateEmployed';
  }
  if (s.includes('details') && s.includes('payment')) return 'paymentDetails';
  if (s.includes('payment') && s.includes('made') && !s.includes('amount') && !s.includes('details')) {
    return 'paymentDate';
  }
  if (/^\s*a\)?\s*maternity\s+benefit/i.test(raw) || (s.includes('maternity') && s.includes('benefit') && !s.includes('amount') && !s.includes('date'))) {
    return 'maternityBenefit';
  }
  if (s.includes('maternity') && s.includes('benefit') && s.includes('amount')) return 'maternityAmount';
  if (s.includes('maternity') && s.includes('benefit') && s.includes('date')) return 'maternityDate';
  if (/^\s*b\)?\s*subsequent/i.test(raw) || (s.includes('subsequent') && s.includes('payment') && !s.includes('amount') && !s.includes('date'))) {
    return 'subsequentPayment';
  }
  if (s.includes('subsequent') && s.includes('payment') && s.includes('amount')) return 'subsequentAmount';
  if (s.includes('subsequent') && s.includes('payment') && s.includes('date')) return 'subsequentDate';
  if (/^\s*c\)?\s*bonus/i.test(raw) || (s === 'bonus' || (s.includes('bonus') && !s.includes('amount') && !s.includes('date')))) {
    return 'bonus';
  }
  if (s.includes('bonus') && s.includes('amount')) return 'bonusAmount';
  if (s.includes('bonus') && s.includes('date')) return 'bonusDate';
  if (s.includes('section') && /\b9\b/.test(s) && s.includes('amount')) return 'leave9Amount';
  if (s.includes('section') && /\b9\b/.test(s) && s.includes('date')) return 'leave9Date';
  if (s.includes('section') && /\b10\b/.test(s) && s.includes('amount')) return 'leave10Amount';
  if (s.includes('section') && /\b10\b/.test(s) && s.includes('date')) return 'leave10Date';
  return '';
}

function findFormATableHeader(headers, columnKind) {
  if (!Array.isArray(headers)) return null;
  return headers.find((header) => classifyFormATableColumn(header) === columnKind) || null;
}

function getFormAEmployeeNameCandidates(emp) {
  if (!emp || typeof emp !== 'object') return [];
  const first = String(emp.FirstName || emp['FirstName'] || emp.firstName || '').trim();
  const last = String(emp.LastName || emp['LastName'] || emp.lastName || '').trim();
  const full = [first, last].filter(Boolean).join(' ').trim();
  const candidates = [];
  if (full) candidates.push(full.toLowerCase());
  if (first) candidates.push(first.toLowerCase());
  return candidates;
}

function buildFormAAutofillTableRow(emp, index, headers, extras = {}) {
  const row = {};
  (headers || []).forEach((header) => {
    row[header] = '';
  });
  const namePart =
    [emp?.FirstName || emp?.['FirstName'] || '', emp?.LastName || emp?.['LastName'] || '']
      .map((v) => String(v || '').trim())
      .filter(Boolean)
      .join(' ') ||
    emp?.Name ||
    emp?.['Employee Name'] ||
    '';
  const agePart = computeAgeFromDobForFormA(emp);
  const hasStandaloneAgeCol = (headers || []).some((h) => classifyFormATableColumn(h) === 'age');
  const womanValue = namePart
    ? hasStandaloneAgeCol
      ? namePart
      : agePart
        ? `${namePart} (${agePart})`
        : namePart
    : '';
  const husbandValue =
    emp?.Father_s_Name ||
    emp?.['Father_s_Name'] ||
    emp?.Father_Name ||
    emp?.['Father_Name'] ||
    emp?.Spouse_Name ||
    emp?.['Spouse_Name'] ||
    '';
  const natureValue =
    emp?.Designation ||
    emp?.designation ||
    emp?.['Designation.displayValue'] ||
    emp?.['Nature of Work'] ||
    '';
  const formatDate = (raw) => {
    const value = String(raw || '').trim();
    if (!value) return '';
    const d = parseFlexibleStatutoryDate(value) || parseFlexibleEmployeeDate(value);
    if (!d || Number.isNaN(d.getTime())) return value;
    const dd = String(d.getDate()).padStart(2, '0');
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    return `${dd}-${mm}-${d.getFullYear()}`;
  };
  const pickText = (patterns) => {
    if (!emp || typeof emp !== 'object') return '';
    const keys = Object.keys(emp);
    for (let i = 0; i < patterns.length; i += 1) {
      const re = patterns[i];
      const hit = keys.find((k) => re.test(String(k || '').replace(/[^a-z0-9]/gi, ' ')));
      if (hit && emp[hit] != null && String(emp[hit]).trim() !== '') return String(emp[hit]).trim();
    }
    return '';
  };
  const dojRaw =
    pickText([/dateofjoining/i, /date_of_joining/i, /joiningdate/i, /doj/i]) ||
    String(
      emp?.Dateofjoining ||
        emp?.['Dateofjoining'] ||
        emp?.['Date of Joining'] ||
        emp?.Date_of_Joining ||
        ''
    ).trim();
  const maternityValue = extras.maternityAmount || extras.maternityBenefit || '';
  const valuesByKind = {
    sno: String(index + 1),
    womanAge: womanValue,
    age: agePart || '',
    husbandFather: husbandValue,
    natureOfWork: natureValue,
    dateEmployed: formatDate(dojRaw),
    noticePregnancy: formatDate(
      pickText([/pregnancy.*notice/, /notice.*pregnancy/, /pregnan.*notice/])
    ),
    noticeDelivery: formatDate(
      pickText([/delivery.*notice/, /notice.*delivery/, /deliver.*notice/])
    ),
    proofBirth: formatDate(pickText([/proof.*birth/, /birth.*proof/, /date.*birth.*proof/])),
    proofDeath: formatDate(pickText([/proof.*death/, /death.*proof/])),
    datesEmployed: extras.datesEmployedSummary || '',
    paymentDetails: extras.paymentDetails || '',
    maternityBenefit: maternityValue,
    maternityAmount: maternityValue,
    subsequentPayment: extras.subsequentPayment || '',
    bonus: extras.bonus || '',
    paymentDate: extras.paymentDate || '',
  };
  (headers || []).forEach((header) => {
    const kind = classifyFormATableColumn(header);
    if (kind && valuesByKind[kind] != null && valuesByKind[kind] !== '') {
      row[header] = valuesByKind[kind];
    }
  });
  return row;
}

function isFemaleEmployeeForFormA(empItem) {
  return resolveFormDEmployeeGender(unwrapStatutoryAutofillEmployee(empItem)) === 'female';
}

function filterFemaleEmployeesForFormA(employees) {
  if (!Array.isArray(employees)) return [];
  return employees.filter(isFemaleEmployeeForFormA);
}

function buildFormAAutofillTableHeaders() {
  return [...FORM_A_AUTOFILL_TABLE_HEADERS];
}

function isFormAEstablishmentHeaderField(field) {
  return FORM_A_ESTABLISHMENT_HEADER_KEYS.has(String(field?.key || '').trim());
}

function shouldShowFormAHeaderFieldInAutofillModal(formHeader, field, tableHeaders) {
  if (shouldHideFormAHeaderField(formHeader, field)) return false;
  if (
    (isFormATableLayoutFormHeader(formHeader) ||
      (isFormAHeaderFieldLayoutFormHeader(formHeader) &&
        Array.isArray(tableHeaders) &&
        tableHeaders.length > 0))
  ) {
    return isFormAEstablishmentHeaderField(field);
  }
  return true;
}

function computeAgeFromDobForFormA(emp) {
  if (!emp || typeof emp !== 'object') return '';
  const dobRaw =
    emp.Date_of_birth ||
    emp['Date_of_birth'] ||
    emp.DateofBirth ||
    emp['Date of Birth'] ||
    emp['DateofBirth'] ||
    '';
  const dob = parseFlexibleStatutoryDate(dobRaw) || parseFlexibleEmployeeDate(dobRaw);
  if (dob && !Number.isNaN(dob.getTime())) {
    const today = new Date();
    let age = today.getFullYear() - dob.getFullYear();
    const md = today.getMonth() - dob.getMonth();
    if (md < 0 || (md === 0 && today.getDate() < dob.getDate())) age -= 1;
    if (age >= 0 && age < 120) return String(age);
  }
  const direct = emp.Age || emp['Age'] || emp.age || emp['Employee Age'] || '';
  return direct !== '' && direct != null ? String(direct).trim() : '';
}

const pickFirstNonEmptyString = (...values) => {
  for (let i = 0; i < values.length; i += 1) {
    const s = String(values[i] ?? '').trim();
    if (s) return s;
  }
  return '';
};

function resolveStatutoryFormNameTitleLine(value) {
  const t = String(value || '').trim();
  if (!t) return '';
  const first = t.split('\n')[0]?.trim() || '';
  return first.replace(/\.xlsx$/i, '').replace(/_/g, ' ').trim();
}

function resolveStatutoryFormNameFromFileLabel(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return raw.replace(/\.xlsx$/i, '').replace(/[/\\?%*:|"<>]/g, '_').trim();
}

/** Resolve display form name for StatutoryData save/fetch (Form 10, Form A, Form 12, etc.). */
function resolveStatutoryFormNameForDatastore(item, extras = {}) {
  const {
    resolvedItem,
    formHeader,
    formFileModalData,
    autofillItem,
    parsedFormHeader,
    fileName
  } = extras;
  return pickFirstNonEmptyString(
    item?.formName,
    item?.FormName,
    resolvedItem?.formName,
    resolvedItem?.FormName,
    autofillItem?.formName,
    autofillItem?.FormName,
    formFileModalData?.item?.formName,
    formFileModalData?.item?.FormName,
    resolveStatutoryFormNameTitleLine(formHeader?.title),
    resolveStatutoryFormNameTitleLine(parsedFormHeader?.title),
    resolveStatutoryFormNameTitleLine(formFileModalData?.parsedFormHeader?.title),
    item?.description,
    item?.Description,
    formFileModalData?.item?.description,
    formFileModalData?.item?.Description,
    resolveStatutoryFormNameFromFileLabel(formFileModalData?.formFileName),
    resolveStatutoryFormNameFromFileLabel(formFileModalData?.fileName),
    resolveStatutoryFormNameFromFileLabel(fileName)
  );
}

function withStatutoryFormNameFields(payload, formName) {
  const name = canonicalStatutoryDataFormName(formName) || String(formName || '').trim();
  if (!payload || typeof payload !== 'object') return payload;
  if (!name) return payload;
  return { ...payload, formName: name, FormName: name };
}

const findNestedValueByNormalizedKey = (obj, targetNormalizedKey, depth = 0) => {
  if (!obj || typeof obj !== 'object' || depth > 5) return '';
  const entries = Object.entries(obj);
  for (let i = 0; i < entries.length; i += 1) {
    const [k, v] = entries[i];
    const nk = String(k || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    if (nk === targetNormalizedKey) {
      if (v != null && String(v).trim() !== '') return String(v).trim();
      const dv = obj[`${k}.displayValue`];
      if (dv != null && String(dv).trim() !== '') return String(dv).trim();
    }
  }
  for (let i = 0; i < entries.length; i += 1) {
    const [, v] = entries[i];
    if (v && typeof v === 'object') {
      const nested = findNestedValueByNormalizedKey(v, targetNormalizedKey, depth + 1);
      if (nested) return nested;
    }
  }
  return '';
};

const tryParseAttendanceJson = (val) => {
  if (!val) return null;
  if (typeof val === 'object') return val;
  if (typeof val !== 'string') return null;
  const s = String(val).trim();
  if (!s) return null;
  try {
    return JSON.parse(s);
  } catch (_) {
    return null;
  }
};

const getAttendanceRecordEmployeeMeta = (obj) => {
  if (!obj || typeof obj !== 'object') return null;
  const parsed = tryParseAttendanceJson(obj.employeeDetails) || obj.employeeDetails;
  return parsed && typeof parsed === 'object' ? parsed : null;
};

const expandAttendanceLookupIdVariants = (raw) => {
  const s = String(raw || '').trim();
  if (!s || s === '-') return [];
  const variants = new Set([s, s.toLowerCase(), s.replace(/\s+/g, ''), s.replace(/\s+/g, '').toLowerCase()]);
  const noLead = s.replace(/^0+/, '') || '0';
  variants.add(noLead);
  variants.add(noLead.toLowerCase());
  return Array.from(variants).filter(Boolean);
};

/** Zoho getUserReport uses "16-Mar-2020 09:20 AM" on FirstIn/LastOut as well as plain "09:20 AM". */
const parseAttendanceTimeToMinutes = (raw) => {
  const value = String(raw || '').trim();
  if (!value || value === '-') return null;
  const zohoDt = value.match(/\b(\d{1,2}):(\d{2})\s*(am|pm)\b/i);
  if (zohoDt) {
    let hh = Number(zohoDt[1]);
    const mm = Number(zohoDt[2]);
    const meridiem = zohoDt[3].toLowerCase();
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;
    if (meridiem === 'pm' && hh < 12) hh += 12;
    if (meridiem === 'am' && hh === 12) hh = 0;
    return hh * 60 + mm;
  }
  const m24 = value.match(/^(\d{1,2}):(\d{2})$/);
  if (m24) {
    const hh = Number(m24[1]);
    const mm = Number(m24[2]);
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;
    return hh * 60 + mm;
  }
  return null;
};

const getAttendanceShiftStartRaw = (rec) =>
  pickFirstNonEmptyString(
    rec?.ShiftStartTime,
    rec?.['ShiftStartTime'],
    rec?.shiftStartTime,
    rec?.FirstIn,
    rec?.['FirstIn'],
    rec?.firstIn,
    rec?.InTime,
    rec?.['InTime'],
    rec?.CheckIn,
    rec?.['CheckIn'],
    findNestedValueByNormalizedKey(rec, 'shiftstarttime'),
    findNestedValueByNormalizedKey(rec, 'firstin')
  );

const getAttendanceShiftEndRaw = (rec) =>
  pickFirstNonEmptyString(
    rec?.ShiftEndTime,
    rec?.['ShiftEndTime'],
    rec?.shiftEndTime,
    rec?.LastOut,
    rec?.['LastOut'],
    rec?.lastOut,
    rec?.OutTime,
    rec?.['OutTime'],
    rec?.CheckOut,
    rec?.['CheckOut'],
    findNestedValueByNormalizedKey(rec, 'shiftendtime'),
    findNestedValueByNormalizedKey(rec, 'lastout')
  );

const getAttendanceShiftNameRaw = (rec) =>
  pickFirstNonEmptyString(
    rec?.ShiftName,
    rec?.['ShiftName'],
    rec?.shiftName,
    rec?.Shift,
    rec?.['Shift'],
    findNestedValueByNormalizedKey(rec, 'shiftname'),
    findNestedValueByNormalizedKey(rec, 'shift')
  );

const FORM_25_TN_DEFAULT_SHIFT_START = '09.00';
const FORM_25_TN_DEFAULT_SHIFT_END = '05:00';
const FORM_25_TN_DEFAULT_SHIFT_NAME = 'General Shift Sites';
const FORM_25_TN_DEFAULT_DAILY_HOURS = '8';

/** Form 25 TN: shift columns ← People ShiftStartTime / ShiftEndTime / ShiftName. */
const resolveForm25ShiftStartValue = (empItem, attendanceRec) =>
  getAttendanceShiftStartRaw(attendanceRec) || readFormPGJShiftStartFromEmployee(empItem);

const resolveForm25ShiftEndValue = (empItem, attendanceRec) =>
  getAttendanceShiftEndRaw(attendanceRec) || readFormPGJShiftEndFromEmployee(empItem);

const resolveForm25ShiftNameValue = (empItem, attendanceRec) =>
  getAttendanceShiftNameRaw(attendanceRec) || readFormPGJShiftNameFromEmployee(empItem);

const formatAttendanceShiftTimeDisplay = (raw) => {
  const s = String(raw || '').trim();
  if (!s || s === '-') return '';
  return s;
};

const getAttendanceOvertimeHoursNumber = (source) => {
  const raw = pickFirstNonEmptyString(
    source?.OverTime,
    source?.['OverTime'],
    source?.ApprovedOverTime,
    source?.['ApprovedOverTime'],
    source?.Approved_OT,
    source?.['Approved_OT'],
    source?.approved_overtime,
    source?.['approved_overtime'],
    source?.Overtime,
    source?.['Overtime'],
    source?.overtime,
    source?.['overtime'],
    source?.overtime_hrs,
    source?.['overtime_hrs'],
    source?.OTTime,
    source?.['OTTime'],
    source?.OTHours,
    source?.['OTHours'],
    source?.OT,
    source?.['OT'],
    source?.OvertimeHours,
    source?.['OvertimeHours'],
    source?.OverTimeHours,
    source?.['OverTimeHours'],
    findNestedValueByNormalizedKey(source || {}, 'overtime'),
    findNestedValueByNormalizedKey(source || {}, 'othours'),
    findNestedValueByNormalizedKey(source || {}, 'approvedovertime'),
    findNestedValueByNormalizedKey(source || {}, 'overtimeworked')
  );
  const n = Number(raw);
  if (Number.isFinite(n) && n > 0) return n;
  const s = String(raw || '').trim();
  if (s && !/^0{1,2}:0{2}$/.test(s)) {
    const m = parseAttendanceTimeToMinutes(s);
    if (m != null && m > 0) return m / 60;
  }
  const totalRaw = pickFirstNonEmptyString(
    source?.TotalHours,
    source?.['TotalHours'],
    source?.totalHours,
    source?.['totalHours']
  );
  const workRaw = pickFirstNonEmptyString(
    source?.WorkingHours,
    source?.['WorkingHours'],
    source?.workingHours,
    source?.['workingHours']
  );
  if (totalRaw && workRaw) {
    const totalMins = parseAttendanceTimeToMinutes(totalRaw);
    const workMins = parseAttendanceTimeToMinutes(workRaw);
    if (totalMins != null && workMins != null && totalMins > workMins) {
      return (totalMins - workMins) / 60;
    }
  }
  return 0;
};

const attendanceRecordDateKeyForOt = (obj) => {
  const dRaw = pickFirstNonEmptyString(obj?.date, obj?.Date);
  if (!dRaw) return '';
  const normalized = normalizeAttendanceDateKey(dRaw);
  if (normalized) return normalized;
  const s = String(dRaw).trim();
  const isoPrefix = s.match(/^(\d{4}-\d{2}-\d{2})/);
  if (isoPrefix) return isoPrefix[1];
  const d = new Date(s);
  if (!Number.isNaN(d.getTime())) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }
  return '';
};

const formatStatutoryOvertimeHoursDisplay = (hoursNum) => {
  if (!Number.isFinite(hoursNum) || hoursNum <= 0) return '';
  if (Math.abs(hoursNum - Math.round(hoursNum)) < 0.01) return String(Math.round(hoursNum));
  const whole = Math.floor(hoursNum);
  const mins = Math.round((hoursNum - whole) * 60);
  if (whole <= 0) return `${mins} min`;
  if (mins <= 0) return String(whole);
  return `${whole}:${String(mins).padStart(2, '0')}`;
};

const attendanceRecordMinutesWorked = (rec) => {
  if (!rec || typeof rec !== 'object') return null;
  const daily = pickFirstNonEmptyString(
    rec?.WorkingHours,
    rec?.workingHours,
    rec?.DailyWorkedHours,
    rec?.dailyWorkedHours
  );
  if (daily) {
    if (/^0{1,2}:0{2}$/.test(daily)) return null;
    const m = parseAttendanceTimeToMinutes(daily);
    if (m != null && m > 0) return m;
    const n = Number(String(daily).replace(/,/g, '').trim());
    if (Number.isFinite(n) && n > 0 && n <= 24 && !daily.includes(':')) return Math.round(n * 60);
  }
  const st = getAttendanceShiftStartRaw(rec);
  const et = getAttendanceShiftEndRaw(rec);
  if (st && et && st !== '-' && et !== '-') {
    const startMin = parseAttendanceTimeToMinutes(st);
    const endMin = parseAttendanceTimeToMinutes(et);
    if (startMin != null && endMin != null) {
      let diff = endMin - startMin;
      if (diff < 0) diff += 24 * 60;
      if (diff > 0) return diff;
    }
  }
  const total = getAttendanceTotalHoursRaw(rec);
  if (total && total !== '-' && total !== '00:00') {
    const m = parseAttendanceTimeToMinutes(total);
    if (m != null && m > 0) return m;
  }
  return null;
};

const formatMinutesAsHoursCell = (totalMins) => {
  if (!Number.isFinite(totalMins) || totalMins <= 0) return '';
  const h = Math.floor(totalMins / 60);
  const m = Math.round(totalMins % 60);
  return `${h}:${String(m).padStart(2, '0')}`;
};

const isForm25WorkCommencesHeader = (h) =>
  /time\s+at\s+which\s+work\s+commence/.test(String(h || '').toLowerCase().replace(/\s+/g, ' '));

const isForm25WorkEndsHeader = (h) =>
  /time\s+at\s+which\s+work\s+end/.test(String(h || '').toLowerCase().replace(/\s+/g, ' '));

const isForm25SchemeOfShiftsHeader = (h) =>
  /scheme\s+of\s+shift/.test(String(h || '').toLowerCase().replace(/\s+/g, ' '));

const isForm25AttendanceOnlyHeader = (h) =>
  isForm25WorkCommencesHeader(h) || isForm25WorkEndsHeader(h) || isForm25SchemeOfShiftsHeader(h);

const getAttendanceTotalHoursRaw = (rec) =>
  pickFirstNonEmptyString(rec?.TotalHours, rec?.totalHours, rec?.['Total Hours']);

const recordHasAttendanceTotalHours = (rec) => {
  if (!rec || typeof rec !== 'object') return false;
  const raw = getAttendanceTotalHoursRaw(rec);
  return Boolean(raw && raw !== '-' && raw !== '00:00');
};

const recordHasAttendancePresence = (rec) => {
  if (!rec || typeof rec !== 'object') return false;
  const status = String(rec?.Status ?? rec?.status ?? '').trim().toLowerCase();
  if (!status || status === '-') return false;
  if (/^(absent|holiday|weekend|week off|weekoff|on leave|leave|nil|na|none)$/.test(status)) return false;
  return true;
};

const recordHasAttendanceStatusField = (rec) => {
  if (!rec || typeof rec !== 'object') return false;
  const status = String(rec?.Status ?? rec?.status ?? '').trim();
  return Boolean(status && status !== '-');
};

const isForm25StatutoryContext = (hints = {}) => {
  const blob = [
    hints.fileName,
    hints.formFileName,
    hints.item?.formName,
    hints.item?.FormName,
    hints.formHeaderTitle,
    hints.formHeaderSubtitle,
    Array.isArray(hints.tableHeaders) ? hints.tableHeaders.join(' ') : ''
  ]
    .map((s) => String(s || ''))
    .join(' ');
  return /\bform[\s._-]*25\b/i.test(blob);
};

/** Form V Tamil Nadu — Register of Employment (day grid: P / A / WO / CL). */
const isFormVTamilNaduRegisterOfEmploymentContext = (
  formHeader,
  rowItem,
  fileName,
  tableHeaders,
  sheetText = ''
) => {
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    rowItem?.State,
    rowItem?.state,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.wagePeriodText,
    sheetText,
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : '',
  ]
    .map((v) => String(v || '').toLowerCase())
    .join(' ');
  const isFormV =
    /\bform\s*[-_]?\s*v\b/.test(parts) ||
    /\bform[\s._-]*5\b/.test(parts) ||
    /form_v[_\s-]/.test(parts);
  if (!isFormV) return false;
  const isTamilNadu = /tamil[\s._-]*nadu|tamilnadu/.test(parts);
  const isRegisterOfEmployment = /register\s+of\s+employment/.test(parts);
  if (isTamilNadu || isRegisterOfEmployment) return true;
  const dayCols = (Array.isArray(tableHeaders) ? tableHeaders : []).filter((h) => {
    const t = String(h || '').trim();
    if (/^\d{1,2}$/.test(t)) {
      const n = Number(t);
      return n >= 1 && n <= 31;
    }
    return /_(?:[1-9]|[12]\d|3[01])$/.test(t) || /(?:^|[^0-9])([1-9]|[12]\d|3[01])$/.test(t);
  }).length;
  return dayCols >= 5 && /daily\s+hours|hours\s+of\s+work/.test(parts);
};

/** Form 25 / Form V daily grid: Present / Absent / Weekend / Contingency Leave. */
const formatForm25DayAttendanceStatus = (rec) => {
  if (!rec || typeof rec !== 'object') return '';
  const statusRaw = String(rec?.Status ?? rec?.status ?? '').trim();
  const statusLower = statusRaw.toLowerCase().replace(/\s+/g, ' ').trim();

  if (statusRaw && statusRaw !== '-') {
    if (
      /contingency\s*leave|contingency|\bc\/?l\b|^cl$/.test(statusLower)
    ) {
      return 'ContingencyLeave';
    }
    if (
      /^absent$/.test(statusLower) ||
      /^a$/.test(statusLower) ||
      /loss of pay|\blop\b|unpaid|not present/.test(statusLower)
    ) {
      return 'Absent';
    }
    if (/^wo$|weekend|week off|weekoff|^holiday$|weekly\s*off/.test(statusLower)) {
      return 'Weekend';
    }
    if (
      /^present$/.test(statusLower) ||
      /^p$/.test(statusLower) ||
      /on duty|half day|halfday|sick|paid leave|work from home|\bwfh\b/.test(statusLower)
    ) {
      return 'Present';
    }
    if (/leave/.test(statusLower) && /contingency/.test(statusLower)) {
      return 'ContingencyLeave';
    }
    return /absent/i.test(statusRaw) ? 'Absent' : 'Present';
  }

  const firstIn = getAttendanceShiftStartRaw(rec);
  const lastOut = getAttendanceShiftEndRaw(rec);
  const hasPunch =
    (firstIn && firstIn !== '-') || (lastOut && lastOut !== '-');
  if (hasPunch) {
    if (firstIn === '-' && lastOut === '-') return 'Absent';
    return 'Present';
  }

  const shiftStart = String(rec?.ShiftStartTime ?? rec?.shiftStartTime ?? '').trim();
  const shiftEnd = String(rec?.ShiftEndTime ?? rec?.shiftEndTime ?? '').trim();
  if ((shiftStart && shiftStart !== '-') || (shiftEnd && shiftEnd !== '-')) {
    return 'Present';
  }

  const working = String(rec?.WorkingHours ?? rec?.workingHours ?? '').trim();
  if (working && working !== '-' && working !== '00:00') return 'Present';

  const total = getAttendanceTotalHoursRaw(rec);
  if (total && total !== '-' && total !== '00:00') return 'Present';

  if (recordHasAttendancePresence(rec)) return 'Present';

  return 'Absent';
};

const normalizeForm25StatusToken = (statusRaw) =>
  String(statusRaw || '').trim().toLowerCase().replace(/\s+/g, ' ');

const getAttendanceStatusRaw = (rec) => {
  if (!rec || typeof rec !== 'object') return '';
  const raw = pickFirstNonEmptyString(
    rec?.Status,
    rec?.['Status'],
    rec?.status,
    findNestedValueByNormalizedKey(rec, 'status')
  );
  const s = String(raw || '').trim();
  return s && s !== '-' ? s : '';
};

/** Daily grid cell: raw Status from attendance API. */
const getForm25DayCellDisplay = (rec) => getAttendanceStatusRaw(rec);

const isWeekendCalendarDate = (date) => {
  if (!date || !(date instanceof Date) || Number.isNaN(date.getTime())) return false;
  const dow = date.getDay();
  return dow === 0 || dow === 6;
};

/** Day columns: Present → P, Absent → A, Weekend → WO, Contingency Leave → CL. */
const formatForm25DayAttendanceCode = (rec, dayDate) => {
  if (!rec) {
    return isWeekendCalendarDate(dayDate) ? 'WO' : 'A';
  }
  const bucket = formatForm25DayAttendanceStatus(rec);
  if (bucket === 'Present') return 'P';
  if (bucket === 'Absent') return 'A';
  if (bucket === 'Weekend') return 'WO';
  if (bucket === 'ContingencyLeave') return 'CL';
  if (isWeekendCalendarDate(dayDate)) return 'WO';
  return 'A';
};

/** Form V Tamil Nadu Register of Employment — same P / A / WO / CL codes. */
const formatFormVTamilNaduDayAttendanceCode = (rec, dayDate) =>
  formatForm25DayAttendanceCode(rec, dayDate);

/** Form Q Maharashtra: P/A/WO only when attendance API has a record for that day. */
const formatFormQDayAttendanceCode = (rec, dayDate) => {
  if (!rec) return '';
  return formatForm25DayAttendanceCode(rec, dayDate);
};

/**
 * Fast Form Q day-grid paint from cached/prefetched attendance (before full merge finishes).
 * Returns number of cells written.
 */
const applyFormQMaharashtraAttendanceFromCache = (
  mappedData,
  employees,
  headers,
  attendanceRawOrRecords,
  options = {}
) => {
  const rows = Array.isArray(mappedData) ? mappedData : [];
  const emps = Array.isArray(employees) ? employees : [];
  const hdrs = Array.isArray(headers) ? headers : [];
  if (rows.length === 0 || hdrs.length === 0 || !attendanceRawOrRecords) return 0;

  const {
    targetYear,
    targetMonthIndex,
    getNameCandidates = null,
    sdate = '',
    edate = '',
  } = options;
  if (!Number.isFinite(targetYear) || !Number.isFinite(targetMonthIndex)) return 0;

  const dateDayHeaders = hdrs
    .map((header) => {
      const t = String(header || '').trim();
      const direct = t.match(/^(\d{1,2})$/);
      if (direct) {
        const day = Number(direct[1]);
        if (day >= 1 && day <= 31) return { header, day };
      }
      const suffixed = t.match(/(?:^|_)(\d{1,2})$/);
      if (suffixed) {
        const day = Number(suffixed[1]);
        if (day >= 1 && day <= 31) return { header, day };
      }
      return null;
    })
    .filter(Boolean);
  if (dateDayHeaders.length === 0) return 0;

  const records = (
    Array.isArray(attendanceRawOrRecords)
      ? attendanceRawOrRecords
      : expandAttendanceToDailyRows(attendanceRawOrRecords)
  ).filter((rec) => {
    const k = normalizeAttendanceDateKey(rec?.date ?? rec?.Date ?? '');
    if (!k) return false;
    if (sdate && k < sdate) return false;
    if (edate && k > edate) return false;
    return true;
  });
  if (records.length === 0) return 0;

  const byIdDate = new Map();
  const byNameDate = new Map();
  const byEmailDate = new Map();
  records.forEach((rec) => {
    const iso = normalizeAttendanceDateKey(rec?.date ?? rec?.Date ?? '');
    if (!iso) return;
    getAttendanceEmployeeIdCandidates(rec)
      .flatMap(expandAttendanceLookupIdVariants)
      .forEach((id) => {
        const key = `${id}::${iso}`;
        if (!byIdDate.has(key)) byIdDate.set(key, rec);
      });
    getAttendanceNameLookupKeys(rec).forEach((nameKey) => {
      const key = `${nameKey}::${iso}`;
      if (!byNameDate.has(key)) byNameDate.set(key, rec);
    });
    const email = getAttendanceEmployeeEmail(rec);
    if (email) {
      const key = `${email}::${iso}`;
      if (!byEmailDate.has(key)) byEmailDate.set(key, rec);
    }
  });

  const today = new Date();
  const isCurrentSelectedMonth =
    targetYear === today.getFullYear() && targetMonthIndex === today.getMonth();
  let wrote = 0;

  rows.forEach((row, rowIndex) => {
    if (!row || typeof row !== 'object') return;
    const empItem = emps[rowIndex];
    const emp = empItem && (empItem.Employee || empItem.employee || empItem);
    const idCandidates = Array.from(
      new Set(
        getAttendanceEmployeeIdCandidates(emp || {})
          .map((v) => String(v || '').trim())
          .filter(Boolean)
          .flatMap(expandAttendanceLookupIdVariants)
      )
    );
    const nameCandidates = Array.from(
      new Set(
        [
          ...(typeof getNameCandidates === 'function' ? getNameCandidates(emp || {}) : []),
          ...getAttendanceNameLookupKeys(emp || {}),
        ]
          .map((v) => String(v || '').trim().toLowerCase())
          .filter(Boolean)
      )
    );
    const emailCandidate = getAttendanceEmployeeEmail(emp || {});

    dateDayHeaders.forEach(({ header, day }) => {
      const dayDate = new Date(targetYear, targetMonthIndex, day);
      if (dayDate.getMonth() !== targetMonthIndex) return;
      if (shouldSkipStatutoryDayAttendanceForEmployee(emp, dayDate, row, hdrs)) {
        row[header] = '';
        return;
      }
      if (isCurrentSelectedMonth && day > today.getDate()) {
        row[header] = '';
        return;
      }
      const iso = formatStatutoryPrefetchYmd(dayDate);
      const byId = idCandidates.map((id) => byIdDate.get(`${id}::${iso}`)).find(Boolean);
      const byName =
        !byId &&
        nameCandidates.map((name) => byNameDate.get(`${name}::${iso}`)).find(Boolean);
      const byEmail =
        !byId && !byName && emailCandidate
          ? byEmailDate.get(`${emailCandidate}::${iso}`)
          : null;
      const rec = byId || byName || byEmail || null;
      const code = formatFormQDayAttendanceCode(rec, dayDate);
      if (!code) return;
      row[header] = code;
      wrote += 1;
    });
  });

  return wrote;
};

const form25StatusIsHalfDay = (statusRaw) => {
  const s = normalizeForm25StatusToken(statusRaw);
  return /half\s*day|halfday|\bhd\b|\b0\.5\b/.test(s);
};

const form25StatusIsAbsentOrLop = (statusRaw) => {
  const s = normalizeForm25StatusToken(statusRaw);
  if (!s || s === '-') return true;
  return (
    /^absent$/.test(s) ||
    /^a$/.test(s) ||
    /loss of pay|\blop\b|unpaid|not present/.test(s)
  );
};

/** Total Days Worked: Present, Weekend, paid leave, half day (0.5) — Absent/Tour do not add. */
const form25DayCountFromStatus = (statusRaw) => {
  const s = normalizeForm25StatusToken(statusRaw);
  if (!s || form25StatusIsAbsentOrLop(s)) return 0;
  if (/weekend|week off|weekoff/.test(s)) return 1;
  if (/\btour\b/.test(s)) return 0;
  if (/comp\s*off|\bco\b|compensatory/.test(s)) return 0;
  if (form25StatusIsHalfDay(s)) return 0.5;
  if (/^present$|^p$|on duty|wfh|work from home/.test(s)) return 1;
  if (/^cl$|casual leave|^pl$|privilege leave|^sl$|sick leave|^el$|earned leave|^ml$|maternity/.test(s)) {
    return 1;
  }
  if (/\bleave\b/.test(s) && !/unpaid|loss/.test(s)) return 1;
  return 0;
};

const computeForm25LossOfPayDays = (workedDays, year, monthIndex) => {
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
  return Math.max(0, daysInMonth - Math.round(Number(workedDays) || 0));
};

/** Form 25 Total Hours Worked = Paid_days × 8 (Paid_days = counted worked/paid days). */
const aggregateForm25WorkedTotalsFromRecords = (records) => {
  let days = 0;
  (records || []).forEach((rec) => {
    const status = getForm25DayCellDisplay(rec);
    if (!status) return;
    days += form25DayCountFromStatus(status);
  });
  const paidDays = Math.round(days);
  return {
    days: paidDays,
    totalHours: paidDays * 8
  };
};

/** Form 25 daily hours column: worked hours + overtime from attendance. */
const formatForm25DailyHoursWithOvertime = (rec) => {
  if (!rec || typeof rec !== 'object') return '';
  if (formatForm25DayAttendanceStatus(rec) === 'Absent') return '';
  let totalMins = attendanceRecordMinutesWorked(rec);
  const otHours = getAttendanceOvertimeHoursNumber(rec);
  if (otHours > 0) totalMins = (totalMins || 0) + Math.round(otHours * 60);
  return formatMinutesAsHoursCell(totalMins);
};

const getAttendanceEmployeeFirstName = (obj) => {
  const sources = [obj, getAttendanceRecordEmployeeMeta(obj)].filter(Boolean);
  for (let i = 0; i < sources.length; i += 1) {
    const src = sources[i];
    const name = pickFirstNonEmptyString(
      src?.FirstName,
      src?.firstName,
      src?.['First Name'],
      src?.['first name'],
      src?.First_Name,
      findNestedValueByNormalizedKey(src, 'firstname')
    );
    if (name) return name;
  }
  return '';
};

const getAttendanceEmployeeLastName = (obj) => {
  const sources = [obj, getAttendanceRecordEmployeeMeta(obj)].filter(Boolean);
  for (let i = 0; i < sources.length; i += 1) {
    const src = sources[i];
    const name = pickFirstNonEmptyString(
      src?.LastName,
      src?.lastName,
      src?.['Last Name'],
      src?.['last name'],
      src?.Last_Name,
      findNestedValueByNormalizedKey(src, 'lastname')
    );
    if (name) return name;
  }
  return '';
};

const getAttendanceEmployeeDisplayName = (obj) => {
  if (!obj || typeof obj !== 'object') return '';
  const sources = [obj, getAttendanceRecordEmployeeMeta(obj)].filter(Boolean);
  for (let si = 0; si < sources.length; si += 1) {
    const src = sources[si];
    const first = getAttendanceEmployeeFirstName(src);
    const last = getAttendanceEmployeeLastName(src);
    const full = `${first} ${last}`.trim();
    const name = pickFirstNonEmptyString(
      full,
      src?.EmployeeName,
      src?.['Employee Name'],
      src?.['EmployeeName'],
      src?.Name,
      src?.['Name'],
      src?.name,
      src?.['name'],
      first,
      findNestedValueByNormalizedKey(src, 'name')
    );
    if (name) return String(name).trim().toLowerCase();
  }
  return '';
};

const getAttendanceNameLookupKeys = (obj) => {
  const keys = new Set();
  const add = (val) => {
    const s = String(val || '').trim().toLowerCase();
    if (!s || s === '-') return;
    keys.add(s);
    s.split(/\s+/).forEach((part) => {
      if (part.length > 1) keys.add(part);
    });
  };
  add(getAttendanceEmployeeDisplayName(obj));
  add(getAttendanceEmployeeFirstName(obj));
  add(getAttendanceEmployeeLastName(obj));
  const meta = getAttendanceRecordEmployeeMeta(obj);
  if (meta && typeof meta === 'object') {
    add(meta.name);
    add(meta.Name);
    add(meta['name']);
  }
  return Array.from(keys);
};

const namesLooselyMatchAttendance = (a, b) => {
  const x = String(a || '').trim().toLowerCase();
  const y = String(b || '').trim().toLowerCase();
  if (!x || !y) return false;
  if (x === y) return true;
  if (x.includes(y) || y.includes(x)) return true;
  const xParts = x.split(/\s+/).filter((p) => p.length > 1);
  const yParts = y.split(/\s+/).filter((p) => p.length > 1);
  return xParts.some((p) => yParts.includes(p));
};

const getAttendanceEmployeeEmail = (obj) => {
  const sources = [obj, getAttendanceRecordEmployeeMeta(obj)].filter(Boolean);
  for (let i = 0; i < sources.length; i += 1) {
    const src = sources[i];
    const email = pickFirstNonEmptyString(
      src?.EmailID,
      src?.Email,
      src?.email,
      src?.emailId,
      src?.['Email ID'],
      src?.Work_Email,
      src?.work_email,
      src?.workEmail,
      src?.['mail id'],
      src?.mailId,
      findNestedValueByNormalizedKey(src, 'emailid'),
      findNestedValueByNormalizedKey(src, 'email'),
      findNestedValueByNormalizedKey(src, 'workemail')
    );
    if (email) return String(email).trim().toLowerCase();
  }
  return '';
};

