const FORM_XV_WORKMAN_HEADER_KEYS = new Set([
  'form_xv_workman',
  'form_xv_age_or_dob',
  'form_xv_identification_marks',
  'form_xv_father_or_husband_name'
]);

/** Legacy combined list (site header fields only — workman details live in the table). */
const FORM_XV_HEADER_LABEL_SPECS = [...FORM_XV_SITE_HEADER_LABEL_SPECS];

const FORM_XV_TABLE_HEADERS = [
  'Sr.No.',
  'Name and address of the workman',
  'Age or date of birth',
  'Identification marks',
  "Father's/Husband's name",
  'Total period for which employed_From',
  'Total period for which employed_To',
  'Nature of work done',
  'Rate of wage (with particulars of work)',
  'Remarks'
];

const normalizeFormXVTableHeader = (h) =>
  String(h || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const isFormXVPeriodFromHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return n.includes('from') && (n.includes('period') || n.includes('employed'));
};

const isFormXVPeriodToHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return n.includes('to') && !n.includes('from') && (n.includes('period') || n.includes('employed'));
};

const isFormXVNatureOfWorkHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return n.includes('nature') && n.includes('work');
};

const isFormXVRateOfWageHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return n.includes('rate') && n.includes('wage');
};

const isFormXVWorkmanNameHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return (n.includes('workman') || n.includes('workmen')) && (n.includes('name') || n.includes('address'));
};

const isFormXVAgeOrDobHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  if (n.includes('wage')) return false;
  return (n.includes('age') && n.includes('birth')) || n === 'age' || /^age or date of birth/.test(n);
};

const isFormXVIdentificationMarksHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return n.includes('identification') && n.includes('mark');
};

const isFormXVFatherOrHusbandHeader = (h) => {
  const n = normalizeFormXVTableHeader(h);
  return (n.includes('father') || n.includes('husband')) && n.includes('name');
};

const isFormXVPeopleTableAutofillHeader = (h) =>
  isFormXVWorkmanNameHeader(h) ||
  isFormXVAgeOrDobHeader(h) ||
  isFormXVIdentificationMarksHeader(h) ||
  isFormXVFatherOrHusbandHeader(h) ||
  isFormXVPeriodFromHeader(h) ||
  isFormXVPeriodToHeader(h) ||
  isFormXVNatureOfWorkHeader(h) ||
  isFormXVRateOfWageHeader(h);

const isFormXVRemarksHeader = (h) => normalizeFormXVTableHeader(h).includes('remarks');

/** Workman identity band in the Excel template (above the employment table). */
const FORM_XV_WORKMAN_HEADER_LABEL_SPECS = [
  {
    match: /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i,
    label: 'Name and address of the workman',
    key: 'form_xv_workman',
    rowTest: isFormXVWorkmanNameHeader
  },
  {
    match: /age\s+or\s+date\s+of\s+birth/i,
    label: 'Age or date of birth',
    key: 'form_xv_age_or_dob',
    rowTest: isFormXVAgeOrDobHeader
  },
  {
    match: /identification\s+marks/i,
    label: 'Identification marks',
    key: 'form_xv_identification_marks',
    rowTest: isFormXVIdentificationMarksHeader
  },
  {
    match: /father.*husband.*name|husband.*father.*name/i,
    label: "Father's/Husband's name",
    key: 'form_xv_father_or_husband_name',
    rowTest: isFormXVFatherOrHusbandHeader
  }
];

const isFormXVExportTableHeader = (h) =>
  !isFormXVWorkmanNameHeader(h) &&
  !isFormXVAgeOrDobHeader(h) &&
  !isFormXVIdentificationMarksHeader(h) &&
  !isFormXVFatherOrHusbandHeader(h);

const getFormXVExportTableHeaders = (hdrs) => {
  const list = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [...FORM_XV_TABLE_HEADERS];
  const exportHdrs = list.filter(isFormXVExportTableHeader);
  return exportHdrs.length > 0 ? exportHdrs : [...FORM_XV_TABLE_HEADERS].filter(isFormXVExportTableHeader);
};

const isFormXVSkipAutofillHeader = (h) => isFormXVRemarksHeader(h);

const rowHasMeaningfulFormXVExportData = (row, hdrs) => {
  if (!row || typeof row !== 'object') return false;
  const headers = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : FORM_XV_TABLE_HEADERS;
  return headers.some((header) => {
    const n = normalizeFormXVTableHeader(header);
    if (n.includes('sr') && (n.includes('no') || n === 'sno' || n === 'srno')) return false;
    const value = String(row[header] ?? '').trim();
    return value !== '';
  });
};

const buildFormXVSingleEmployeeExportRow = (row, hdrs) => {
  const headers = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : FORM_XV_TABLE_HEADERS;
  const out = { ...(row && typeof row === 'object' ? row : {}) };
  const srHeader = headers[0] || 'Sr.No.';
  out[srHeader] = 1;
  return out;
};

const mapFormXVRowsFromEmployees = (employees, headers, helpers = {}) => {
  const hdrs = Array.isArray(headers) && headers.length > 0 ? headers : [...FORM_XV_TABLE_HEADERS];
  const list = Array.isArray(employees) ? employees : [];
  const { sanitizeValue = (v) => String(v ?? '').trim() } = helpers;
  return list.map((empItem, rowIndex) => {
    const emp = empItem?.Employee || empItem?.employee || empItem;
    const row = {};
    hdrs.forEach((header, colIndex) => {
      if (isFormXVSkipAutofillHeader(header)) {
        row[header] = '';
        return;
      }
      if (colIndex === 0 || (normalizeFormXVTableHeader(header).includes('sr') && normalizeFormXVTableHeader(header).includes('no'))) {
        row[header] = rowIndex + 1;
        return;
      }
      if (isFormXVWorkmanNameHeader(header)) {
        row[header] = sanitizeValue(buildEmployeeWorkmanNameAndAddress(empItem));
        return;
      }
      if (isFormXVAgeOrDobHeader(header)) {
        row[header] = sanitizeValue(buildEmployeeAgeOrDobForFormXV(empItem));
        return;
      }
      if (isFormXVIdentificationMarksHeader(header)) {
        row[header] = sanitizeValue(buildEmployeeIdentificationMarks(empItem));
        return;
      }
      if (isFormXVFatherOrHusbandHeader(header)) {
        row[header] = sanitizeValue(buildEmployeeFatherOrHusbandName(empItem));
        return;
      }
      if (isFormXVPeriodFromHeader(header)) {
        row[header] = sanitizeValue(formatStatutoryDateDisplay(getEmployeeDateofjoiningRaw(emp)));
        return;
      }
      if (isFormXVPeriodToHeader(header)) {
        row[header] = sanitizeValue(formatStatutoryDateDisplay(getEmployeeDateofexitRaw(emp)));
        return;
      }
      if (isFormXVNatureOfWorkHeader(header)) {
        row[header] = sanitizeValue(
          emp?.Designation ||
            emp?.designation ||
            emp?.['Designation.displayValue'] ||
            emp?.['Designation'] ||
            emp?.JobTitle ||
            emp?.jobTitle ||
            emp?.['JobTitle'] ||
            ''
        );
        return;
      }
      if (isFormXVRateOfWageHeader(header)) {
        row[header] = '';
      }
    });
    return row;
  });
};

const resolveFormXVRateOfWageFromPayroll = (payrollRow) => readPayrollNetPayForStatutory(payrollRow);

const FORM_XV_GJ_FIXED_THARUN_WAGE_RATE = '70404';
const FORM_XV_GJ_FIXED_EMPLOYEE_MATCHES = ['tharun', 'tarun'];

const resolveFormXVEmployeeNameForMatch = (emp = {}) => {
  const fn = String(emp.FirstName || emp.firstName || emp['First Name'] || '').trim();
  const ln = String(emp.LastName || emp.lastName || emp['Last Name'] || '').trim();
  const full = `${fn} ${ln}`.trim();
  if (full) return full;
  return String(emp.Name || emp.EmployeeName || emp['Employee Name'] || '').trim();
};

const isFormXVGJFixedEmployee = (emp = {}) => {
  const name = resolveFormXVEmployeeNameForMatch(emp).toLowerCase();
  if (!name) return false;
  return FORM_XV_GJ_FIXED_EMPLOYEE_MATCHES.some((token) => name.includes(token));
};

const resolveFormXVRateOfWage = (emp, payrollRow, helpers = {}) => {
  const {
    monthCandidates = null,
    item = null,
    fileName = '',
    formHeader = null,
    sheetText = '',
  } = helpers;
  if (
    isFormXVMPContext(formHeader, item, fileName, sheetText) &&
    isAprilPayrollMonthCandidates(monthCandidates)
  ) {
    const mpDefault = resolveFormXXIIIMPAprilDefaultNormalRate(emp);
    if (mpDefault) return mpDefault;
  }
  if (isFormXVGJContext(formHeader, item, fileName, sheetText) && isFormXVGJFixedEmployee(emp || {})) {
    return FORM_XV_GJ_FIXED_THARUN_WAGE_RATE;
  }
  return resolveFormXVRateOfWageFromPayroll(payrollRow);
};

const buildFormXVWageRateEnrichHelpers = (modalData, formFileModalData, monthCandidates) => ({
  monthCandidates,
  item: modalData?.item || formFileModalData?.item || null,
  fileName: String(
    formFileModalData?.fileName || formFileModalData?.formFileName || modalData?.fileName || ''
  ).trim(),
  formHeader: modalData?.parsedFormHeader || formFileModalData?.parsedFormHeader || null,
  sheetText: formFileModalData?.sheetText || modalData?.sheetText || '',
});

const enrichFormXVPayrollRows = (mappedData, employees, headers, helpers = {}) => {
  const hdrs = Array.isArray(headers) && headers.length > 0 ? headers : [...FORM_XV_TABLE_HEADERS];
  const rateHeader = hdrs.find(isFormXVRateOfWageHeader);
  const {
    resolvePayrollRow = null,
    sanitizeValue = (v) => String(v ?? '').trim(),
    overwrite = true,
    rowIndexOffset = 0,
    monthCandidates = null,
    item = null,
    fileName = '',
    formHeader = null,
    sheetText = '',
  } = helpers;
  if (!rateHeader || !Array.isArray(mappedData) || mappedData.length === 0) {
    return 0;
  }
  const wageHelpers = { monthCandidates, item, fileName, formHeader, sheetText };
  let hits = 0;
  mappedData.forEach((row, rowIndex) => {
    const empItem = employees?.[rowIndex + rowIndexOffset];
    const emp = empItem?.Employee || empItem?.employee || empItem;
    const payrollRow =
      typeof resolvePayrollRow === 'function' ? resolvePayrollRow(emp, row, rowIndex) : null;
    const netPay = resolveFormXVRateOfWage(emp, payrollRow, wageHelpers);
    if (netPay === '') return;
    const existing = String(row[rateHeader] ?? '').trim();
    const existingLower = existing.toLowerCase();
    const existingIsPlaceholder =
      !existing ||
      /^enter\b/.test(existingLower) ||
      existingLower.includes('enter ') ||
      existingLower.includes('select ');
    if (!overwrite && existing && !existingIsPlaceholder) return;
    row[rateHeader] = sanitizeValue(netPay);
    hits += 1;
  });
  return hits;
};

const overlayFormXVUserEditsOntoRows = (mappedRows, tableRows, hdrs) => {
  const headers = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [...FORM_XV_TABLE_HEADERS];
  const priorRows = Array.isArray(tableRows) ? tableRows : [];
  const priorHdrs =
    priorRows.length > 0 ? Object.keys(priorRows.find((r) => r && typeof r === 'object') || {}) : headers;
  return (Array.isArray(mappedRows) ? mappedRows : []).map((row, index) => {
    const saved = priorRows[index];
    if (!saved || typeof saved !== 'object' || !rowHasMeaningfulFormXVExportData(saved, headers)) {
      return row;
    }
    const canonicalSaved = mapFormXVRowsToCanonicalHeaders([saved], priorHdrs, headers)[0] || saved;
    const merged = { ...row };
    headers.forEach((header) => {
      const value = getFormXVRowValueForHeader(canonicalSaved, header);
      if (String(value ?? '').trim() !== '') merged[header] = canonicalSaved[header] ?? value;
    });
    return merged;
  });
};

/** Rebuild all employee rows from People cache, then overlay saved/imported grid edits. */
const resolveFormXVExportRows = (mappedData, hdrs, employeesOverride = null) => {
  const headers = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [...FORM_XV_TABLE_HEADERS];
  const tableRows = mapFormXVRowsToCanonicalHeaders(
    Array.isArray(mappedData) ? mappedData : [],
    headers,
    headers
  );
  const employees = Array.isArray(employeesOverride) ? employeesOverride : [];
  if (employees.length > 0) {
    const fromEmployees = mapFormXVRowsFromEmployees(employees, headers, {
      sanitizeValue: (v) => String(v ?? '').trim()
    });
    return overlayFormXVUserEditsOntoRows(fromEmployees, tableRows, headers);
  }
  return tableRows;
};

const triggerFormXVZipDownload = (blob, fileName) => {
  if (!blob || !fileName) return;
  const downloadUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = downloadUrl;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(downloadUrl);
};

const resolveFormXVEmployeeDownloadBaseName = (row, hdrs, fallbackIndex = 0) => {
  const headers = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : FORM_XV_TABLE_HEADERS;
  const workmanHeader = headers.find(isFormXVWorkmanNameHeader);
  const raw = workmanHeader ? String(row?.[workmanHeader] ?? '').trim() : '';
  const nameOnly = raw.split(',')[0].trim();
  const label =
    nameOnly ||
    String(row?.__employeeLookupName ?? '').trim() ||
    `Employee_${fallbackIndex + 1}`;
  const slug = label
    .replace(/[^\w\s.-]/g, '')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '')
    .slice(0, 48);
  return slug || `Employee_${fallbackIndex + 1}`;
};

const allocateUniqueFormXVDownloadFileName = (baseName, usedNames) => {
  const root = String(baseName || 'Employee').trim() || 'Employee';
  const count = usedNames.get(root) || 0;
  usedNames.set(root, count + 1);
  const suffix = count > 0 ? `_${count + 1}` : '';
  return `Form_XV_${root}${suffix}.xlsx`;
};

const formXVMPEscapeXml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const formXVMPColToLetter = (col) => {
  let result = '';
  let n = col;
  while (n > 0) {
    const rem = (n - 1) % 26;
    result = String.fromCharCode(65 + rem) + result;
    n = Math.floor((n - 1) / 26);
  }
  return result;
};

const formXVMPToCellRef = (row, col) => `${formXVMPColToLetter(col)}${row}`;

const formXVMPUpsertInlineStrCell = (sheetXml, cellRef, value) => {
  const text = formXVMPEscapeXml(String(value ?? '').trim());
  const cellXml = text
    ? `<c r="${cellRef}" t="inlineStr"><is><t xml:space="preserve">${text}</t></is></c>`
    : `<c r="${cellRef}"/>`;
  const cellRe = new RegExp(`<c\\s+r="${cellRef}"[^>]*(?:/>|>[\\s\\S]*?</c>)`, 'i');
  if (cellRe.test(sheetXml)) {
    return sheetXml.replace(cellRe, cellXml);
  }
  const rowNum = cellRef.replace(/^[A-Z]+/i, '');
  const rowRe = new RegExp(`(<row\\s+r="${rowNum}"[^>]*>)([\\s\\S]*?)(</row>)`, 'i');
  if (!rowRe.test(sheetXml)) return sheetXml;
  return sheetXml.replace(rowRe, `$1$2${cellXml}$3`);
};

const resolveFormXVMPWorksheetEntry = (zipFiles) =>
  Object.keys(zipFiles)
    .filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/i.test(name))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))[0] || null;

const formatFormXVCellForXmlPatch = (value, header) => {
  const coerced = coerceFormXVCellExportValue(value, header);
  if (coerced == null || coerced === '') return '';
  if (coerced instanceof Date) {
    return coerced.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).replace(/ /g, '-');
  }
  return String(coerced).trim();
};

const resolveFormXVStackedExportCellPositions = (worksheet, layout, hdrs, { preferTamilNadu = false } = {}) => {
  if (!worksheet || !layout) return [];
  const { headerRow, dataStartRow, columnByHeader, hdrs: exportHdrs, allHdrs } = layout;
  const fullHdrs = Array.isArray(allHdrs) && allHdrs.length > 0 ? allHdrs : hdrs;
  const positions = [];
  const seenRefs = new Set();
  const valueCol = resolveFormXVStackedValueColumn(worksheet, headerRow, { preferTamilNadu });

  const pushPos = (row, col, headerKey) => {
    const cellRef = formXVMPToCellRef(row, col);
    if (seenRefs.has(cellRef)) return;
    seenRefs.add(cellRef);
    positions.push({ row, col, headerKey, cellRef });
  };

  for (const spec of FORM_XV_WORKMAN_HEADER_LABEL_SPECS) {
    const label = findFormXVMasterLabelCell(worksheet, headerRow, spec.match, 12);
    if (!label) continue;
    const headerKey = fullHdrs.find((h) => spec.rowTest(h));
    if (headerKey) pushPos(label.row, valueCol, headerKey);
  }

  const tableHdrs = Array.isArray(exportHdrs) && exportHdrs.length > 0 ? exportHdrs : getFormXVExportTableHeaders(fullHdrs);
  for (let j = 0; j < tableHdrs.length; j += 1) {
    pushPos(dataStartRow, columnByHeader[j], tableHdrs[j]);
  }
  return positions;
};

const prepareFormXVMPFastZipTemplate = async ({
  templateArrayBuffer,
  headersToUse,
  parsedHeaderRowIndex,
  parsedDataStartIndex,
  parsedFormHeader,
  headerFormData,
  preferTamilNadu = false
}) => {
  const hdrs =
    Array.isArray(headersToUse) && headersToUse.length > 0 ? headersToUse : [...FORM_XV_TABLE_HEADERS];
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(templateArrayBuffer);
  const worksheet = workbook.worksheets[0];
  if (!worksheet) throw new Error('Template worksheet not found.');

  const layout = resolveFormXVWorksheetExportLayout(worksheet, {
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    headersToUse: hdrs
  });

  clearFormXVStackedCertificateValueBand(worksheet, layout.headerRow, { preferTamilNadu });
  clearFormXVDataRows(worksheet, layout, 1);

  writeFormXVHeaderFieldsToWorksheet(worksheet, layout, {
    parsedFormHeader,
    headerFormData,
    includeStaticBoxes: true,
    includeNatureBox: false,
    preferTamilNadu,
    // Fast-zip path is only used for stacked certificates (MP / TN).
    forceStacked: true
  });
  ensureFormXVStackedTitleBand(worksheet, layout.headerRow, { preferTamilNadu });
  const positions = resolveFormXVStackedExportCellPositions(worksheet, layout, hdrs, {
    preferTamilNadu
  });

  const preparedBuffer = await workbook.xlsx.writeBuffer();
  const templateZip = await JSZip.loadAsync(preparedBuffer);
  const sheetEntry = resolveFormXVMPWorksheetEntry(templateZip.files);
  if (!sheetEntry) throw new Error('Template worksheet XML not found.');
  const baseSheetXml = await templateZip.file(sheetEntry).async('string');
  const staticFiles = {};
  await Promise.all(
    Object.keys(templateZip.files).map(async (path) => {
      const file = templateZip.files[path];
      if (!file || file.dir || path === sheetEntry) return;
      staticFiles[path] = await file.async('uint8array');
    })
  );
  return { sheetEntry, baseSheetXml, staticFiles, positions, hdrs };
};

const buildFormXVMPFastZipDownload = async ({
  exportRows,
  hdrs,
  fastTemplate,
  formFileName,
  parsedFormHeader,
  applySignSeal
}) => {
  const { sheetEntry, baseSheetXml, staticFiles, positions } = fastTemplate;
  const zip = new JSZip();
  const usedNames = new Map();
  for (let i = 0; i < exportRows.length; i += 1) {
    const singleRow = buildFormXVSingleEmployeeExportRow(exportRows[i], hdrs);
    let sheetXml = baseSheetXml;
    for (let pi = 0; pi < positions.length; pi += 1) {
      const pos = positions[pi];
      let value = resolveFormXVExportRowValue(singleRow, pos.headerKey, hdrs);
      const hdrNorm = normalizeFormXVTableHeader(pos.headerKey);
      if (
        (value == null || String(value).trim() === '') &&
        (hdrNorm.includes('sr') && hdrNorm.includes('no'))
      ) {
        value = 1;
      }
      sheetXml = formXVMPUpsertInlineStrCell(
        sheetXml,
        pos.cellRef,
        formatFormXVCellForXmlPatch(value, pos.headerKey)
      );
    }
    const entryZip = new JSZip();
    Object.entries(staticFiles).forEach(([path, data]) => {
      entryZip.file(path, data);
    });
    entryZip.file(sheetEntry, sheetXml);
    let xlsxBytes = await entryZip.generateAsync({ type: 'uint8array', compression: 'STORE' });
    if (typeof applySignSeal === 'function') {
      const sealed = await applySignSeal(new Blob([xlsxBytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }));
      if (sealed instanceof Blob) {
        xlsxBytes = new Uint8Array(await sealed.arrayBuffer());
      }
    }
    const baseName = resolveFormXVEmployeeDownloadBaseName(singleRow, hdrs, i);
    zip.file(allocateUniqueFormXVDownloadFileName(baseName, usedNames), xlsxBytes);
    if (i > 0 && i % 25 === 0) {
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
  }
  const zipBase = String(formFileName || parsedFormHeader?.title || 'Form_XV_MP')
    .replace(/\.xlsx?$/i, '')
    .replace(/[^\w.-]+/g, '_');
  return {
    blob: await zip.generateAsync({ type: 'blob', compression: 'STORE' }),
    fileName: `${zipBase}_Employees.zip`
  };
};

const coerceFormXVCellExportValue = (value, headerName) => {
  const s = value == null ? '' : String(value).trim();
  if (!s) return '';
  const h = normalizeFormXVTableHeader(headerName);
  const looksLikeLongNumeric = /^\d{8,}$/.test(s.replace(/[\s-]/g, ''));
  if (looksLikeLongNumeric || h.includes('nature') || h.includes('remarks') || h.includes('from') || h.includes('to')) {
    return s;
  }
  if (
    h.includes('workman') ||
    h.includes('workmen') ||
    h.includes('identification') ||
    h.includes('father') ||
    h.includes('husband') ||
    (h.includes('age') && !h.includes('wage'))
  ) {
    return s;
  }
  if (/^-?\d+(\.\d+)?$/.test(s) && (h.includes('sr') || h.includes('serial') || h.includes('rate'))) {
    return Number(s);
  }
  return s;
};

const formXVExcelCellValueToString = (val) => {
  if (val == null) return '';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
  if (val instanceof Date) return val.toISOString();
  if (typeof val === 'object') {
    if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
    if (val.text != null) return String(val.text);
    if (val.result != null) return String(val.result);
  }
  return '';
};

const resolveFormXVWorksheetExportLayout = (worksheet, { parsedHeaderRowIndex, parsedDataStartIndex, headersToUse }) => {
  if (!worksheet) throw new Error('Template worksheet not found.');
  const maxScanRows = Math.max(80, worksheet.rowCount + 10);
  const maxScanCols = 30;
  let headerRow = parsedHeaderRowIndex != null && parsedHeaderRowIndex >= 0 ? parsedHeaderRowIndex + 1 : -1;
  if (headerRow < 1) {
    for (let r = 1; r <= maxScanRows; r += 1) {
      const rowBits = [];
      for (let c = 1; c <= maxScanCols; c += 1) {
        const t = normalizeFormXVTableHeader(formXVExcelCellValueToString(worksheet.getCell(r, c)?.value));
        if (t) rowBits.push(t);
      }
      const joined = rowBits.join(' ');
      if (
        (/\bsr\.?\s*no\b/.test(joined) || /\bserial\b/.test(joined)) &&
        (joined.includes('nature') || joined.includes('workman')) &&
        joined.includes('wage')
      ) {
        headerRow = r;
        break;
      }
    }
  }
  if (headerRow < 1) throw new Error('Could not locate Form XV table header row.');

  let dataStartRow =
    parsedDataStartIndex != null && parsedDataStartIndex >= 0 ? parsedDataStartIndex + 1 : headerRow + 2;
  for (let r = headerRow + 1; r <= Math.min(headerRow + 4, maxScanRows); r += 1) {
    let fromCol = -1;
    let toCol = -1;
    for (let c = 1; c <= maxScanCols; c += 1) {
      const t = normalizeFormXVTableHeader(formXVExcelCellValueToString(worksheet.getCell(r, c)?.value));
      if (t === 'from') fromCol = c;
      if (t === 'to' && !t.includes('from')) toCol = c;
    }
    if (fromCol > 0 && toCol > fromCol) {
      dataStartRow = r + 1;
      // TN templates often have a 1..6 column-index row under From/To — skip it.
      let indexHits = 0;
      for (let c = 1; c <= 6; c += 1) {
        const idx = String(formXVExcelCellValueToString(worksheet.getCell(dataStartRow, c)?.value) || '').trim();
        if (idx === String(c)) indexHits += 1;
      }
      if (indexHits >= 4) dataStartRow += 1;
      break;
    }
  }

  const hdrs =
    Array.isArray(headersToUse) && headersToUse.length > 0 ? headersToUse : [...FORM_XV_TABLE_HEADERS];
  const exportHdrs = getFormXVExportTableHeaders(hdrs);

  const resolveFormXVExportColumn = (header, colIndex) => {
    const target = normalizeFormXVTableHeader(header);
    const preferSubRow =
      (target.includes('from') && target.includes('period')) ||
      (target.includes('to') && target.includes('period') && !target.includes('from'));
    const preferParentRow =
      target.includes('nature') ||
      target.includes('rate') ||
      target.includes('remark') ||
      (target.includes('sr') && target.includes('no'));
    const orderedRows = preferSubRow
      ? [headerRow + 1, headerRow].filter((r) => r >= 1)
      : preferParentRow
        ? [headerRow, headerRow + 1].filter((r) => r >= 1)
        : [headerRow, headerRow + 1].filter((r) => r >= 1);
    for (let ri = 0; ri < orderedRows.length; ri += 1) {
      const r = orderedRows[ri];
      for (let c = 1; c <= maxScanCols; c += 1) {
        const cellNorm = normalizeFormXVTableHeader(formXVExcelCellValueToString(worksheet.getCell(r, c)?.value));
        if (!cellNorm) continue;
        if (target.includes('nature') && cellNorm.includes('nature') && cellNorm.includes('work')) return c;
        if (target.includes('rate') && target.includes('wage') && cellNorm.includes('rate') && cellNorm.includes('wage')) {
          return c;
        }
        if (cellNorm === target || cellNorm.includes(target) || target.includes(cellNorm)) {
          return c;
        }
        if (target.includes('from') && cellNorm === 'from') return c;
        if (target.includes('to') && !target.includes('from') && cellNorm === 'to') return c;
      }
    }
    return colIndex + 1;
  };

  const columnByHeader = exportHdrs.map((header, j) => resolveFormXVExportColumn(header, j));
  const usedExportCols = [...new Set(columnByHeader)];
  return { headerRow, dataStartRow, hdrs: exportHdrs, allHdrs: hdrs, columnByHeader, usedExportCols, maxScanCols };
};

const getFormXVRowValueForHeader = (row, header) => {
  if (!row || typeof row !== 'object') return '';
  if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];
  const target = normalizeFormXVTableHeader(header);
  const keys = Object.keys(row);
  const exact = keys.filter((k) => normalizeFormXVTableHeader(k) === target);
  if (exact.length === 1) return row[exact[0]];
  const fuzzy = keys.find((k) => {
    const n = normalizeFormXVTableHeader(k);
    return n && (n.includes(target) || target.includes(n));
  });
  return fuzzy ? row[fuzzy] : '';
};

const splitFormXVHeaderBoxLines = (text) => {
  const s = String(text || '').trim();
  if (!s) return [];
  if (s.includes('\n')) return s.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const parts = s.split(/,\s*/).map((part) => part.trim()).filter(Boolean);
  if (parts.length <= 1) return [s];
  return parts;
};

/** Master cell only — merge slaves echo the same label and falsely push the value column to G. */
const formXVCellIsMergeSlave = (cell) =>
  !!(cell && cell.isMerged && cell.master && cell.master !== cell);

const formXVMergeEndCol = (worksheet, row, col) => {
  if (!worksheet || row < 1 || col < 1) return col;
  try {
    const cell = worksheet.getCell(row, col);
    const master = cell?.isMerged && cell.master ? cell.master : cell;
    if (!master) return col;
    const masterRow = master.row || row;
    const masterCol = master.col || col;
    let endCol = masterCol;
    // Walk right while still in the same merge.
    for (let c = masterCol + 1; c <= masterCol + 12; c += 1) {
      const next = worksheet.getCell(masterRow, c);
      if (next?.isMerged && next.master && next.master === master) {
        endCol = c;
        continue;
      }
      break;
    }
    return endCol;
  } catch (_) {
    return col;
  }
};

/** Leftmost master cell matching a header label above the employment table. */
const findFormXVMasterLabelCell = (worksheet, headerRow, matchRe, maxCol = 8) => {
  if (!worksheet || headerRow < 2 || !matchRe) return null;
  let best = null;
  for (let r = 1; r < headerRow; r += 1) {
    for (let c = 1; c <= maxCol; c += 1) {
      const cell = worksheet.getCell(r, c);
      if (formXVCellIsMergeSlave(cell)) continue;
      const cellStr = String(formXVExcelCellValueToString(cell?.value) || '').trim();
      if (!cellStr || !matchRe.test(cellStr)) continue;
      if (!best || c < best.col || (c === best.col && r < best.row)) {
        best = { row: r, col: c };
      }
    }
  }
  return best;
};

/** TN template signature: certificate labels stacked in column A above the employment table (A–F body). */
const detectFormXVTamilNaduTemplateLayout = (worksheet, headerRow) => {
  if (!worksheet || headerRow < 6) return false;
  const contractor = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?contractor/i
  );
  if (!contractor || contractor.col > 1) return false;
  const workman = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i
  );
  const principal = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?principal\s+employer|principal\s+employer/i
  );
  if (!(workman && workman.col === contractor.col && principal && principal.col === contractor.col)) {
    return false;
  }
  // TN title band is in column A (rows 1–3). MP keeps FORM XV in column F.
  let hasTnTitleInColA = false;
  for (let r = 1; r <= Math.min(4, headerRow - 1); r += 1) {
    const text = String(formXVExcelCellValueToString(worksheet.getCell(r, 1)?.value) || '').trim();
    if (
      /^form\s*xv\b/i.test(text) ||
      /^service\s+certificate\b/i.test(text) ||
      /^\(?\s*see\s+rule\b/i.test(text)
    ) {
      hasTnTitleInColA = true;
      break;
    }
  }
  const mpTitle = String(formXVExcelCellValueToString(worksheet.getCell(2, 6)?.value) || '').trim();
  const hasMpTitleInColF = /^form\s*xv\b/i.test(mpTitle);
  if (hasMpTitleInColF && !hasTnTitleInColA) return false;
  const mergeEnd = formXVMergeEndCol(worksheet, contractor.row, contractor.col);
  // TN: either full-width A:F label merges, or title band in column A with stacked col-A labels.
  return hasTnTitleInColA || mergeEnd >= 6;
};

/** MP/TN Form XV — labels stack in one column; values sit on the same row (not AP two-column boxes). */
const detectFormXVStackedCertificateLayout = (worksheet, headerRow, forceStacked = false) => {
  if (forceStacked) return true;
  if (!worksheet || headerRow < 2) return false;
  const contractor = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?contractor/i
  );
  const establishment = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /establishment[\s\S]*contract/i
  );
  const nature = findFormXVMasterLabelCell(worksheet, headerRow, /nature\s+and\s+location/i);
  const principal = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?principal\s+employer|principal\s+employer/i
  );
  const workman = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i
  );

  const labelCols = [contractor, establishment, nature, principal, workman]
    .filter(Boolean)
    .map((x) => x.col);
  // Tamil Nadu / MP: several certificate labels share one column (usually A).
  if (labelCols.length >= 3 && labelCols.every((c) => c === labelCols[0])) return true;
  if (contractor && establishment && contractor.col === establishment.col) return true;
  // MP stacked certificate — workman label without a separate nature/location header row.
  if (workman && !nature) return true;
  return false;
};

/** MP stacked certificate — values align in column E beside labels in column B. */
const FORM_XV_MP_STACKED_VALUE_COL = 5;
const FORM_XV_MP_STACKED_VALUE_COL_TO = 6;
/** MP template title band (FORM XV / See rule 77 / Service Certificate) lives in column F. */
const FORM_XV_MP_TITLE_COL = 6;

/** Title / legal-reference cells — must never be wiped when clearing the value band. */
const isFormXVStackedTitleBandText = (text) => {
  const s = String(text || '').trim();
  if (!s) return false;
  return (
    /^form\s*xv\b/i.test(s) ||
    /^service\s+certificate\b/i.test(s) ||
    /^\(?\s*see\s+rule\b/i.test(s) ||
    /\bsee\s+rule\s*\d+/i.test(s)
  );
};

/**
 * Value column beside stacked labels.
 * Never use column G for TN (form body is A–F); full-width A:F label merges write into the label cell.
 */
const resolveFormXVStackedValueColumn = (worksheet, headerRow, { preferTamilNadu = false } = {}) => {
  const contractor = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?contractor/i
  );
  if (!contractor) return preferTamilNadu ? 2 : FORM_XV_MP_STACKED_VALUE_COL;
  const mergeEnd = formXVMergeEndCol(worksheet, contractor.row, contractor.col);
  // Label occupies the whole A–F band — caller writes value into the label master cell.
  if (mergeEnd >= 6 && contractor.col <= 1) return contractor.col;
  const nextCol = mergeEnd + 1;
  if (preferTamilNadu) {
    // Keep values inside the A–F certificate body (never column G).
    if (nextCol >= 1 && nextCol <= 6) return nextCol;
    return Math.min(Math.max(contractor.col + 1, 2), 6);
  }
  if (contractor.col === 2) return FORM_XV_MP_STACKED_VALUE_COL;
  if (nextCol >= 1 && nextCol <= 14) return nextCol;
  return FORM_XV_MP_STACKED_VALUE_COL;
};

/**
 * Restore Form XV title band if clearing wiped titles.
 * MP titles live in column F; TN titles are centered across the A–F certificate body (rows 1–3).
 */
const ensureFormXVStackedTitleBand = (worksheet, headerRow, { preferTamilNadu = false } = {}) => {
  if (!worksheet || headerRow < 2) return;
  const titleSpecs = preferTamilNadu
    ? [
        { row: 1, value: 'Form XV', bold: true },
        { row: 2, value: '(See rule 77)', bold: false },
        { row: 3, value: 'Service Certificate', bold: true }
      ]
    : [
        { row: 2, value: 'FORM XV', bold: true },
        { row: 3, value: '(See rule 77)', bold: false },
        { row: 4, value: 'Service Certificate', bold: true }
      ];
  let hasAnyTitle = false;
  for (let r = 1; r < Math.min(headerRow, 8); r += 1) {
    for (let c = 1; c <= 8; c += 1) {
      const text = String(formXVExcelCellValueToString(worksheet.getCell(r, c)?.value) || '').trim();
      if (isFormXVStackedTitleBandText(text)) {
        hasAnyTitle = true;
        break;
      }
    }
    if (hasAnyTitle) break;
  }
  if (hasAnyTitle) return;
  const titleCol = preferTamilNadu ? 1 : FORM_XV_MP_TITLE_COL;
  for (const spec of titleSpecs) {
    if (spec.row >= headerRow) continue;
    const cell = worksheet.getCell(spec.row, titleCol);
    if (String(formXVExcelCellValueToString(cell?.value) || '').trim()) continue;
    cell.value = spec.value;
    cell.alignment = {
      ...(cell.alignment || {}),
      horizontal: 'center',
      vertical: 'middle'
    };
    if (spec.bold) {
      cell.font = { ...(cell.font || {}), bold: true };
    }
  }
};

const clearFormXVStackedCertificateValueBand = (
  worksheet,
  headerRow,
  { preferTamilNadu = false } = {}
) => {
  if (!worksheet || headerRow < 2) return;
  const valueCol = resolveFormXVStackedValueColumn(worksheet, headerRow, { preferTamilNadu });
  const clearFrom = preferTamilNadu ? Math.min(valueCol, 2) : valueCol;
  // MP: clear the value column (E) only — column F holds FORM XV / See rule 77 / Service Certificate.
  const clearTo = preferTamilNadu
    ? FORM_XV_MP_STACKED_VALUE_COL_TO
    : valueCol;
  for (let r = 1; r < headerRow; r += 1) {
    for (let c = clearFrom; c <= clearTo; c += 1) {
      const cell = worksheet.getCell(r, c);
      if (formXVCellIsMergeSlave(cell)) continue;
      // Do not wipe label master cells when valueCol === labelCol (full-width merge case).
      const text = String(formXVExcelCellValueToString(cell?.value) || '').trim();
      if (isFormXVStackedTitleBandText(text)) continue;
      if (
        /name\s+and\s+address\s+of\s+(?:the\s+)?contractor|nature\s+and\s+location|establishment[\s\S]*contract|principal\s+employer|name\s+and\s+address\s+of\s+the\s+workm[ae]n|age\s+or\s+date\s+of\s+birth|identification\s+marks|father.*husband/i.test(
          text
        )
      ) {
        // TN re-export: strip prior "Label: value" fills so only the statutory label remains.
        if (preferTamilNadu && /:/.test(text)) {
          const labelOnly = text
            .split(/\r?\n/)[0]
            .replace(/:\s+.*$/, '')
            .replace(/\s*:+\s*$/, '')
            .trim();
          if (labelOnly) cell.value = labelOnly;
        }
        continue;
      }
      cell.value = '';
    }
    // Clear stray AP exports that landed in column G outside the A–F form body.
    if (preferTamilNadu) {
      for (let c = 7; c <= 14; c += 1) {
        worksheet.getCell(r, c).value = '';
      }
    }
  }
  ensureFormXVStackedTitleBand(worksheet, headerRow, { preferTamilNadu });
};

const fitFormXVStackedValueRowHeight = (worksheet, row, valueText, valueCol, { preferTamilNadu = false } = {}) => {
  if (!worksheet || row < 1) return;
  const text = String(valueText || '');
  if (!text) return;
  const explicitLines = text.split(/\r?\n/).length;
  const colWidth = Number(worksheet.getColumn(valueCol)?.width) || 11;
  // TN labels span A–F; estimate wrap width from the certificate body, not a single narrow column.
  const charsPerLine = preferTamilNadu
    ? Math.max(40, Math.floor(colWidth * 6))
    : Math.max(8, Math.floor(colWidth * 1.1));
  let wrapLines = 0;
  text.split(/\r?\n/).forEach((line) => {
    wrapLines += Math.max(1, Math.ceil(String(line).length / charsPerLine));
  });
  const lines = Math.max(explicitLines, wrapLines);
  if (lines <= 1) return;
  const rowObj = worksheet.getRow(row);
  const maxHeight = preferTamilNadu ? 48 : 120;
  const nextHeight = Math.min(maxHeight, Math.max(Number(rowObj.height) || 15, lines * (preferTamilNadu ? 12 : 14)));
  rowObj.height = nextHeight;
};

const writeFormXVStackedHeaderValue = (
  worksheet,
  matchRe,
  value,
  headerRow,
  preferredCol = FORM_XV_MP_STACKED_VALUE_COL,
  { preferTamilNadu = false } = {}
) => {
  const text = String(value || '').trim();
  if (!text || !worksheet) return false;
  const label = findFormXVMasterLabelCell(worksheet, headerRow, matchRe);
  if (!label) return false;
  const lines = splitFormXVHeaderBoxLines(text);
  const valueText = lines.length > 1 ? lines.join('\n') : text;
  const mergeEnd = formXVMergeEndCol(worksheet, label.row, label.col);
  // Full-width A–F label merges (TN): never write into a merge slave column — that wipes the label.
  const fullWidthLabelMerge = mergeEnd >= 6 && label.col <= 1;
  // Tamil Nadu certificate: always keep value on the same label row as "Label: value".
  const writeIntoLabelCell = preferTamilNadu || (fullWidthLabelMerge && preferredCol <= mergeEnd);

  if (writeIntoLabelCell) {
    const master = worksheet.getCell(label.row, label.col);
    const labelText = String(formXVExcelCellValueToString(master?.value) || '').trim();
    // Keep the statutory label; put the filled value after it (TN stays compact on one/few lines).
    const labelOnly =
      labelText
        .split(/\r?\n/)[0]
        .replace(/\s*:+\s*$/, '')
        .replace(/:\s+.*$/, '')
        .trim() || labelText;
    let cellValue;
    if (preferTamilNadu || fullWidthLabelMerge) {
      const compact = valueText.replace(/\s*\n\s*/g, ', ').replace(/\s+/g, ' ').trim();
      cellValue = `${labelOnly}: ${compact}`;
    } else {
      cellValue = `${labelOnly}\n${valueText}`;
    }
    master.value = cellValue;
    master.alignment = {
      ...(master.alignment || {}),
      horizontal: 'left',
      vertical: preferTamilNadu ? 'middle' : 'top',
      wrapText: true,
      shrinkToFit: false
    };
    fitFormXVStackedValueRowHeight(worksheet, label.row, cellValue, label.col, { preferTamilNadu });
    return true;
  }

  // Same row as the label — never write into the title column (F) on MP templates.
  let valueCol = preferredCol > label.col ? preferredCol : Math.min(mergeEnd + 1, 6);
  if (!preferTamilNadu && valueCol === FORM_XV_MP_TITLE_COL) {
    valueCol = FORM_XV_MP_STACKED_VALUE_COL;
  }
  // Guard: if the resolved value column is still inside the label merge, preserve the label.
  if (valueCol >= label.col && valueCol <= mergeEnd) {
    const master = worksheet.getCell(label.row, label.col);
    const labelText = String(formXVExcelCellValueToString(master?.value) || '').trim();
    const labelOnly =
      labelText
        .split(/\r?\n/)[0]
        .replace(/\s*:+\s*$/, '')
        .trim() || labelText;
    const compact = valueText.replace(/\s*\n\s*/g, ', ').replace(/\s+/g, ' ').trim();
    const cellValue = `${labelOnly}: ${compact}`;
    master.value = cellValue;
    master.alignment = {
      ...(master.alignment || {}),
      horizontal: 'left',
      vertical: 'middle',
      wrapText: true,
      shrinkToFit: false
    };
    fitFormXVStackedValueRowHeight(worksheet, label.row, cellValue, label.col, { preferTamilNadu: true });
    return true;
  }
  const cell = worksheet.getCell(label.row, valueCol);
  cell.value = valueText;
  cell.alignment = {
    ...(cell.alignment || {}),
    horizontal: 'left',
    vertical: 'top',
    wrapText: true,
    shrinkToFit: false
  };
  // Keep value band readable so wrapped text does not spill into neighbouring rows.
  if (!preferTamilNadu) {
    const col = worksheet.getColumn(valueCol);
    const cur = Number(col.width) || 0;
    if (cur > 0 && cur < 28) col.width = 28;
  }
  fitFormXVStackedValueRowHeight(worksheet, label.row, valueText, valueCol, { preferTamilNadu });
  return true;
};

const clearFormXVStackedHeaderValueCells = (worksheet, headerRow, opts = {}) => {
  if (!worksheet || headerRow < 2) return;
  clearFormXVStackedCertificateValueBand(worksheet, headerRow, opts);
};

/** Resolve the bordered/merged value box under a Form XV_GJ site label. */
const resolveFormXVGJSiteBoxArea = (worksheet, labelRow, labelCol, side = 'left') => {
  const halfStart = side === 'right' ? Math.max(6, labelCol) : Math.max(1, Math.min(labelCol, 3));
  const halfEnd = side === 'right' ? 12 : 5;
  const boxTop = labelRow + 1;
  if (!worksheet || labelRow < 1) {
    return { row: boxTop, col: halfStart, rowSpan: 6, colSpan: halfEnd - halfStart + 1 };
  }
  const colLettersToNum = (letters) => {
    let n = 0;
    for (const ch of String(letters || '').toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64);
    return n;
  };
  // Prefer an existing merge that sits directly under the label in this half.
  try {
    const mergeList = Array.isArray(worksheet.model?.merges) ? worksheet.model.merges : [];
    let best = null;
    for (const range of mergeList) {
      const parts = String(range || '').split(':');
      if (parts.length !== 2) continue;
      const start = String(parts[0]).match(/^([A-Z]+)(\d+)$/i);
      const end = String(parts[1]).match(/^([A-Z]+)(\d+)$/i);
      if (!start || !end) continue;
      const top = Math.min(Number(start[2]), Number(end[2]));
      const bottom = Math.max(Number(start[2]), Number(end[2]));
      const left = Math.min(colLettersToNum(start[1]), colLettersToNum(end[1]));
      const right = Math.max(colLettersToNum(start[1]), colLettersToNum(end[1]));
      if (top < boxTop || top > labelRow + 3) continue;
      if (bottom - top < 1) continue;
      const overlapLeft = Math.max(left, halfStart);
      const overlapRight = Math.min(right, halfEnd);
      if (overlapRight < overlapLeft) continue;
      if (!best || top < best.top || (top === best.top && left < best.left)) {
        best = { top, bottom, left: overlapLeft, right: overlapRight };
      }
    }
    if (best) {
      return {
        row: best.top,
        col: best.left,
        rowSpan: best.bottom - best.top + 1,
        colSpan: best.right - best.left + 1
      };
    }
  } catch (_) {
    /* fall through to defaults */
  }
  return {
    row: boxTop,
    col: halfStart,
    rowSpan: 6,
    colSpan: halfEnd - halfStart + 1
  };
};

const clearFormXVGJSiteBoxSpill = (worksheet, headerRow) => {
  if (!worksheet || headerRow < 8) return;
  const workman = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i,
    14
  );
  const nature = findFormXVMasterLabelCell(worksheet, headerRow, /nature\s+and\s+location/i, 14);
  const principal = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+(?:the\s+)?principal\s+employer|principal\s+employer/i,
    14
  );
  let clearFrom = 21;
  if (nature) {
    const area = resolveFormXVGJSiteBoxArea(worksheet, nature.row, nature.col, 'left');
    clearFrom = Math.max(clearFrom, area.row + area.rowSpan);
  }
  if (principal) {
    const area = resolveFormXVGJSiteBoxArea(worksheet, principal.row, principal.col, 'right');
    clearFrom = Math.max(clearFrom, area.row + area.rowSpan);
  }
  const clearUntil = workman ? workman.row - 1 : Math.min(headerRow - 1, 34);
  if (clearFrom > clearUntil) return;
  // Gap rows between principal/nature boxes and workman band often keep orphan fragments (e.g. "Theni").
  for (let r = clearFrom; r <= clearUntil; r += 1) {
    for (let c = 1; c <= 14; c += 1) {
      const cell = worksheet.getCell(r, c);
      if (formXVCellIsMergeSlave(cell)) continue;
      const text = String(formXVExcelCellValueToString(cell?.value) || '').trim();
      if (!text) continue;
      if (
        /name\s+and\s+address|nature\s+and\s+location|principal\s+employer|age\s+or\s+date|identification|father|husband|form\s*xv|service\s+certificate|vide\s+rule|see\s+rule/i.test(
          text
        )
      ) {
        continue;
      }
      cell.value = '';
    }
  }
};

const ensureFormXVGJTitleBandAlignment = (worksheet, headerRow) => {
  if (!worksheet || headerRow < 2) return;
  for (let r = 1; r <= Math.min(5, headerRow - 1); r += 1) {
    for (let c = 1; c <= 12; c += 1) {
      const cell = worksheet.getCell(r, c);
      if (formXVCellIsMergeSlave(cell)) continue;
      const text = String(formXVExcelCellValueToString(cell?.value) || '').trim();
      if (!text) continue;
      if (
        /^form\s*xv\b/i.test(text) ||
        /^service\s+certificate\b/i.test(text) ||
        /vide\s+rule\s*77/i.test(text) ||
        /^\(?\s*see\s+rule\b/i.test(text)
      ) {
        cell.alignment = {
          ...(cell.alignment || {}),
          horizontal: 'center',
          vertical: 'middle',
          wrapText: /vide\s+rule|see\s+rule/i.test(text),
          shrinkToFit: false
        };
        if (/^form\s*xv\b|^service\s+certificate\b/i.test(text)) {
          cell.font = { ...(cell.font || {}), bold: true };
        }
      }
    }
  }
};

const writeFormXVHeaderFieldsToWorksheet = (
  worksheet,
  layout,
  {
    parsedFormHeader,
    headerFormData,
    employeeRow = null,
    hdrs = null,
    includeStaticBoxes = true,
    includeNatureBox = true,
    preferTamilNadu = false,
    preferGujarat = false,
    forceStacked = false
  }
) => {
  const { headerRow } = layout;
  const headerFields = parsedFormHeader?.fields;
  const headerValues = headerFormData && typeof headerFormData === 'object' ? headerFormData : {};
  const allHdrs = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [...FORM_XV_TABLE_HEADERS];

  const resolveHeaderValue = (key, labelMatch) => {
    if (key && Object.prototype.hasOwnProperty.call(headerValues, key)) {
      const direct = String(headerValues[key] ?? '').trim();
      if (direct && !isStatutoryHeaderPlaceholderValue(direct)) return direct;
    }
    if (!Array.isArray(headerFields)) return '';
    const field = headerFields.find((f) => {
      if (key && f?.key === key) return true;
      const lbl = String(f?.label || '');
      return labelMatch && labelMatch.test(lbl);
    });
    const fromField = String(field?.value ?? headerValues[field?.key] ?? '').trim();
    return fromField && !isStatutoryHeaderPlaceholderValue(fromField) ? fromField : '';
  };

  // Gujarat two-column boxes must never take the TN/MP stacked path.
  const stackedLayout =
    !preferGujarat &&
    (detectFormXVStackedCertificateLayout(worksheet, headerRow, forceStacked || preferTamilNadu) ||
      preferTamilNadu);
  if (stackedLayout) {
    const stackedValueCol = resolveFormXVStackedValueColumn(worksheet, headerRow, {
      preferTamilNadu
    });
    const stackedSiteSpecs = [
      {
        key: 'form_xv_contractor',
        match: /name\s+and\s+address\s+of\s+(?:the\s+)?contractor/i,
        static: true
      },
      {
        key: 'form_xv_nature_location_work',
        match: /nature\s+and\s+location/i,
        static: false
      },
      {
        key: 'form_xv_establishment_contract_carried',
        match: /establishment[\s\S]*contract/i,
        static: true
      },
      {
        key: 'form_xv_principal_employer',
        match: /name\s+and\s+address\s+of\s+(?:the\s+)?principal\s+employer|principal\s+employer/i,
        static: true
      }
    ];
    for (const spec of stackedSiteSpecs) {
      if (spec.static && !includeStaticBoxes) continue;
      if (!spec.static && !includeNatureBox) continue;
      let value = resolveHeaderValue(spec.key, spec.match);
      if (spec.key === 'form_xv_nature_location_work') {
        const natureHeader = allHdrs.find(isFormXVNatureOfWorkHeader);
        const natureLine =
          employeeRow && natureHeader
            ? String(getFormXVRowValueForHeader(employeeRow, natureHeader) ?? '').trim()
            : '';
        value = [value, natureLine].filter(Boolean).join('\n');
      }
      writeFormXVStackedHeaderValue(worksheet, spec.match, value, headerRow, stackedValueCol, {
        preferTamilNadu
      });
    }
    return;
  }

  const findFormXVSiteLabel = (matchRe) => {
    const found = findFormXVMasterLabelCell(worksheet, headerRow, matchRe, 12);
    return found ? { labelRow: found.row, labelCol: found.col } : null;
  };

  const resolveFormXVSiteBoxAnchor = (spec) => {
    const label = findFormXVSiteLabel(spec.match);
    if (label) {
      if (preferGujarat) {
        const area = resolveFormXVGJSiteBoxArea(
          worksheet,
          label.labelRow,
          label.labelCol,
          spec.side
        );
        return area;
      }
      const interiorRow = label.labelRow + 1;
      const interiorCol =
        spec.side === 'right'
          ? label.labelCol >= 6
            ? label.labelCol
            : 7
          : label.labelCol <= 5
            ? label.labelCol
            : 2;
      return { row: interiorRow, col: interiorCol, rowSpan: 5, colSpan: 4 };
    }
    if (spec.key === 'form_xv_nature_location_work') {
      const principal = findFormXVSiteLabel(/principal\s+employer/i);
      if (principal) {
        if (preferGujarat) {
          return resolveFormXVGJSiteBoxArea(worksheet, principal.labelRow, 2, 'left');
        }
        return { row: principal.labelRow + 1, col: 2, rowSpan: 5, colSpan: 4 };
      }
    }
    return { ...spec.defaultAnchor, rowSpan: 5, colSpan: 4 };
  };

  const splitFormXVBoxLines = (text) => {
    const s = String(text || '').trim();
    if (!s) return [];
    if (s.includes('\n')) return s.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
    const parts = s.split(/,\s*/).map((part) => part.trim()).filter(Boolean);
    if (parts.length <= 1) return [s];
    return parts;
  };

  const clearFormXVSiteBox = (row, col, rowSpan = 5, colSpan = 4) => {
    for (let r = row; r < row + rowSpan; r += 1) {
      for (let c = col; c < col + colSpan; c += 1) {
        const cell = worksheet.getCell(r, c);
        if (formXVCellIsMergeSlave(cell)) continue;
        cell.value = '';
      }
    }
  };

  const writeFormXVSiteBoxMultiline = (anchor, lines, rowSpan = 5, colSpan = 4) => {
    const parts = (Array.isArray(lines) ? lines : [lines])
      .map((line) => dedupeFormXVRepeatedText(line))
      .filter(Boolean);
    if (parts.length === 0 || !anchor) return;
    const spanRows = Number(anchor.rowSpan) > 0 ? Number(anchor.rowSpan) : rowSpan;
    const spanCols = Number(anchor.colSpan) > 0 ? Number(anchor.colSpan) : colSpan;
    clearFormXVSiteBox(anchor.row, anchor.col, spanRows, spanCols);
    const cell = worksheet.getCell(anchor.row, anchor.col);
    cell.value = parts.join('\n');
    cell.alignment = {
      ...(cell.alignment || {}),
      horizontal: 'left',
      vertical: 'top',
      wrapText: true,
      shrinkToFit: false
    };
  };

  const siteBoxSpecs = [
    {
      key: 'form_xv_contractor',
      match: /name\s+and\s+address\s+of\s+(?:the\s+)?contractor/i,
      defaultAnchor: { row: 7, col: preferGujarat ? 1 : 2 },
      side: 'left',
      static: true
    },
    {
      key: 'form_xv_establishment_contract_carried',
      match: /establishment[\s\S]*contract\s+is\s+car/i,
      defaultAnchor: { row: 7, col: preferGujarat ? 6 : 7 },
      side: 'right',
      static: true
    },
    {
      key: 'form_xv_nature_location_work',
      match: /nature\s+and\s+location/i,
      defaultAnchor: { row: 15, col: preferGujarat ? 1 : 2 },
      side: 'left',
      static: false
    },
    {
      key: 'form_xv_principal_employer',
      match: /name\s+and\s+address\s+of\s+(?:the\s+)?principal\s+employer|principal\s+employer/i,
      defaultAnchor: { row: 15, col: preferGujarat ? 6 : 7 },
      side: 'right',
      static: true
    }
  ];

  for (const spec of siteBoxSpecs) {
    if (spec.static && !includeStaticBoxes) continue;
    if (!spec.static && !includeNatureBox) continue;

    const anchor = resolveFormXVSiteBoxAnchor(spec);
    if (!anchor) continue;

    if (spec.key === 'form_xv_nature_location_work') {
      const locationLine = resolveHeaderValue(spec.key, spec.match);
      const natureHeader = allHdrs.find(isFormXVNatureOfWorkHeader);
      const natureLine =
        employeeRow && natureHeader ? String(getFormXVRowValueForHeader(employeeRow, natureHeader) ?? '').trim() : '';
      writeFormXVSiteBoxMultiline(anchor, [locationLine, natureLine].filter(Boolean));
      continue;
    }

    const value = resolveHeaderValue(spec.key, spec.match);
    writeFormXVSiteBoxMultiline(anchor, splitFormXVBoxLines(value));
  }

  if (preferGujarat) {
    clearFormXVGJSiteBoxSpill(worksheet, headerRow);
    ensureFormXVGJTitleBandAlignment(worksheet, headerRow);
  }
};

const dedupeFormXVRepeatedText = (text) => {
  const s = String(text || '').trim();
  if (!s) return '';
  const words = s.split(/\s+/).filter(Boolean);
  if (words.length >= 2) {
    for (let n = 1; n <= Math.floor(words.length / 2); n += 1) {
      if (words.length % n !== 0) continue;
      const phrase = words.slice(0, n).join(' ');
      const reps = words.length / n;
      if (reps > 1 && Array(reps).fill(phrase).join(' ') === words.join(' ')) {
        return phrase;
      }
    }
  }
  return s;
};

const looksLikeFormXVWorkmanLabelCell = (cellStr, spec) => {
  const s = String(cellStr || '').trim();
  if (!s) return false;
  if (spec.key === 'form_xv_workman' && /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i.test(s)) return true;
  const cellNorm = normalizeFormXVTableHeader(s);
  const labelNorm = normalizeFormXVTableHeader(spec.label);
  if (spec.match.test(s)) return true;
  if (cellNorm === labelNorm) return true;
  if (cellNorm === normalizeFormXVTableHeader('Name and address of the workmen')) return spec.key === 'form_xv_workman';
  if (cellNorm.startsWith(labelNorm) && /:\s*$/.test(s)) return true;
  if (cellNorm.startsWith(labelNorm) && s.length <= spec.label.length + 8) return true;
  return false;
};

/** AP Form XV — workman values align in column F beside the B–E label band. */
const FORM_XV_WORKMAN_VALUE_COL = 6;

const resolveFormXVWorkmanValueColumn = (worksheet, headerRow) => {
  for (let r = 1; r < headerRow; r += 1) {
    for (let c = 1; c <= 5; c += 1) {
      const cellStr = String(formXVExcelCellValueToString(worksheet.getCell(r, c)?.value) || '').trim();
      if (!cellStr || !/name\s+and\s+address\s+of\s+contractor/i.test(cellStr)) continue;
      for (let vc = FORM_XV_WORKMAN_VALUE_COL; vc <= 10; vc += 1) {
        const v = String(formXVExcelCellValueToString(worksheet.getCell(r, vc)?.value) || '').trim();
        if (v && !/^[_\s.-]+$/.test(v) && !/name\s+and\s+address/i.test(v)) return vc;
      }
      for (let vr = r + 1; vr < Math.min(r + 6, headerRow); vr += 1) {
        const v = String(
          formXVExcelCellValueToString(worksheet.getCell(vr, FORM_XV_WORKMAN_VALUE_COL)?.value) || ''
        ).trim();
        if (v && !/name\s+and\s+address|nature\s+and\s+location/i.test(v)) return FORM_XV_WORKMAN_VALUE_COL;
      }
    }
  }
  return FORM_XV_WORKMAN_VALUE_COL;
};

const resetFormXVWorkmanLabelCell = (worksheet, row, col, spec) => {
  const cellStr = String(formXVExcelCellValueToString(worksheet.getCell(row, col)?.value) || '').trim();
  if (!looksLikeFormXVWorkmanLabelCell(cellStr, spec)) return;
  const beforeColon = cellStr.includes(':') ? cellStr.split(':')[0].trim() : spec.label.replace(/\s*:+\s*$/, '').trim();
  worksheet.getCell(row, col).value = `${beforeColon} :`;
};

const setFormXVWorkmanCellValue = (worksheet, row, col, value, { preferGujarat = false } = {}) => {
  const text = dedupeFormXVRepeatedText(value);
  if (!text) return;
  const cell = worksheet.getCell(row, col);
  cell.value = coerceFormXVCellExportValue(text, '');
  const multiline = String(text).includes('\n');
  cell.alignment = {
    ...(cell.alignment || {}),
    horizontal: 'left',
    // GJ template: single-line workman values sit mid-height beside tall B–E label merges.
    vertical: multiline ? 'top' : preferGujarat ? 'middle' : (cell.alignment?.vertical || 'top'),
    wrapText: multiline,
    shrinkToFit: false
  };
};

const clearFormXVStaleBelowRowValue = (worksheet, row, col, value) => {
  const belowRow = row + 1;
  const text = dedupeFormXVRepeatedText(value);
  if (!text) return;
  for (let dc = Math.max(1, col - 1); dc <= col + 4; dc += 1) {
    const belowCell = worksheet.getCell(belowRow, dc);
    const belowText = String(formXVExcelCellValueToString(belowCell?.value) || '').trim();
    if (!belowText) continue;
    const dedupedBelow = dedupeFormXVRepeatedText(belowText);
    if (dedupedBelow === text || belowText.includes(text) || text.includes(dedupedBelow)) {
      belowCell.value = '';
    }
  }
};

const clearFormXVWorkmanValueCells = (worksheet, layout, opts = {}) => {
  if (!worksheet || !layout) return;
  const { headerRow } = layout;
  const preferTamilNadu = !!opts.preferTamilNadu;
  const preferGujarat = !!opts.preferGujarat;
  if (
    !preferGujarat &&
    (detectFormXVStackedCertificateLayout(worksheet, headerRow, preferTamilNadu) || preferTamilNadu)
  ) {
    clearFormXVStackedHeaderValueCells(worksheet, headerRow, { preferTamilNadu });
    return;
  }
  const valueCol = resolveFormXVWorkmanValueColumn(worksheet, headerRow);
  const workman = findFormXVMasterLabelCell(
    worksheet,
    headerRow,
    /name\s+and\s+address\s+of\s+the\s+workm[ae]n/i,
    20
  );
  // GJ/AP: only clear the workman value band — never wipe site-box columns above it.
  const clearFromRow = preferGujarat && workman ? workman.row : 1;
  for (let r = clearFromRow; r < headerRow; r += 1) {
    const cell = worksheet.getCell(r, valueCol);
    if (formXVCellIsMergeSlave(cell)) continue;
    const text = String(formXVExcelCellValueToString(cell?.value) || '').trim();
    if (
      /name\s+and\s+address|nature\s+and\s+location|principal\s+employer|form\s*xv|service\s+certificate|vide\s+rule/i.test(
        text
      )
    ) {
      continue;
    }
    cell.value = '';
  }
};

const writeFormXVWorkmanFieldsToWorksheet = (
  worksheet,
  layout,
  row,
  hdrs,
  { preferTamilNadu = false, preferGujarat = false } = {}
) => {
  if (!worksheet || !row || typeof row !== 'object') return;
  const { headerRow } = layout;
  const allHdrs = Array.isArray(hdrs) && hdrs.length > 0 ? hdrs : [...FORM_XV_TABLE_HEADERS];
  const filledSpecs = new Set();
  const stackedLayout =
    !preferGujarat &&
    (detectFormXVStackedCertificateLayout(worksheet, headerRow, preferTamilNadu) || preferTamilNadu);
  const defaultValueCol = resolveFormXVWorkmanValueColumn(worksheet, headerRow);
  const stackedValueCol = stackedLayout
    ? resolveFormXVStackedValueColumn(worksheet, headerRow, { preferTamilNadu })
    : defaultValueCol;

  if (preferGujarat) {
    clearFormXVWorkmanValueCells(worksheet, layout, { preferGujarat: true });
  }

  for (const spec of FORM_XV_WORKMAN_HEADER_LABEL_SPECS) {
    if (filledSpecs.has(spec.key)) continue;
    const label = findFormXVMasterLabelCell(worksheet, headerRow, spec.match, 20);
    if (!label) continue;
    const headerKey = allHdrs.find((h) => spec.rowTest(h));
    let rawValue = headerKey ? getFormXVRowValueForHeader(row, headerKey) : '';
    if (!String(rawValue ?? '').trim()) {
      rawValue = resolveFormXVExportRowValue(row, headerKey || spec.label, allHdrs);
    }
    const value = dedupeFormXVRepeatedText(rawValue);
    if (!value) continue;

    if (stackedLayout) {
      writeFormXVStackedHeaderValue(worksheet, spec.match, value, headerRow, stackedValueCol, {
        preferTamilNadu
      });
    } else {
      // GJ: value column is F (beside B–E label merges); keep label text intact.
      const valueCol = preferGujarat
        ? Math.max(defaultValueCol, formXVMergeEndCol(worksheet, label.row, label.col) + 1, 6)
        : defaultValueCol;
      resetFormXVWorkmanLabelCell(worksheet, label.row, label.col, spec);
      if (preferGujarat) {
        const labelCell = worksheet.getCell(label.row, label.col);
        labelCell.alignment = {
          ...(labelCell.alignment || {}),
          horizontal: 'left',
          vertical: 'middle',
          wrapText: true
        };
      }
      clearFormXVStaleBelowRowValue(worksheet, label.row, valueCol, value);
      setFormXVWorkmanCellValue(worksheet, label.row, valueCol, value, { preferGujarat });
    }
    filledSpecs.add(spec.key);
  }
};

const clearFormXVDataRows = (worksheet, layout, rowCount = 1) => {
  const { dataStartRow, usedExportCols } = layout;
  const clearToRow = dataStartRow + Math.max(0, rowCount - 1);
  for (let r = dataStartRow; r <= clearToRow; r += 1) {
    for (let ci = 0; ci < usedExportCols.length; ci += 1) {
      worksheet.getCell(r, usedExportCols[ci]).value = '';
    }
  }
};

const resolveFormXVExportRowValue = (row, header, allHdrs = null) => {
  let value = getFormXVRowValueForHeader(row, header);
  if (String(value ?? '').trim() !== '') return value;
  const keys = Array.isArray(allHdrs) && allHdrs.length > 0 ? allHdrs : Object.keys(row || {});
  if (isFormXVNatureOfWorkHeader(header)) {
    const alt = keys.find((h) => isFormXVNatureOfWorkHeader(h));
    if (alt) value = getFormXVRowValueForHeader(row, alt);
  } else if (isFormXVWorkmanNameHeader(header)) {
    const alt = keys.find((h) => isFormXVWorkmanNameHeader(h));
    if (alt) value = getFormXVRowValueForHeader(row, alt);
  }
  return value;
};

const writeFormXVDataRowsToWorksheet = (worksheet, layout, sourceRows, { preferGujarat = false } = {}) => {
  const { dataStartRow, hdrs, columnByHeader, allHdrs } = layout;
  const rows = (Array.isArray(sourceRows) ? sourceRows : []).filter(
    (row) => row && typeof row === 'object' && Object.values(row).some((v) => String(v ?? '').trim() !== '')
  );
  clearFormXVDataRows(worksheet, layout, Math.max(rows.length, 1));
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    for (let j = 0; j < hdrs.length; j += 1) {
      const header = hdrs[j];
      const exportCol = columnByHeader[j];
      let value = resolveFormXVExportRowValue(row, header, allHdrs);
      if ((value == null || String(value).trim() === '') && j === 0) {
        value = i + 1;
      }
      if (value == null || value === '') continue;
      const cell = worksheet.getCell(dataStartRow + i, exportCol);
      cell.value = coerceFormXVCellExportValue(value, header);
      if (preferGujarat) {
        cell.alignment = {
          ...(cell.alignment || {}),
          horizontal: 'center',
          vertical: 'middle',
          wrapText: false
        };
      }
    }
  }
  return rows.length;
};

const autofitExcelJSColumns = (worksheet, colFrom, colTo, rowFrom, rowTo, minWidth = 12) => {
  if (!worksheet) return;
  const start = Math.max(1, colFrom);
  const end = Math.max(start, colTo);
  const r0 = Math.max(1, rowFrom);
  const r1 = Math.max(r0, rowTo);
  const minW = Math.max(8, Number(minWidth) || 12);
  for (let c = start; c <= end; c += 1) {
    let maxLen = minW;
    for (let r = r0; r <= r1; r += 1) {
      const cell = worksheet.getCell(r, c);
      const raw = cell?.value;
      let text = '';
      if (raw == null) text = '';
      else if (typeof raw === 'object' && raw.richText) {
        text = raw.richText.map((part) => part?.text || '').join('');
      } else if (typeof raw === 'object' && raw.text != null) {
        text = String(raw.text);
      } else {
        text = String(raw);
      }
      maxLen = Math.max(maxLen, text.length + 2);
    }
    const col = worksheet.getColumn(c);
    col.width = Math.min(Math.max(maxLen, minW), 72);
  }
};

/**
 * Form XXIII AP Register of Wages — center title/vide-rule + table headers.
 * Never call mergeCells here: merge/unmerge on export caused Excel [Repaired].
 */
const centerFormXXIIIAPRegisterOfWagesLayout = (
  worksheet,
  { tableColMax = 15, headerRowStart = 5, headerRowEnd = 6 } = {}
) => {
  if (!worksheet) return;
  const lastCol = Math.max(13, Number(tableColMax) || 15);

  const cellPlain = (cell) => {
    const raw = cell?.value;
    if (raw == null) return '';
    if (typeof raw === 'object' && Array.isArray(raw.richText)) {
      return raw.richText.map((p) => p?.text || '').join('');
    }
    if (typeof raw === 'object' && raw.text != null) return String(raw.text);
    return String(raw);
  };

  const isTitleText = (t) => {
    const s = String(t || '')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    return /form\s*xxiii/i.test(s) || /^register\s+of\s+wages\b/i.test(s);
  };
  const isVideRuleText = (t) =>
    /vide\s+rule|shops\s*&\s*establishment\s+rules/i.test(
      String(t || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
    );

  // Title + subtitle: center alignment only (template already merges across columns).
  for (let r = 1; r <= 2; r += 1) {
    for (let c = 1; c <= lastCol; c += 1) {
      const cell = worksheet.getCell(r, c);
      const t = cellPlain(cell).trim();
      if (!t) continue;
      if (!isTitleText(t) && !isVideRuleText(t)) continue;
      cell.alignment = {
        ...(cell.alignment || {}),
        horizontal: 'center',
        vertical: 'middle',
        wrapText: false,
        textRotation: 0
      };
      if (isTitleText(t)) {
        cell.font = { ...(cell.font || {}), bold: true, size: cell.font?.size || 14 };
      } else if (isVideRuleText(t)) {
        cell.font = { ...(cell.font || {}), italic: true, size: cell.font?.size || 11 };
      }
    }
  }

  // Table headers (incl. Amount / Reason under Deductions group): center + wrap.
  const hr0 = Math.max(3, Number(headerRowStart) || 5);
  const hr1 = Math.max(hr0, Number(headerRowEnd) || 6);
  for (let r = hr0; r <= hr1; r += 1) {
    for (let c = 1; c <= lastCol; c += 1) {
      const cell = worksheet.getCell(r, c);
      const t = cellPlain(cell).trim();
      if (!t) continue;
      cell.alignment = {
        ...(cell.alignment || {}),
        horizontal: 'center',
        vertical: 'middle',
        wrapText: true,
        textRotation: 0
      };
    }
  }

  // Name column: keep readable width so headers/names do not shred vertically.
  try {
    const nameCol = worksheet.getColumn(2);
    if (!nameCol.width || Number(nameCol.width) < 18) nameCol.width = 22;
  } catch (_) {
    /* ignore */
  }
};

/** @deprecated kept for callers; prefer centerFormXXIIIAPRegisterOfWagesLayout */
const restoreFormXXIIIAPRegisterOfWagesTitleAlignment = centerFormXXIIIAPRegisterOfWagesLayout;

/** Form XIX RJ / OT templates often ship with hidden title rows — force visible on download. */
const unhideExcelJSWorksheetRows = (worksheet, rowTo = null) => {
  if (!worksheet) return;
  const last = Math.max(
    1,
    Number(rowTo) || 0,
    Number(worksheet.actualRowCount) || 0,
    Number(worksheet.rowCount) || 0,
    40
  );
  for (let r = 1; r <= last; r += 1) {
    const row = worksheet.getRow(r);
    if (row.hidden) row.hidden = false;
    if (row.height != null && Number(row.height) > 0 && Number(row.height) < 12) {
      row.height = 18;
    }
  }
};

/** SheetJS path — clear hidden flags preserved from formmaster templates. */
const unhideSheetJsWorksheetRows = (ws, rowTo = null) => {
  if (!ws) return;
  const rowsMeta = ws['!rows'];
  if (!Array.isArray(rowsMeta) || rowsMeta.length === 0) return;
  let maxR = Number(rowTo);
  if (!Number.isFinite(maxR) || maxR < 0) {
    try {
      maxR = ws['!ref'] ? XLSX.utils.decode_range(ws['!ref']).e.r : rowsMeta.length - 1;
    } catch (_) {
      maxR = rowsMeta.length - 1;
    }
  }
  maxR = Math.max(maxR, rowsMeta.length - 1);
  for (let r = 0; r <= maxR; r += 1) {
    if (!rowsMeta[r]) continue;
    if (rowsMeta[r].hidden) rowsMeta[r].hidden = false;
    if (rowsMeta[r].h != null && Number(rowsMeta[r].h) > 0 && Number(rowsMeta[r].h) < 12) {
      rowsMeta[r].h = 18;
    }
    if (rowsMeta[r].hpt != null && Number(rowsMeta[r].hpt) > 0 && Number(rowsMeta[r].hpt) < 12) {
      rowsMeta[r].hpt = 18;
    }
  }
};

/**
 * Form XIX RJ sample body uses tall vertical merges (often 3–4 rows per sample employee).
 * Writing one employee per Excel row into those merges collapses emp 1–3 into one cell —
 * only the last write (serial 4+) remains visible. Unmerge before filling the body.
 */
const unmergeExcelJSVerticalMergesInRange = (worksheet, rowFrom, rowTo, colFrom, colTo) => {
  if (!worksheet) return;
  const merges = worksheet?.model?.merges;
  if (!Array.isArray(merges) || merges.length === 0) return;
  const r0 = Math.max(1, rowFrom);
  const r1 = Math.max(r0, rowTo);
  const c0 = Math.max(1, colFrom);
  const c1 = Math.max(c0, colTo);
  const toRemove = [];
  for (const range of merges) {
    const parts = String(range || '').split(':');
    if (parts.length !== 2) continue;
    const start = parts[0].match(/^([A-Z]+)(\d+)$/i);
    const end = parts[1].match(/^([A-Z]+)(\d+)$/i);
    if (!start || !end) continue;
    const mr1 = parseInt(start[2], 10);
    const mr2 = parseInt(end[2], 10);
    const mc1 = XLSX.utils.decode_col(start[1].toUpperCase()) + 1;
    const mc2 = XLSX.utils.decode_col(end[1].toUpperCase()) + 1;
    if (mr2 <= mr1) continue; // horizontal-only merge — keep
    if (mr2 < r0 || mr1 > r1) continue;
    if (mc2 < c0 || mc1 > c1) continue;
    toRemove.push(range);
  }
  toRemove.forEach((range) => {
    try {
      worksheet.unMergeCells(range);
    } catch (_) {
      /* ignore */
    }
  });
};

/**
 * Unmerge any merges (horizontal or vertical) intersecting a body rectangle.
 * Form 25 TN: form-index "9" merge across days 1–30 on the first body row swallows attendance.
 */
const unmergeExcelJSAllMergesInRange = (worksheet, rowFrom, rowTo, colFrom, colTo) => {
  if (!worksheet) return;
  const merges = worksheet?.model?.merges;
  if (!Array.isArray(merges) || merges.length === 0) return;
  const r0 = Math.max(1, rowFrom);
  const r1 = Math.max(r0, rowTo);
  const c0 = Math.max(1, colFrom);
  const c1 = Math.max(c0, colTo);
  const toRemove = [];
  for (const range of merges) {
    const parts = String(range || '').split(':');
    if (parts.length !== 2) continue;
    const start = parts[0].match(/^([A-Z]+)(\d+)$/i);
    const end = parts[1].match(/^([A-Z]+)(\d+)$/i);
    if (!start || !end) continue;
    const mr1 = parseInt(start[2], 10);
    const mr2 = parseInt(end[2], 10);
    const mc1 = XLSX.utils.decode_col(start[1].toUpperCase()) + 1;
    const mc2 = XLSX.utils.decode_col(end[1].toUpperCase()) + 1;
    if (mr2 < r0 || mr1 > r1) continue;
    if (mc2 < c0 || mc1 > c1) continue;
    toRemove.push(range);
  }
  toRemove.forEach((range) => {
    try {
      worksheet.unMergeCells(range);
    } catch (_) {
      /* ignore */
    }
  });
};

/** SheetJS: drop vertical body merges so each employee occupies its own row. */
const unmergeSheetJsVerticalMergesInRange = (ws, rowFrom0, rowTo0, colFrom0, colTo0) => {
  if (!ws || !Array.isArray(ws['!merges']) || ws['!merges'].length === 0) return;
  const r0 = Math.max(0, rowFrom0);
  const r1 = Math.max(r0, rowTo0);
  const c0 = Math.max(0, colFrom0);
  const c1 = Math.max(c0, colTo0);
  ws['!merges'] = ws['!merges'].filter((m) => {
    if (!m?.s || !m?.e) return true;
    if (m.e.r <= m.s.r) return true; // keep horizontal merges
    if (m.e.r < r0 || m.s.r > r1) return true;
    if (m.e.c < c0 || m.s.c > c1) return true;
    return false; // remove vertical merge intersecting data body
  });
};

/** Remove only merges that straddle header → data (keeps pure header merges and template layout). */
const unmergeSheetJsHeaderIntoDataVerticalMerges = (ws, dataStartRow0, colFrom0, colTo0) => {
  if (!ws || !Array.isArray(ws['!merges']) || ws['!merges'].length === 0) return;
  const ds = Math.max(0, dataStartRow0);
  const c0 = Math.max(0, colFrom0);
  const c1 = Math.max(c0, colTo0);
  ws['!merges'] = ws['!merges'].filter((m) => {
    if (!m?.s || !m?.e) return true;
    if (m.e.r <= m.s.r) return true; // horizontal
    if (m.e.r < ds || m.s.r >= ds) return true; // entirely above or entirely in/below data
    if (m.e.c < c0 || m.s.c > c1) return true;
    return false; // straddles header into data
  });
};

const STATUTORY_MANAGER_INCHARGE_HEADER_KEYS = ['form_header_manager_incharge'];

const normalizeHeaderLabelForMatch = (label) =>
  String(label || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

/** Excel labels like "Name of the Manager/Incharge:" */
const isManagerInchargeHeaderLabel = (label) => {
  const compact = normalizeHeaderLabelForMatch(label);
  if (!compact) return false;
  if (/name\s+of\s+the\s+manager/.test(compact) && /incharge/.test(compact)) return true;
  if (/name\s+of\s+the\s+manager/.test(compact)) return true;
  if (/manager\s*\/\s*incharge/.test(compact)) return true;
  if (/manager/.test(compact) && /\bin\s*charge\b/.test(compact)) return true;
  return false;
};

const resolveStableStatutoryHeaderFieldKey = (label) => {
  if (isManagerInchargeHeaderLabel(label)) return 'form_header_manager_incharge';
  if (isPrincipalEmployerHeaderLabel(label)) return 'statutory_employer_name_address';
  if (isEstablishmentNameHeaderLabel(label)) return 'statutory_establishment_name_address';
  if (isEstablishmentAddressHeaderLabel(label)) return 'statutory_establishment_address';
  if (isFactoryHeaderLabel(label)) return 'statutory_factory_name_address';
  return null;
};

const isStatutoryHeaderPlaceholderValue = (value) => {
  const s = String(value || '').trim().toLowerCase();
  if (!s) return true;
  if (/^enter\b/.test(s) || s.includes('enter ') || s.includes('select ')) return true;
  // Demo/sample company leftovers from multi-company list[0] fallback
  if (/^company\s*name(\s*\d+)?(\b|,|:|$)/.test(s.replace(/\s+/g, ' '))) return true;
  if (/^delphi(\b|,|:|$)/.test(s.replace(/\s+/g, ' '))) return true;
  return false;
};

/** Site Management contractor fields → "Name and Address of the Contractor" line. */
const buildSiteContractorNameAndAddress = (site) => {
  if (!site || typeof site !== 'object') return '';
  const name = String(site.contractorName ?? site.ContractorName ?? '').trim();
  const addr = String(site.contractorAddress ?? site.ContractorAddress ?? '').trim();
  const city = String(site.contractorCity ?? site.ContractorCity ?? '').trim();
  const state = String(site.contractorState ?? site.ContractorState ?? '').trim();
  const parts = [];
  if (name) parts.push(name);
  const addrLine = [addr, city, state].filter(Boolean).join(', ');
  if (addrLine) parts.push(addrLine);
  return parts.join(', ').trim();
};

const findSiteDetailByName = (siteDetailsList, siteName, stateHint = '') => {
  if (!Array.isArray(siteDetailsList) || siteDetailsList.length === 0) return null;
  const tokens = String(siteName || '')
    .trim()
    .split(/\s*,\s*/)
    .map((t) => t.trim().toLowerCase())
    .filter(Boolean);
  if (tokens.length === 0) return null;
  const siteNameNorm = (s) =>
    String(s?.siteName ?? s?.SiteName ?? s?.name ?? s?.Name ?? '')
      .trim()
      .toLowerCase();
  const siteStateNorm = (s) =>
    String(s?.siteState ?? s?.SiteState ?? s?.contractorState ?? s?.ContractorState ?? '')
      .trim()
      .toLowerCase();
  const stateNorm = String(stateHint || '')
    .trim()
    .toLowerCase();
  const matchesState = (site) => {
    if (!stateNorm) return true;
    const ss = siteStateNorm(site);
    if (!ss) return false;
    return ss === stateNorm || ss.includes(stateNorm) || stateNorm.includes(ss);
  };
  const pickSite = (candidates, token) => {
    if (!Array.isArray(candidates) || candidates.length === 0) return null;
    const exactState = candidates.find((s) => siteNameNorm(s) === token && matchesState(s));
    if (exactState) return exactState;
    const byState = candidates.find(matchesState);
    if (byState) return byState;
    const exact = candidates.find((s) => siteNameNorm(s) === token);
    if (exact) return exact;
    return candidates[0];
  };
  for (const token of tokens) {
    const exact = siteDetailsList.find((s) => siteNameNorm(s) === token);
    if (exact && matchesState(exact)) return exact;
    const fuzzyCandidates = siteDetailsList.filter((s) => {
      const sn = siteNameNorm(s);
      return sn && (sn === token || sn.includes(token) || token.includes(sn));
    });
    const picked = pickSite(fuzzyCandidates, token);
    if (picked) return picked;
  }
  return null;
};

const siteLocationFromRecord = (site) =>
  String(site?.location ?? site?.Location ?? '').trim();

const siteCityFromRecord = (site) =>
  String(site?.siteCity ?? site?.SiteCity ?? site?.city ?? site?.City ?? '').trim();

const siteStateFromRecordForLocation = (site) =>
  String(site?.siteState ?? site?.SiteState ?? site?.state ?? site?.State ?? '').trim();

const normalizeLocationCompareKey = (value) =>
  String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '');

