/** Split multi-value location strings ("Theni / Madurai", "A, B") into normalized tokens. */
const splitLocationCompareTokens = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return [];
  const parts = raw
    .split(/[,;/|]+/)
    .map((p) => normalizeLocationCompareKey(p))
    .filter(Boolean);
  const full = normalizeLocationCompareKey(raw);
  const out = [];
  const seen = new Set();
  [full, ...parts].forEach((t) => {
    if (!t || seen.has(t)) return;
    seen.add(t);
    out.push(t);
  });
  return out;
};

const unwrapZohoEmployeeRecord = (empItem) => {
  if (!empItem || typeof empItem !== 'object') return empItem;
  if (empItem.Employee && typeof empItem.Employee === 'object') return empItem.Employee;
  if (empItem.employee && typeof empItem.employee === 'object') return empItem.employee;
  return empItem;
};

const getEmployeeWorkLocation = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';
  const raw =
    emp.LocationName ??
    emp['LocationName'] ??
    emp['Location Name'] ??
    emp['LocationName.displayValue'] ??
    emp.Work_location ??
    emp['Work_location'] ??
    emp['Work Location'] ??
    emp.work_location ??
    emp.workLocation ??
    emp.Location ??
    emp.location ??
    '';
  if (raw && typeof raw === 'object') {
    return String(raw.display_value ?? raw.name ?? raw.Name ?? '').trim();
  }
  return String(raw || '').trim();
};

/**
 * Strict site↔employee location match.
 * Exact token match, or safe prefix when both sides are long enough
 * (e.g. "Theni" ↔ "Theni Allinagaram"). Never use short substring includes
 * — that let tokens like "i" / "n" falsely match "Theni".
 */
const locationTokensMatch = (empTok, siteTok) => {
  if (!empTok || !siteTok) return false;
  if (empTok === siteTok) return true;
  const short = empTok.length <= siteTok.length ? empTok : siteTok;
  const long = empTok.length <= siteTok.length ? siteTok : empTok;
  if (short.length < 4) return false;
  return long.startsWith(short);
};

const employeeMatchesSiteLocation = (empItem, targetLocation) => {
  const targetTokens = splitLocationCompareTokens(targetLocation);
  if (targetTokens.length === 0) return true;
  const empTokens = splitLocationCompareTokens(getEmployeeWorkLocation(empItem));
  if (empTokens.length === 0) return false;
  return empTokens.some((empTok) =>
    targetTokens.some((siteTok) => locationTokensMatch(empTok, siteTok))
  );
};

/** Block e.g. LocationName=Karnataka on a Tamil Nadu (Theni) site. */
const employeeLocationConflictsWithSiteState = (empItem, site) => {
  if (!site) return false;
  const siteStateKey = normalizeLocationCompareKey(siteStateFromRecordForLocation(site));
  if (!siteStateKey || !INDIAN_STATE_LOCATION_KEYS.has(siteStateKey)) return false;
  const empLocKeys = splitLocationCompareTokens(getEmployeeWorkLocation(empItem));
  return empLocKeys.some(
    (empKey) => INDIAN_STATE_LOCATION_KEYS.has(empKey) && empKey !== siteStateKey
  );
};

/** Site Management Location / City / site-name targets for one or more comma-joined site names. */
const resolveSiteLocationsForAutofill = (siteName, siteDetailsList) => {
  if (!siteName || !Array.isArray(siteDetailsList) || siteDetailsList.length === 0) return [];
  const tokens = String(siteName)
    .trim()
    .split(/\s*,\s*/)
    .map((t) => t.trim())
    .filter(Boolean);
  const locations = [];
  const seen = new Set();
  const pushLoc = (loc) => {
    const key = normalizeLocationCompareKey(loc);
    if (!key || seen.has(key)) return;
    seen.add(key);
    locations.push(String(loc).trim());
  };
  for (const token of tokens) {
    const site = findSiteDetailByName(siteDetailsList, token);
    if (site) {
      const primary = siteLocationFromRecord(site);
      if (primary) {
        pushLoc(primary);
      } else {
        // Location blank in Site Management — still scope by city / site name so
        // Karnataka people are not pulled into Theni (Tamil Nadu) forms.
        pushLoc(siteCityFromRecord(site));
        pushLoc(token);
      }
    } else {
      pushLoc(token);
    }
  }
  return locations;
};

const resolveSitesForEmployeeLocationFilter = (siteName, siteDetailsList) => {
  if (!siteName || !Array.isArray(siteDetailsList) || siteDetailsList.length === 0) return [];
  return String(siteName)
    .trim()
    .split(/\s*,\s*/)
    .map((t) => t.trim())
    .filter(Boolean)
    .map((token) => findSiteDetailByName(siteDetailsList, token))
    .filter(Boolean);
};

const filterEmployeesBySiteLocation = (employees, siteName, siteDetailsList) => {
  if (!Array.isArray(employees) || employees.length === 0) return employees;
  const locations = resolveSiteLocationsForAutofill(siteName, siteDetailsList);
  const sites = resolveSitesForEmployeeLocationFilter(siteName, siteDetailsList);
  if (locations.length === 0 && sites.length === 0) return employees;
  return employees.filter((emp) => {
    if (sites.some((site) => employeeLocationConflictsWithSiteState(emp, site))) {
      return false;
    }
    if (locations.length === 0) return true;
    return locations.some((loc) => employeeMatchesSiteLocation(emp, loc));
  });
};

const buildSiteInchargeName = (site) =>
  String(site?.inchargeName ?? site?.InchargeName ?? '').trim();

const buildSiteEstablishmentNameAndAddress = (site) => {
  if (!site || typeof site !== 'object') return '';
  const name = String(site.siteName ?? site.SiteName ?? '').trim();
  const addr = String(site.siteAddress ?? site.SiteAddress ?? '').trim();
  const city = String(site.siteCity ?? site.SiteCity ?? '').trim();
  const state = String(site.siteState ?? site.SiteState ?? '').trim();
  const parts = [];
  if (name) parts.push(name);
  const addrLine = [addr, city, state].filter(Boolean).join(', ');
  if (addrLine) parts.push(addrLine);
  return parts.join(', ').trim();
};

const buildSiteNatureAndLocation = (site) => siteLocationFromRecord(site);

const parseFlexibleEmployeeDate = (raw) => {
  const s = String(raw || '').trim();
  if (!s) return null;
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
};

const parseFlexibleStatutoryDate = (raw) => {
  const value = String(raw || '').trim();
  if (!value) return null;

  if (/^\d{4}-\d{2}-\d{2}/.test(value)) {
    const d = new Date(`${value.substring(0, 10)}T00:00:00`);
    if (!Number.isNaN(d.getTime())) return d;
  }

  const direct = new Date(value);
  if (!Number.isNaN(direct.getTime())) return direct;

  let m = value.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})$/);
  if (m) {
    const dd = Number(m[1]);
    const mm = Number(m[2]) - 1;
    const yyyy = Number(m[3].length === 2 ? `20${m[3]}` : m[3]);
    const d = new Date(yyyy, mm, dd);
    if (!Number.isNaN(d.getTime())) return d;
  }

  m = value.match(/^(\d{1,2})[-/\s]([A-Za-z]{3,})[-/\s](\d{2,4})$/);
  if (m) {
    const dd = Number(m[1]);
    const mon = String(m[2]).slice(0, 3).toLowerCase();
    const yyyy = Number(m[3].length === 2 ? `20${m[3]}` : m[3]);
    const months = {
      jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
      jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11
    };
    if (Object.prototype.hasOwnProperty.call(months, mon)) {
      const d = new Date(yyyy, months[mon], dd);
      if (!Number.isNaN(d.getTime())) return d;
    }
  }
  return null;
};

const calendarDateOnly = (date) => {
  if (!date || !(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
};

const getEmployeeDateofjoiningRaw = (emp) => {
  const e = unwrapZohoEmployeeRecord(emp) || emp || {};
  return (
    coerceZohoPeopleDateRaw(e.Dateofjoining) ||
    coerceZohoPeopleDateRaw(e['Dateofjoining']) ||
    coerceZohoPeopleDateRaw(e.DateofJoining) ||
    coerceZohoPeopleDateRaw(e['Date of Joining']) ||
    coerceZohoPeopleDateRaw(e['DateofJoining']) ||
    coerceZohoPeopleDateRaw(e.dateOfJoining) ||
    coerceZohoPeopleDateRaw(e['Date of joining']) ||
    coerceZohoPeopleDateRaw(e.Date_of_Joining) ||
    coerceZohoPeopleDateRaw(e['Date_of_Joining']) ||
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(e, 'dateofjoining')) ||
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(e, 'dateofjoin')) ||
    ''
  );
};

const resolveStatutoryEmployeeJoinDate = (emp, row = null, headers = null) => {
  const fromEmp = parseFlexibleStatutoryDate(getEmployeeDateofjoiningRaw(emp));
  if (fromEmp) return fromEmp;
  if (!row || !Array.isArray(headers)) return null;
  const joinHeader = headers.find((h) =>
    /date\s+of\s+entry\s+into\s+service/i.test(String(h || '').replace(/_/g, ' '))
  );
  if (!joinHeader) return null;
  return parseFlexibleStatutoryDate(row[joinHeader]);
};

const resolveStatutoryEmployeeExitDate = (emp, row = null, headers = null) => {
  const fromEmp = parseFlexibleStatutoryDate(getEmployeeDateofexitRaw(emp));
  if (fromEmp) return fromEmp;
  if (!row || !Array.isArray(headers)) return null;
  const exitHeader = headers.find((h) =>
    /date\s+of\s+(exit|leaving|relieving)/i.test(String(h || '').replace(/_/g, ' '))
  );
  if (!exitHeader) return null;
  return parseFlexibleStatutoryDate(row[exitHeader]);
};

const isStatutoryDayBeforeEmployeeJoining = (emp, dayDate, row = null, headers = null) => {
  const doj = resolveStatutoryEmployeeJoinDate(emp, row, headers);
  if (!doj) return false;
  const day = calendarDateOnly(dayDate);
  const join = calendarDateOnly(doj);
  if (!day || !join) return false;
  return day < join;
};

const isStatutoryDayAfterEmployeeExit = (emp, dayDate, row = null, headers = null) => {
  const doe = resolveStatutoryEmployeeExitDate(emp, row, headers);
  if (!doe) return false;
  const day = calendarDateOnly(dayDate);
  const exit = calendarDateOnly(doe);
  if (!day || !exit) return false;
  return day > exit;
};

const shouldSkipStatutoryDayAttendanceForEmployee = (emp, dayDate, row = null, headers = null) =>
  isStatutoryDayBeforeEmployeeJoining(emp, dayDate, row, headers) ||
  isStatutoryDayAfterEmployeeExit(emp, dayDate, row, headers);

const listStatutoryAttendanceDayHeaders = (headers) =>
  (headers || [])
    .map((header) => {
      const t = String(header || '').trim();
      const direct = t.match(/^(\d{1,2})$/);
      if (direct) {
        const day = Number(direct[1]);
        if (day >= 1 && day <= 31) return { header, day };
      }
      const suffixed = t.match(/(?:^|_)(\d{1,2})$/);
      if (suffixed) {
        const day = Number(suffixed[1]);
        if (day >= 1 && day <= 31) return { header, day };
      }
      return null;
    })
    .filter(Boolean);

const scrubStatutoryPreJoinDayMarks = (
  rows,
  employees,
  headers,
  { selectedMonth = '', rowIndexOffset = 0, item = null, wagePeriodLine = '' } = {}
) => {
  if (!Array.isArray(rows) || rows.length === 0) return 0;
  const dayHeaders = listStatutoryAttendanceDayHeaders(headers);
  if (dayHeaders.length === 0) return 0;
  const { year: targetYear, monthIndex: targetMonthIndex } = resolveStatutoryAttendanceMonthYear(
    selectedMonth,
    item,
    wagePeriodLine
  );
  let cleared = 0;
  rows.forEach((row, rowIndex) => {
    const empItem = employees?.[rowIndex + rowIndexOffset] ?? employees?.[rowIndex];
    const emp = empItem && (empItem.Employee || empItem.employee || empItem);
    dayHeaders.forEach(({ header, day }) => {
      const dayDate = new Date(targetYear, targetMonthIndex, day);
      if (dayDate.getMonth() !== targetMonthIndex) return;
      if (!shouldSkipStatutoryDayAttendanceForEmployee(emp, dayDate, row, headers)) return;
      if (String(row[header] ?? '').trim() !== '') cleared += 1;
      row[header] = '';
    });
  });
  return cleared;
};

const coerceZohoPeopleDateRaw = (value) => {
  if (value == null || value === '') return '';
  if (typeof value === 'object' && !Array.isArray(value)) {
    const nested =
      value.display_value ??
      value.displayValue ??
      value.date ??
      value.Date ??
      value.value ??
      '';
    return nested != null && String(nested).trim() !== '' ? String(nested).trim() : '';
  }
  return String(value).trim();
};

const getEmployeeDateofexitRaw = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';

  const direct = pickFirstNonEmptyString(
    coerceZohoPeopleDateRaw(emp.Dateofexit),
    coerceZohoPeopleDateRaw(emp['Dateofexit']),
    coerceZohoPeopleDateRaw(emp['Date of Exit']),
    coerceZohoPeopleDateRaw(emp.dateOfExit),
    coerceZohoPeopleDateRaw(emp['dateOfExit']),
    coerceZohoPeopleDateRaw(emp.Date_of_Exit),
    coerceZohoPeopleDateRaw(emp['Date_of_Exit']),
    coerceZohoPeopleDateRaw(emp.Date_of_exit),
    coerceZohoPeopleDateRaw(emp['Date_of_exit']),
    coerceZohoPeopleDateRaw(emp.DateofExit),
    coerceZohoPeopleDateRaw(emp['DateofExit']),
    coerceZohoPeopleDateRaw(emp.LastWorkingDate),
    coerceZohoPeopleDateRaw(emp['LastWorkingDate']),
    coerceZohoPeopleDateRaw(emp.Last_Working_Date),
    coerceZohoPeopleDateRaw(emp['Last Working Date']),
    coerceZohoPeopleDateRaw(emp.DOE),
    coerceZohoPeopleDateRaw(emp['DOE']),
    coerceZohoPeopleDateRaw(emp['Dateofexit.displayValue']),
    coerceZohoPeopleDateRaw(emp['Date_of_Exit.displayValue']),
    coerceZohoPeopleDateRaw(emp['LastWorkingDate.displayValue'])
  );
  if (direct) return direct;

  return pickFirstNonEmptyString(
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(emp, 'dateofexit')),
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(emp, 'dateofexitdisplayvalue')),
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(emp, 'lastworkingdate')),
    coerceZohoPeopleDateRaw(findNestedValueByNormalizedKey(emp, 'doe'))
  );
};

const addDaysToEmployeeJoiningDate = (emp, daysToAdd) => {
  const base = parseFlexibleStatutoryDate(getEmployeeDateofjoiningRaw(emp));
  if (!base) return '';
  const result = new Date(base.getFullYear(), base.getMonth(), base.getDate());
  result.setDate(result.getDate() + daysToAdd);
  const iso = `${result.getFullYear()}-${String(result.getMonth() + 1).padStart(2, '0')}-${String(result.getDate()).padStart(2, '0')}`;
  return formatStatutoryDateDisplay(iso);
};

const buildEmployeeWorkmanNameAndAddress = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';
  const employeeName = pickFirstNonEmptyString(
    emp.Name,
    emp['Name'],
    emp.Name1,
    emp['Name1'],
    emp.EmployeeName,
    emp['Employee Name'],
    emp['EmployeeName'],
    `${emp.FirstName || emp['FirstName'] || ''} ${emp.LastName || emp['LastName'] || ''}`.trim(),
    findNestedValueByNormalizedKey(emp, 'employeename'),
    findNestedValueByNormalizedKey(emp, 'name')
  );
  const address = buildForm11EmployeeAddress(emp);
  if (employeeName && address) return `${employeeName}\n${address}`;
  return [employeeName, address].filter(Boolean).join('\n');
};

const buildEmployeeAgeOrDobForFormXV = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';
  const dobRaw =
    emp.Date_of_birth ||
    emp['Date_of_birth'] ||
    emp.DateofBirth ||
    emp['Date of Birth'] ||
    emp['DateofBirth'] ||
    '';
  if (String(dobRaw || '').trim()) return String(dobRaw).trim();
  const dob = parseFlexibleEmployeeDate(dobRaw);
  if (dob) {
    const today = new Date();
    let age = today.getFullYear() - dob.getFullYear();
    const md = today.getMonth() - dob.getMonth();
    if (md < 0 || (md === 0 && today.getDate() < dob.getDate())) age -= 1;
    if (age >= 0 && age < 120) return String(age);
  }
  const direct = emp.Age || emp['Age'] || emp.age || emp['Employee Age'] || '';
  return direct != null && String(direct).trim() !== '' ? String(direct).trim() : '';
};

const buildEmployeeIdentificationMarks = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';
  return String(
    emp.Identification_Marks ||
      emp['Identification Marks'] ||
      emp.IdentificationMarks ||
      emp.identification_marks ||
      emp['Identification_marks'] ||
      ''
  ).trim();
};

const buildEmployeeFatherOrHusbandName = (empItem) => {
  const emp = unwrapZohoEmployeeRecord(empItem);
  if (!emp || typeof emp !== 'object') return '';
  const fatherName =
    emp.Father_s_Name ||
    emp['Father_s_Name'] ||
    emp.Father_Name ||
    emp['Father_Name'] ||
    emp.FathersName ||
    emp['Father/Spouse Name'] ||
    emp['Father Name'] ||
    '';
  if (String(fatherName || '').trim()) return String(fatherName).trim();
  const spouseName =
    emp.Spouse_Name || emp['Spouse_Name'] || emp.spouseName || emp['Spouse Name'] || '';
  return String(spouseName || '').trim();
};

const applyFormXVHeaderAutofillFromEmployee = (headerData, empItem) => {
  if (!headerData || typeof headerData !== 'object' || !empItem) return headerData;
  return headerData;
};

/** Fill contractor + manager/incharge + establishment from Site; employer from company_function only. */
const applySiteManagementToHeaderFormData = (
  headerData,
  siteName,
  siteDetailsList,
  formHeaderFields = [],
  companyRecord = null,
  stateHint = '',
  options = {}
) => {
  if (!headerData || typeof headerData !== 'object') return headerData;
  const site = findSiteDetailByName(siteDetailsList, siteName, stateHint);
  // Employer comes from company_function even when site lookup fails.
  if (!site && !companyRecord) return headerData;

  const establishmentFromCompany = Boolean(options?.establishmentFromCompany);
  /** Form VI TN: "Name and Address of the Factory" ← company name + address. */
  const factoryFromCompany = Boolean(options?.factoryFromCompany);
  const out = { ...headerData };
  let changed = false;

  const contractorText = site ? buildSiteContractorNameAndAddress(site) : '';
  if (contractorText) {
    for (const key of STATUTORY_CONTRACTOR_HEADER_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(out, key)) continue;
      const cur = String(out[key] ?? '').trim();
      if (!cur || isStatutoryHeaderPlaceholderValue(cur)) {
        out[key] = contractorText;
        changed = true;
      }
    }
  }

  const factoryNameOnly = site ? String(site.siteName ?? site.SiteName ?? '').trim() : '';
  const siteFactoryText = site ? buildSiteEstablishmentNameAndAddress(site) : '';
  const companyFactoryText =
    buildCompanyNameAndAddress(companyRecord) ||
    buildCompanyNameWithSiteAddress(companyRecord, site) ||
    '';
  const factoryText = factoryFromCompany
    ? companyFactoryText || siteFactoryText
    : siteFactoryText;
  if (factoryText) {
    const resolveFactoryValue = (key) => {
      if (factoryFromCompany) return factoryText;
      if (key === 'form14_header_factory') return factoryNameOnly || factoryText;
      if (key === 'form25_ap_header_factory') return factoryText || factoryNameOnly;
      return factoryText;
    };
    const shouldWriteFactory = (cur) =>
      factoryFromCompany || !cur || isStatutoryHeaderPlaceholderValue(cur);
    for (const key of STATUTORY_FACTORY_HEADER_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(out, key)) continue;
      const cur = String(out[key] ?? '').trim();
      if (!shouldWriteFactory(cur)) continue;
      const nextVal = resolveFactoryValue(key);
      if (!nextVal || cur === nextVal) continue;
      out[key] = nextVal;
      changed = true;
    }
    const fields = Array.isArray(formHeaderFields) ? formHeaderFields : [];
    for (const field of fields) {
      if (!isFactoryHeaderLabel(field?.label)) continue;
      const key = field?.key;
      if (!key) continue;
      const cur = String(out[key] ?? '').trim();
      if (!shouldWriteFactory(cur)) continue;
      const nextVal = resolveFactoryValue(key);
      if (!nextVal || cur === nextVal) continue;
      out[key] = nextVal;
      changed = true;
    }
  }

  if (site) {
    const form14Place = buildSitePlaceFromSite(site);
    const form14District = buildSiteDistrictFromSite(site);
    const form14HeaderFills = [
      ['form14_header_factory', factoryNameOnly || factoryText],
      ['form14_header_place', form14Place],
      ['form14_header_district', form14District],
      ['form25_ap_header_factory', factoryText || factoryNameOnly],
      ['form25_ap_header_place', form14Place],
      ['form25_ap_header_district', form14District]
    ];
    for (const [key, text] of form14HeaderFills) {
      if (!text || !Object.prototype.hasOwnProperty.call(out, key)) continue;
      const cur = String(out[key] ?? '').trim();
      if (!cur || isStatutoryHeaderPlaceholderValue(cur)) {
        out[key] = text;
        changed = true;
      }
    }

    const establishmentText = establishmentFromCompany
      ? buildCompanyNameWithSiteAddress(companyRecord, site) || buildCompanyNameAndAddress(companyRecord)
      : buildSiteEstablishmentNameAndAddress(site);
    const establishmentAddress = establishmentFromCompany
      ? buildSiteEstablishmentAddressOnly(site) ||
        (() => {
          if (!companyRecord || typeof companyRecord !== 'object') return '';
          const addr = String(companyRecord.companyAddress ?? companyRecord.CompanyAddress ?? '').trim();
          const city = String(companyRecord.city ?? companyRecord.City ?? '').trim();
          const state = String(companyRecord.state ?? companyRecord.State ?? '').trim();
          const postal = String(companyRecord.postalcode ?? companyRecord.PostalCode ?? '').trim();
          return [addr, city, state, postal].filter(Boolean).join(', ') || establishmentText;
        })()
      : buildFormAEstablishmentAddressFromSite(site);
    if (establishmentText) {
      const fillEstablishmentKey = (key) => {
        const cur = String(out[key] ?? '').trim();
        if (establishmentFromCompany || !cur || isStatutoryHeaderPlaceholderValue(cur)) {
          out[key] = establishmentText;
          changed = true;
        }
      };
      fillEstablishmentKey('form_a_establishment_name');
      fillEstablishmentKey('form_q_establishment');
    }
    if (establishmentAddress) {
      const fillAddressKey = (key) => {
        const cur = String(out[key] ?? '').trim();
        if (establishmentFromCompany || !cur || isStatutoryHeaderPlaceholderValue(cur)) {
          out[key] = establishmentAddress;
          changed = true;
        }
      };
      fillAddressKey('form_a_establishment_address');
    }
    const natureLocationText = buildSiteNatureAndLocation(site);
    // Principal employer: company_function only (never site name/address).
    const principalEmployerText = buildCompanyNameAndAddress(companyRecord);
    const formXVSiteHeaderFillers = [
      ['form_xv_contractor', contractorText],
      ['form_xv_nature_location_work', natureLocationText],
      ['form_xv_establishment_contract_carried', establishmentText],
      ['form_xv_principal_employer', principalEmployerText]
    ];
    formXVSiteHeaderFillers.forEach(([key, value]) => {
      if (!value) return;
      const cur = Object.prototype.hasOwnProperty.call(out, key) ? String(out[key] ?? '').trim() : '';
      // Always overwrite principal employer with company_function when available.
      if (
        key === 'form_xv_principal_employer' ||
        !cur ||
        isStatutoryHeaderPlaceholderValue(cur)
      ) {
        if (cur === value) return;
        out[key] = value;
        changed = true;
      }
    });

    const inchargeName = buildSiteInchargeName(site);
    if (inchargeName) {
      const applyInchargeToKey = (key) => {
        if (!key) return;
        const cur = Object.prototype.hasOwnProperty.call(out, key) ? String(out[key] ?? '').trim() : '';
        // Always overwrite with Site Management Incharge Name (not template leftovers).
        if (!Object.prototype.hasOwnProperty.call(out, key) || cur !== inchargeName) {
          out[key] = inchargeName;
          changed = true;
        }
      };
      for (const key of STATUTORY_MANAGER_INCHARGE_HEADER_KEYS) {
        applyInchargeToKey(key);
      }
      const fields = Array.isArray(formHeaderFields) ? formHeaderFields : [];
      for (const field of fields) {
        if (!isManagerInchargeHeaderLabel(field?.label)) continue;
        applyInchargeToKey(field.key);
      }
    }
  }

  const base = applySiteCompanyHeaderAutofill(changed ? out : headerData, {
    site,
    company: companyRecord,
    formHeaderFields,
    isPlaceholder: isStatutoryHeaderPlaceholderValue,
    establishmentFromCompany,
  });
  return applyFormXXIIIMPHeaderFieldsFromSite(base, site, {
    formHeaderFields,
    isPlaceholder: isStatutoryHeaderPlaceholderValue
  });
};

const applyStatutorySiteCompanyHeaders = (
  headerData,
  siteName,
  siteDetailsList,
  formHeaderFields,
  item,
  companyDetailsList,
  context = null
) => {
  const companies =
    Array.isArray(companyDetailsList) && companyDetailsList.length > 0
      ? companyDetailsList
      : readCompanyDetailsCache() || [];
  const stateHint = String(item?.state ?? item?.State ?? '').trim();
  const site = findSiteDetailByName(siteDetailsList, siteName, stateHint);
  const company = resolveCompanyRecordForStatutory(item, companies, site);
  // Form B / Form U TN: establishment = company legal name + site address (never siteName).
  const fileNameHint =
    context?.fileName ||
    [
      item?.fileName,
      item?.FileName,
      item?.displayFileName,
      item?.formFileName,
      item?.FormFileName,
      item?.templateFileName,
    ]
      .filter(Boolean)
      .join(' ');
  const formHeaderProbe = context?.formHeader || {
    title: item?.title,
    subtitle: item?.subtitle,
    reference: item?.reference,
    fields: formHeaderFields,
  };
  const tableHeadersProbe =
    context?.tableHeaders ||
    (Array.isArray(formHeaderFields)
      ? formHeaderFields.map((f) => f?.label || '').filter(Boolean)
      : []);
  const formIFinesEstablishmentFromCompany = isFormIRegisterOfFinesContext(
    item,
    fileNameHint,
    formHeaderProbe,
    tableHeadersProbe,
    context?.sheetText || ''
  );
  const establishmentFromCompany =
    isFormBTamilNaduEstablishmentFromCompanyContext({
      formHeader: formHeaderProbe,
      rowItem: item,
      fileName: fileNameHint,
      tableHeaders: tableHeadersProbe,
    }) ||
    isFormUTamilNaduEmployeeRegisterContext({
      item,
      fileName: fileNameHint,
      formFileName: fileNameHint,
      formHeaderTitle: formHeaderProbe?.title,
      formHeaderSubtitle: formHeaderProbe?.subtitle,
      tableHeaders: tableHeadersProbe,
    }) ||
    // Form V TN Register of Employment — same as Form U: company legal name + site address.
    isFormVTamilNaduRegisterOfEmploymentContext(
      formHeaderProbe,
      item,
      fileNameHint,
      tableHeadersProbe,
      context?.sheetText || ''
    ) ||
    // Form I TN Register of Employees Placed under suspension — company name + address, never siteName.
    isFormITamilNaduSuspensionWorkbookContext({
      fileName: fileNameHint,
      formFileName: fileNameHint,
      formHeader: formHeaderProbe,
      headers: tableHeadersProbe,
      sheetText: context?.sheetText || '',
    }) ||
    formIFinesEstablishmentFromCompany;
  const factoryFromCompany =
    isFormVIFestivalContext(formHeaderProbe, item, fileNameHint, tableHeadersProbe) ||
    isFormVITamilNaduHolidayContext(
      formHeaderProbe,
      item,
      fileNameHint,
      '',
      tableHeadersProbe
    ) ||
    isForm25TamilNaduCompensatoryHolidaysContext(
      formHeaderProbe,
      item,
      fileNameHint,
      tableHeadersProbe,
      context?.sheetText || ''
    ) ||
    // Form 10 Overtime Muster (Rule 78): factory = company name + address.
    isForm10OvertimeMusterContext(formHeaderProbe, item, fileNameHint, tableHeadersProbe);
  let next = applySiteManagementToHeaderFormData(
    headerData,
    siteName,
    siteDetailsList,
    formHeaderFields,
    company,
    stateHint,
    { establishmentFromCompany, factoryFromCompany }
  );
  if (establishmentFromCompany) {
    const companyText = formIFinesEstablishmentFromCompany
      ? buildCompanyNameAndAddress(company) ||
        buildStatutoryEmployerTextFromCompanies(companies, item, null)
      : buildCompanyNameWithSiteAddress(company, site) ||
        buildCompanyNameAndAddress(company) ||
        buildStatutoryEmployerTextFromCompanies(companies, item, site);
    next = applyFormBTamilNaduEstablishmentFromCompany(next, companyText);
  }
  return next;
};

/** @deprecated Use applySiteManagementToHeaderFormData */
const applySiteContractorToHeaderFormData = (headerData, siteName, siteDetailsList, formHeaderFields) =>
  applySiteManagementToHeaderFormData(headerData, siteName, siteDetailsList, formHeaderFields);

/** Ensure parsed form header field keys exist before site autofill (download without opening modal). */
const seedHeaderFormDataFromParsedFields = (headerData, formHeaderFields) => {
  const fields = Array.isArray(formHeaderFields) ? formHeaderFields : [];
  if (fields.length === 0) return headerData;
  const out = headerData && typeof headerData === 'object' ? { ...headerData } : {};
  let changed = !headerData || typeof headerData !== 'object';
  for (const field of fields) {
    if (!field?.key) continue;
    let fromField = String(field.value ?? '').trim();
    // Never seed sample template employer text (Delphi / Company Name 2) into Form U headers.
    if (
      isPrincipalEmployerHeaderLabel(field.label) &&
      looksLikeDemoCompanyHeaderValue(fromField)
    ) {
      fromField = '';
    }
    const cur = Object.prototype.hasOwnProperty.call(out, field.key)
      ? String(out[field.key] ?? '').trim()
      : '';
    if (!Object.prototype.hasOwnProperty.call(out, field.key)) {
      out[field.key] = fromField;
      changed = true;
    } else if (!cur && fromField) {
      out[field.key] = fromField;
      changed = true;
    } else if (
      isPrincipalEmployerHeaderLabel(field.label) &&
      looksLikeDemoCompanyHeaderValue(cur)
    ) {
      out[field.key] = '';
      changed = true;
    }
  }
  return changed ? out : headerData;
};

/** Write Form 10 / Form 12 merged factory+contractor header block into ExcelJS worksheet (0-based r,c from parser). */
const writeForm10Form12HeaderFieldsToExcelJsWorksheet = (worksheet, headerFormData, parsedFormHeader) => {
  if (!worksheet || !headerFormData || typeof headerFormData !== 'object') return;
  const effectiveFormHeader = parsedFormHeader || {};
  const toCell = (r, c) => worksheet.getCell(Number(r) + 1, Number(c) + 1);

  if (effectiveFormHeader.form12MergedHeaderCell) {
    const { r, c } = effectiveFormHeader.form12MergedHeaderCell;
    const vF = String(headerFormData.form12_header_factory ?? '').trim();
    const vC = String(headerFormData.form12_header_contractor ?? '').trim();
    const vR = String(headerFormData.form12_header_registration ?? '').trim();
    const combined = `Name and Address of the Factory: ${vF}\nName and Address of the Contractor: ${vC}\nRegistration No: ${vR}`;
    toCell(r, c).value = combined;
  }
  if (effectiveFormHeader.form10MergedHeaderCell) {
    const { r, c } = effectiveFormHeader.form10MergedHeaderCell;
    const vF = String(headerFormData.form10_header_factory ?? '').trim();
    const vC = String(headerFormData.form10_header_contractor ?? '').trim();
    const combined = `Name and Address of the Factory: ${vF}\nName and Address of the Contractor: ${vC}`;
    toCell(r, c).value = combined;
  } else if (
    effectiveFormHeader.form10MonthEndingCell ||
    Object.prototype.hasOwnProperty.call(headerFormData, 'form10_header_factory') ||
    Object.prototype.hasOwnProperty.call(headerFormData, 'form10_header_month_ending')
  ) {
    // Factory-only Form 10 templates: write into the "Name and Address of the Factory:" label cell.
    const vF = String(
      headerFormData.form10_header_factory ??
        headerFormData.statutory_factory_name_address ??
        ''
    ).trim();
    if (vF) {
      const maxRows = Math.min(8, Number(worksheet.rowCount) || 8);
      const maxCols = Math.min(20, Number(worksheet.columnCount) || 20);
      for (let r = 1; r <= maxRows; r += 1) {
        let wroteFactory = false;
        for (let c = 1; c <= maxCols; c += 1) {
          const cell = worksheet.getCell(r, c);
          const raw = String(cell?.value ?? '')
            .replace(/\s+/g, ' ')
            .trim();
          if (!raw || !/name\s+and\s+address\s+of\s+the\s+factory/i.test(raw)) continue;
          if (/name\s+and\s+address\s+of\s+the\s+contractor/i.test(raw)) continue;
          cell.value = `Name and Address of the Factory: ${vF}`;
          wroteFactory = true;
          break;
        }
        if (wroteFactory) break;
      }
    }
  }
  const form10MonthEndingLabelOnly = 'Month ending :';
  const form10MonthValueColAfterLabel = (row1Based, labelCol1Based) => {
    // Prefer the first column to the right of any merge that covers the label cell.
    try {
      const merges = worksheet._merges || {};
      for (const key of Object.keys(merges)) {
        const m = merges[key];
        const top = Number(m?.top ?? m?.model?.top);
        const bottom = Number(m?.bottom ?? m?.model?.bottom);
        const left = Number(m?.left ?? m?.model?.left);
        const right = Number(m?.right ?? m?.model?.right);
        if (
          row1Based >= top &&
          row1Based <= bottom &&
          labelCol1Based >= left &&
          labelCol1Based <= right
        ) {
          return right + 1;
        }
      }
    } catch (_) {
      /* ignore merge introspection failures */
    }
    return labelCol1Based + 1;
  };

  if (effectiveFormHeader.form10MonthEndingCell) {
    const me = effectiveFormHeader.form10MonthEndingCell;
    const vM = String(headerFormData.form10_header_month_ending ?? '').trim();
    const cell = toCell(me.r, me.c);
    if (me.writeMode === 'full') {
      // Keep the Month ending box as label-only; value goes beside the box (not inside).
      cell.value = form10MonthEndingLabelOnly;
      const valueCol = form10MonthValueColAfterLabel(Number(me.r) + 1, Number(me.c) + 1);
      worksheet.getCell(Number(me.r) + 1, valueCol).value = vM || '';
    } else {
      cell.value = vM || '';
    }
  }
  // Rewrite leftover template "Month ending: …" / bare Month-YYYY cells in the header band.
  // The Month ending box stays label-only; value (or blank) goes beside it (not inside).
  if (Object.prototype.hasOwnProperty.call(headerFormData, 'form10_header_month_ending')) {
    const monthEndingVal = String(headerFormData.form10_header_month_ending ?? '').trim();
    const monthNames =
      'January|February|March|April|May|June|July|August|September|October|November|December';
    const bareMonthYearRe = new RegExp(`^(${monthNames})-\\d{4}$`, 'i');
    const fullMonthEndingRe = /^Month ending\s*:/i;
    const maxRows = Math.min(8, Number(worksheet.rowCount) || 8);
    const maxCols = Math.min(20, Number(worksheet.columnCount) || 20);
    for (let r = 1; r <= maxRows; r += 1) {
      for (let c = 1; c <= maxCols; c += 1) {
        const cell = worksheet.getCell(r, c);
        const raw = String(cell?.value ?? '')
          .replace(/\s+/g, ' ')
          .trim();
        if (!raw) continue;
        if (fullMonthEndingRe.test(raw)) {
          cell.value = form10MonthEndingLabelOnly;
          const valueCol = form10MonthValueColAfterLabel(r, c);
          const adj = worksheet.getCell(r, valueCol);
          const adjRaw = String(adj?.value ?? '')
            .replace(/\s+/g, ' ')
            .trim();
          if (!adjRaw || bareMonthYearRe.test(adjRaw) || !monthEndingVal) {
            adj.value = monthEndingVal || '';
          }
        } else if (bareMonthYearRe.test(raw)) {
          cell.value = monthEndingVal || '';
        }
      }
    }
  }
};

const excelJsCellText = (val) => {
  if (val == null) return '';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
    return String(val);
  }
  if (val instanceof Date) return val.toISOString();
  if (typeof val === 'object') {
    if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
    if (val.text != null) return String(val.text);
    if (val.result != null) return String(val.result);
  }
  return '';
};

/** Form 14 AP — factory / place / district in column A as "Label : value" (merged-cell safe). */
function writeForm14APHeaderFieldsToExcelJsWorksheet(worksheet, headerFormData) {
  if (!worksheet || !headerFormData || typeof headerFormData !== 'object') return;
  const form14Rows = [
    { row: 2, key: 'form14_header_factory', label: 'Name of the factory' },
    { row: 3, key: 'form14_header_place', label: 'Place' },
    { row: 4, key: 'form14_header_district', label: 'District' }
  ];
  const writeRow = (r, label, key) => {
    const value = String(headerFormData[key] ?? '').trim();
    if (!value) return;
    const rawLabel = excelJsCellText(worksheet.getCell(r, 1)?.value).trim();
    const labelNorm = String(label).replace(/:+$/, '').trim();
    if (rawLabel && new RegExp(`^${labelNorm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i').test(rawLabel.replace(/:+$/, '').trim())) {
      worksheet.getCell(r, 1).value = formatStatutoryHeaderLabelValueExport(label, rawLabel, value);
      return;
    }
    if (!rawLabel || rawLabel === value || !rawLabel.includes(':')) {
      worksheet.getCell(r, 1).value = formatStatutoryHeaderLabelValueExport(label, label, value);
    }
  };
  for (let r = 1; r <= 15; r += 1) {
    const rawLabel = excelJsCellText(worksheet.getCell(r, 1)?.value).trim();
    if (!rawLabel) continue;
    const label = rawLabel.replace(/:+$/, '').trim();
    let key = null;
    let canonicalLabel = label;
    if (/^name\s+of\s+the\s+factory$/i.test(label)) {
      key = 'form14_header_factory';
      canonicalLabel = 'Name of the factory';
    } else if (/^place$/i.test(label)) {
      key = 'form14_header_place';
      canonicalLabel = 'Place';
    } else if (/^district$/i.test(label)) {
      key = 'form14_header_district';
      canonicalLabel = 'District';
    }
    if (!key) continue;
    const value = String(headerFormData[key] ?? '').trim();
    if (!value) continue;
    worksheet.getCell(r, 1).value = formatStatutoryHeaderLabelValueExport(canonicalLabel, rawLabel, value);
  }
  form14Rows.forEach(({ row, key, label }) => writeRow(row, label, key));
}

