/** Site name for Site Management header autofill — explicit row site / URL param first. */
const resolveStatutorySiteNameForContractorAutofill = (item, ctx = {}) => {
  const explicit = String(
    item?.site ?? item?.Site ?? item?.siteName ?? item?.SiteName ?? ''
  ).trim();
  if (explicit) return explicit;
  const fromUrl = String(ctx.siteFromUrl || '').trim();
  if (fromUrl) return fromUrl;
  if (Array.isArray(ctx.allowedSiteNameList) && ctx.allowedSiteNameList.length === 1) {
    return String(ctx.allowedSiteNameList[0] || '').trim();
  }
  if (typeof ctx.resolveSiteFn === 'function') {
    try {
      return String(ctx.resolveSiteFn(item, ctx.allRows) || '').trim();
    } catch (err) {
      console.warn('resolveSiteDisplayName failed during contractor autofill:', err);
    }
  }
  return '';
};

const friendlyZohoPeopleAutofillError = (rawMessage, httpStatus) => {
  const msg = String(rawMessage || '').trim();
  if (/request failed with status code 400/i.test(msg)) {
    return 'Zoho People returned a bad request (400). Check that the employee form API is enabled and OAuth scopes include employee access.';
  }
  if (/request failed with status code 401/i.test(msg)) {
    return 'Zoho People authorization failed (401). Refresh the People API token in server settings.';
  }
  if (httpStatus && Number(httpStatus) >= 400) {
    return `Employee data API failed (HTTP ${httpStatus})${msg ? `: ${msg}` : ''}`;
  }
  return msg || 'Failed to fetch employee data from Zoho People';
};

/** Form I: merged heading block — Form I / REGISTER OF FINES or REGISTER OF WORKMEN / legal lines. */
const splitFormIHeaderBlock = (text) => {
  const t = String(text || '')
    .replace(/\r\n/g, '\n')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .trim();
  if (!t) return null;
  if (!/\bform\s*[-–]?\s*i\b/i.test(t)) return null;
  const hasWorkmen = /register\s+of\s+workmen/i.test(t);
  const hasFines = /register\s+of\s+fines/i.test(t);
  if (!hasWorkmen && !hasFines) return null;

  const lines = t
    .split('\n')
    .map((l) => l.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  if (lines.length === 0) return null;

  const titleLine = lines.find((l) => /\bform\s*[-–]?\s*i\b/i.test(l)) || 'FORM I';
  const subtitleLine =
    lines.find((l) => /register\s+of\s+fines/i.test(l)) ||
    lines.find((l) => /register\s+of\s+workmen/i.test(l)) ||
    (hasFines ? 'REGISTER OF FINES' : 'REGISTER OF WORKMEN');
  const bracketRule = lines.find((l) => /^\[.*\]$/.test(l) || /see\s+sub-?rule|see\s+rule/i.test(l)) || '';
  const actLine =
    lines.find((l) => /tamil\s+nadu\s+industrial\s+establishments/i.test(l)) ||
    lines.find((l) => /minimum\s+wages\s+act/i.test(l)) ||
    '';
  const reference = [bracketRule, actLine].filter(Boolean).join('\n').trim();

  return {
    title: titleLine,
    subtitle: subtitleLine,
    reference
  };
};

const escapeRegExp = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Remove echoed form title from merged-cell subtitle text (Form 10 / Form 12 templates repeat "FORM No. N" in the same block as REGISTER / prescribed lines). */
const stripSubtitleTitleEcho = (formTitleText, chunk) => {
  const title = String(formTitleText || '').trim();
  if (!title || chunk == null) return String(chunk || '').trim();
  const tn = title.replace(/\s+/g, ' ').trim().toLowerCase();
  const titleRe = new RegExp(`^\\s*${escapeRegExp(title)}\\s*`, 'i');
  return String(chunk)
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => {
      let l = line.trim();
      if (!l) return '';
      if (l.replace(/\s+/g, ' ').trim().toLowerCase() === tn) return '';
      l = l.replace(titleRe, '').trim();
      return l;
    })
    .filter(Boolean)
    .join('\n')
    .trim();
};

/** Form 25 — contractor / establishment / principal employer (wide layouts; value may be in cells to the right). */
/** Form 14 AP — factory / place / district labels in column A (no colon). */
const FORM_14_AP_HEADER_SPECS = [
  {
    key: 'form14_header_factory',
    label: 'Name of the factory:',
    test: (raw) => /^name\s+of\s+the\s+factory\s*:?\s*$/i.test(raw)
  },
  {
    key: 'form14_header_place',
    label: 'Place:',
    test: (raw) => /^place\s*:?\s*$/i.test(raw)
  },
  {
    key: 'form14_header_district',
    label: 'District:',
    test: (raw) => /^district\s*:?\s*$/i.test(raw)
  }
];

function isForm14ChildWorkersContext(formHeader, rowItem, fileName, sheetText = '') {
  const parts = [
    rowItem?.formName,
    rowItem?.FormName,
    rowItem?.formFileName,
    rowItem?.FormFileName,
    fileName,
    formHeader?.title,
    formHeader?.subtitle,
    formHeader?.reference,
    sheetText
  ]
    .join(' ')
    .toLowerCase();
  // Rajasthan Shops Form 14 (hours of work) — not AP Factories Form 14 child workers.
  if (
    /form[\s._-]*14[\s._-]*rj|\bform_14_rj\b|\b14_rj\b/.test(parts) ||
    (/rajasthan/.test(parts) && /record\s+of\s+(?:the\s+)?hours\s+of\s+work/.test(parts))
  ) {
    return false;
  }
  const sheetSays11 =
    statutorySheetContentIndicatesFormNumber(formHeader, sheetText, 11) &&
    (/period\s+of\s+work|rule\s*79/.test(parts) ||
      /notice\s+of\s+period\s+of\s+work/.test(parts));
  if (sheetSays11) return false;
  if (statutorySheetContentIndicatesFormNumber(formHeader, sheetText, 14)) return true;
  if (/register\s+of\s+child\s+worker|child\s+worker/.test(parts)) return true;
  if (/rule\s*86/.test(parts) && !/rule\s*79/.test(parts)) return true;
  if (
    statutoryFilenameRequestsFormNumber(
      rowItem?.formFileName,
      rowItem?.FormFileName,
      fileName,
      rowItem?.formName,
      rowItem?.FormName,
      14
    )
  ) {
    return !sheetSays11;
  }
  return /form_14[_\s-]*andhra/i.test(parts) && !sheetSays11;
}

const FORM25_SHEET_HEADER_SPECS = [
  {
    key: 'form25_contractor',
    label: 'Name and Address of the Contractor:',
    res: [/^Name and Address of the Contractor\s*:\s*(.*)$/is]
  },
  {
    key: 'form25_establishment',
    label: 'Name and address of establishment in/ under which contract is carried on:',
    res: [
      /^Name and address of establishment\s+in\s*\/\s*under which contract is carried on\s*:\s*(.*)$/is,
      /^Name\s+and\s+address\s+of\s+establishment[\s\S]{0,220}?contract\s+is\s+carried\s+on\s*:\s*(.*)$/is
    ]
  },
  {
    key: 'form25_principal_employer',
    label: 'Name and address of Principal Employer:',
    res: [/^Name and address of Principal Employer\s*:\s*(.*)$/is]
  }
];

const scanForm25RowValueAfterLabelColumn = (row, labelCol, effectiveSheetCols, getMergedAwareCellText) => {
  const maxC = Math.max(80, effectiveSheetCols);
  for (let nc = labelCol + 1; nc < Math.min(labelCol + 45, maxC); nc++) {
    const t = String(getMergedAwareCellText(row, nc) || '').trim();
    if (!t) continue;
    const tl = t.toLowerCase();
    if (/^name\s+and\s+address/i.test(tl)) continue;
    if (/^nature\s+and\s+location/i.test(tl)) continue;
    if (/^for\s+the\s+month/i.test(tl)) continue;
    if (/^approved\s+festival/i.test(tl)) continue;
    if (/^place\s*:?\s*$/i.test(tl)) continue;
    if (/^district\s*:?\s*$/i.test(tl)) continue;
    if (/^name\s+of\s+the\s+factory/i.test(tl)) continue;
    return t;
  }
  return '';
};

function enrichForm14APHeadersFromSheet(headerRowIndex, effectiveSheetCols, getMergedAwareCellText) {
  const results = [];
  for (const spec of FORM_14_AP_HEADER_SPECS) {
    outer: for (let r = 0; r < headerRowIndex; r++) {
      for (let c = 0; c < Math.max(20, effectiveSheetCols); c++) {
        const raw = String(getMergedAwareCellText(r, c) || '').trim();
        if (!raw || !spec.test(raw)) continue;
        const inline = raw.match(/:\s*(.+)$/);
        let val = inline ? String(inline[1] || '').trim() : '';
        if (!val) val = scanForm25RowValueAfterLabelColumn(r, c, effectiveSheetCols, getMergedAwareCellText);
        results.push({ label: spec.label, value: val, key: spec.key });
        break outer;
      }
    }
  }
  return results;
}

const enrichForm25AddressHeadersFromSheet = (headerRowIndex, effectiveSheetCols, getMergedAwareCellText) => {
  const results = [];
  for (const spec of FORM25_SHEET_HEADER_SPECS) {
    const patterns = spec.res || [];
    outer: for (let r = 0; r < headerRowIndex; r++) {
      for (let c = 0; c < Math.max(80, effectiveSheetCols); c++) {
        const raw = String(getMergedAwareCellText(r, c) || '').trim();
        if (!raw) continue;
        let m = null;
        for (let pi = 0; pi < patterns.length; pi++) {
          m = raw.match(patterns[pi]);
          if (m) break;
        }
        if (!m) continue;
        let val = (m[1] || '').trim().replace(/\s+/g, ' ');
        if (!val) val = scanForm25RowValueAfterLabelColumn(r, c, effectiveSheetCols, getMergedAwareCellText);
        results.push({ label: spec.label, value: val, key: spec.key });
        break outer;
      }
    }
  }
  return results;
};

/** Tamil Nadu LWF Form C–style grids: fixed category rows × quarterly columns — not one Zoho row per employee. */
const isFixedRowAggregateComplianceTable = (headers) => {
  const list = Array.isArray(headers) ? headers.map((h) => String(h || '').toLowerCase()) : [];
  if (list.length < 2) return false;
  const hasQuarterCols = list.some((h) => /quarter\s+ending/.test(h));
  const hasFinesDetailsCol = list.some((h) =>
    /details\s+of\s+fines|unpaid\s+accumulations/.test(h)
  );
  const looksLikeEmployeeRegister =
    list.some((h) => /\bs\.?\s*no\b|serial\s+number/.test(h)) &&
    list.some((h) => /name\s+of\s+(the\s+)?employee/.test(h));
  return hasQuarterCols && hasFinesDetailsCol && !looksLikeEmployeeRegister;
};

/**
 * Vertically merged body cells (common on TN LWF Form C) repeat the same merged values for each
 * physical sheet row; the parser then emits duplicate logical rows. Keep one row per consecutive run.
 */
const dedupeConsecutiveFixedAggregateBodyRows = (rows) => {
  if (!Array.isArray(rows) || rows.length < 2) return rows;
  const signature = (row) => {
    if (Array.isArray(row)) return row.map((v) => String(v ?? '').trim()).join('\x1f');
    if (row && typeof row === 'object') return Object.values(row).map((v) => String(v ?? '').trim()).join('\x1f');
    return String(row ?? '').trim();
  };
  const out = [];
  let prevSig = null;
  for (const row of rows) {
    const sig = signature(row);
    if (sig === prevSig) continue;
    prevSig = sig;
    out.push(row);
  }
  return out;
};

const normalizeAggregateRowText = (txt) =>
  String(txt || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

/** TN LWF Form C category labels often embed soft line breaks / asterisk markers from the Excel template. */
const normalizeFixedAggregateCategoryLabel = (txt) =>
  String(txt || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\r?\n/g, ' ')
    .replace(/\*+of-*/gi, '* of ')
    .replace(/\s+/g, ' ')
    .trim();

const cellValueIsSignatureFooterText = (value) => {
  const norm = normalizeAggregateRowText(value);
  if (!norm) return false;
  if (/\b(authorised|authorized)\s+signator(y|ies)\b/i.test(norm)) return true;
  if (norm.includes('authorised signatory') || norm.includes('authorized signatory')) return true;
  if (/signature\s+of\s+employer/i.test(norm)) return true;
  if (/^for\s*\(/.test(norm)) return true;
  if (/manager\s*\/\s*authorised\s+person/i.test(norm)) return true;
  return false;
};

/** Legal footnote under the Form C grid — must not become a data / quarter cell value. */
const cellValueIsUnpaidAccumulationsFootnote = (value) => {
  const norm = normalizeAggregateRowText(value);
  if (!norm) return false;
  if (/see\s+definition\s+of/.test(norm) && /unpaid\s+accumulations/.test(norm)) return true;
  if (
    /under\s+section\s*2\s*\(?\s*i\s*\)?/.test(norm) &&
    /labour\s+welfare\s+fund\s+act/.test(norm)
  ) {
    return true;
  }
  return false;
};

const collectFixedAggregateRowValues = (row, headers) => {
  if (Array.isArray(row)) {
    return row.map((v) => String(v ?? '').trim()).filter(Boolean);
  }
  if (!row || typeof row !== 'object') return [];
  const hdrs = Array.isArray(headers) && headers.length > 0 ? headers : Object.keys(row);
  return hdrs.map((h) => String(row[h] ?? '').trim()).filter(Boolean);
};

const isFixedAggregateCategoryLabelRow = (row, headers) => {
  const labelHeader = (headers || []).find((h) =>
    /details\s+of\s+fines|unpaid\s+accumulations/i.test(String(h || ''))
  );
  if (!labelHeader) return false;
  const labelVal = String(row?.[labelHeader] ?? '').trim();
  if (!labelVal || /^enter\s+/i.test(labelVal)) return false;
  if (cellValueIsUnpaidAccumulationsFootnote(labelVal)) return false;
  return true;
};

/** Footnote row (*See definition of "Unpaid Accumulations"…) often merged across all quarter columns. */
const isFixedAggregateComplianceFootnoteRow = (row, headers) => {
  const values = collectFixedAggregateRowValues(row, headers);
  if (values.length === 0) return false;
  const footnoteVals = values.filter((v) => cellValueIsUnpaidAccumulationsFootnote(v));
  if (footnoteVals.length === 0) return false;
  // Pure footnote row: every non-empty cell is the definition text (common when A–E are merged).
  if (footnoteVals.length === values.length) return true;
  const labelHeader = (headers || []).find((h) =>
    /details\s+of\s+fines|unpaid\s+accumulations/i.test(String(h || ''))
  );
  if (labelHeader && cellValueIsUnpaidAccumulationsFootnote(row?.[labelHeader])) return true;
  return false;
};

/** Signature / employer footer rows must not appear as editable Form C (LWF) grid rows. */
const isFixedAggregateComplianceFooterRow = (row, headers) => {
  if (isFixedAggregateComplianceFootnoteRow(row, headers)) return true;
  if (isFixedAggregateCategoryLabelRow(row, headers)) return false;
  const values = collectFixedAggregateRowValues(row, headers);
  if (values.length === 0) return false;
  if (values.some((v) => cellValueIsSignatureFooterText(v))) return true;

  const hdrs = Array.isArray(headers) ? headers : [];
  const labelHeader = hdrs.find((h) => /details\s+of\s+fines|unpaid\s+accumulations/i.test(String(h || '')));
  const labelVal = labelHeader ? String(row?.[labelHeader] ?? '').trim() : '';
  const labelIsEmptyOrPlaceholder = !labelVal || /^enter\s+/i.test(labelVal);
  const quarterHeaders = hdrs.filter((h) => /quarter\s+ending/i.test(String(h || '')));
  const quarterVals = quarterHeaders.map((h) => String(row?.[h] ?? '').trim()).filter(Boolean);
  if (labelIsEmptyOrPlaceholder && quarterVals.length > 0) {
    const allFooterish = quarterVals.every((v) => {
      if (cellValueIsSignatureFooterText(v)) return true;
      if (cellValueIsUnpaidAccumulationsFootnote(v)) return true;
      if (/^\d{1,3}$/.test(normalizeAggregateRowText(v))) return true;
      return false;
    });
    if (allFooterish) return true;
  }
  return false;
};

const stripFixedAggregateComplianceFooterRows = (rows, headers) => {
  if (!Array.isArray(rows) || rows.length === 0) return rows;
  return rows.filter((row) => !isFixedAggregateComplianceFooterRow(row, headers));
};

/** Remove signature/footer/footnote bleed from quarter columns while keeping category + fines entry rows. */
const sanitizeFixedAggregateComplianceRows = (rows, headers) => {
  if (!Array.isArray(rows) || rows.length === 0) return rows;
  const hdrs = Array.isArray(headers) ? headers : [];
  const quarterHeaders = hdrs.filter((h) => /quarter\s+ending/i.test(String(h || '')));
  const labelHeader = hdrs.find((h) => /details\s+of\s+fines|unpaid\s+accumulations/i.test(String(h || '')));

  const cleaned = stripFixedAggregateComplianceFooterRows(rows, hdrs).map((row) => {
    if (!row || typeof row !== 'object') return row;
    const next = { ...row };
    let changed = false;

    if (labelHeader) {
      const rawLabel = String(next[labelHeader] ?? '');
      const cleanedLabel = normalizeFixedAggregateCategoryLabel(rawLabel);
      if (cleanedLabel !== rawLabel) {
        next[labelHeader] = cleanedLabel;
        changed = true;
      }
    }

    hdrs.forEach((h) => {
      const v = String(next[h] ?? '').trim();
      if (!v) return;
      if (cellValueIsUnpaidAccumulationsFootnote(v)) {
        next[h] = '';
        changed = true;
      }
    });

    if (quarterHeaders.length === 0) return changed ? next : row;
    if (isFixedAggregateCategoryLabelRow(next, hdrs)) {
      // Category rows may still have footnote bleed copied into quarter cells via tall merges.
      quarterHeaders.forEach((h) => {
        const v = String(next[h] ?? '').trim();
        if (!v) return;
        if (cellValueIsUnpaidAccumulationsFootnote(v) || cellValueIsSignatureFooterText(v)) {
          next[h] = '';
          changed = true;
        }
      });
      return changed ? next : row;
    }

    const labelVal = labelHeader ? String(next[labelHeader] ?? '').trim() : '';
    const isFinesEntryRow = !labelVal || /^enter\s+/i.test(labelVal);
    quarterHeaders.forEach((h) => {
      const v = String(next[h] ?? '').trim();
      if (!v) return;
      if (cellValueIsSignatureFooterText(v) || cellValueIsUnpaidAccumulationsFootnote(v)) {
        next[h] = '';
        changed = true;
        return;
      }
      if (isFinesEntryRow && /^\d{1,3}$/.test(normalizeAggregateRowText(v))) {
        next[h] = '';
        changed = true;
      }
    });
    return changed ? next : row;
  });

  // Tall vertical merges on TN Form C copy the same quarter value onto every category row.
  // Keep Nil / blank-placeholder bleed on every row (required for March column defaults);
  // only collapse other duplicated non-empty values to the first category row.
  if (quarterHeaders.length === 0 || cleaned.length < 2) return cleaned;
  const quarterSig = (row) =>
    quarterHeaders.map((h) => String(row?.[h] ?? '').trim().replace(/_+/g, '').toLowerCase()).join('\x1f');
  const firstSig = quarterSig(cleaned[0]);
  if (!firstSig || !/[a-z0-9]/.test(firstSig)) return cleaned;
  const firstIsNilOnly = firstSig
    .split('\x1f')
    .filter(Boolean)
    .every((part) => /^nil$/i.test(part));
  if (firstIsNilOnly) return cleaned;
  const sameAsFirstCount = cleaned.filter((row) => quarterSig(row) === firstSig).length;
  if (sameAsFirstCount < Math.max(3, Math.ceil(cleaned.length * 0.6))) return cleaned;
  return cleaned.map((row, idx) => {
    if (idx === 0 || quarterSig(row) !== firstSig) return row;
    const next = { ...row };
    quarterHeaders.forEach((h) => {
      next[h] = '';
    });
    return next;
  });
};

/** Classify TN LWF Form C category labels for mapping modal rows → template slots. */
const classifyFormCLabourWelfareCategory = (label) => {
  const n = normalizeAggregateRowText(label);
  if (!n) return null;
  if (/total\s+realisations/.test(n)) return 'realisations';
  if (/\(ii\)|over\s*[- ]?time/.test(n)) return 'ot';
  if (/\(iii\)|dearness/.test(n)) return 'da';
  if (/\(iv\)|\bbonus\b/.test(n)) return 'bonus';
  if (/\(v\)|\bgratuity\b/.test(n)) return 'gratuity';
  if (/\(vi\)|any\s+other\s+item/.test(n)) return 'other';
  if (/standing\s+orders/.test(n)) return 'standing';
  if (/payment\s+of\s+wages/.test(n)) return 'pow';
  if (/basic\s+wages|total\s+amount\s+being\s+unpaid|\(i\)/.test(n)) return 'basic';
  return null;
};

const normalizeFormCQuarterCellValue = (value) => {
  const text = String(value ?? '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return '';
  if (cellValueIsUnpaidAccumulationsFootnote(text)) return '';
  const compact = text.replace(/_+/g, '').trim();
  if (/^nil$/i.test(compact)) return 'Nil';
  return text;
};

/** LWF Form-C: “[See rule … Labour Welfare …]” is rendered on its own line under the title (not the generic reference block). */
const shouldAppendReferenceToFormCTitle = (formHeader) => {
  const title = String(formHeader?.title || '').trim();
  const ref = String(formHeader?.reference || '').trim();
  if (!title || !ref) return false;
  if (!/\bform\s*[-–]?\s*c\b/i.test(title)) return false;
  return /^\s*\[\s*see\s+rule\s+\d+/i.test(ref) && /labour\s+welfare/i.test(ref);
};

const shouldPlaceFormBReferenceBeforeSubtitle = (formHeader) => {
  const title = String(formHeader?.title || '').trim();
  const subtitle = String(formHeader?.subtitle || '').trim();
  const ref = String(formHeader?.reference || '').trim();
  if (!title || !ref) return false;
  if (!/\bform\s*["']?\s*b\b/i.test(title)) return false;
  if (subtitle && !/register\s+of\s+wages/i.test(subtitle)) return false;
  return /labou?r\s*welfare\s*fund\s*rules?/i.test(ref);
};

const shouldPlaceFormAReferenceBeforeSubtitle = (formHeader) => {
  const title = String(formHeader?.title || '').trim();
  const subtitle = String(formHeader?.subtitle || '').trim();
  const ref = String(formHeader?.reference || '').trim();
  if (!ref) return false;
  const looksLikeFormA = /\bform\s*[-"']?\s*a\b/i.test(title) || /maternity\s+benefit\s+rules?/i.test(ref);
  if (!looksLikeFormA) return false;
  if (subtitle && !/register\s+of\s+muster\s+roll/i.test(subtitle)) return false;
  return /\bsee\s+sub-?rule\b/i.test(ref) && /maternity\s+benefit\s+rules?/i.test(ref);
};

const isFormAMusterRollContext = (formHeader) => {
  const title = String(formHeader?.title || '').trim();
  const subtitle = String(formHeader?.subtitle || '').trim();
  const ref = String(formHeader?.reference || '').trim();
  const text = [title, subtitle, ref].join(' ').toLowerCase();
  return (
    (/\bform\s*[-"']?\s*a\b/.test(text) || /maternity\s+benefit\s+rules?/.test(text)) &&
    /register\s+of\s+muster\s+roll/.test(text)
  );
};

const isFormAMusterRollRowContext = (formHeader, item, fileName = '', sheetText = '') => {
  if (isFormAMusterRollContext(formHeader)) return true;
  const blob = [
    item?.formName,
    item?.FormName,
    item?.act,
    item?.Act,
    item?.description,
    item?.Description,
    fileName,
    sheetText
  ]
    .join(' ')
    .toLowerCase();
  const formAName = /\bform[\s_\-]*a\b/.test(blob);
  if (
    formAName &&
    /maternity\s+benefit|register\s+of\s+muster\s+roll|muster\s+roll|tamil\s*nadu|tamilnadu/.test(blob)
  ) {
    return true;
  }
  const fn = String(fileName || '').toLowerCase();
  if (/\bform[\s_\-]*a\b/.test(fn) && /tamil|maternity|muster/.test(fn)) return true;
  if (/form[\s_\-]*a[\s_\-]+tamil/i.test(fn.replace(/\.xlsx?$/i, ''))) return true;
  return false;
};

const headersIndicateFormAMusterRoll = (tableHeaders) => {
  if (!Array.isArray(tableHeaders) || tableHeaders.length === 0) return false;
  const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
  if (/name\s+of\s+the\s+woman/.test(joined)) return true;
  if (/woman/.test(joined) && /\bage\b/.test(joined)) return true;
  if (/husband\s+or\s+father/.test(joined) && /nature\s+of\s+work/.test(joined)) return true;
  if (/no\.?\s*of\s+days?\s+employed/.test(joined) && /laid\s+off/.test(joined)) return true;
  if (/no\.?\s*of\s+days?\s+not\s+employed/.test(joined)) return true;
  if (/date\s+on\s+which\s+employed/.test(joined) && /month/.test(joined)) return true;
  return false;
};

const headersLookLikePivotOrWrongFormATable = (tableHeaders) => {
  if (!Array.isArray(tableHeaders) || tableHeaders.length === 0) return false;
  const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join(' | ');
  if (/row\s+labels/.test(joined)) return true;
  if (/count\s+of\s+(male|female)/.test(joined)) return true;
  if (/sum\s+of\s+(gross|basic)\s+wage/.test(joined) && !/woman|workman|maternity/.test(joined)) return true;
  return false;
};

const isFormAMusterTableHeaderRowText = (rowTextLower) => {
  if (!rowTextLower || headersLookLikePivotOrWrongFormATable([rowTextLower])) return false;
  if (!rowHasTableSerialHeader(rowTextLower) && !/\bserial\b/.test(rowTextLower)) return false;
  return /woman|workman|husband|nature\s+of\s+work|days\s+employed|laid\s+off|not\s+employed|maternity/.test(
    rowTextLower
  );
};

const findFormAMusterTableAnchor = (getMergedAwareCellText, maxRows = 80, maxCols = 140) => {
  for (let r = 0; r < maxRows; r += 1) {
    const cells = [];
    for (let c = 0; c < maxCols; c += 1) {
      cells.push(String(getMergedAwareCellText(r, c) || '').trim());
    }
    const rowTextLower = cells.filter(Boolean).join(' ').toLowerCase();
    if (!isFormAMusterTableHeaderRowText(rowTextLower)) continue;
    let snoCol = 0;
    for (let c = 0; c < maxCols; c += 1) {
      const t = normalizeExcelHeaderCell(getMergedAwareCellText(r, c));
      if (
        t &&
        (t === 's.no' ||
          t === 's no' ||
          t === 'sl.no' ||
          t === 'sl no' ||
          t.includes('s.no') ||
          t.includes('serial'))
      ) {
        snoCol = c;
        break;
      }
    }
    return { r, c: snoCol };
  }
  return null;
};

const collectFormATableHeaderCells = (getMergedAwareCellText, headerRowIndex, startCol, maxCols) => {
  const normalizeHeaderText = (txt) =>
    String(txt || '')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  const rebuilt = [];
  let emptyStreak = 0;
  for (let colIdx = startCol; colIdx < maxCols; colIdx += 1) {
    let h = normalizeHeaderText(getMergedAwareCellText(headerRowIndex, colIdx));
    if (!h) {
      for (let lookFwd = 1; lookFwd <= 2; lookFwd += 1) {
        const cand = normalizeHeaderText(getMergedAwareCellText(headerRowIndex + lookFwd, colIdx));
        if (!cand || /^\d+$/.test(cand) || cand.length < 2) continue;
        h = cand;
        break;
      }
    }
    if (!h) {
      if (rebuilt.length === 0) continue;
      emptyStreak += 1;
      if (emptyStreak >= 6) break;
      continue;
    }
    emptyStreak = 0;
    rebuilt.push(h);
  }
  while (rebuilt.length > 0 && !rebuilt[rebuilt.length - 1]) rebuilt.pop();
  return rebuilt;
};

const computeFormADataStartIndex = (getMergedAwareCellText, headerRowIndex, startCol, headers, jsonDataLength) => {
  let dataStartIndex = headerRowIndex + 1;
  if (headerRowIndex + 1 < jsonDataLength) {
    let seqHits = 0;
    for (let i = 0; i < headers.length; i += 1) {
      const t = String(getMergedAwareCellText(headerRowIndex + 1, startCol + i) || '')
        .replace(/\s+/g, '')
        .trim();
      if (t === String(i + 1)) seqHits += 1;
    }
    if (seqHits >= Math.max(3, Math.floor(headers.length * 0.4))) {
      dataStartIndex = headerRowIndex + 2;
    }
  }
  return dataStartIndex;
};

const findFormAMusterTableAnchorRelaxed = (getMergedAwareCellText, maxRows = 120, maxCols = 140, sheetText = '') => {
  let searchFrom = 0;
  for (let r = 0; r < maxRows; r += 1) {
    const rowText = [];
    for (let c = 0; c < maxCols; c += 1) {
      rowText.push(String(getMergedAwareCellText(r, c) || '').trim());
    }
    const joined = rowText.filter(Boolean).join(' ').toLowerCase();
    if (/register\s+of\s+muster\s+roll|maternity\s+benefit/.test(joined)) searchFrom = r;
  }
  for (let r = searchFrom; r < maxRows; r += 1) {
    const cells = [];
    for (let c = 0; c < maxCols; c += 1) {
      cells.push(String(getMergedAwareCellText(r, c) || '').trim());
    }
    const nonEmpty = cells.filter(Boolean);
    if (nonEmpty.length < 3 || headersLookLikePivotOrWrongFormATable(nonEmpty)) continue;
    const rowTextLower = nonEmpty.join(' ').toLowerCase();
    if (/^1[\s.)-]*name\s+of\s+the\s+establishment/.test(rowTextLower.replace(/^\s+/, ''))) continue;
    if (!rowHasTableSerialHeader(rowTextLower) && !/\bserial\b/.test(rowTextLower)) continue;
    let snoCol = 0;
    for (let c = 0; c < maxCols; c += 1) {
      const t = normalizeExcelHeaderCell(getMergedAwareCellText(r, c));
      if (
        t &&
        (t === 's.no' ||
          t === 's no' ||
          t === 'sl.no' ||
          t === 'sl no' ||
          t.includes('s.no') ||
          t.includes('serial'))
      ) {
        snoCol = c;
        return { r, c: snoCol };
      }
    }
  }
  return null;
};

const rebuildFormATableHeadersFromSheetRelaxed = ({
  jsonData,
  effectiveSheetCols,
  getMergedAwareCellText,
  sheetText = ''
}) => {
  const maxRows = Math.min(120, (jsonData?.length || 0) + 5);
  const maxCols = Math.max(effectiveSheetCols || 0, 50);
  const anchor = findFormAMusterTableAnchorRelaxed(getMergedAwareCellText, maxRows, maxCols, sheetText);
  if (!anchor) return null;
  const rebuilt = collectFormATableHeaderCells(getMergedAwareCellText, anchor.r, anchor.c, maxCols);
  if (rebuilt.length < 3 || headersLookLikePivotOrWrongFormATable(rebuilt)) return null;
  return {
    headers: rebuilt,
    headerRowIndex: anchor.r,
    dataStartIndex: computeFormADataStartIndex(
      getMergedAwareCellText,
      anchor.r,
      anchor.c,
      rebuilt,
      jsonData?.length || 0
    ),
    startCol: anchor.c
  };
};

const buildWorksheetParseHelpers = (worksheet, jsonData) => {
  const range = XLSX.utils.decode_range(worksheet['!ref'] || 'A1:A1');
  const maxSheetCols = range.e && typeof range.e.c === 'number' ? range.e.c + 1 : 0;
  const merges = worksheet['!merges'] || [];
  let mergeMaxCol = 0;
  for (let mi = 0; mi < merges.length; mi += 1) {
    const m = merges[mi];
    if (m && m.e && typeof m.e.c === 'number') mergeMaxCol = Math.max(mergeMaxCol, m.e.c + 1);
  }
  const effectiveSheetCols = Math.max(maxSheetCols, mergeMaxCol);
  const getRawCellText = (r, c) => {
    if (r < 0 || c < 0) return '';
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = worksheet[ref];
    if (!cell || cell.v == null) return '';
    return String(cell.v).trim();
  };
  const getMergedAwareCellText = (r, c) => {
    const direct = getRawCellText(r, c);
    if (direct) return direct;
    for (let i = 0; i < merges.length; i += 1) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        const topLeft = getRawCellText(m.s.r, m.s.c);
        if (topLeft) return topLeft;
      }
    }
    return '';
  };
  return { effectiveSheetCols, getMergedAwareCellText, jsonData: jsonData || XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '' }) };
};

const extractFormATableDataFromSheet = (jsonData, layout, getMergedAwareCellText) => {
  if (!layout?.headers?.length) return [];
  const rows = [];
  const startIndex = layout.dataStartIndex ?? layout.headerRowIndex + 1;
  const startCol = layout.startCol ?? 0;
  for (let i = startIndex; i < (jsonData?.length || 0); i += 1) {
    const rowData = {};
    for (let j = 0; j < layout.headers.length; j += 1) {
      rowData[layout.headers[j]] = String(getMergedAwareCellText(i, startCol + j) || '').trim();
    }
    if (Object.values(rowData).some((val) => val)) rows.push(rowData);
  }
  return rows;
};

const resolveFormATableHeadersFromWorkbook = (workbook, hints = {}) => {
  const sheetName = workbook?.SheetNames?.[0];
  if (!sheetName) return null;
  const worksheet = workbook.Sheets[sheetName];
  if (!worksheet) return null;
  const { effectiveSheetCols, getMergedAwareCellText, jsonData } = buildWorksheetParseHelpers(worksheet);
  const sheetText = jsonData
    .slice(0, 45)
    .map((row) => (Array.isArray(row) ? row : []).map((c) => String(c || '')).join(' '))
    .join(' ');
  const formHeader = hints.formHeader || null;
  const item = hints.item || null;
  const fileName = hints.fileName || hints.formFileName || sheetName || '';
  if (
    !isFormAMusterRollContext(formHeader) &&
    !isFormAMusterRollRowContext(formHeader, item, fileName, hints.sheetText || sheetText)
  ) {
    return null;
  }
  let rebuild = rebuildFormATableHeadersFromSheet({ jsonData, effectiveSheetCols, getMergedAwareCellText });
  if (!rebuild?.headers?.length) {
    rebuild = rebuildFormATableHeadersFromSheetRelaxed({
      jsonData,
      effectiveSheetCols,
      getMergedAwareCellText,
      sheetText: hints.sheetText || sheetText
    });
  }
  if (!rebuild?.headers?.length) return null;
  return {
    ...rebuild,
    tableData: extractFormATableDataFromSheet(jsonData, rebuild, getMergedAwareCellText)
  };
};

const applyFormAWorkbookLayoutToParsed = (parsed, workbook, hints = {}) => {
  if (!parsed || !workbook) return parsed;
  const currentHeaders = Array.isArray(parsed.headers) ? parsed.headers : [];
  if (
    headersIndicateFormAMusterRoll(currentHeaders) &&
    !headersLookLikePivotOrWrongFormATable(currentHeaders)
  ) {
    return parsed;
  }
  const layout = resolveFormATableHeadersFromWorkbook(workbook, {
    ...hints,
    formHeader: hints.formHeader || parsed.formHeader
  });
  if (layout?.headers?.length) {
    return {
      ...parsed,
      headers: layout.headers,
      tableData: layout.tableData?.length ? layout.tableData : parsed.tableData,
      headerRowIndex: layout.headerRowIndex,
      dataStartIndex: layout.dataStartIndex,
      tableStartCol: layout.startCol
    };
  }
  return applyFormAHeaderFieldLayoutToParsed(parsed, workbook, hints);
};

const rebuildFormATableHeadersFromSheet = ({
  jsonData,
  effectiveSheetCols,
  getMergedAwareCellText
}) => {
  const maxRows = Math.min(80, (jsonData?.length || 0) + 5);
  const maxCols = Math.max(effectiveSheetCols || 0, 40);
  const anchor = findFormAMusterTableAnchor(getMergedAwareCellText, maxRows, maxCols);
  if (!anchor) return null;
  const rebuilt = collectFormATableHeaderCells(getMergedAwareCellText, anchor.r, anchor.c, maxCols);
  if (rebuilt.length < 3 || headersLookLikePivotOrWrongFormATable(rebuilt)) return null;
  return {
    headers: rebuilt,
    headerRowIndex: anchor.r,
    dataStartIndex: computeFormADataStartIndex(
      getMergedAwareCellText,
      anchor.r,
      anchor.c,
      rebuilt,
      jsonData?.length || 0
    ),
    startCol: anchor.c
  };
};

const FORM_A_NUMBERED_HEADER_SPECS = [
  {
    match: /^1\.?\s*name\s+of\s+the\s+establishment/i,
    label: 'Name of the Establishment:',
    key: 'form_a_establishment_name'
  },
  {
    match: /address\s+of\s+the\s+establishment/i,
    label: 'Address of the Establishment:',
    key: 'form_a_establishment_address'
  },
  {
    match: /^2\.?\s*name\s+of\s+the\s+woman/i,
    label: 'Name of the woman and age:',
    key: 'form_a_woman_name_age'
  },
  {
    match: /^\s*age\s*:?\s*$/i,
    label: 'Age:',
    key: 'form_a_age'
  },
  {
    match: /^3\.?\s*name\s+of\s+husband/i,
    label: 'Name of husband or father:',
    key: 'form_a_husband_father'
  },
  {
    match: /^4\.?\s*nature\s+of\s+work/i,
    label: 'Nature of Work:',
    key: 'form_a_nature_of_work'
  },
  {
    match: /^5\.?\s*date\s+on\s+which\s+employed/i,
    label: 'Date on which employed:',
    key: 'form_a_date_employed'
  },
  {
    match: /^6\.?\s*dates\s+with\s+month/i,
    label: 'Dates with month and year in which employed:',
    key: 'form_a_dates_employed'
  },
  {
    match: /^7\.?\s*date\s+of\s+giving\s+notice.*preg/i,
    label: 'Date of giving notice of Pregnancy:',
    key: 'form_a_notice_pregnancy'
  },
  {
    match: /^8\.?\s*date\s+of\s+giving\s+notice.*deliv/i,
    label: 'Date of giving notice of Delivery:',
    key: 'form_a_notice_delivery'
  },
  {
    match: /^9\.?\s*date\s+of\s+production\s+of\s+proof.*birth/i,
    label: 'Date of Production of Proof of Birth:',
    key: 'form_a_proof_birth'
  },
  {
    match: /^10\.?\s*date\s+of\s+production\s+of\s+proof.*death/i,
    label: 'Date of production of proof of death if any:',
    key: 'form_a_proof_death'
  },
  {
    match: /^11\.?\s*date\s+on\s+which\s+payment\s+was\s+made/i,
    label: 'Date on which payment was made:',
    key: 'form_a_payment_date'
  },
  {
    match: /^12\.?\s*details\s+of\s+payment/i,
    label: 'Details of Payment:',
    key: 'form_a_payment_details'
  },
  {
    match: /^\s*a\)?\s*maternity\s+benefit/i,
    label: 'a) Maternity Benefit:',
    key: 'form_a_maternity_benefit'
  },
  {
    match: /^\s*b\)?\s*subsequent\s+paym/i,
    label: 'b) Subsequent Payment:',
    key: 'form_a_subsequent_payment'
  },
  {
    match: /^\s*c\)?\s*bonus/i,
    label: 'c) Bonus:',
    key: 'form_a_bonus'
  }
];

/** Map one Autofill table row → Form A vertical template header keys (per-employee ZIP). */
const mapFormAAutofillRowToHeaderFormData = (row, headers, baseHeaderData = {}) => {
  const out = { ...(baseHeaderData && typeof baseHeaderData === 'object' ? baseHeaderData : {}) };
  const isPlaceholder = (v) => /^enter\s+/i.test(String(v ?? '').trim());
  const pickKind = (kind) => {
    const header = findFormATableHeader(headers, kind);
    if (!header || !row || typeof row !== 'object') return '';
    let value = row[header];
    if (value == null || String(value).trim() === '' || isPlaceholder(value)) {
      const target = normalizeLooseHeaderText(header);
      const hit = Object.keys(row).find((k) => {
        if (String(k).startsWith('__')) return false;
        return normalizeLooseHeaderText(k) === target || classifyFormATableColumn(k) === kind;
      });
      value = hit ? row[hit] : '';
    }
    if (value == null || isPlaceholder(value)) return '';
    return String(value).trim();
  };
  const pickAllKind = (kind) => {
    if (!row || typeof row !== 'object') return '';
    const list = Array.isArray(headers) && headers.length > 0 ? headers : Object.keys(row);
    const parts = [];
    list.forEach((header) => {
      if (classifyFormATableColumn(header) !== kind) return;
      const v = String(row[header] ?? '').trim();
      if (!v || isPlaceholder(v)) return;
      parts.push(v);
    });
    return parts.join('; ');
  };
  const womanRaw = pickKind('womanAge');
  let womanName = womanRaw;
  let ageOnly = '';
  const ageParen = String(womanRaw || '').match(/^(.*)\((\d{1,3})\)\s*$/);
  if (ageParen) {
    womanName = String(ageParen[1] || '').trim();
    ageOnly = ageParen[2];
  }
  // Keep "Name (age)" on the woman line; also fill standalone Age when present.
  out.form_a_woman_name_age = womanRaw || womanName || out.form_a_woman_name_age || '';
  out.form_a_age = pickKind('age') || ageOnly || out.form_a_age || '';
  out.form_a_husband_father = pickKind('husbandFather') || out.form_a_husband_father || '';
  out.form_a_nature_of_work = pickKind('natureOfWork') || out.form_a_nature_of_work || '';
  out.form_a_date_employed = pickKind('dateEmployed') || out.form_a_date_employed || '';
  out.form_a_dates_employed =
    pickAllKind('datesEmployed') || pickKind('datesEmployed') || out.form_a_dates_employed || '';
  out.form_a_notice_pregnancy = pickKind('noticePregnancy') || out.form_a_notice_pregnancy || '';
  out.form_a_notice_delivery = pickKind('noticeDelivery') || out.form_a_notice_delivery || '';
  out.form_a_proof_birth = pickKind('proofBirth') || out.form_a_proof_birth || '';
  out.form_a_proof_death = pickKind('proofDeath') || out.form_a_proof_death || '';
  out.form_a_payment_date = pickKind('paymentDate') || out.form_a_payment_date || '';
  const matCombined = pickKind('maternityBenefit');
  const matAmt = pickKind('maternityAmount');
  const matDate = pickKind('maternityDate');
  out.form_a_maternity_benefit =
    matCombined ||
    [matAmt, matDate].filter(Boolean).join(' / ') ||
    out.form_a_maternity_benefit ||
    '';
  const subCombined = pickKind('subsequentPayment');
  const subAmt = pickKind('subsequentAmount');
  const subDate = pickKind('subsequentDate');
  out.form_a_subsequent_payment =
    subCombined ||
    [subAmt, subDate].filter(Boolean).join(' / ') ||
    out.form_a_subsequent_payment ||
    '';
  const bonusCombined = pickKind('bonus');
  const bonusAmt = pickKind('bonusAmount');
  const bonusDate = pickKind('bonusDate');
  out.form_a_bonus =
    bonusCombined ||
    [bonusAmt, bonusDate].filter(Boolean).join(' / ') ||
    out.form_a_bonus ||
    '';
  const leave9 = [pickKind('leave9Amount'), pickKind('leave9Date')].filter(Boolean).join(' / ');
  const leave10 = [pickKind('leave10Amount'), pickKind('leave10Date')].filter(Boolean).join(' / ');
  const paymentDetailsFromCols = pickKind('paymentDetails');
  const paymentDetails = [leave9 && `Leave wages sec.9: ${leave9}`, leave10 && `Leave wages sec.10: ${leave10}`]
    .filter(Boolean)
    .join('; ');
  if (paymentDetailsFromCols) out.form_a_payment_details = paymentDetailsFromCols;
  else if (paymentDetails) out.form_a_payment_details = paymentDetails;
  return out;
};

const resolveFormAEmployeeDownloadBaseName = (row, headers, index) => {
  const womanHdr = findFormATableHeader(headers, 'womanAge');
  let name = womanHdr && row ? String(row[womanHdr] || '').trim() : '';
  name = name.replace(/\(\d{1,3}\)\s*$/, '').trim();
  if (!name && row && typeof row === 'object') {
    name = String(row.__employeeLookupName || row.Name || '').trim();
  }
  const safe = String(name || `Employee_${index + 1}`)
    .replace(/[^\w.\-]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '')
    .slice(0, 60);
  return safe || `Employee_${index + 1}`;
};

const allocateUniqueFormADownloadFileName = (baseName, usedNames) => {
  const root = String(baseName || 'Employee').replace(/\.xlsx?$/i, '');
  const count = usedNames.get(root) || 0;
  usedNames.set(root, count + 1);
  const suffix = count > 0 ? `_${count + 1}` : '';
  return `Form_A_${root}${suffix}.xlsx`;
};

const formARowLooksExportable = (row, headers) => {
  if (!row || typeof row !== 'object') return false;
  const list = Array.isArray(headers) && headers.length > 0 ? headers : Object.keys(row);
  return list.some((h) => {
    if (String(h).startsWith('__')) return false;
    const v = String(row[h] ?? '').trim();
    return v && !/^enter\s+/i.test(v) && /[a-z]/i.test(v);
  });
};

/**
 * Tamil Nadu Form A (Register of Muster Roll) — vertical one-person template.
 * Download one filled .xlsx per Autofill employee row, packed as a ZIP.
 */
const buildFormATamilNaduPerEmployeeZipDownload = async ({
  templateArrayBuffer,
  headersToUse,
  mappedData,
  parsedFormHeader,
  formFileName,
  headerFormData,
  excelCellValueToString
}) => {
  const hdrs =
    Array.isArray(headersToUse) && headersToUse.length > 0
      ? headersToUse
      : buildFormAAutofillTableHeaders();
  const rows = (Array.isArray(mappedData) ? mappedData : []).filter((row) =>
    formARowLooksExportable(row, hdrs)
  );
  if (rows.length === 0) {
    throw new Error(
      'Form A has no employee rows to export. Click Autofill in the form, then Download again.'
    );
  }
  const baseHeader =
    headerFormData && typeof headerFormData === 'object' ? { ...headerFormData } : {};
  const zip = new JSZip();
  const usedNames = new Map();
  const cellToString =
    typeof excelCellValueToString === 'function'
      ? excelCellValueToString
      : (val) => {
          if (val == null) return '';
          if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
            return String(val);
          }
          if (val instanceof Date) return val.toISOString();
          if (typeof val === 'object') {
            if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
            if (val.text != null) return String(val.text);
            if (val.result != null) return String(val.result);
          }
          return '';
        };

  for (let i = 0; i < rows.length; i += 1) {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(
      templateArrayBuffer instanceof ArrayBuffer
        ? templateArrayBuffer.slice(0)
        : templateArrayBuffer
    );
    const worksheet = workbook.worksheets[0];
    if (!worksheet) throw new Error('Template worksheet not found.');
    const employeeHeader = mapFormAAutofillRowToHeaderFormData(rows[i], hdrs, baseHeader);
    writeFormAHeaderFieldsToExcelWorksheet(worksheet, employeeHeader, parsedFormHeader, {
      excelCellValueToString: cellToString
    });
    const out = await workbook.xlsx.writeBuffer();
    const baseName = resolveFormAEmployeeDownloadBaseName(rows[i], hdrs, i);
    zip.file(allocateUniqueFormADownloadFileName(baseName, usedNames), out);
    if (i > 0 && i % 10 === 0) {
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
  }

  const zipBase = String(formFileName || parsedFormHeader?.title || 'Form_A_TamilNadu')
    .replace(/\.xlsx?$/i, '')
    .replace(/[^\w.-]+/g, '_');
  return {
    blob: await zip.generateAsync({ type: 'blob', compression: 'DEFLATE' }),
    fileName: `${zipBase}_Employees.zip`
  };
};

/** Single vertical Form A sheet (Save / header-only): establishment + one employee. */
const buildFormATamilNaduSingleEmployeeWorkbook = async ({
  templateArrayBuffer,
  headersToUse,
  mappedData,
  parsedFormHeader,
  formFileName,
  headerFormData,
  excelCellValueToString
}) => {
  const hdrs =
    Array.isArray(headersToUse) && headersToUse.length > 0
      ? headersToUse
      : buildFormAAutofillTableHeaders();
  const rows = (Array.isArray(mappedData) ? mappedData : []).filter((row) =>
    formARowLooksExportable(row, hdrs)
  );
  const baseHeader =
    headerFormData && typeof headerFormData === 'object' ? { ...headerFormData } : {};
  const employeeHeader =
    rows.length > 0 ? mapFormAAutofillRowToHeaderFormData(rows[0], hdrs, baseHeader) : baseHeader;
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(templateArrayBuffer);
  const worksheet = workbook.worksheets[0];
  if (!worksheet) throw new Error('Template worksheet not found.');
  const cellToString =
    typeof excelCellValueToString === 'function'
      ? excelCellValueToString
      : (val) => {
          if (val == null) return '';
          if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
            return String(val);
          }
          if (val instanceof Date) return val.toISOString();
          if (typeof val === 'object') {
            if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
            if (val.text != null) return String(val.text);
            if (val.result != null) return String(val.result);
          }
          return '';
        };
  writeFormAHeaderFieldsToExcelWorksheet(worksheet, employeeHeader, parsedFormHeader, {
    excelCellValueToString: cellToString
  });
  const out = await workbook.xlsx.writeBuffer();
  const fileName =
    formFileName ||
    parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
    `Form_${Date.now()}.xlsx`;
  return {
    blob: new Blob([out], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    }),
    fileName: String(fileName).replace(/\.zip$/i, '.xlsx')
  };
};

const enrichFormAHeaderFieldsFromSheet = (headerRowIndex, effectiveSheetCols, getMergedAwareCellText, existingFields = []) => {
  const normLabel = (v) =>
    String(v || '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  const hasLabel = (label) => (existingFields || []).some((f) => normLabel(f.label) === normLabel(label));
  const fields = Array.isArray(existingFields) ? [...existingFields] : [];
  const addField = (label, key, value = '') => {
    if (hasLabel(label)) return;
    fields.push({ label, value, key });
  };
  const scanTo = Math.max(headerRowIndex >= 0 ? headerRowIndex + 1 : 0, 100);
  for (let r = 0; r < scanTo; r += 1) {
    for (let c = 0; c < Math.max(80, effectiveSheetCols || 0); c += 1) {
      const raw = String(getMergedAwareCellText(r, c) || '').trim();
      if (!raw) continue;
      FORM_A_NUMBERED_HEADER_SPECS.forEach((spec) => {
        if (!spec.match.test(raw) || hasLabel(spec.label)) return;
        let value = '';
        for (let nc = c + 1; nc < Math.min(c + 10, Math.max(80, effectiveSheetCols || 0)); nc += 1) {
          const v = String(getMergedAwareCellText(r, nc) || '').trim();
          if (v && v !== ':' && !spec.match.test(v)) {
            value = v;
            break;
          }
        }
        addField(spec.label, spec.key, value);
      });
    }
  }
  return fields;
};

const remapFormARowsByColumnIndex = (rows, priorHeaders, canonicalHeaders) => {
  const list = Array.isArray(rows) ? rows : [];
  const canon = Array.isArray(canonicalHeaders) ? canonicalHeaders : [];
  const prior = Array.isArray(priorHeaders) ? priorHeaders : [];
  const normKey = (h) =>
    String(h || '')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]/gi, ' ');
  return list.map((row, rowIndex) => {
    const out = {};
    canon.forEach((header, colIndex) => {
      let value = '';
      if (row && typeof row === 'object' && !Array.isArray(row)) {
        if (Object.prototype.hasOwnProperty.call(row, header)) {
          value = row[header];
        } else {
          const priorKey = prior[colIndex];
          if (priorKey && Object.prototype.hasOwnProperty.call(row, priorKey)) {
            value = row[priorKey];
          } else {
            const target = normKey(header);
            if (target) {
              const hit = Object.keys(row).find((k) => normKey(k) === target);
              if (hit) value = row[hit];
            }
            if ((value == null || String(value).trim() === '') && priorKey) {
              const priorTarget = normKey(priorKey);
              const priorHit = Object.keys(row).find((k) => normKey(k) === priorTarget);
              if (priorHit) value = row[priorHit];
            }
          }
        }
      } else if (Array.isArray(row) && colIndex < row.length) {
        value = row[colIndex];
      }
      if ((value == null || String(value).trim() === '') && /s\.?\s*no|serial|sl\.?\s*no/i.test(String(header || ''))) {
        value = rowIndex + 1;
      }
      out[header] = value != null ? value : '';
    });
    return out;
  });
};

const shouldHideFormAHeaderField = (formHeader, field) => {
  if (isFormAHeaderFieldLayoutFormHeader(formHeader)) return false;
  if (!isFormAMusterRollContext(formHeader)) return false;
  const label = String(field?.label || '').replace(/\s+/g, ' ').trim().toLowerCase();
  return /^\(?10\)?\s*date\s+on\s+which\s+payment\s+was\s+made\s*:?$/.test(label);
};

const buildFormAEstablishmentNameFromSite = (site) =>
  String(site?.siteName ?? site?.SiteName ?? '').trim();

const buildFormAEstablishmentAddressFromSite = (site) => {
  if (!site || typeof site !== 'object') return '';
  const addr = String(site.siteAddress ?? site.SiteAddress ?? '').trim();
  const city = String(site.siteCity ?? site.SiteCity ?? '').trim();
  const state = String(site.siteState ?? site.SiteState ?? '').trim();
  return [addr, city, state].filter(Boolean).join(', ').trim();
};

const applyFormAEstablishmentFromSite = (headerData, siteName, siteDetailsList) => {
  if (!headerData || typeof headerData !== 'object') return headerData;
  const site = findSiteDetailByName(siteDetailsList, siteName);
  if (!site) return headerData;
  const out = { ...headerData };
  let changed = false;
  const fill = (key, value) => {
    if (!value) return;
    const cur = String(out[key] ?? '').trim();
    if (!cur || isStatutoryHeaderPlaceholderValue(cur)) {
      out[key] = value;
      changed = true;
    }
  };
  fill('form_a_establishment_name', buildSiteEstablishmentNameAndAddress(site));
  fill('form_a_establishment_address', buildFormAEstablishmentAddressFromSite(site));
  return changed ? out : headerData;
};

const pickFormAEmployeeTextField = (emp, patterns) => {
  if (!emp || typeof emp !== 'object') return '';
  const keys = Object.keys(emp);
  for (let i = 0; i < patterns.length; i += 1) {
    const re = patterns[i];
    const hit = keys.find((k) => re.test(String(k || '').replace(/[^a-z0-9]/gi, ' ')));
    if (hit && emp[hit] != null && String(emp[hit]).trim() !== '') return String(emp[hit]).trim();
  }
  return '';
};

const pickEmployeeJoiningDateRaw = (emp) =>
  pickFormAEmployeeTextField(emp, [
    /dateofjoining/i,
    /dateofjoiningdisplayvalue/i,
    /date_of_joining/i,
    /joiningdate/i,
    /doj/i
  ]) ||
  String(
    emp.Dateofjoining ||
      emp['Dateofjoining'] ||
      emp.DateofJoining ||
      emp['Date of Joining'] ||
      emp['DateofJoining'] ||
      emp.dateOfJoining ||
      emp['dateOfJoining'] ||
      emp['Date of joining'] ||
      emp.Date_of_Joining ||
      emp['Date_of_Joining'] ||
      ''
  ).trim();

const formatFormADisplayDate = (raw) => {
  const value = String(raw || '').trim();
  if (!value) return '';
  const d = parseFlexibleStatutoryDate(value) || parseFlexibleEmployeeDate(value);
  if (!d || Number.isNaN(d.getTime())) return value;
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}-${mm}-${d.getFullYear()}`;
};

const buildFormAMonthEmploymentSummary = (selectedMonth, year, daysEmployed, daysLaidOff) => {
  const fullMonth = resolveToFullMonthName(selectedMonth) || String(selectedMonth || '').trim();
  const y = year || new Date().getFullYear();
  const parts = [];
  if (daysEmployed != null && String(daysEmployed).trim() !== '') {
    parts.push(`Employed ${daysEmployed} day(s)`);
  }
  if (daysLaidOff != null && String(daysLaidOff).trim() !== '') {
    parts.push(`Laid off / not employed ${daysLaidOff} day(s)`);
  }
  if (!fullMonth) return parts.join('; ');
  return parts.length ? `${fullMonth} ${y}: ${parts.join('; ')}` : `${fullMonth} ${y}`;
};

const pickForm25RecordValue = (record, keys) => {
  if (!record || typeof record !== 'object' || !Array.isArray(keys)) return '';
  const normKey = (s) =>
    String(s || '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');
  for (let i = 0; i < keys.length; i += 1) {
    const key = keys[i];
    const direct = record[key];
    if (direct != null && String(direct).trim() !== '') return String(direct).trim();
    const targetNorm = normKey(key);
    if (!targetNorm) continue;
    const hit = Object.keys(record).find((k) => {
      const kn = normKey(k);
      return kn === targetNorm || kn.includes(targetNorm) || targetNorm.includes(kn);
    });
    if (hit && record[hit] != null && String(record[hit]).trim() !== '') {
      return String(record[hit]).trim();
    }
  }
  return '';
};

const FORM_A_MARKING_LEGEND = [
  'H for holidays allowed',
  'W/D for work on double wages',
  'W/H for work with substituted holiday',
  'N/E if not eligible for the wages'
];

const FORM_A_DEFAULT_TITLE = 'FORM A';
const FORM_A_DEFAULT_SUBTITLE = 'REGISTER OF MUSTER ROLL';
const FORM_A_DEFAULT_REFERENCE =
  '(See sub-rule (1) of rule 3 of the Maternity Benefit Rules)';

const isFormAHeaderFieldLayoutFormHeader = (formHeader) => !!formHeader?.formAHeaderFieldLayout;

const formAHeaderFieldsHaveData = (headerData) => {
  if (!headerData || typeof headerData !== 'object') return false;
  return Object.values(headerData).some((v) => {
    const s = String(v ?? '').trim();
    return s && !/^enter\b/i.test(s) && !/^select\b/i.test(s);
  });
};

const isFormAHeaderOnlyModalContext = (
  formHeader,
  item,
  fileName,
  sheetText,
  tableHeaders = [],
  headerFields = null
) => {
  // Table layout shows establishment fields + woman-employee grid — not header-only.
  if (isFormATableLayoutFormHeader(formHeader) && Array.isArray(tableHeaders) && tableHeaders.length > 0) {
    return false;
  }
  if (isFormAHeaderFieldLayoutFormHeader(formHeader) && !isFormATableLayoutFormHeader(formHeader)) {
    return true;
  }
  const fn = String(fileName || '');
  const formACtx =
    isFormAMusterRollContext(formHeader) ||
    isFormAMusterRollRowContext(formHeader, item, fn, sheetText) ||
    /\bform[\s._-]*a[\s._-]*[-_.]?tamil/i.test(fn);
  if (!formACtx) return false;
  if (Array.isArray(tableHeaders) && tableHeaders.length > 0 && !headersLookLikePivotOrWrongFormATable(tableHeaders)) {
    return false;
  }
  const fields = headerFields || formHeader?.fields;
  if (Array.isArray(fields) && fields.some((f) => String(f?.key || '').startsWith('form_a_'))) return true;
  if (!tableHeaders?.length || headersLookLikePivotOrWrongFormATable(tableHeaders)) return true;
  return false;
};

const sheetTextIndicatesFormAHeaderFields = (sheetText) => {
  const t = String(sheetText || '').toLowerCase();
  return (
    /register\s+of\s+muster\s+roll/.test(t) &&
    (/name\s+of\s+the\s+woman\s+and\s+age/.test(t) ||
      /name\s+of\s+husband\s+or\s+father/.test(t) ||
      /nature\s+of\s+work/.test(t))
  );
};

/** Ensure Tamil Nadu Form A modal always shows FORM A / muster / maternity heading. */
const enrichFormADisplayHeader = (
  formHeader,
  fileName = '',
  item = null,
  tableHeaders = [],
  sheetText = ''
) => {
  const formACtx =
    isFormAHeaderFieldLayoutFormHeader(formHeader) ||
    isFormAMusterRollContext(formHeader) ||
    isFormAMusterRollRowContext(formHeader, item, fileName, sheetText) ||
    sheetTextIndicatesFormAHeaderFields(sheetText) ||
    (headersIndicateFormAMusterRoll(tableHeaders) &&
      !headersLookLikePivotOrWrongFormATable(tableHeaders) &&
      /\bform[\s._-]*a\b/i.test(
        [fileName, item?.formName, item?.FormName, formHeader?.title].filter(Boolean).join(' ')
      ));
  if (!formACtx) return formHeader;

  const base = formHeader && typeof formHeader === 'object' ? { ...formHeader } : {};
  const title = String(base.title || '').trim();
  const subtitle = String(base.subtitle || '').trim();
  const reference = String(base.reference || '').trim();

  if (!title || !/\bform\s*[-"']?\s*a\b/i.test(title)) {
    base.title = FORM_A_DEFAULT_TITLE;
  }
  if (!subtitle || !/register\s+of\s+muster\s+roll/i.test(subtitle)) {
    base.subtitle = FORM_A_DEFAULT_SUBTITLE;
  }
  if (
    !reference ||
    (!/\bsee\s+sub-?rule\b/i.test(reference) && !/maternity\s+benefit\s+rules?/i.test(reference))
  ) {
    base.reference = FORM_A_DEFAULT_REFERENCE;
  }
  return base;
};

const workbookHasFormAMusterEmployeeTable = (workbook, hints = {}) => {
  if (!workbook) return false;
  const layout = resolveFormATableHeadersFromWorkbook(workbook, hints);
  return !!(
    layout?.headers?.length >= 3 && !headersLookLikePivotOrWrongFormATable(layout.headers)
  );
};

const buildFormAHeaderFieldSpecs = (existingFields = []) => {
  const fields = Array.isArray(existingFields) ? [...existingFields] : [];
  const hasKey = (key) => fields.some((f) => f.key === key);
  FORM_A_NUMBERED_HEADER_SPECS.forEach((spec) => {
    if (!hasKey(spec.key)) {
      fields.push({ label: spec.label, value: '', key: spec.key });
    }
  });
  return fields;
};

const resolveFormAHeaderFieldLayout = (parsed, workbook, hints = {}) => {
  const formHeader = hints.formHeader || parsed?.formHeader || null;
  const item = hints.item || null;
  const fileName = hints.fileName || hints.formFileName || '';
  const sheetText = hints.sheetText || '';
  const formACtx =
    isFormAMusterRollContext(formHeader) ||
    isFormAMusterRollRowContext(formHeader, item, fileName, sheetText);
  if (!formACtx) return null;
  // Prefer a real employee table from the workbook when present.
  if (workbook && workbookHasFormAMusterEmployeeTable(workbook, { ...hints, formHeader, item, fileName, sheetText })) {
    return null;
  }
  if (
    !sheetTextIndicatesFormAHeaderFields(sheetText) &&
    !isFormAMusterRollContext(formHeader) &&
    !isFormAMusterRollRowContext(formHeader, item, fileName, sheetText)
  ) {
    return null;
  }
  let fields = buildFormAHeaderFieldSpecs(formHeader?.fields || []);
  if (workbook?.SheetNames?.[0]) {
    const worksheet = workbook.Sheets[workbook.SheetNames[0]];
    if (worksheet) {
      const { effectiveSheetCols, getMergedAwareCellText } = buildWorksheetParseHelpers(worksheet);
      const scanTo = Math.max(parsed?.headerRowIndex >= 0 ? parsed.headerRowIndex + 1 : 0, 100);
      fields = enrichFormAHeaderFieldsFromSheet(scanTo, effectiveSheetCols, getMergedAwareCellText, fields);
    }
  }
  // Woman / maternity particulars render in the employee table — keep only establishment header fields.
  fields = fields.filter((f) => isFormAEstablishmentHeaderField(f));
  const headers = resolveFormATableHeaders(parsed?.headers || hints.tableHeaders || null);
  const tableData = Array.from({ length: 5 }, () => {
    const row = {};
    headers.forEach((h) => {
      row[h] = '';
    });
    return row;
  });
  return {
    formHeader: enrichFormADisplayHeader(
      {
        ...(formHeader || {}),
        formAHeaderFieldLayout: true,
        formATableLayout: true,
        fields
      },
      fileName,
      item,
      headers,
      sheetText
    ),
    headers,
    tableData,
    headerRowIndex: -1,
    dataStartIndex: 0,
    tableStartCol: 0
  };
};

const applyFormAHeaderFieldLayoutToParsed = (parsed, workbook, hints = {}) => {
  if (!parsed) return parsed;
  // Already converted to table layout with woman-employee columns.
  if (
    isFormATableLayoutFormHeader(parsed.formHeader) &&
    Array.isArray(parsed.headers) &&
    parsed.headers.length > 0
  ) {
    return parsed;
  }
  const layout = resolveFormAHeaderFieldLayout(parsed, workbook, {
    ...hints,
    formHeader: hints.formHeader || parsed.formHeader,
    tableHeaders: parsed.headers
  });
  if (!layout) return parsed;
  return {
    ...parsed,
    formHeader: layout.formHeader,
    headers: layout.headers,
    tableData: layout.tableData,
    headerRowIndex: layout.headerRowIndex,
    dataStartIndex: layout.dataStartIndex,
    tableStartCol: layout.tableStartCol
  };
};

const writeFormAHeaderFieldsToExcelWorksheet = (worksheet, headerFormData, parsedFormHeader, helpers = {}) => {
  if (!worksheet || !headerFormData || typeof headerFormData !== 'object') return;
  const normalize = (txt) =>
    String(txt || '')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  const excelCellValueToString =
    helpers.excelCellValueToString ||
    ((val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    });
  const maxScanRows = Math.max(120, worksheet.rowCount + 10);
  const maxScanCols = 80;
  const fields = Array.isArray(parsedFormHeader?.fields) ? parsedFormHeader.fields : FORM_A_NUMBERED_HEADER_SPECS.map((spec) => ({
    key: spec.key,
    label: spec.label
  }));
  const writeValueBesideLabel = (row, startCol, label, rawLabel, value) => {
    const text = formatStatutoryHeaderLabelValueExport(label, rawLabel || label, value);
    if (!String(text).trim()) return;
    worksheet.getCell(row, startCol).value = text;
  };
  for (let r = 1; r <= maxScanRows; r += 1) {
    for (let c = 1; c <= maxScanCols; c += 1) {
      const raw = excelCellValueToString(worksheet.getCell(r, c)?.value);
      if (!raw) continue;
      FORM_A_NUMBERED_HEADER_SPECS.forEach((spec) => {
        if (!spec.match.test(raw)) return;
        const val = headerFormData[spec.key];
        if (val == null || String(val).trim() === '') return;
        writeValueBesideLabel(r, c, spec.label, raw, val);
      });
      fields.forEach((field) => {
        const label = String(field?.label || '').trim();
        if (!label) return;
        const labelNorm = normalize(label.replace(/:+$/, ''));
        const rawNorm = normalize(raw.replace(/:+$/, ''));
        if (!rawNorm || !labelNorm) return;
        // Short labels (e.g. Age) must match the cell itself — avoid hitting "woman and age".
        if (labelNorm.length <= 8) {
          if (rawNorm !== labelNorm && !new RegExp(`^${labelNorm}\\s*:?$`, 'i').test(rawNorm)) {
            return;
          }
        } else if (!rawNorm.includes(labelNorm) && !labelNorm.includes(rawNorm)) {
          return;
        }
        const val = headerFormData[field.key];
        if (val == null || String(val).trim() === '') return;
        writeValueBesideLabel(r, c, label, raw, val);
      });
    }
  }
};

const isFormVIFestivalContext = (formHeader, rowItem, fileName, tableHeaders) => {
  const parts = [
    (rowItem?.formName || ''),
    (rowItem?.FormName || ''),
    fileName || '',
    (formHeader?.title || ''),
    (formHeader?.subtitle || ''),
    (formHeader?.reference || ''),
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  const isFormVI = /\bform\s*[-–]?\s*vi\b|\bform\s*6\b/.test(parts);
  if (!isFormVI) return false;
  if (/national/.test(parts) && /festival/.test(parts) && /holidays?/.test(parts)) return true;
  if (/(enter\s+days\s+date|enter\s+days\s+dates|days?\s+dates?\s+and\s+months?|festival\s+holidays?)/.test(parts)) return true;
  return false;
};

const isFormVILegendLine = (text) => {
  const t = String(text || '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!t) return false;
  if (t.includes('#ref!')) return false;
  if (/^to\s+be\s+marked\s+as\s+follows\s*:?\s*$/.test(t)) return true;
  if (/^(h|w\/d|w\/h|n\/e)\s*["']?\s*for\b/.test(t)) return true;
  return false;
};

const FORM_VI_CANONICAL_HOLIDAY_HEADERS = [
  '14-01-2022 ( PONGAL)',
  '26/01/2022 (REPUBLIC DAY)',
  '14/04/2022 (TAMIL NEW YEAR)',
  '15/04/2022 (GOOD FRIDAY)',
  '01/05/2022 (MAY DAY)',
  '03/05/2022 (RAMZAN)',
  '15/08/2022 (INDEPENDENCE DAY)',
  '19/08/2022 (KRISHNA JAYANTHI)',
  '31/08/2022 (VINAYAKAR CHATHURTHI)',
  '04/10/2022 (AYUDHA POOJA)',
  '05/10/2022 (VIJAYA DASHAMI)',
  '24/10/2022 (DIWALI)',
  '25/12/2022 (CHRISTMAS)'
];

const FORM_VI_FESTIVAL_BAND_TITLE =
  'Days, dates and months of the year on which National and Festival Holidays are allowed under the section 3 of the Tamil Nadu Industrial Establishments (National and Festival Holidays) Act, 1958 (Tamil Nadu Act XXXIII of 1958)';

const normalizeFormVIHolidayCellText = (txt) =>
  String(txt || '').replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim();

const isFormVIFestivalBandHeader = (header) => {
  const s = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (!s) return false;
  if (s.includes('enter days date')) return true;
  if (s.includes('enter days dates')) return true;
  if (s.includes('days dates') && s.includes('months')) return true;
  if (s.includes('national') && s.includes('festival') && s.includes('holiday')) return true;
  return /festival\s+holidays?/.test(s);
};

const looksLikeFormVIHolidayLabel = (txt) => {
  const s = normalizeFormVIHolidayCellText(txt).toLowerCase();
  if (!s || isFormVIFestivalBandHeader(s)) return false;
  if (/\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}/.test(s)) return true;
  return /pongal|republic\s+day|tamil\s+new\s+year|good\s+friday|may\s+day|ramzan|independence\s+day|krishna|vinayakar|ayudha|vijaya\s+dashami|diwali|christmas/.test(
    s
  );
};

const isFormVIHolidayColumnHeader = (header) => {
  const s = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (!s || s === 'remark' || s === 'remarks') return false;
  if (isFormVIFestivalBandHeader(s)) return false;
  if (looksLikeFormVIHolidayLabel(s)) return true;
  return false;
};

const isFormVIDojHeader = (header) => {
  const s = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
  return s === 'doj' || s === 'd.o.j' || s === 'd.o.j.' || (s.includes('date') && s.includes('join'));
};

/** Form VI TN: "Employee Code" column ← People EmployeeID. */
const isFormVIEmployeeCodeHeader = (header) => {
  const s = String(header || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (!s) return false;
  if (s.includes('employee') && s.includes('code')) return true;
  if (/\bemp\b/.test(s) && s.includes('code')) return true;
  return false;
};

const getFormVIEmployeeDojDisplay = (emp) => formatStatutoryDateDisplay(getEmployeeDateofjoiningRaw(emp));

const remapFormVIRowsByColumnIndex = (rows, oldHeaders, newHeaders) => {
  if (!Array.isArray(rows)) return [];
  if (!Array.isArray(oldHeaders) || !Array.isArray(newHeaders)) return rows;
  return rows.map((row) => {
    const out = {};
    newHeaders.forEach((nh, idx) => {
      const oh = oldHeaders[idx];
      if (oh && row && Object.prototype.hasOwnProperty.call(row, oh)) out[nh] = row[oh];
      else if (row && Object.prototype.hasOwnProperty.call(row, nh)) out[nh] = row[nh];
      else out[nh] = '';
    });
    return out;
  });
};

const formVIExcelCellValueToString = (val) => {
  if (val == null) return '';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
  if (val instanceof Date) return val.toISOString();
  if (typeof val === 'object') {
    if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
    if (val.text != null) return String(val.text);
    if (val.result != null) return String(val.result);
  }
  return '';
};

const formVIExcelNormalize = (txt) =>
  String(txt || '')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

const formVIHolidayMatchToken = (txt) => {
  const s = formVIExcelNormalize(txt);
  const tokens = [
    'pongal',
    'republic day',
    'tamil new year',
    'good friday',
    'may day',
    'ramzan',
    'independence day',
    'krishna jayanthi',
    'vinayakar chathurthi',
    'ayudha pooja',
    'vijaya dashami',
    'diwali',
    'christmas'
  ];
  const hit = tokens.find((t) => s.includes(t));
  if (hit) return hit;
  const date = s.match(/\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}/);
  return date ? date[0].replace(/\//g, '-') : s;
};

const formVIHolidayLabelsMatch = (appHeader, excelLabel) => {
  const a = formVIHolidayMatchToken(appHeader);
  const e = formVIHolidayMatchToken(excelLabel);
  if (!a || !e) return false;
  if (a === e) return true;
  return a.includes(e) || e.includes(a);
};

const ensureFormVIDownloadRowsHaveDefaults = (rows, headers) => {
  if (!Array.isArray(rows) || !Array.isArray(headers)) return rows;
  return rows.map((row) => {
    const next = { ...(row || {}) };
    headers.forEach((h) => {
      if (isFormVIHolidayColumnHeader(h) && !String(next[h] ?? '').trim()) next[h] = 'H';
    });
    return next;
  });
};

const rebuildFormVIFestivalTableHeadersFromSheet = ({
  jsonData,
  getMergedAwareCellText,
  headerRowIndex,
  headers,
  firstSheetName,
  formHeaderInfo
}) => {
  if (!isFormVIFestivalContext(formHeaderInfo, null, firstSheetName, headers)) return null;
  if (headerRowIndex < 0 || !Array.isArray(headers) || headers.length < 6) return null;

  const normHdr = (h) => String(h || '').toLowerCase().replace(/\s+/g, ' ').trim();
  let festStart = -1;
  let festEnd = -1;
  headers.forEach((h, i) => {
    if (isFormVIHolidayColumnHeader(h)) {
      if (festStart < 0) festStart = i;
      festEnd = i + 1;
    }
  });
  if (festStart < 0) {
    for (let i = 0; i < headers.length; i += 1) {
      if (!isFormVIFestivalBandHeader(headers[i])) continue;
      festStart = i;
      festEnd = headers.length;
      for (let j = i + 1; j < headers.length; j += 1) {
        const n = normHdr(headers[j]);
        if (n === 'remarks' || n === 'remark') {
          festEnd = j;
          break;
        }
      }
      break;
    }
  }
  if (festStart < 0 || festEnd <= festStart) return null;

  const holidayLabels = [];
  for (let col = festStart; col < festEnd; col += 1) {
    let label = '';
    for (let rowOff = -3; rowOff <= 2; rowOff += 1) {
      const r = headerRowIndex + rowOff;
      if (r < 0 || !Array.isArray(jsonData) || r >= jsonData.length) continue;
      const cell = normalizeFormVIHolidayCellText(getMergedAwareCellText(r, col));
      if (looksLikeFormVIHolidayLabel(cell)) {
        label = cell;
        break;
      }
    }
    if (!label) label = FORM_VI_CANONICAL_HOLIDAY_HEADERS[col - festStart] || '';
    holidayLabels.push(label || `Holiday ${col - festStart + 1}`);
  }

  const rebuilt = [...headers.slice(0, festStart), ...holidayLabels, ...headers.slice(festEnd)];
  return { headers: rebuilt, holidayLabels };
};

const isFormBLabourWelfareContext = (formHeader, rowItem, fileName, tableHeaders) => {
  const parts = [
    (rowItem?.formName || ''),
    (rowItem?.FormName || ''),
    fileName || '',
    (formHeader?.title || ''),
    (formHeader?.subtitle || ''),
    (formHeader?.reference || ''),
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  if (
    /\bform\s*["']?\s*b\b/.test(parts) &&
    /labour\s*welfare/.test(parts) &&
    /register\s+of\s+wages/.test(parts)
  ) {
    return true;
  }
  // Form_B_-_TamilNadu.xlsx — monthly LWF summary grid (not per-employee wages).
  if (
    /form[_\s-]*b(?:[_\s-]|$)/i.test(parts) &&
    (/tamil/i.test(parts) || /register\s+of\s+wages/i.test(parts)) &&
    !/form[_\s-]*b[_\s-]*(gj|gujarat|rj|rajasthan)/i.test(parts)
  ) {
    if (
      /total\s+emoluments/i.test(parts) ||
      /total\s+number\s+of\s+empl/i.test(parts) ||
      /amounts?\s+deducted/i.test(parts) ||
      /labour\s*welfare|\blwf\b/i.test(parts) ||
      // Filename alone is enough (headers may not be ready on first Autofill tick).
      /form[_\s-]*b[_\s-]*tamil/i.test(parts)
    ) {
      return true;
    }
  }
  return false;
};

/** TN Form B is a one-row monthly summary (not one row per employee). */
const headersIndicateFormBTamilNaduSummaryTable = (tableHeaders) => {
  if (!Array.isArray(tableHeaders) || tableHeaders.length === 0) return false;
  const joined = tableHeaders.map((h) => String(h || '').toLowerCase()).join('\n');
  if (/\btotal\s+emoluments\b/.test(joined)) return true;
  if (/total\s+number\s+of\s+empl/.test(joined)) return true;
  if (/\bamounts?\s+deducted\b/.test(joined) && /other\s+deductions?/.test(joined)) return true;
  return false;
};

/** Tamil Nadu LWF Form C — quarterly fines / unpaid accumulations grid (not Minimum Wages Form I). */
const isFormCLabourWelfareContext = (formHeader, rowItem, fileName, tableHeaders) => {
  const headers = Array.isArray(tableHeaders) ? tableHeaders : [];
  if (isFixedRowAggregateComplianceTable(headers)) return true;
  const parts = [
    rowItem?.formName || '',
    rowItem?.FormName || '',
    fileName || '',
    formHeader?.title || '',
    formHeader?.subtitle || '',
    formHeader?.reference || '',
    headers.join(' ')
  ]
    .join(' ')
    .toLowerCase();
  if (
    /\bform\s*[-–]?\s*c\b/.test(parts) &&
    (/labou?r\s*welfare/.test(parts) ||
      /unpaid\s+accumulations/.test(parts) ||
      /register\s+of\s+fines\s+and\s+unpaid/.test(parts))
  ) {
    return true;
  }
  const fn = String(fileName || '').toLowerCase();
  if (/form[\s._-]*c[\s._-]*tamil|form_c.*tamilnadu/.test(fn)) return true;
  return false;
};

const isRegisterOfWagesFormContext = (formHeader, rowItem, fileName, tableHeaders) => {
  const parts = [
    (rowItem?.formName || ''),
    (rowItem?.FormName || ''),
    fileName || '',
    (formHeader?.title || ''),
    (formHeader?.subtitle || ''),
    (formHeader?.wagePeriodText || ''),
    Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
  ]
    .join(' ')
    .toLowerCase();
  // Rajasthan Form XIX is Register of Overtime — never use Form W Excel merged thead
  // (template has a leading blank spacer that shifts every header one column right).
  if (
    /form[\s._-]*xix[\s._-]*rj|\bxix_rj\b/i.test(parts) ||
    isFormXIXRajasthanOvertimeRegisterContext(
      formHeader,
      rowItem,
      fileName,
      Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
    )
  ) {
    return false;
  }
  // Karnataka Form Q (employment particulars / appointment order) — not Form W wage register.
  if (
    isFormQKarnatakaContext(
      formHeader,
      rowItem,
      fileName,
      Array.isArray(tableHeaders) ? tableHeaders.join(' ') : ''
    )
  ) {
    return false;
  }
  // Maharashtra Form Q (muster-roll cum wage register attendance grid) — dedicated column map.
  if (
    isFormQContext(
      formHeader,
      rowItem,
      fileName,
      tableHeaders
    )
  ) {
    return false;
  }
  // Form 10 / m_10 (Overtime Muster Roll) — "Number in Register" triggers `register` + wage heuristics; never use Form W thead.
  if (
    /\bform\s*no\.?\s*10\b|\bform\s+10\b|m_?10\.xlsx|m_?10|overtime\s*muster|muster\s*roll.*exempted|rule\s*78.*form\s*10/.test(
      parts
    ) &&
    !/\bform\s*w\b|form-w|form_w|register\s+of\s+wages/i.test(parts)
  ) {
    return false;
  }
  // Form B (Tamil Nadu LWF Register of Wages) should not use Form W wage-period/thead behaviors.
  if (isFormBLabourWelfareContext(formHeader, rowItem, fileName, tableHeaders)) return false;
  // Gujarat Form B wage register — dedicated Sample Payroll mapper (not Form W PF heuristics).
  if (isFormBGJGujaratContext(formHeader, rowItem, fileName, '', tableHeaders)) return false;
  // Karnataka Form F / Form H leave registers — dedicated thead, not Form W merge bands.
  if (isFormFLeaveWithWagesContext(formHeader, rowItem, fileName, parts)) return false;
  if (isFormHLeaveBookContext(formHeader, rowItem, fileName)) return false;
  // Form X (leave register) must not use Form W wage-register table header logic.
  if (/\bform[_\s-]*x\b|\bform-x\b|form_x/.test(parts)) return false;
  if (/register\s+of\s+advances?\s+of\s+wages/i.test(parts)) return false;
  if (/\bform\s*xxiii\b|\bform_xxiii\b|\bform-xxiii\b/i.test(parts)) {
    if (/register\s+of\s+overtime|overtime\s+register/i.test(parts)) return false;
    if (isApShopsRegisterOfWagesTableHeaders(tableHeaders)) return true;
    if (/normal\s+rate\s+of\s+wage/.test(parts) && /overtime\s+rate\s+of\s+wage/.test(parts)) {
      return false;
    }
    return true;
  }
  if (isForm15Part2Context(formHeader, rowItem, fileName, tableHeaders)) return true;
  if (parts.includes('form w') || parts.includes('form-w') || parts.includes('form_w')) return true;
  if (
    matchesFormXXVIIHint(parts) &&
    !isFormXXVIIQuarterlyReturnsContext(formHeader, rowItem, fileName, tableHeaders, parts)
  ) {
    return true;
  }
  if (parts.includes('register') && /\bwages?\b/.test(parts) && !/advance/.test(parts)) return true;
  if (/wage\s*period/.test(parts) && /\bwages?\b/.test(parts)) return true;
  return false;
};

/**
 * Pick wage-register table header rows immediately above the first data row. Skips a leading
 * "Wage Period …" row, optional column-number row, and expands upward through merged bands
 * (e.g. Form XXVII "Wages Earned", "Deductions", nested "Other").
 */
const adjustRegisterOfWagesHeaderBand = (
  worksheet,
  dataStartIndex,
  numCols,
  originalHeaderRowIndex,
  startCol = 0
) => {
  const ds = dataStartIndex;
  if (ds == null || ds < 1 || !worksheet || numCols < 1) return null;
  const col0 = Math.max(0, Number(startCol) || 0);
  const merges = worksheet['!merges'] || [];
  const rawCell = (r, c) => {
    if (r < 0 || c < 0) return '';
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };
  const mergedAwareExcel = (r, c) => {
    const d = rawCell(r, c);
    if (d) return d;
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        const t = rawCell(m.s.r, m.s.c);
        if (t) return t;
      }
    }
    return '';
  };
  const mergedAware = (r, logicalC) => mergedAwareExcel(r, col0 + logicalC);
  const rowLooksLikeWagePeriod = (r) => {
    let acc = '';
    const lim = Math.min(numCols, 40);
    for (let c = 0; c < lim; c++) acc += ` ${mergedAware(r, c)}`;
    return /wage\s*period/i.test(acc);
  };
  const rowLooksLikeColumnNumbers = (r) => {
    let hits = 0;
    let total = 0;
    const lim = Math.min(numCols, 40);
    for (let c = 0; c < lim; c++) {
      const t = String(mergedAware(r, c) || '').replace(/\s+/g, '').trim();
      if (!t) continue;
      total += 1;
      if (/^\d+$/.test(t)) hits += 1;
    }
    return total >= 5 && hits >= Math.max(4, Math.floor(total * 0.7));
  };
  const rowHeaderBlob = (r) => {
    const parts = [];
    const lim = Math.min(numCols, 40);
    for (let c = 0; c < lim; c++) {
      const t = String(mergedAware(r, c) || '').trim();
      if (t) parts.push(t);
    }
    return parts.join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
  };
  const rowHasWageRegisterHeaderSignal = (r) => {
    if (rowLooksLikeWagePeriod(r) || rowLooksLikeColumnNumbers(r)) return false;
    const blob = rowHeaderBlob(r);
    if (!blob) return false;
    return (
      /wages?\s*earned|deductions?|gross\s*wages?|net\s*wages?|provident|allowance|serial|s\.?\s*no|sl\.?\s*no/.test(blob) ||
      /rate\s+of\s+wages?|date\s+of\s+appoint|actual\s+wages?|date\s+of\s+pay|normal\s+wages?/.test(blob) ||
      /daily\s+attendance|units\s+of\s+work|muster\s+roll|register\s+of\s+workmen/.test(blob) ||
      blob.includes('other allowances') ||
      blob.includes('fines') ||
      blob.includes('advance paid') ||
      blob.includes('advances') ||
      blob.includes('labour welfare') ||
      (blob.includes('damage') && blob.includes('fine'))
    );
  };
  const rowConnectsToHeaderBand = (r, bandBottom) => {
    if (r < 0 || r > bandBottom) return false;
    if (rowHasWageRegisterHeaderSignal(r)) return true;
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m?.s || !m?.e) continue;
      if (m.s.c >= col0 + numCols) continue;
      const spansBand = m.s.r <= r && m.e.r >= bandBottom;
      const touchesRow = m.s.r <= r && m.e.r >= r;
      if (!touchesRow) continue;
      const val = rawCell(m.s.r, m.s.c).toLowerCase();
      if (
        spansBand ||
        /wages?\s*earned|deductions?|other\s+allowance|gross\s*wages?|net\s*wages?|advances?|damages\s*\/\s*fine|labour\s*welfare/.test(val)
      ) {
        return true;
      }
    }
    return false;
  };

  let r1 = ds - 1;
  while (r1 >= 0 && rowLooksLikeColumnNumbers(r1)) r1 -= 1;
  if (r1 < 0) return null;

  let r0 =
    originalHeaderRowIndex != null && originalHeaderRowIndex >= 0
      ? Math.min(originalHeaderRowIndex, r1)
      : Math.max(0, r1 - 2);
  while (r0 < r1 && rowLooksLikeWagePeriod(r0)) r0 += 1;

  while (r0 > 0 && rowConnectsToHeaderBand(r0 - 1, r1)) {
    r0 -= 1;
    while (r0 > 0 && rowLooksLikeWagePeriod(r0 - 1)) break;
  }

  while (r1 - r0 < 2 && r0 > 0 && !rowLooksLikeWagePeriod(r0 - 1) && rowConnectsToHeaderBand(r0 - 1, r1)) {
    r0 -= 1;
  }

  if (r0 > r1) return null;
  return { r0, r1 };
};

/** Map modal/register-of-wages headers to exact Excel column indices (merged header bands). */
function buildRegisterOfWagesHeaderColumnMap(
  worksheet,
  dataStartIndex,
  headersToUse,
  originalHeaderRowIndex,
  options = {}
) {
  const allowFallback = options?.allowFallback !== false;
  const map = new Map();
  if (!worksheet || !Array.isArray(headersToUse) || headersToUse.length === 0) return map;
  const numCols = Math.max(headersToUse.length + 8, 24);
  const band = adjustRegisterOfWagesHeaderBand(
    worksheet,
    dataStartIndex,
    numCols,
    originalHeaderRowIndex
  );
  if (!band) return map;
  const merges = worksheet['!merges'] || [];
  const rawCell = (r, c) => {
    if (r < 0 || c < 0) return '';
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };
  const mergedAware = (r, c) => {
    const d = rawCell(r, c);
    if (d) return d;
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        const t = rawCell(m.s.r, m.s.c);
        if (t) return t;
      }
    }
    return '';
  };
  const norm = (txt) =>
    String(txt || '')
      .replace(/\r?\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, '');
  const formWAliasBucket = (n) => {
    if (!n) return '';
    // Form XVIII "SL.No.in register of workmen" must not alias to plain Sl No.
    if (/register/.test(n) && /(workmen|workman)/.test(n) && /(sl\s*no|s\s*no|serial)/.test(n)) {
      return 'registersno';
    }
    if (
      /^(s\s*no|sl\s*no|serial\s*no|serial)(\s|$)/.test(n) ||
      /^(s\s*no|sl\s*no|serial\s*no|serial)$/.test(n)
    ) {
      return 'sno';
    }
    if (/name/.test(n) && /(employee|worker|emp)/.test(n)) return 'name';
    if (/identification|employee id|emp id|worker id|employee number/.test(n)) return 'empid';
    if (/number of days|no of days|days worked/.test(n)) return 'days';
    if (/basic/.test(n) && /wage|wag/.test(n)) return 'basic';
    if (/dearness/.test(n)) return 'da';
    if (/house rent|home rent|\bhra\b/.test(n)) return 'hra';
    if (/other allowance/.test(n)) return 'otherallow';
    if (/overtime/.test(n) && /(el\b|festival|accumulated|national)/.test(n)) return 'otel';
    if (/overtime/.test(n)) return 'ot';
    if (/gross/.test(n) && /wage|wag/.test(n)) return 'gross';
    if (/net/.test(n) && /wage|wag/.test(n)) return 'net';
    if (/provident/.test(n) && /\bno\b|number|a\/c|account/.test(n)) return 'pfno';
    if (/provident|\bpf\b/.test(n)) return 'pf';
    if (/(esi|esic)/.test(n) && /\bno\b|number|corporation/.test(n)) return 'esino';
    if (/employee.?s? state insurance|\besi\b|esic/.test(n)) return 'esi';
    if (/labour welfare/.test(n)) return 'lwf';
    if (/total/.test(n) && /deduction/.test(n)) return 'totalded';
    if (/^deductions?$/.test(n)) return 'totalded';
    if (/date of pay/.test(n)) return 'dop';
    if (/advance paid/.test(n)) return 'advpaid';
    if (/advance recover/.test(n) && /begin/.test(n)) return 'advbegin';
    if (/advance recover/.test(n) && !/pending|begin/.test(n)) return 'advrec';
    if (/pending recover/.test(n) && /advance/.test(n)) return 'advpend';
    if (/damage|fine/.test(n) && /impos/.test(n)) return 'fineimpos';
    if (/damage|fine/.test(n) && /recover/.test(n) && !/pending/.test(n)) return 'finerec';
    if (/damage|fine/.test(n) && /made on|date/.test(n)) return 'finedate';
    if (/damage|fine/.test(n) && /pending/.test(n)) return 'finepend';
    return n;
  };
  const splitHeaderKey = (header) => {
    const h = String(header || '');
    const idx = h.indexOf('_');
    if (idx <= 0) return { main: h, sub: '' };
    return { main: h.slice(0, idx), sub: h.slice(idx + 1) };
  };
  const colKeys = [];
  const maxScanCols = Math.max(numCols, headersToUse.length + 6, 40);
  for (let c = 0; c < maxScanCols; c++) {
    const leaf = mergedAware(band.r1, c);
    let parent = '';
    for (let r = band.r0; r < band.r1; r++) {
      const pt = mergedAware(r, c);
      if (pt && norm(pt) !== norm(leaf)) {
        parent = pt;
        break;
      }
    }
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m?.s || !m?.e) continue;
      if (m.s.c <= c && m.e.c >= c && m.s.r <= band.r0 && m.e.r >= band.r1 - 1) {
        const pt = rawCell(m.s.r, m.s.c);
        if (pt && norm(pt) !== norm(leaf)) parent = pt;
      }
    }
    const leafNorm = norm(leaf);
    const parentNorm = norm(parent);
    const combinedNorm = parentNorm && leafNorm && parentNorm !== leafNorm
      ? norm(`${parent}_${leaf}`)
      : leafNorm;
    if (!leafNorm && c >= headersToUse.length + 2) break;
    colKeys.push({
      c,
      leafNorm,
      parentNorm,
      combinedNorm,
      leafAlias: formWAliasBucket(leafNorm),
      combinedAlias: formWAliasBucket(combinedNorm)
    });
  }
  const usedCols = new Set();
  headersToUse.forEach((header) => {
    const hNorm = norm(header);
    const hAlias = formWAliasBucket(hNorm);
    const { main, sub } = splitHeaderKey(header);
    const mainNorm = norm(main);
    const subNorm = norm(sub);
    let best = null;
    let bestScore = 0;
    for (const ck of colKeys) {
      if (usedCols.has(ck.c)) continue;
      let score = 0;
      if (hNorm && ck.combinedNorm && hNorm === ck.combinedNorm) score = 4000;
      else if (mainNorm && subNorm && mainNorm === ck.parentNorm && subNorm === ck.leafNorm) score = 3500;
      else if (hNorm && ck.leafNorm && hNorm === ck.leafNorm) score = 3000;
      else if (mainNorm && !subNorm && mainNorm === ck.leafNorm) score = 2500;
      else if (hAlias && ck.leafAlias && hAlias === ck.leafAlias && hAlias !== ck.leafNorm) score = 2200;
      else if (hAlias && ck.combinedAlias && hAlias === ck.combinedAlias && hAlias !== hNorm) score = 2100;
      // Intentionally no loose includes() score — that shifted Form W Basic/Net/PF into wrong Excel columns.
      if (score > bestScore) {
        bestScore = score;
        best = ck;
      }
    }
    if (best && bestScore > 0) {
      map.set(header, best.c);
      usedCols.add(best.c);
    }
  });
  const mappedCols = [...map.values()];
  if (allowFallback) {
    let fallbackCol = mappedCols.length > 0 ? Math.min(...mappedCols) : 0;
    headersToUse.forEach((header) => {
      if (map.has(header)) return;
      while (usedCols.has(fallbackCol)) fallbackCol += 1;
      map.set(header, fallbackCol);
      usedCols.add(fallbackCol);
      fallbackCol += 1;
    });
  }
  return map;
}

/** AP CLRA Form XXIII overtime register — sequential columns from S.No., data below index row. */
function buildApClraOvertimeRegisterExcelLayout(
  worksheet,
  headersToUse,
  leafHeaderRowIndex,
  dataStartIndexHint,
  originalHeaderRowIndex
) {
  const layout = {
    dataStartRow: Number.isFinite(dataStartIndexHint) && dataStartIndexHint >= 0 ? dataStartIndexHint : 6,
    tableStartCol: 0,
    headerToCol: new Map()
  };
  if (!worksheet || !Array.isArray(headersToUse) || headersToUse.length === 0) return layout;

  const merges = worksheet['!merges'] || [];
  const rawCell = (r, c) => {
    if (r < 0 || c < 0) return '';
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };
  const mergedAware = (r, c) => {
    const d = rawCell(r, c);
    if (d) return d;
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m?.s || !m?.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        const t = rawCell(m.s.r, m.s.c);
        if (t) return t;
      }
    }
    return '';
  };

  let snoRow = -1;
  let snoCol = 0;
  for (let r = 0; r < 45; r += 1) {
    for (let c = 0; c < 20; c += 1) {
      const t = normalizeWageRegisterHeaderCell(mergedAware(r, c));
      if (excelCellLooksLikeSerialHeader(t) || isWageRegisterSerialHeaderCell(t)) {
        snoRow = r;
        snoCol = c;
        break;
      }
    }
    if (snoRow >= 0) break;
  }
  if (snoRow < 0) return layout;

  layout.tableStartCol = snoCol;
  const bandEnd = Math.max(
    snoRow,
    Number.isFinite(leafHeaderRowIndex) && leafHeaderRowIndex >= 0 ? leafHeaderRowIndex : snoRow,
    Number.isFinite(originalHeaderRowIndex) && originalHeaderRowIndex >= 0 ? originalHeaderRowIndex : snoRow
  );

  let dataStartRow = bandEnd + 1;
  for (let probe = bandEnd + 1; probe <= bandEnd + 4 && probe < 55; probe += 1) {
    let seqHits = 0;
    for (let j = 0; j < headersToUse.length; j += 1) {
      const t = String(mergedAware(probe, snoCol + j) || '').replace(/\s+/g, '').trim();
      if (t === String(j + 1)) seqHits += 1;
    }
    if (seqHits >= Math.max(4, Math.floor(headersToUse.length * 0.45))) {
      dataStartRow = probe + 1;
      break;
    }
  }
  if (Number.isFinite(dataStartIndexHint) && dataStartIndexHint >= 0) {
    dataStartRow = Math.max(dataStartRow, dataStartIndexHint);
  }
  layout.dataStartRow = dataStartRow;
  layout.snoRow = snoRow;
  layout.tableHeaderStartRow1 = snoRow + 1;
  headersToUse.forEach((header, j) => {
    layout.headerToCol.set(header, snoCol + j);
  });
  return layout;
}

/** ExcelJS fallback when SheetJS sheet is missing (MP single-sheet overtime templates). */
function buildApClraOvertimeRegisterExcelLayoutFromExcelJs(
  worksheet,
  headersToUse,
  leafHeaderRowIndex,
  dataStartIndexHint,
  originalHeaderRowIndex
) {
  const layout = {
    dataStartRow: Number.isFinite(dataStartIndexHint) && dataStartIndexHint >= 0 ? dataStartIndexHint : 6,
    tableStartCol: 0,
    headerToCol: new Map(),
    snoRow: -1,
    tableHeaderStartRow1: null,
  };
  if (!worksheet || !Array.isArray(headersToUse) || headersToUse.length === 0) return layout;

  const cellText = (r1, c1) => excelJsCellText(worksheet.getCell(r1, c1)?.value).trim();

  let snoRow1 = -1;
  let snoCol1 = 1;
  for (let r = 1; r <= 45; r += 1) {
    for (let c = 1; c <= 20; c += 1) {
      const t = normalizeWageRegisterHeaderCell(cellText(r, c));
      if (excelCellLooksLikeSerialHeader(t) || isWageRegisterSerialHeaderCell(t)) {
        snoRow1 = r;
        snoCol1 = c;
        break;
      }
    }
    if (snoRow1 >= 0) break;
  }
  if (snoRow1 < 0) return layout;

  layout.snoRow = snoRow1 - 1;
  layout.tableStartCol = snoCol1 - 1;
  const bandEnd1 = Math.max(
    snoRow1,
    Number.isFinite(leafHeaderRowIndex) && leafHeaderRowIndex >= 0 ? leafHeaderRowIndex + 1 : snoRow1,
    Number.isFinite(originalHeaderRowIndex) && originalHeaderRowIndex >= 0 ? originalHeaderRowIndex + 1 : snoRow1
  );

  let dataStartRow1 = bandEnd1 + 1;
  for (let probe = bandEnd1 + 1; probe <= bandEnd1 + 4 && probe < 55; probe += 1) {
    let seqHits = 0;
    for (let j = 0; j < headersToUse.length; j += 1) {
      const t = String(cellText(probe, snoCol1 + j) || '').replace(/\s+/g, '').trim();
      if (t === String(j + 1)) seqHits += 1;
    }
    if (seqHits >= Math.max(4, Math.floor(headersToUse.length * 0.45))) {
      dataStartRow1 = probe + 1;
      break;
    }
  }
  if (Number.isFinite(dataStartIndexHint) && dataStartIndexHint >= 0) {
    dataStartRow1 = Math.max(dataStartRow1, dataStartIndexHint + 1);
  }
  layout.dataStartRow = dataStartRow1 - 1;
  layout.tableHeaderStartRow1 = snoRow1;
  headersToUse.forEach((header, j) => {
    layout.headerToCol.set(header, snoCol1 - 1 + j);
  });
  return layout;
}

/** AP Shops Form XXIII: map each parsed header to the exact Excel column from merged header bands. */
function buildApShopsRegisterOfWagesExcelLayout(
  worksheet,
  headersToUse,
  originalHeaderRowIndex,
  leafHeaderRowIndex,
  dataStartIndexHint
) {
  const layout = {
    dataStartRow: Number.isFinite(dataStartIndexHint) && dataStartIndexHint >= 0 ? dataStartIndexHint : 6,
    tableStartCol: 0,
    headerToCol: new Map()
  };
  if (!worksheet || !Array.isArray(headersToUse) || headersToUse.length === 0) return layout;

  const merges = worksheet['!merges'] || [];
  const rawCell = (r, c) => {
    if (r < 0 || c < 0) return '';
    const ref = XLSX.utils.encode_cell({ r, c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };
  const mergedAware = (r, c) => {
    const d = rawCell(r, c);
    if (d) return d;
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m?.s || !m?.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
        const t = rawCell(m.s.r, m.s.c);
        if (t) return t;
      }
    }
    return '';
  };

  let snoRow = -1;
  let snoCol = 0;
  for (let r = 0; r < 45; r += 1) {
    for (let c = 0; c < 25; c += 1) {
      const t = normalizeWageRegisterHeaderCell(mergedAware(r, c));
      if (isWageRegisterSerialHeaderCell(t)) {
        snoRow = r;
        snoCol = c;
        break;
      }
    }
    if (snoRow >= 0) break;
  }
  if (snoRow < 0) return layout;

  layout.tableStartCol = snoCol;
  const band = adjustRegisterOfWagesHeaderBand(
    worksheet,
    Math.max(snoRow + 2, layout.dataStartRow),
    Math.max(headersToUse.length + 8, 20),
    Number.isFinite(originalHeaderRowIndex) && originalHeaderRowIndex >= 0
      ? originalHeaderRowIndex
      : snoRow
  );
  const r0 = band?.r0 ?? snoRow;
  const r1 = band?.r1 ?? Math.max(snoRow, leafHeaderRowIndex >= 0 ? leafHeaderRowIndex : snoRow);
  layout.dataStartRow = r1 + 1;

  const norm = (txt) => normalizeWageRegisterExportHeader(txt);
  const splitHeaderKey = (header) => {
    const h = String(header || '');
    const idx = h.indexOf('_');
    if (idx <= 0) return { main: h, sub: '' };
    return { main: h.slice(0, idx), sub: h.slice(idx + 1) };
  };

  const colMeta = [];
  const maxScanCol = Math.max(snoCol + headersToUse.length + 4, snoCol + 16);
  for (let c = snoCol; c <= maxScanCol; c += 1) {
    const parts = [];
    for (let r = r0; r <= r1; r += 1) {
      const t = String(mergedAware(r, c) || '').trim();
      if (!t || isWageRegisterParentBannerText(t) || /^\d+$/.test(t)) continue;
      if (!parts.includes(t)) parts.push(t);
    }
    if (parts.length === 0 && c > snoCol + headersToUse.length + 2) break;
    const leaf = parts[parts.length - 1] || '';
    const parent = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
    colMeta.push({ c, leaf, parent, full: parts.join(' ') });
  }

  const usedCols = new Set();
  colMeta.forEach((cm) => {
    if (!norm(cm.leaf)) usedCols.add(cm.c);
  });
  const scoreHeaderColumn = (header, cm) => {
    const nh = norm(header);
    const nl = norm(cm.leaf);
    const np = norm(cm.parent);
    const nf = norm(cm.full);
    const { main, sub } = splitHeaderKey(header);
    const mainNorm = norm(main);
    const subNorm = norm(sub);
    if (nh && nh === nl) return 4000;
    if (mainNorm && subNorm && mainNorm === np && subNorm === nl) return 3800;
    if (nh && nf && nh === nf) return 3600;
    if (mainNorm && !subNorm && mainNorm === nl) return 3200;
    // Keep "Wages Earned" / "Wages Earned for Overtime" / "Normal…" on distinct columns.
    if (/overtime/.test(nh) && nl === 'wages earned') return 0;
    if (nh === 'wages earned' && /overtime/.test(nl)) return 0;
    if (/overtime/.test(nh) && /overtime/.test(nl) && /wage|earned/.test(nl)) return 4200;
    if (nh === 'wages earned' && nl === 'wages earned') return 4100;
    if (nh === 'normal wages earned' && nl.includes('normal') && nl.includes('earned')) return 4100;
    if (/amount/.test(nh) && /amount/.test(nl) && /deduction/.test(np)) return 3400;
    if (/reason/.test(nh) && /reason/.test(nl)) return 3300;
    if (/remark/.test(nh) && /remark/.test(nl)) return 3100;
    if (nh && nl && (nh.includes(nl) || nl.includes(nh))) return 900;
    if (nh && nf && (nh.includes(nf) || nf.includes(nh))) return 850;
    if (nh.includes('basic') && nh.includes('wage') && nl.includes('basic') && (nl.includes('wage') || nl.includes('wages'))) {
      return 4050;
    }
    if (
      nh.includes('total') &&
      nh.includes('deduction') &&
      nl.includes('total') &&
      nl.includes('deduction')
    ) {
      return 4050;
    }
    if (nh.includes('net') && nh.includes('paid') && nl.includes('net') && nl.includes('paid')) {
      return 4050;
    }
    if ((nh.includes('day') || nh.includes('days')) && nh.includes('work') && nl.includes('work')) {
      return 4040;
    }
    if (
      (nh === 'total' || (nh.includes('total') && !nh.includes('deduction') && !nh.includes('net'))) &&
      (nl.includes('other') || nl.includes('cash') || nl.includes('overtime') || nl === 'seva' || nl === 'esi' || nl === 'pf' || nl === 'pt')
    ) {
      return 0;
    }
    if (nh.includes('total') && nh.includes('deduction') && (nl === 'seva' || nl === 'esi' || nl === 'pf' || nl === 'pt')) {
      return 0;
    }
    if (nh.includes('net') && nh.includes('paid') && nl.includes('total') && nl.includes('deduction') && !nl.includes('net')) {
      return 0;
    }
    if (nh === 'total' && nl === 'total' && !np.includes('deduction')) return 4030;
    return 0;
  };

  headersToUse.forEach((header) => {
    let best = null;
    let bestScore = 0;
    colMeta.forEach((cm) => {
      if (usedCols.has(cm.c)) return;
      const score = scoreHeaderColumn(header, cm);
      if (score > bestScore) {
        bestScore = score;
        best = cm.c;
      }
    });
    if (best != null && bestScore > 0) {
      layout.headerToCol.set(header, best);
      usedCols.add(best);
    }
  });

  // Never invent columns past the template header band (that spilled Rate/Net into col S
  // and painted empty bordered columns N–R, which also corrupted Excel merges → [Repaired]).
  const templateCols = colMeta.filter((cm) => norm(cm.leaf) || norm(cm.parent)).map((cm) => cm.c);
  layout.templateLastCol =
    templateCols.length > 0 ? Math.max(...templateCols) : snoCol + Math.max(headersToUse.length - 1, 0);
  layout.templateFirstCol = snoCol;

  return layout;
}

/** AP multi-tab templates: export only the target worksheet (e.g. Form XXIII), not Form XII. */
function cloneWorkbookSingleSheet(workbook, sheetName) {
  const names = Array.isArray(workbook?.SheetNames) ? workbook.SheetNames : [];
  if (names.length <= 1) return workbook;
  const keep = resolveWorkbookSheetByHint(workbook, sheetName) || names[0];
  if (!keep || !workbook.Sheets?.[keep]) return workbook;
  const single = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(single, workbook.Sheets[keep], keep);
  return single;
}

/**
 * Build up to three <tr> rows for Register of Wages / Form W table headers, using the same
 * rowspan/colspan merges as the Excel sheet (Deductions band, Advances, etc.).
 */
const buildRegisterOfWagesHeaderRows = (worksheet, r0, r1, numCols, startCol = 0) => {
  if (!worksheet || numCols < 1 || r1 < r0) return null;
  const col0 = Math.max(0, Number(startCol) || 0);
  const merges = worksheet['!merges'] || [];

  const getActiveMerge = (r, c) => {
    for (let i = 0; i < merges.length; i++) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) return m;
    }
    return { s: { r, c }, e: { r, c } };
  };

  const getTopLeftValue = (m) => {
    const ref = XLSX.utils.encode_cell({ r: m.s.r, c: m.s.c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };

  const bandRows = r1 - r0 + 1;
  const skipped = Array.from({ length: bandRows }, () => Array(numCols).fill(false));
  const trs = [];

  const thStyle = {
    backgroundColor: STAT_FORM_FILE_ACCENT_BG,
    color: 'white',
    padding: '8px 6px',
    textAlign: 'center',
    fontWeight: '600',
    fontSize: '11px',
    lineHeight: 1.25,
    border: `1px solid ${STAT_FORM_FILE_ACCENT_BORDER}`,
    verticalAlign: 'middle',
    whiteSpace: 'normal',
    wordBreak: 'break-word',
    minWidth: '72px'
  };

  for (let r = r0; r <= r1; r++) {
    const rr = r - r0;
    const tds = [];
    for (let c = 0; c < numCols; c++) {
      if (skipped[rr][c]) continue;
      const excelC = col0 + c;
      const m = getActiveMerge(r, excelC);
      const intersectSr = Math.max(m.s.r, r0);
      const intersectSc = Math.max(m.s.c, col0);
      let intersectEr = Math.min(m.e.r, r1);
      const intersectEc = Math.min(m.e.c, col0 + numCols - 1);
      if (intersectSr > intersectEr || intersectSc > intersectEc) {
        tds.push(
          <th key={`h-${r}-${c}-e`} style={thStyle} rowSpan={1} colSpan={1}>
            {'\u00a0'}
          </th>
        );
        skipped[rr][c] = true;
        continue;
      }
      if (r !== intersectSr || excelC !== intersectSc) continue;
      let rowspan = intersectEr - intersectSr + 1;
      const colspan = intersectEc - intersectSc + 1;
      const label = getTopLeftValue(m);
      const normHdr = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
      if (rowspan === 1 && colspan === 1 && r < r1 && label) {
        const belowRef = XLSX.utils.encode_cell({ r: r + 1, c: excelC });
        const belowCell = worksheet[belowRef];
        const below = belowCell && belowCell.v != null ? String(belowCell.v).trim() : '';
        if (below && normHdr(label) === normHdr(below)) {
          rowspan = 2;
          intersectEr = r + 1;
        }
      }
      tds.push(
        <th key={`h-${intersectSr}-${intersectSc}`} rowSpan={rowspan} colSpan={colspan} style={thStyle}>
          {label || '\u00a0'}
        </th>
      );
      for (let mr = intersectSr; mr <= intersectEr; mr++) {
        for (let mc = intersectSc; mc <= intersectEc; mc++) {
          const logicalMc = mc - col0;
          if (mr >= r0 && mr <= r1 && logicalMc >= 0 && logicalMc < numCols) {
            skipped[mr - r0][logicalMc] = true;
          }
        }
      }
    }
    trs.push(<tr key={`head-row-${r}`}>{tds}</tr>);
  }
  return trs.length ? trs : null;
};

/**
 * Register-of-wages thead when display columns skip template cols (e.g. Form T April hides day 31).
 * Each logical column maps to an absolute Excel column index.
 */
const buildRegisterOfWagesHeaderRowsMapped = (worksheet, r0, r1, excelColIndices) => {
  if (!worksheet || !Array.isArray(excelColIndices) || excelColIndices.length < 1 || r1 < r0) {
    return null;
  }
  const numCols = excelColIndices.length;
  const merges = worksheet['!merges'] || [];

  const getActiveMerge = (r, excelC) => {
    for (let i = 0; i < merges.length; i += 1) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && excelC >= m.s.c && excelC <= m.e.c) return m;
    }
    return { s: { r, c: excelC }, e: { r, c: excelC } };
  };

  const getTopLeftValue = (m) => {
    const ref = XLSX.utils.encode_cell({ r: m.s.r, c: m.s.c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };

  const logicalColsInMerge = (m) => {
    const out = [];
    for (let lc = 0; lc < numCols; lc += 1) {
      const ec = excelColIndices[lc];
      if (ec >= m.s.c && ec <= m.e.c) out.push(lc);
    }
    return out;
  };

  const bandRows = r1 - r0 + 1;
  const skipped = Array.from({ length: bandRows }, () => Array(numCols).fill(false));
  const trs = [];

  const thStyle = {
    backgroundColor: STAT_FORM_FILE_ACCENT_BG,
    color: 'white',
    padding: '8px 6px',
    textAlign: 'center',
    fontWeight: '600',
    fontSize: '11px',
    lineHeight: 1.25,
    border: `1px solid ${STAT_FORM_FILE_ACCENT_BORDER}`,
    verticalAlign: 'middle',
    whiteSpace: 'normal',
    wordBreak: 'break-word',
    minWidth: '72px'
  };

  for (let r = r0; r <= r1; r += 1) {
    const rr = r - r0;
    const tds = [];
    for (let lc = 0; lc < numCols; lc += 1) {
      if (skipped[rr][lc]) continue;
      const excelC = excelColIndices[lc];
      const m = getActiveMerge(r, excelC);
      if (r !== m.s.r || excelC !== m.s.c) {
        skipped[rr][lc] = true;
        continue;
      }
      const intersectSr = Math.max(m.s.r, r0);
      let intersectEr = Math.min(m.e.r, r1);
      const touched = logicalColsInMerge(m);
      if (!touched.length) {
        skipped[rr][lc] = true;
        continue;
      }
      const colspan = touched.length;
      const label = getTopLeftValue(m);
      const normHdr = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
      let rowspan = intersectEr - intersectSr + 1;
      if (rowspan === 1 && colspan === 1 && r < r1 && label) {
        const belowRef = XLSX.utils.encode_cell({ r: r + 1, c: excelC });
        const belowCell = worksheet[belowRef];
        const below = belowCell && belowCell.v != null ? String(belowCell.v).trim() : '';
        if (below && normHdr(label) === normHdr(below)) {
          rowspan = 2;
          intersectEr = r + 1;
        }
      }
      tds.push(
        <th key={`h-mapped-${intersectSr}-${excelC}`} rowSpan={rowspan} colSpan={colspan} style={thStyle}>
          {label || '\u00a0'}
        </th>
      );
      for (let mr = intersectSr; mr <= intersectEr; mr += 1) {
        logicalColsInMerge(m).forEach((logicalMc) => {
          if (mr >= r0 && mr <= r1 && logicalMc >= 0 && logicalMc < numCols) {
            skipped[mr - r0][logicalMc] = true;
          }
        });
      }
    }
    trs.push(<tr key={`head-row-mapped-${r}`}>{tds}</tr>);
  }
  return trs.length ? trs : null;
};

const buildMergedWorksheetHeaderRows = (worksheet, r0, r1, numCols, startCol = 0) => {
  if (!worksheet || numCols < 1 || r1 < r0) return null;
  const merges = worksheet['!merges'] || [];
  const col0 = Math.max(0, Number(startCol) || 0);

  const getActiveMerge = (r, c) => {
    for (let i = 0; i < merges.length; i += 1) {
      const m = merges[i];
      if (!m || !m.s || !m.e) continue;
      if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) return m;
    }
    return { s: { r, c }, e: { r, c } };
  };

  const getTopLeftValue = (m) => {
    const ref = XLSX.utils.encode_cell({ r: m.s.r, c: m.s.c });
    const cell = worksheet[ref];
    if (cell && cell.v != null) return String(cell.v).trim();
    return '';
  };

  const bandRows = r1 - r0 + 1;
  const skipped = Array.from({ length: bandRows }, () => Array(numCols).fill(false));
  const trs = [];
  const thStyle = {
    backgroundColor: STAT_FORM_FILE_ACCENT_BG,
    color: 'white',
    padding: '10px 12px',
    textAlign: 'center',
    fontWeight: '700',
    fontSize: '13px',
    border: `1px solid ${STAT_FORM_FILE_ACCENT_BORDER}`,
    verticalAlign: 'middle',
    whiteSpace: 'normal',
    lineHeight: 1.35
  };

  for (let rr = 0; rr < bandRows; rr += 1) {
    const actualR = r0 + rr;
    const cells = [];
    let hasAny = false;
    for (let i = 0; i < numCols; i += 1) {
      if (skipped[rr][i]) continue;
      const excelCol = col0 + i;
      const m = getActiveMerge(actualR, excelCol);
      const top = m.s.r - r0;
      if (top < 0 || top >= bandRows) continue;
      if (actualR !== m.s.r || excelCol !== m.s.c) {
        skipped[rr][i] = true;
        continue;
      }
      const rowSpan = Math.min(m.e.r, r1) - m.s.r + 1;
      const colSpan = Math.min(m.e.c, col0 + numCols - 1) - m.s.c + 1;
      for (let r2 = rr; r2 < rr + rowSpan && r2 < bandRows; r2 += 1) {
        for (let ci = i; ci < i + colSpan && ci < numCols; ci += 1) skipped[r2][ci] = true;
      }
      const text = getTopLeftValue(m);
      if (text) hasAny = true;
      cells.push(
        <th
          key={`merged-h-${actualR}-${excelCol}`}
          rowSpan={rowSpan > 1 ? rowSpan : undefined}
          colSpan={colSpan > 1 ? colSpan : undefined}
          style={thStyle}
          title={text}
        >
          {text || '\u00a0'}
        </th>
      );
    }
    if (cells.length > 0 && hasAny) trs.push(<tr key={`merged-r-${actualR}`}>{cells}</tr>);
  }

  return trs.length ? trs : null;
};

/** Proof Submission column: only PDF / images (not draft Excel or Word). */
const PROOF_SUBMISSION_DOC_EXT = /\.(pdf|png|jpe?g|gif|webp|bmp|tiff?|heic)$/i;
const isProofSubmissionDocumentFileName = (name) => PROOF_SUBMISSION_DOC_EXT.test(String(name || '').trim());
const isRowStatusApproved = (row) => {
  const rawStatus = row?.status != null && row.status !== '' ? row.status : row?.Status;
  if (String(rawStatus || '').trim().toLowerCase() === 'approved') return true;
  const rawApproval = row?.approval != null && row.approval !== '' ? row.approval : row?.Approval;
  const aNorm = String(rawApproval || '').trim().toLowerCase();
  return aNorm === 'approved' || aNorm === 'approve';
};

function statutorySendForApprovalIsSent(row) {
  if (!row) return false;
  return /^sent$/i.test(String(row?.sendForApproval ?? row?.SendForApproval ?? '').trim());
}

/** Display status for Statutory grid Status column and Status filter (matches table rendering). */
const getStatutoryRowDisplayStatus = (item) => {
  const raw = item?.status != null && item.status !== '' ? item.status : item?.Status;
  const norm = String(raw || '').trim();
  const normalized = norm.toLowerCase();
  const rawApproval = item?.approval != null && item.approval !== '' ? item.approval : item?.Approval;
  const approvalNorm = String(rawApproval || '').trim().toLowerCase();
  if (approvalNorm === 'approved' || approvalNorm === 'approve' || normalized === 'approved' || normalized === 'approve') {
    return 'Approved';
  }
  if (approvalNorm === 'rejected' || approvalNorm === 'reject' || normalized === 'rejected' || normalized === 'reject') {
    return 'Returned';
  }
  if (statutorySendForApprovalIsSent(item)) return 'Pending';
  const draftVal = item?.draftFile ?? item?.DraftFile ?? null;
  const hasDraftFile =
    draftVal != null &&
    String(draftVal).trim() !== '' &&
    String(draftVal).trim() !== 'null' &&
    String(draftVal).trim() !== 'undefined';
  if (!hasDraftFile) return 'Yet to Complete';
  if (norm === '' || norm === '-' || norm === '—') {
    return statutorySendForApprovalIsSent(item) ? 'Pending' : 'Yet to Complete';
  }
  if (normalized === 'pending') {
    return statutorySendForApprovalIsSent(item) ? 'Pending' : 'Yet to Complete';
  }
  if (normalized === 'yet to complete' || normalized === 'yet to comply') {
    return statutorySendForApprovalIsSent(item) ? 'Pending' : 'Yet to Complete';
  }
  return norm;
};

const AUTH_SIGNATORY_LABEL_RE =
  /\b(authorised|authorized)\s+signator(y|ies)\b/i;

function statutoryExcelCellText(val) {
  if (val == null) return '';
  if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
  if (val instanceof Date) return val.toISOString();
  if (typeof val === 'object') {
    if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
    if (val.text != null) return String(val.text);
    if (val.result != null) return String(val.result);
  }
  return '';
}

function detectImageExtensionFromArrayBuffer(ab) {
  const u = new Uint8Array(ab.byteLength ? ab.slice(0, 12) : []);
  if (u.length >= 4 && u[0] === 0x89 && u[1] === 0x50 && u[2] === 0x4e && u[3] === 0x47) return 'png';
  if (u.length >= 3 && u[0] === 0xff && u[1] === 0xd8 && u[2] === 0xff) return 'jpeg';
  if (u.length >= 6 && u[0] === 0x47 && u[1] === 0x49 && u[2] === 0x46) return 'gif';
  if (u.length >= 12 && u[8] === 0x57 && u[9] === 0x45 && u[10] === 0x42 && u[11] === 0x50) return 'webp';
  return 'png';
}

function looksLikeJsonErrorArrayBuffer(ab) {
  if (!ab || !ab.byteLength) return true;
  const head = new TextDecoder('utf-8', { fatal: false }).decode(new Uint8Array(ab.slice(0, 120))).trim();
  return head.startsWith('{') && (head.includes('"failure"') || head.includes('"status"'));
}

function normalizeFooterSearchText(txt) {
  return String(txt || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\r?\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function getFooterScanCellText(worksheet, r, c) {
  let cell;
  try {
    cell = worksheet.getCell(r, c);
  } catch {
    return '';
  }
  const fromValue = statutoryExcelCellText(cell.value).replace(/\u00a0/g, ' ').trim();
  if (fromValue) return fromValue;
  try {
    const t = String(cell.text || '').replace(/\u00a0/g, ' ').trim();
    if (t) return t;
  } catch {
    /* ignore */
  }
  return '';
}

function footerRowMatchesAuthorisedSignatory(normRow) {
  if (!normRow) return false;
  if (AUTH_SIGNATORY_LABEL_RE.test(normRow)) return true;
  if (normRow.includes('authorised signatory') || normRow.includes('authorized signatory')) return true;
  if (normRow.includes('authorised') && normRow.includes('signatory')) return true;
  if (normRow.includes('authorized') && normRow.includes('signatory')) return true;
  return false;
}

function excelColumnLetterFrom1Based(col1Based) {
  let n = Math.max(1, Math.floor(col1Based));
  let s = '';
  while (n > 0) {
    const rem = (n - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s || 'A';
}

function findAuthorisedSignatoryCell(worksheet) {
  const maxRow = 520;
  const maxCol = 120;
  for (let r = 1; r <= maxRow; r += 1) {
    const rowChunks = [];
    for (let c = 1; c <= maxCol; c += 1) {
      const raw = getFooterScanCellText(worksheet, r, c);
      if (!raw) continue;
      rowChunks.push(normalizeFooterSearchText(raw));
    }
    const normRow = rowChunks.join(' ').trim();
    if (!footerRowMatchesAuthorisedSignatory(normRow)) continue;
    for (let c = 1; c <= maxCol; c += 1) {
      const raw = getFooterScanCellText(worksheet, r, c);
      const norm = normalizeFooterSearchText(raw);
      if (!norm) continue;
      if (
        AUTH_SIGNATORY_LABEL_RE.test(norm) ||
        norm.includes('authorised signatory') ||
        norm.includes('authorized signatory') ||
        (norm.includes('signatory') && (norm.includes('authorised') || norm.includes('authorized')))
      ) {
        return { row: r, col: c };
      }
    }
    for (let c = 1; c <= maxCol; c += 1) {
      if (String(getFooterScanCellText(worksheet, r, c) || '').trim()) return { row: r, col: c };
    }
    return { row: r, col: 21 };
  }
  return null;
}

async function resolveCompanyIdForStatutoryTemplateDownload(item) {
  let listResp;
  try {
    listResp = await fetch('/server/company_function/company');
  } catch {
    return null;
  }
  if (!listResp || !listResp.ok) return null;
  const j = await listResp.json().catch(() => null);
  const list = j?.data?.companyDetails;
  if (!Array.isArray(list) || list.length === 0) return null;
  const target = String(item?.companyName || item?.CompanyName || '')
    .trim()
    .toLowerCase();
  if (target) {
    const match = list.find((co) => String(co.companyName || '').trim().toLowerCase() === target);
    if (match?.id != null) return match.id;
  }
  return list[0]?.id ?? null;
}

async function fetchCompanyHeadHrImageArrayBuffers(companyId) {
  if (companyId == null || companyId === '') return { sign: null, seal: null };
  const base = `/server/company_function/company/${encodeURIComponent(String(companyId))}/file/`;
  const fetchOne = async (docType) => {
    try {
      const r = await fetch(`${base}${docType}`);
      if (!r.ok) return null;
      const buf = await r.arrayBuffer();
      if (!buf || !buf.byteLength || looksLikeJsonErrorArrayBuffer(buf)) return null;
      return buf;
    } catch {
      return null;
    }
  };
  const [sign, seal] = await Promise.all([fetchOne('HeadHRSign'), fetchOne('HeadHRSeal')]);
  return { sign, seal };
}

const STATUTORY_SIGNATORY_FOOTER_FONT = { name: 'Palatino Linotype', size: 12, bold: true, color: { argb: 'FF000000' } };

function clearWorksheetCellRect(worksheet, r1, r2, c1, c2) {
  const rStart = Math.min(r1, r2);
  const rEnd = Math.max(r1, r2);
  const cStart = Math.min(c1, c2);
  const cEnd = Math.max(c1, c2);
  for (let r = rStart; r <= rEnd; r += 1) {
    for (let c = cStart; c <= cEnd; c += 1) {
      try {
        worksheet.getCell(r, c).value = null;
      } catch {
        /* ignore */
      }
    }
  }
}

/** Template often leaves "Signature of Employer / ..." on rows that overlap seal images — remove all but `keepRow1Based`. */
function removeGhostSignatureEmployerFooterText(worksheet, keepRow1Based, scanR1, scanR2, maxCol = 70) {
  const rLo = Math.max(1, Math.min(scanR1, scanR2));
  const rHi = Math.min(520, Math.max(scanR1, scanR2));
  const needle = /signature\s+of\s+employer/i;
  for (let r = rLo; r <= rHi; r += 1) {
    if (r === keepRow1Based) continue;
    for (let c = 1; c <= maxCol; c += 1) {
      try {
        const raw = getFooterScanCellText(worksheet, r, c);
        if (!raw || !needle.test(String(raw))) continue;
        worksheet.getCell(r, c).value = null;
      } catch {
        /* ignore */
      }
    }
  }
}

function applyMergedFooterTextLine(worksheet, row1Based, centerCol1Based, text, mergeHalfSpanCols) {
  const l = Math.max(1, centerCol1Based - mergeHalfSpanCols);
  const r = Math.min(90, centerCol1Based + mergeHalfSpanCols);
  const leftL = excelColumnLetterFrom1Based(l);
  const rightL = excelColumnLetterFrom1Based(r);
  const rangeAddr = `${leftL}${row1Based}:${rightL}${row1Based}`;
  try {
    worksheet.unMergeCells(rangeAddr);
  } catch {
    /* no existing merge for this exact range */
  }
  try {
    worksheet.mergeCells(rangeAddr);
  } catch {
    const cell = worksheet.getCell(row1Based, centerCol1Based);
    cell.value = text;
    cell.alignment = { vertical: 'middle', horizontal: 'center', wrapText: false };
    cell.font = { ...STATUTORY_SIGNATORY_FOOTER_FONT };
    return;
  }
  const cell = worksheet.getCell(row1Based, l);
  cell.value = text;
  cell.alignment = { vertical: 'middle', horizontal: 'center', wrapText: false };
  cell.font = { ...STATUTORY_SIGNATORY_FOOTER_FONT };
}

function writeStatutoryAuthorisedSignatoryFooterBlock(worksheet, sigRow1Based, sigCol1Based, footerCompanyName) {
  const companyPart =
    footerCompanyName && String(footerCompanyName).trim() ? String(footerCompanyName).trim() : 'Company Name';
  const lineForCompany = `For (${companyPart})`;
  const lineAuthorised = 'Authorised Signatory';
  const lineSignature = 'Signature of Employer / Manager / Authorised Person';
  /** Layout: For (row-3) → HeadHRSign (rows-2..-1) → Authorised (row) → HeadHRSeal (rows+1..+2) → Signature (row+3). */
  const forRow = Math.max(1, sigRow1Based - 3);
  const signatureLineRow = sigRow1Based + 3;
  applyMergedFooterTextLine(worksheet, forRow, sigCol1Based, lineForCompany, 5);
  applyMergedFooterTextLine(worksheet, sigRow1Based, sigCol1Based, lineAuthorised, 5);
  applyMergedFooterTextLine(worksheet, signatureLineRow, sigCol1Based, lineSignature, 7);
}

async function injectHeadHrSignSealAboveAuthorisedSignatoryInBlob(blob, { signBuffer, sealBuffer, footerCompanyName }) {
  const validSign = signBuffer && signBuffer.byteLength && !looksLikeJsonErrorArrayBuffer(signBuffer);
  const validSeal = sealBuffer && sealBuffer.byteLength && !looksLikeJsonErrorArrayBuffer(sealBuffer);
  if (!validSign && !validSeal) return blob;
  const arrayBuffer = await blob.arrayBuffer();
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(arrayBuffer);
  let anchorWs = null;
  let anchor = null;
  const sheets = Array.from(workbook.worksheets || []).sort((a, b) => {
    const score = (name) => (/form\s*u\b/i.test(String(name || '')) ? 0 : 1);
    return score(a.name) - score(b.name);
  });
  for (let i = 0; i < sheets.length; i += 1) {
    const ws = sheets[i];
    const found = findAuthorisedSignatoryCell(ws);
    if (found) {
      anchorWs = ws;
      anchor = found;
      break;
    }
  }
  if (!anchorWs || !anchor) return blob;

  const { row: sigRow, col: sigCol } = anchor;
  const sigCol0 = sigCol - 1;
  const signImageTop1Based = Math.max(1, sigRow - 2);
  const signImageBot1Based = signImageTop1Based + 1;
  const sealImageTop1Based = sigRow + 1;
  const sealImageBot1Based = sealImageTop1Based + 1;
  /** ~half prior width: anchor across two columns centered on sigCol (was five). */
  const imgBandLeft1 = Math.max(1, sigCol - 1);
  const imgBandRight1 = Math.min(90, imgBandLeft1 + 1);
  [signImageTop1Based, signImageBot1Based, sealImageTop1Based, sealImageBot1Based].forEach((rn) => {
    const row = anchorWs.getRow(rn);
    row.height = Math.max(Number(row.height) || 0, 56);
  });

  const forRow = Math.max(1, sigRow - 3);
  const signatureLineRow = sigRow + 3;
  const clearC1 = Math.max(1, sigCol - 14);
  const clearC2 = Math.min(90, sigCol + 14);
  clearWorksheetCellRect(anchorWs, signImageTop1Based, signImageBot1Based, clearC1, clearC2);
  clearWorksheetCellRect(anchorWs, sealImageTop1Based, sealImageBot1Based, clearC1, clearC2);
  removeGhostSignatureEmployerFooterText(anchorWs, signatureLineRow, forRow - 2, signatureLineRow + 4, clearC2);

  const pushImage = (buf, rangeStr, tlFallback) => {
    if (!buf || !buf.byteLength || looksLikeJsonErrorArrayBuffer(buf)) return;
    const ext = detectImageExtensionFromArrayBuffer(buf);
    if (ext === 'webp') {
      console.warn('Statutory template: WebP Head HR image is not supported for Excel embedding; skip.');
      return;
    }
    const uint = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
    let imageId;
    try {
      imageId = workbook.addImage({ buffer: uint, extension: ext });
    } catch (e) {
      console.warn('Statutory template: addImage buffer rejected:', e);
      return;
    }
    try {
      if (rangeStr) {
        anchorWs.addImage(imageId, rangeStr);
        return;
      }
    } catch (e) {
      console.warn('Statutory template: addImage range anchor failed, trying tl/ext:', e);
    }
    if (tlFallback) {
      try {
        anchorWs.addImage(imageId, tlFallback);
      } catch (e2) {
        console.warn('Statutory template: addImage tl/ext anchor failed:', e2);
      }
    }
  };

  const signRange = `${excelColumnLetterFrom1Based(imgBandLeft1)}${signImageTop1Based}:${excelColumnLetterFrom1Based(imgBandRight1)}${signImageBot1Based}`;
  const sealRange = `${excelColumnLetterFrom1Based(imgBandLeft1)}${sealImageTop1Based}:${excelColumnLetterFrom1Based(imgBandRight1)}${sealImageBot1Based}`;
  const signTlRow0 = signImageTop1Based - 1;
  const sealTlRow0 = sealImageTop1Based - 1;
  const signTl = {
    tl: { col: Math.max(0, sigCol0 - 1) + 0.05, row: signTlRow0 + 0.04 },
    ext: { width: 90, height: 56 }
  };
  const sealTl = {
    tl: { col: Math.max(0, sigCol0 - 1) + 0.05, row: sealTlRow0 + 0.04 },
    ext: { width: 90, height: 56 }
  };

  pushImage(validSign ? signBuffer : null, signRange, signTl);
  pushImage(validSeal ? sealBuffer : null, sealRange, sealTl);

  try {
    writeStatutoryAuthorisedSignatoryFooterBlock(anchorWs, sigRow, sigCol, footerCompanyName);
  } catch (e) {
    console.warn('Statutory template: signatory footer text write failed:', e);
  }
  removeGhostSignatureEmployerFooterText(anchorWs, signatureLineRow, forRow - 2, signatureLineRow + 4, clearC2);

  const outBuf = await workbook.xlsx.writeBuffer();
  return new Blob([outBuf], { type: blob.type || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
}

async function prefetchApprovedStatutoryHeadHrSignSealPayload(item) {
  if (!isRowStatusApproved(item)) return null;
  try {
    const companyId = await resolveCompanyIdForStatutoryTemplateDownload(item);
    const { sign, seal } = await fetchCompanyHeadHrImageArrayBuffers(companyId);
    const footerCompanyName =
      String(item?.companyName || item?.CompanyName || '').trim() || null;
    return { signBuffer: sign, sealBuffer: seal, footerCompanyName };
  } catch (err) {
    console.warn('Statutory template: Head HR sign/seal prefetch failed:', err);
    return null;
  }
}

async function appendApprovedStatutoryHeadHrSignSealToDownloadBlob(blob, item) {
  const payload = await prefetchApprovedStatutoryHeadHrSignSealPayload(item);
  if (!payload) return blob;
  try {
    return await injectHeadHrSignSealAboveAuthorisedSignatoryInBlob(blob, payload);
  } catch (err) {
    console.warn('Statutory template: Head HR sign/seal injection failed:', err);
    return blob;
  }
}

/** Latest activity time for table ordering (new saves/submissions surface first). */
const getStatutoryRowActivityTimeMs = (row) => {
  const raw =
    row?.modifiedTime ??
    row?.ModifiedTime ??
    row?.modified_time ??
    row?.createdTime ??
    row?.CreatedTime ??
    row?.created_time ??
    '';
  const parsed = Date.parse(String(raw || '').trim());
  if (Number.isFinite(parsed)) return parsed;
  const idStr = String(row?.id ?? '').trim();
  if (/^\d+$/.test(idStr)) {
    const n = Number.parseInt(idStr, 10);
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
};

/** Draft saved (Autofill → Save) or workflow sent — surface these rows before lines still empty. */
const hasStatutoryDraftSubmittedForSort = (row) => {
  const draftVal = row?.draftFile ?? row?.DraftFile ?? null;
  const hasDraftFile =
    draftVal != null &&
    String(draftVal).trim() !== '' &&
    String(draftVal).trim().toLowerCase() !== 'null' &&
    String(draftVal).trim().toLowerCase() !== 'undefined';
  if (hasDraftFile) return true;
  const sfa = String(row?.sendForApproval ?? row?.SendForApproval ?? '').trim();
  return /^sent$/i.test(sfa);
};

