  /** Karnataka Form XIV / XIX — lean ZIP download from saved draft + sample data (avoids formmaster 429). */
  const handleKarnatakaEmployeeZipDownload = async (
    draftApiRowId,
    fileName,
    sourceItem,
    resolvedFormFileItem,
    formKind
  ) => {
    const lineItem = sourceItem || resolvedFormFileItem || {};
    const fn = String(
      fileName ||
        sourceItem?.draftFileName ||
        sourceItem?.DraftFileName ||
        resolvedFormFileItem?.formFileName ||
        'form-draft.xlsx'
    ).replace(/[^a-zA-Z0-9._-]/g, '_');
    try {
      setFormFileLoading(true);
      setError('');
      setSuccess('Generating employee ZIP...');
      const sampleContext = buildStatutorySampleDataFetchContext(sourceItem, resolvedFormFileItem);
      const draftUrl = `/server/statutoryreg_function/statutory/${draftApiRowId}/file/Draft?_ts=${Date.now()}`;
      const [draftResp, sampleBlock] = await Promise.all([
        fetchHttpWithRetry(draftUrl),
        fetchStatutorySampleDataSnapshot(draftApiRowId, sampleContext).catch(() => null)
      ]);
      if (!draftResp.ok) {
        throw new Error(
          `Could not load saved draft (HTTP ${draftResp.status}). Wait a moment and try Download Draft File again.`
        );
      }
      const templateArrayBuffer = await draftResp.arrayBuffer();
      if (!isValidExcelArrayBuffer(templateArrayBuffer)) {
        throw new Error('Saved draft is not a valid Excel file. Open Autofill, save again, then download.');
      }
      const templateWb = XLSX.read(templateArrayBuffer, { type: 'array' });
      const draftParseHints = {
        fileName: fn,
        formFileName: fileName,
        formName: lineItem?.formName || lineItem?.FormName,
        item: lineItem
      };
      let parsed = parseExcelForm(templateWb, draftParseHints);
      let draftPreferredSheet =
        resolveFormXIVWorkbookSheetName(templateWb, {
          ...draftParseHints,
          formHeader: parsed?.formHeader,
          formHeaderTitle: parsed?.formHeader?.title,
          formHeaderSubtitle: parsed?.formHeader?.subtitle
        }) || parsed.sheetName || templateWb.SheetNames?.[0] || '';
      if (draftPreferredSheet && draftPreferredSheet !== parsed.sheetName) {
        parsed = parseExcelForm(templateWb, {
          ...draftParseHints,
          preferredSheetName: draftPreferredSheet,
          formHeaderTitle: undefined,
          formHeaderSubtitle: undefined,
          formHeader: undefined
        });
        draftPreferredSheet = parsed.sheetName || draftPreferredSheet;
      }
      let headersToUse = Array.isArray(parsed.headers) && parsed.headers.length > 0 ? [...parsed.headers] : [];
      let mappedData = [];
      let headerFormData = {};
      const sampleApplied = applyStatutorySampleDataBlockToDownload([], headersToUse, sampleBlock, {
        preferSampleOnly: true
      });
      if (sampleApplied.usedSnapshot) {
        mappedData = sampleApplied.mappedData || [];
        headersToUse =
          Array.isArray(sampleApplied.headersToUse) && sampleApplied.headersToUse.length > 0
            ? sampleApplied.headersToUse
            : headersToUse;
        headerFormData = sampleApplied.headerFormData || {};
      }
      if (!mappedData.length) {
        const importBlock = await fetchStatutoryImportDataSnapshot(draftApiRowId, sampleContext).catch(
          () => null
        );
        const importApplied = applyStatutorySampleDataBlockToDownload([], headersToUse, importBlock, {
          preferSampleOnly: true
        });
        if (importApplied.usedSnapshot) {
          mappedData = importApplied.mappedData || [];
          headersToUse =
            Array.isArray(importApplied.headersToUse) && importApplied.headersToUse.length > 0
              ? importApplied.headersToUse
              : headersToUse;
          headerFormData = importApplied.headerFormData || headerFormData;
        }
      }
      if (!mappedData.length && headersToUse.length > 0) {
        const draftRows = extractMappedRowsFromSavedDraft({
          draftWorkbook: templateWb,
          templateHeaders: headersToUse,
          templateHeaderRowIndex: parsed.headerRowIndex,
          templateDataStartIndex: parsed.dataStartIndex,
          tableStartCol: parsed.tableStartCol ?? 0,
          hasSubColumns: parsed.subColumns && Object.keys(parsed.subColumns || {}).length > 0
        });
        if (Array.isArray(draftRows) && draftRows.length > 0) {
          mappedData = draftRows;
        }
      }
      const employeesForExport = resolveStatutoryEmployeesForSaveOrder(autofillEmployeesRef.current);
      let zipResult;
      if (formKind === 'xiv') {
        const xivHdrs = resolveFormXIVMPTableHeaders(headersToUse, {
          item: lineItem,
          fileName: fn,
          formHeader: parsed.formHeader,
          sheetText: parsed.sheetText || ''
        });
        const xivPayMonth = resolvePayrollMonthIsoCandidates(
          selectedMonth,
          lineItem,
          parsed?.formHeader?.wagePeriodText || ''
        );
        const cachedPayroll = getCachedForm15PayrollTableRows(xivPayMonth);
        const payrollRows = resolveFormXIVMPPayrollRowsForAutofill(
          cachedPayroll?.rows?.length > 0
            ? cachedPayroll.rows.map((row) => flattenPayrollEarningColumns(row))
            : [],
          xivPayMonth
        );
        const resolvePayrollRow =
          payrollRows.length > 0 ? buildFormXIXMPPayrollRowResolver(payrollRows) : null;
        if (
          resolvePayrollRow &&
          Array.isArray(mappedData) &&
          mappedData.length > 0 &&
          xivHdrs.find(isFormXIVMPWageRateHeader)
        ) {
          enrichFormXIVMPPayrollRows(mappedData, employeesForExport.length > 0 ? employeesForExport : mappedData, xivHdrs, {
            sanitizeValue: (v) => String(v ?? '').trim(),
            overwrite: false,
            monthCandidates: xivPayMonth,
            item: lineItem,
            fileName: fn,
            formHeader: parsed.formHeader,
            resolvePayrollRow: (emp) => resolvePayrollRow(emp)
          });
        }
        zipResult = await buildFormXIVMPPerEmployeeDownload({
          templateArrayBuffer,
          mappedData,
          headersToUse: xivHdrs,
          parsedFormHeader: parsed.formHeader,
          formFileName: fileName || fn,
          headerFormData,
          rowItem: lineItem || sourceItem || resolvedFormFileItem || null,
          sheetText: parsed?.sheetText || formFileModalData?.sheetText || '',
          preferredSheetName: draftPreferredSheet || parsed?.sheetName || '',
        });
        triggerFormXIVMPZipDownload(zipResult.blob, zipResult.fileName);
      } else {
        const kaHdrs = resolveFormXIXKarnatakaWageTableHeaders(headersToUse);
        const kaMonth = resolvePayrollMonthIsoCandidates(
          selectedMonth,
          lineItem,
          resolveFormXIXKarnatakaPayrollMonthHints({
            wagePeriodText: parsed?.formHeader?.wagePeriodText || '',
            headerFormData,
            parsedHeaderFormData: headerFormData
          })
        );
        const kaCachedPayroll = getCachedForm15PayrollTableRows(kaMonth);
        const kaPayrollRows = resolveFormXIXKarnatakaPayrollRowsForAutofill(
          kaCachedPayroll?.rows?.length > 0
            ? kaCachedPayroll.rows.map((row) => flattenPayrollEarningColumns(row))
            : null,
          kaMonth
        );
        const resolveKaPayrollRow =
          kaPayrollRows.length > 0 ? buildFormXIXMPPayrollRowResolver(kaPayrollRows) : null;
        zipResult = await buildFormXIXKarnatakaPerEmployeeDownload({
          templateArrayBuffer,
          mappedData,
          headersToUse: kaHdrs,
          parsedFormHeader: parsed.formHeader,
          formFileName: fileName || fn,
          headerFormData,
          employeesOverride: employeesForExport,
          resolvePayrollRow: resolveKaPayrollRow
            ? (emp) => {
                const hit = resolveKaPayrollRow(emp);
                return hit && !hit.fetch_error ? hit : null;
              }
            : null,
          monthCandidates: kaMonth
        });
        triggerFormXIXKarnatakaZipDownload(zipResult.blob, zipResult.fileName);
      }
      setSuccess('Employee ZIP downloaded.');
      setTimeout(() => setSuccess(''), 4000);
    } catch (err) {
      console.warn('Karnataka lean ZIP download failed, using full generate path:', err);
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId,
        skipBackgroundPrefetch: true
      });
    } finally {
      setFormFileLoading(false);
    }
  };

  const handleDownloadSavedDraftFile = async (draftApiRowId, fileName, sourceItem, resolvedFormFileItem) => {
    // Pin draft column links before any async fetch so polling cannot blank them.
    setFormFileLoading(true);
    if (!draftApiRowId) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem);
      return;
    }

    const draftFileHintEarly = String(
      fileName ||
        sourceItem?.draftFileName ||
        sourceItem?.DraftFileName ||
        resolvedFormFileItem?.formFileName ||
        resolvedFormFileItem?.FormFileName ||
        ''
    );

    // Form T Karnataka: prefer instant stream of Save/cached bytes (already A–I repaired at Save).
    // Only rebuild/repair when cache is missing or server draft is still J-shifted.
    const formTDraftHintBlob = [
      sourceItem?.formName,
      sourceItem?.FormName,
      resolvedFormFileItem?.formName,
      resolvedFormFileItem?.FormName,
      draftFileHintEarly
    ]
      .filter(Boolean)
      .join(' ');
    if (isFormTSEContext(null, sourceItem || resolvedFormFileItem, draftFileHintEarly, formTDraftHintBlob)) {
      try {
        setFormFileLoading(true);
        setError('');
        setSuccess('Downloading draft...');
        let buffer = null;
        const lastExport = readFormTSELastExport();
        const lineItem = sourceItem || resolvedFormFileItem || {};
        const downloadName =
          fileName || lastExport?.fileName || 'Form_T_Karnataka.xlsx';

        const triggerFormTBufferDownload = (buf, name) => {
          const blob = new Blob([buf], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
          });
          const url = URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.download = name;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          URL.revokeObjectURL(url);
        };

        const hdrs =
          Array.isArray(lastExport?.headers) && lastExport.headers.length > 0
            ? lastExport.headers
            : Array.isArray(formFileModalData?.parsedTableHeaders)
              ? formFileModalData.parsedTableHeaders
              : Array.isArray(statutoryAutofillExportCacheRef.current?.headers)
                ? statutoryAutofillExportCacheRef.current.headers
                : [];
        const rows =
          Array.isArray(lastExport?.rows) && lastExport.rows.length > 0
            ? lastExport.rows
            : formTSEDownloadHasSubstantiveRows(
                formTableDataRef.current,
                hdrs
              )
              ? formTableDataRef.current
              : Array.isArray(statutoryAutofillExportCacheRef.current?.rows)
                ? statutoryAutofillExportCacheRef.current.rows
                : [];

        // 1) Same bytes as Save auto-download — do not regenerate onto a blank Form T_KA template.
        const lastExportHasRows = formTSEDownloadHasSubstantiveRows(
          lastExport?.rows,
          lastExport?.headers || hdrs
        );
        if (
          lastExport?.arrayBuffer &&
          lastExport.arrayBuffer.byteLength >= 32 &&
          (lastExportHasRows || (await formTSEWorkbookHasIdentityInColumnA(lastExport.arrayBuffer)))
        ) {
          const readyBuf = await prepareFormTSEWorkbookForDownload(lastExport.arrayBuffer);
          triggerFormTBufferDownload(readyBuf, downloadName);
          writeFormTSELastExport({
            ...(lastExport || {}),
            arrayBuffer: readyBuf,
            fileName: downloadName
          });
          setSuccess('Draft file downloaded.');
          setTimeout(() => setSuccess(''), 3000);
          return;
        }

        let formTEmployees = resolveStatutoryEmployeesForSaveOrder(
          autofillEmployeesRef.current
        );
        if (
          !formTSEDownloadHasSubstantiveRows(rows, hdrs) &&
          formTEmployees.length === 0
        ) {
          try {
            await Promise.race([
              fetchPeopleDataForAutofillDisplay(),
              new Promise((_, reject) =>
                setTimeout(() => reject(new Error('People fetch timed out')), 12000)
              )
            ]);
          } catch (_) {
            /* cache / mapped rows */
          }
          formTEmployees = resolveStatutoryEmployeesForSaveOrder(
            autofillEmployeesRef.current
          );
        }

        const rebuildFormTFromCleanTemplate = async (mappedRows, mappedHdrs, employees) => {
          const canWrite =
            formTSEDownloadHasSubstantiveRows(mappedRows, mappedHdrs) ||
            (Array.isArray(employees) && employees.length > 0);
          if (!canWrite) return null;
          const templateMeta = resolveStatutoryFormTemplateForRow(
            lineItem,
            { formmasterFormFileByMatchKey, formFileByFormKey, formmasterTemplates },
            {}
          );
          const hasFormFile =
            templateMeta?.formFile &&
            templateMeta.formFile !== 'null' &&
            String(templateMeta.formFile).trim() !== '';
          if (!hasFormFile) return null;
          const fn = (
            templateMeta.formFileName ||
            resolvedFormFileItem?.formFileName ||
            fileName ||
            'Form_T_Karnataka.xlsx'
          ).replace(/[^a-zA-Z0-9._-]/g, '_');
          const fileUrl = `/server/formmaster_function/templates/download/${templateMeta.formFile}?fileName=${encodeURIComponent(fn)}`;
          const templateCacheKey = `formmaster|${templateMeta.formFile}|${fn}`;
          const entry = await fetchFormTemplateArrayBuffer([fileUrl], templateCacheKey);
          const templateBuf = entry?.arrayBuffer;
          if (!templateBuf || templateBuf.byteLength < 32) return null;
          const rebuilt = await buildFormTSEWorkbookWithTemplateStyles({
            templateArrayBuffer: templateBuf,
            mappedData: mappedRows,
            headersToUse: mappedHdrs,
            employees,
            parsedHeaderRowIndex: lastExport?.headerRowIndex ?? formFileModalData?.headerRowIndex ?? -1,
            parsedDataStartIndex: lastExport?.dataStartIndex ?? formFileModalData?.dataStartIndex ?? -1,
            parsedTableStartCol: 0,
            parsedFormHeader: formFileModalData?.parsedFormHeader || null,
            headerFormData: lastExport?.headerFormData || {},
            headerSiteContext: lastExport?.headerSiteContext || {},
            formFileName: fileName || lastExport?.fileName || fn,
            currentItem: lineItem,
            sheetNameHint: formFileModalData?.sheetName || 'Form T'
          });
          let out = await rebuilt.blob.arrayBuffer();
          out = await repairFormTSEWorkbookColumnAlignment(out);
          return out;
        };

        // 2) Stream saved Draft bytes only when employee names are already in the table body.
        const resp = await fetch(
          `/server/statutoryreg_function/statutory/${draftApiRowId}/file/Draft?disposition=attachment&_ts=${Date.now()}`,
          { cache: 'no-store' }
        );
        if (resp.ok) {
          buffer = await resp.arrayBuffer();
        }
        if (buffer && buffer.byteLength >= 32) {
          if (!(await formTSEWorkbookHasIdentityInColumnA(buffer))) {
            buffer = await repairFormTSEWorkbookColumnAlignment(buffer);
          }
        } else {
          buffer = null;
        }
        if (!(buffer && (await formTSEWorkbookHasIdentityInColumnA(buffer)))) {
          const rebuilt = await rebuildFormTFromCleanTemplate(rows, hdrs, formTEmployees);
          if (rebuilt) buffer = rebuilt;
        }
        if (!(buffer && (await formTSEWorkbookHasIdentityInColumnA(buffer)))) {
          throw new Error('Form T draft has no employee rows; regenerating.');
        }
        buffer = await prepareFormTSEWorkbookForDownload(buffer);
        writeFormTSELastExport({
          ...(lastExport || {}),
          arrayBuffer: buffer,
          fileName: downloadName,
          headers: hdrs,
          rows
        });
        triggerFormTBufferDownload(buffer, downloadName);
        setSuccess('Draft file downloaded.');
        setTimeout(() => setSuccess(''), 3000);
      } catch (formTDraftErr) {
        console.warn('Form T draft download failed, falling back to regenerate:', formTDraftErr);
        await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
          sampleStatutoryId: draftApiRowId,
          draftApiRowId
          // Do not preferSavedDraftTemplate — regenerate must use clean formmaster.
        });
      } finally {
        setFormFileLoading(false);
      }
      return;
    }

    // Karnataka employee ZIP still needs lean rebuild from saved draft + sample.
    const isFormXIVKarnatakaDownloadRow =
      isFormXIVKarnatakaContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHintEarly,
        ''
      ) ||
      isFormXIVKarnatakaContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHintEarly,
        ''
      );
    if (isFormXIVKarnatakaDownloadRow) {
      await handleKarnatakaEmployeeZipDownload(
        draftApiRowId,
        fileName,
        sourceItem,
        resolvedFormFileItem,
        'xiv'
      );
      return;
    }
    const isFormXIXKarnatakaDownloadRow =
      isFormXIXKarnatakaWageSlipContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHintEarly,
        ''
      ) ||
      isFormXIXKarnatakaWageSlipContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHintEarly,
        ''
      );
    if (isFormXIXKarnatakaDownloadRow) {
      await handleKarnatakaEmployeeZipDownload(
        draftApiRowId,
        fileName,
        sourceItem,
        resolvedFormFileItem,
        'xix'
      );
      return;
    }

    // Fast path: stream the already-saved draft file — no sample fetch / regenerate / ExcelJS.
    // Saved drafts already include the system note + alignment from Save.
    // Form X leave register drafts were often saved with mis-mapped Name/Gender (serial digits);
    // always regenerate so download matches Autofill.
    const tryFastSavedDraftDownload = async () => {
      try {
        const fastDraftHint = String(
          fileName ||
            sourceItem?.draftFileName ||
            sourceItem?.DraftFileName ||
            resolvedFormFileItem?.formFileName ||
            resolvedFormFileItem?.FormFileName ||
            ''
        );
        const fastDraftBlob = [
          sourceItem?.formName,
          sourceItem?.FormName,
          resolvedFormFileItem?.formName,
          resolvedFormFileItem?.FormName,
          fastDraftHint
        ]
          .filter(Boolean)
          .join(' ');
        if (
          isFormXLeaveSocialSecurityContext(
            null,
            sourceItem || resolvedFormFileItem,
            fastDraftHint,
            fastDraftBlob
          ) ||
          isForm15Part1AutofillContext(
            fastDraftHint,
            null,
            sourceItem || resolvedFormFileItem
          ) ||
          // Form 11 RJ: older saved drafts often have Name shifted into the commence column.
          isForm11RajasthanContext(
            null,
            sourceItem || resolvedFormFileItem,
            fastDraftHint,
            fastDraftBlob
          )
        ) {
          return false;
        }
        setFormFileLoading(true);
        setError('');
        setSuccess('Downloading draft...');
        const isFormTFast = isFormTSEContext(
          null,
          sourceItem || resolvedFormFileItem,
          fastDraftHint,
          fastDraftBlob
        );
        // Form T: prefer the exact workbook from the last Save auto-download (correct A–I alignment).
        if (isFormTFast) {
          const lastExport = readFormTSELastExport();
          if (
            lastExport?.arrayBuffer &&
            lastExport.arrayBuffer.byteLength >= 32 &&
            (formTSEDownloadHasSubstantiveRows(
              lastExport.rows,
              lastExport.headers
            ) ||
              (await formTSEWorkbookHasIdentityInColumnA(lastExport.arrayBuffer)))
          ) {
            const readyBuf = await prepareFormTSEWorkbookForDownload(lastExport.arrayBuffer);
            const blob = new Blob([readyBuf], {
              type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download =
              fileName || lastExport.fileName || 'Form_T_Karnataka.xlsx';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
            setSuccess('Draft file downloaded.');
            setTimeout(() => setSuccess(''), 3000);
            setFormFileLoading(false);
            return true;
          }
        }
        // Prefer attachment disposition; fall back to plain Draft URL if the server rejects it.
        let resp = await fetch(
          `/server/statutoryreg_function/statutory/${draftApiRowId}/file/Draft?disposition=attachment&_ts=${Date.now()}`,
          { cache: 'no-store' }
        );
        if (!resp.ok) {
          resp = await fetch(
            `/server/statutoryreg_function/statutory/${draftApiRowId}/file/Draft?_ts=${Date.now()}`,
            { cache: 'no-store' }
          );
        }
        if (!resp.ok) return false;
        const arrayBuffer = await resp.arrayBuffer();
        if (!arrayBuffer || arrayBuffer.byteLength < 32) return false;
        // Form 11 RJ: never stream older column-shifted drafts — regenerate onto clean template.
        try {
          const probeWb = XLSX.read(arrayBuffer, { type: 'array' });
          if (sheetJsWorkbookLooksLikeForm11Rajasthan(probeWb)) {
            return false;
          }
        } catch (_) {
          /* keep fast path if probe fails */
        }
        // Form T: repair J→A if needed, then open at column A (not the attendance freeze at J).
        let downloadBuffer = arrayBuffer;
        if (isFormTFast) {
          downloadBuffer = await prepareFormTSEWorkbookForDownload(arrayBuffer);
          if (!(await formTSEWorkbookHasIdentityInColumnA(downloadBuffer))) return false;
        }
        const blob = new Blob([downloadBuffer], {
          type: resp.headers.get('content-type') || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = fileName || 'draft_file.xlsx';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        setSuccess('Draft file downloaded.');
        setTimeout(() => setSuccess(''), 3000);
        setFormFileLoading(false);
        return true;
      } catch (fastErr) {
        console.warn('Fast saved draft download skipped:', fastErr);
        return false;
      }
      // On failure leave formFileLoading true so regenerate / fallback can keep draft links pinned.
    };

    if (await tryFastSavedDraftDownload()) return;

    const draftFileHint = String(
      fileName ||
        sourceItem?.draftFileName ||
        sourceItem?.DraftFileName ||
        resolvedFormFileItem?.formFileName ||
        resolvedFormFileItem?.FormFileName ||
        ''
    );
    const draftRegenerateBlob = [
      sourceItem?.formName,
      sourceItem?.FormName,
      sourceItem?.description,
      sourceItem?.Description,
      resolvedFormFileItem?.formName,
      resolvedFormFileItem?.FormName,
      resolvedFormFileItem?.formFileName,
      draftFileHint
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    const isFormXLeaveDownloadRow = isFormXLeaveSocialSecurityContext(
      null,
      sourceItem || resolvedFormFileItem,
      draftFileHint,
      draftRegenerateBlob
    );
    const isForm15Part1LeaveDownloadRow = isForm15Part1AutofillContext(
      draftFileHint,
      null,
      sourceItem || resolvedFormFileItem
    );
    const isForm11RJDownloadRow = isForm11RajasthanContext(
      null,
      sourceItem || resolvedFormFileItem,
      draftFileHint,
      draftRegenerateBlob
    );
    if (isFormXLeaveDownloadRow || isForm15Part1LeaveDownloadRow || isForm11RJDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXVIIDownloadRow =
      isFormXVIICLRARegisterOfWagesContext(null, sourceItem || resolvedFormFileItem, draftFileHint) ||
      isFormXVIICLRARegisterOfWagesContext(null, resolvedFormFileItem, draftFileHint) ||
      matchesFormXVIIHint(draftRegenerateBlob);
    if (isFormXVIIDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXXIIIDownloadRow =
      !isFormXVIIDownloadRow &&
      (isFormXXIIIContext(null, sourceItem || resolvedFormFileItem, draftFileHint) ||
      isFormXXIIIContext(null, resolvedFormFileItem, draftFileHint) ||
      isFormXXIIIContext(null, sourceItem, resolvedFormFileItem?.formFileName || '') ||
      /\bform[\s._-]*xxiii\b/i.test(draftRegenerateBlob) ||
      (/\bandhra[\s._-]*pradesh\b/.test(draftRegenerateBlob) &&
        /register\s+of\s+wages/i.test(draftRegenerateBlob) &&
        !/register\s+of\s+advances?/i.test(draftRegenerateBlob)));
    if (isFormXXIIIDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXXIIDownloadRow =
      !isForm12AdvancesRegisterContext(null, sourceItem || resolvedFormFileItem, draftFileHint, null) &&
      (isFormXXIIRegisterOfEmploymentContext(null, sourceItem || resolvedFormFileItem, draftFileHint, null, '') ||
        isFormXXIIRegisterOfEmploymentContext(
          null,
          resolvedFormFileItem,
          resolvedFormFileItem?.formFileName || draftFileHint,
          null,
          ''
        ) ||
        matchesFormXXIIHint(draftRegenerateBlob));
    if (isFormXXIIDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXXVIDownloadRow =
      isFormXXVIContext(null, sourceItem || resolvedFormFileItem, draftFileHint) ||
      isFormXXVIContext(null, resolvedFormFileItem, draftFileHint) ||
      isFormXXVIContext(null, sourceItem, resolvedFormFileItem?.formFileName || '') ||
      matchesFormXXVIHint(draftRegenerateBlob);
    if (isFormXXVIDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isForm11DownloadRow = isForm11EsicAccidentBookContext(
      null,
      sourceItem || resolvedFormFileItem,
      fileName || sourceItem?.draftFileName || resolvedFormFileItem?.formFileName || '',
      null
    );
    if (isForm11DownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem);
      return;
    }
    const isForm2APDownloadRow =
      isForm2APChangeNoticeContext(null, sourceItem || resolvedFormFileItem, draftFileHint, '') ||
      isForm2APChangeNoticeContext(null, resolvedFormFileItem, resolvedFormFileItem?.formFileName || draftFileHint, '') ||
      /form[\s._-]*2[\s._-]*a/i.test(draftRegenerateBlob);
    if (isForm2APDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXVDownloadRow =
      isFormXVContext(null, sourceItem || resolvedFormFileItem, draftFileHint) ||
      isFormXVContext(null, resolvedFormFileItem, resolvedFormFileItem?.formFileName || draftFileHint);
    if (isFormXVDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXIRJDownloadRow =
      isFormXIRajasthanServiceCertificateContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXIRajasthanServiceCertificateContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      );
    if (isFormXIRJDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXIVMPDownloadRow =
      isFormXIVMPEmploymentCardContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXIVMPEmploymentCardContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      ) ||
      isFormXRajasthanEmploymentCardContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXRajasthanEmploymentCardContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      );
    if (isFormXIVMPDownloadRow) {
      // Form XIV MP and Form X RJ — regenerate per-employee ZIP (saved draft is a single .xlsx).
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXIXMPDownloadRow =
      isFormXIXMPWageSlipContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXIXMPWageSlipContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      );
    if (isFormXIXMPDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXIXAPDownloadRow =
      isFormXIXAPTableWageSlipContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXIXAPTableWageSlipContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      ) ||
      isFormXIXAPWageSlipContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      );
    if (isFormXIXAPDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXVIIIMPDownloadRow =
      isFormXVIIIMPCombinedRegisterContext(
        null,
        sourceItem || resolvedFormFileItem,
        draftFileHint,
        ''
      ) ||
      isFormXVIIIMPCombinedRegisterContext(
        null,
        resolvedFormFileItem,
        resolvedFormFileItem?.formFileName || draftFileHint,
        ''
      );
    if (isFormXVIIIMPDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    const isFormXIIIDownloadRow = isFormXIIIRegisterOfWorkmenContext(
      null,
      sourceItem || resolvedFormFileItem,
      fileName || resolvedFormFileItem?.formFileName || draftFileHintEarly || '',
      '',
      null
    );
    const isFormIDownloadRow =
      !isFormXIIIDownloadRow &&
      (isFormIRegisterOfFinesContext(
        sourceItem || resolvedFormFileItem,
        fileName || resolvedFormFileItem?.formFileName || '',
        null,
        null,
        ''
      ) ||
      isFormIRegisterOfWorkmenContext(
        sourceItem || resolvedFormFileItem,
        fileName || resolvedFormFileItem?.formFileName || draftFileHintEarly || '',
        null,
        null,
        ''
      ) ||
      /form[_\s-]*i(?:[_\s-]|$)/i.test(
        String(fileName || resolvedFormFileItem?.formFileName || draftFileHintEarly || '')
      ) ||
      /form[_\s-]*i(?:[_\s-]|$)/i.test(String(sourceItem?.formName || sourceItem?.FormName || '')) ||
      /\bform\s*[-"']?\s*i\b/i.test(String(sourceItem?.formName || sourceItem?.FormName || '')));
    if (isFormIDownloadRow || isFormXIIIDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId,
        skipBackgroundPrefetch:
          isFormFileModalOpenRef.current &&
          countMeaningfulFormTableRows(formTableDataRef.current) > 0
      });
      return;
    }
    const isForm25DownloadRow =
      /\bform\s*[-"']?\s*25\b/i.test(String(sourceItem?.formName || sourceItem?.FormName || '')) ||
      /\bform\s*[-"']?\s*25\b/i.test(String(resolvedFormFileItem?.formName || resolvedFormFileItem?.FormName || '')) ||
      /\bform\s*[-"']?\s*25\b/i.test(String(fileName || ''));
    if (isForm25DownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem);
      return;
    }
    // Form V: always regenerate from Autofill grid (saved Draft xlsx is often still empty template).
    const formVDownloadHint = [
      sourceItem?.formName,
      sourceItem?.FormName,
      resolvedFormFileItem?.formName,
      resolvedFormFileItem?.FormName,
      fileName,
      draftFileHintEarly,
      resolvedFormFileItem?.formFileName,
      resolvedFormFileItem?.FormFileName
    ]
      .filter(Boolean)
      .join(' ');
    const isFormVDownloadRow =
      /form[_\s-]*v(?:[_\s-]|$)/i.test(formVDownloadHint) ||
      /\bform\s*[-"']?\s*v\b/i.test(formVDownloadHint) ||
      (/register\s+of\s+employment/i.test(formVDownloadHint) && /tamil/i.test(formVDownloadHint));
    const liveFormVGridReady =
      isFormFileModalOpenRef.current &&
      countMeaningfulFormTableRows(formTableDataRef.current) > 0 &&
      isFormVDownloadRow;
    if (isFormVDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId,
        skipBackgroundPrefetch: liveFormVGridReady
      });
      return;
    }
    // Form U: always regenerate from Autofill grid (saved Draft xlsx is often still empty template).
    const formUDownloadHint = [
      sourceItem?.formName,
      sourceItem?.FormName,
      resolvedFormFileItem?.formName,
      resolvedFormFileItem?.FormName,
      fileName,
      draftFileHintEarly,
      resolvedFormFileItem?.formFileName,
      resolvedFormFileItem?.FormFileName
    ]
      .filter(Boolean)
      .join(' ');
    const isFormUDownloadRow =
      /form[_\s-]*u(?:[_\s-]|$)/i.test(formUDownloadHint) ||
      /\bform\s*[-"']?\s*u\b/i.test(formUDownloadHint);
    const liveFormUGridReady =
      isFormFileModalOpenRef.current &&
      countMeaningfulFormTableRows(formTableDataRef.current) > 0 &&
      isFormUDownloadRow;
    if (isFormUDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId,
        skipBackgroundPrefetch: liveFormUGridReady
      });
      return;
    }
    // Form W / Register of Wages: always regenerate from Autofill grid (saved Draft xlsx is often still empty template).
    const formWDownloadHint = [
      sourceItem?.formName,
      sourceItem?.FormName,
      resolvedFormFileItem?.formName,
      resolvedFormFileItem?.FormName,
      fileName,
      draftFileHintEarly,
      resolvedFormFileItem?.formFileName,
      resolvedFormFileItem?.FormFileName
    ]
      .filter(Boolean)
      .join(' ');
    const isFormWDownloadRow =
      /form[_\s-]*w(?:[_\s-]|$)/i.test(formWDownloadHint) ||
      /\bform\s*[-"']?\s*w\b/i.test(formWDownloadHint) ||
      (/register\s+of\s+wages/i.test(formWDownloadHint) &&
        !/labour\s*welfare/i.test(formWDownloadHint) &&
        !/\bform\s*[-"']?\s*b\b/i.test(formWDownloadHint));
    const liveFormWGridReady =
      isFormFileModalOpenRef.current &&
      countMeaningfulFormTableRows(formTableDataRef.current) > 0 &&
      isFormWDownloadRow;
    if (isFormWDownloadRow) {
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId,
        skipBackgroundPrefetch: liveFormWGridReady
      });
      return;
    }
    const isFormTSEDownloadRow = isFormTSEContext(
      null,
      sourceItem || resolvedFormFileItem,
      draftFileHint,
      ''
    );
    if (isFormTSEDownloadRow) {
      // Regenerate from formmaster (skipBackgroundPrefetch false → never use dirty Draft as template).
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
      return;
    }
    try {
      setFormFileLoading(true);
      setError('');
      await handleViewDraftFileGenerate(sourceItem, resolvedFormFileItem, {
        sampleStatutoryId: draftApiRowId,
        draftApiRowId
      });
    } catch (err) {
      console.error('Saved draft direct download error:', err);
      setError(err?.message || 'Failed to download saved draft file.');
    } finally {
      setFormFileLoading(false);
    }
  };

  /** Download PDF of the same Excel data used by Download Draft File. */
  const handleDownloadDraftPdf = async (draftApiRowId, fileName, sourceItem, resolvedFormFileItem) => {
    const lineItem = sourceItem || resolvedFormFileItem || {};
    // Prefer catalog form name only — never use the Excel draft file name as a PDF heading.
    const pdfTitle = String(lineItem?.formName || lineItem?.FormName || '').trim();
    const pdfDownloadName = draftFileNameToPdfName(
      fileName ||
        sourceItem?.draftFileName ||
        sourceItem?.DraftFileName ||
        resolvedFormFileItem?.formFileName ||
        'statutory-draft.pdf'
    );

    const triggerPdfDownload = (blob) => {
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = pdfDownloadName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    };

    try {
      setFormFileLoading(true);
      setError('');
      setSuccess('Preparing PDF...');

      let arrayBuffer = null;
      let sourceFileName =
        fileName ||
        sourceItem?.draftFileName ||
        sourceItem?.DraftFileName ||
        resolvedFormFileItem?.formFileName ||
        'draft.xlsx';

      // Prefer last Form T export when available (same bytes as Download Draft File).
      const lastFormT = readFormTSELastExport();
      if (
        lastFormT?.arrayBuffer &&
        lastFormT.arrayBuffer.byteLength >= 32 &&
        isFormTSEContext(null, lineItem, sourceFileName, '')
      ) {
        arrayBuffer = lastFormT.arrayBuffer;
        sourceFileName = lastFormT.fileName || sourceFileName;
      }

      // Always prefer the same generated Excel/ZIP as Download Draft File (full autofill data).
      if (!arrayBuffer || arrayBuffer.byteLength < 32) {
        try {
          setSuccess('Generating draft for PDF...');
          const generated = await handleViewDraftFileGenerate(sourceItem || lineItem, resolvedFormFileItem, {
            sampleStatutoryId: draftApiRowId,
            draftApiRowId,
            returnBlobOnly: true
          });
          if (generated?.blob) {
            arrayBuffer = await generated.blob.arrayBuffer();
            sourceFileName = generated.fileName || sourceFileName;
          }
        } catch (genErr) {
          console.warn('PDF regenerate failed, trying saved draft:', genErr);
        }
      }

      // Fallback: saved draft file on server.
      if ((!arrayBuffer || arrayBuffer.byteLength < 32) && draftApiRowId) {
        try {
          const resp = await fetch(
            `/server/statutoryreg_function/statutory/${draftApiRowId}/file/Draft?disposition=attachment&_ts=${Date.now()}`,
            { cache: 'no-store' }
          );
          if (resp.ok) {
            const buf = await resp.arrayBuffer();
            if (buf && buf.byteLength >= 32) {
              arrayBuffer = buf;
              const cd = resp.headers.get('content-disposition') || '';
              const cdMatch = /filename\*?=(?:UTF-8''|")?([^\";]+)/i.exec(cd);
              if (cdMatch?.[1]) {
                try {
                  sourceFileName =
                    decodeURIComponent(cdMatch[1].replace(/"/g, '').trim()) || sourceFileName;
                } catch (_) {
                  sourceFileName = cdMatch[1].replace(/"/g, '').trim() || sourceFileName;
                }
              }
            }
          }
        } catch (savedDraftErr) {
          console.warn('Saved draft PDF fetch skipped:', savedDraftErr);
        }
      }

      if (!arrayBuffer || arrayBuffer.byteLength < 32) {
        throw new Error('No draft Excel data found. Use Autofill → Save, then Download PDF.');
      }

      setSuccess('Building PDF...');
      const pdfBlob = await buildStatutoryDraftPdfBlob({
        arrayBuffer,
        fileName: sourceFileName,
        title: pdfTitle,
        monthLabel: selectedMonth || ''
      });
      triggerPdfDownload(pdfBlob);
      setSuccess('PDF downloaded.');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Download draft PDF error:', err);
      setSuccess('');
      setError(err?.message || 'Failed to download draft PDF.');
      setTimeout(() => setError(''), 5000);
    } finally {
      setFormFileLoading(false);
    }
  };

  // Save form file data to Excel and upload as draft
